select private.rules_import_historical_version($rules${"governing_body":"Buhurt International","history":"archive-2026-10-06","inventory_key":"authenticity/aesthetics-and-decorations","version":{"version":"2024.12","title":"Armors and weapons Aesthetics and Decoration 2024.12","published_on":null,"effective_from":null,"note":"Title \"Armors and weapons Aesthetics and Decoration\" (the current document is \"Armors and Weapons Aesthetics and Decoration\"); cover \"VER. 2024.12\"; change log only \"11-Nov-2024: Document has been created\". Older than the current 26.1.","source_url":"https://drive.google.com/file/d/10jWjYxOx7M4s1LPoMyTRTNOiIhTsbTaJ/view","source_sha256":"6d2eeed99605990d3b0a0d0a2ed2eada69235c38f5326f6e600e1cd95f730876","retrieved_at":null,"page_count":18,"extractor":"pdftotext unknown -layout -enc UTF-8","content_sha256":"1463833f8d31c25178bccb451b78122415ea57a87b8d57650615ff27af38c25e","detected":{"version":null,"date":null},"confirmed_by":"Claude Code (Pack 22 historical import), read from the archived PDF: cover (OCR of the page image), footers and change log","historical":true,"edition_seq":1,"edition_evidence":"Title \"Armors and weapons Aesthetics and Decoration\" (the current document is \"Armors and Weapons Aesthetics and Decoration\"); cover \"VER. 2024.12\"; change log only \"11-Nov-2024: Document has been created\". Older than the current 26.1.","source_files":[{"file":"Authenticity/Archive/Armors and weapons Aesthetics and Decoration V2024.12.pdf","archive":"Authenticity","sha256":"6d2eeed99605990d3b0a0d0a2ed2eada69235c38f5326f6e600e1cd95f730876","drive_file_id":"10jWjYxOx7M4s1LPoMyTRTNOiIhTsbTaJ"}],"reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1"],"pages":18,"source_lines":235,"assigned_lines":396,"furniture_lines":49,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.9962,"provisions":34,"numbered":33,"needs_review":0,"verified":0,"empty_pages":[1],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":0,"picture_text_lines":0,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"aesthetics-and-decorations:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Definition and general requirements","body":"Armors and weapons aesthetics are very important for the fighters' appearance and sports representation. The development of our sport will be easier with well-maintained and properly finished armor and weapons. Crafting armor and its parts is a process mostly made by hand with the help of different hand tools such as hammers and files, even during the surfacing process and polishing. Thus, it is not rare to find such traces on artifacts, even in the corners of a highly polished armor.","page_from":3,"page_to":3,"stable_key":"aesthetics-and-decorations:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a09261c60517114f7bb3991bf3a4af83fc4a02cd142399a9e1cefaa1c9e2c95e","has_figures":true,"extraction":"text"},{"ordinal":3,"depth":1,"kind":"rule","number":"1.1","title":null,"body":"The following aesthetics are allowed:\n● Matte polish (see page 4)\n● Satin Polish (see page 7)\n● Mirror Polish (see page 9)\n● Blackening and Bluing (see page 11)","page_from":3,"page_to":3,"stable_key":"aesthetics-and-decorations:1.1","parent_key":"aesthetics-and-decorations:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"400f4067c99b1742861fd5f4adc339c2cf4e52021c46f2b3da62ff1f97c44d13","has_figures":true,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"1.2","title":"All types of aesthetics must respect the following requirements","body":"● Be based on historical sources.\n● Be homogenous regarding the whole set of armor: it is not allowed to mix different aesthetics in the same armor set unless specifically written in the specific requirements.\n● The steel surface does not present strong forging remains, big filing traces, and modern grinding marks.\n● Must be properly polished, any highly unpolished armor part is denied.\n● Must be free of rust.","page_from":3,"page_to":3,"stable_key":"aesthetics-and-decorations:1.2","parent_key":"aesthetics-and-decorations:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f6c62c392d2aac2fa040f05fffaf88b13f6c73d2a5ae3bbc255fab2037b8e903","has_figures":true,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"1.3","title":"Decoration","body":"An armor can be decorated with different methods, such as\n● etching\n● engraving\n● plating and gilding Helmets can be decorated with the medieval spirit, with crest, torse, burlets or orle for example.\n\nExample of burlet:\n\nPicture from Age of Craft ©","page_from":3,"page_to":3,"stable_key":"aesthetics-and-decorations:1.3","parent_key":"aesthetics-and-decorations:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1750770c10e41684a72f625ec917763b308fe8fccd0c0fc6b1fa84125a48f4bc","has_figures":true,"extraction":"text"},{"ordinal":6,"depth":1,"kind":"rule","number":"1.4","title":"Painted armor","body":"As the topic of painted armors is very controversial among armor experts, historical sources can’t stand a clear position about painted armor. We have historical sources for late-15th century helmets (mainly Sallets) but nothing relevant for the 14th century nor for armor parts. Therefore, any painted armor metal part, metal buckler or weapon is denied.","page_from":3,"page_to":3,"stable_key":"aesthetics-and-decorations:1.4","parent_key":"aesthetics-and-decorations:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d727401a871a77b018c1b3ae324344f623bd962022f91b2ac2567c187eba134f","has_figures":true,"extraction":"text"},{"ordinal":7,"depth":0,"kind":"section","number":"2","title":"Matte Polish","body":"","page_from":4,"page_to":4,"stable_key":"aesthetics-and-decorations:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"517f1ccd7af4f743bfbf743ef5dfd8994ba631b57d0aa8a0e20084dcf1d4b0ef","has_figures":true,"extraction":"text"},{"ordinal":8,"depth":1,"kind":"rule","number":"2.1","title":"Matte polish definition and sources","body":"A basic polishing method, widely used during the Middle Ages. Its appearance is flat and gray, and subtle marks from the polishing process are still visible. A utilitarian finish that hides scratches and holds a protective oil film well. The basic and most common finish is the matte polish. It is recommended for all types of 14th and 15th century armor and weapons.\n\nIt is approved for 14th-century, Transitional armors and 15th-century armors.\n\nArmet, on display at the Metropolitan Museum of Arts (MET) - 1440 - New York (USA)","page_from":4,"page_to":4,"stable_key":"aesthetics-and-decorations:2.1","parent_key":"aesthetics-and-decorations:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d5cae6a49d54e9f0a695c15dc8f7ceaa5d2b6e63f52fcb2bdfb3a426476c2256","has_figures":true,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"2.2","title":"Specific requirements","body":"● The whole armor or weapon must be matte polished.\n● It is denied to have an armor set mixing matte polish with other aesthetics.\n● Matte polish can be used with other decoration techniques, such as etching, engraving, gilding or plating.","page_from":4,"page_to":4,"stable_key":"aesthetics-and-decorations:2.2","parent_key":"aesthetics-and-decorations:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e885c8ccbf134f017199b99beb7c1de4c0d17ec1246fd9be5091a5c0d4cdf2f0","has_figures":true,"extraction":"text"},{"ordinal":10,"depth":1,"kind":"rule","number":"2.3","title":"Examples of Approved finishes","body":"Picture from Medieval Extreme © Picture from Master Uley ©\n\nAcceptable grinder marks","page_from":5,"page_to":5,"stable_key":"aesthetics-and-decorations:2.3","parent_key":"aesthetics-and-decorations:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c61dacfe020db99ad013113b79cc81acfb454f7074b968a5c35eb37038d2e016","has_figures":true,"extraction":"text"},{"ordinal":11,"depth":1,"kind":"rule","number":"2.4","title":"Examples of Denied finishes","body":"Excessive rust Unpolished weapons\n\nUnpolished Picture from The Medieval Things ©","page_from":6,"page_to":6,"stable_key":"aesthetics-and-decorations:2.4","parent_key":"aesthetics-and-decorations:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"792999749463470e28f485cce0012cbfa598f5bbe2992f2d75b708b3754da07b","has_figures":true,"extraction":"text"},{"ordinal":12,"depth":0,"kind":"section","number":"3","title":"Satin Polish","body":"","page_from":7,"page_to":7,"stable_key":"aesthetics-and-decorations:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"09fcd430ef71b6b2c708cdfe59d26db3d2866d0ca247ceb66c26628b103844ee","has_figures":true,"extraction":"text"},{"ordinal":13,"depth":1,"kind":"rule","number":"3.1","title":"Definition and sources","body":"Satin polish has a semi-reflective surface with a subdued sheen, the polishing marks are small and only visible upon close inspection. A practical polishing method that balances functionality with a refined appearance. Armors are polished with multiple grinding grits to obtain an intermediary reflective finish. It is not as shiny as mirror polishing.\n\nIt is approved for 14th-century, Transitional armors and 15th-century armors.\n\nMontefeltro Altarpiece by Piero della Francesca - 1472 - Italy Note: the helmet in this art is mirror polished","page_from":7,"page_to":7,"stable_key":"aesthetics-and-decorations:3.1","parent_key":"aesthetics-and-decorations:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"565f91780b99e2e442b0b129d6694df03c43392bbad7eb6e7bf233cbde584620","has_figures":true,"extraction":"text"},{"ordinal":14,"depth":1,"kind":"rule","number":"3.2","title":"Specific requirements","body":"● The whole armor must be satin polished or a mix of satin and mirror polished.\n● It is denied to have an armor set mixing matte polishing parts with satin polishing parts.\n● It is denied to have an armor set mixing black/blued polishing parts with satin polishing parts.\n● Satin polish can be used with other decoration techniques, such as etching, engraving, gilding or plating.","page_from":8,"page_to":8,"stable_key":"aesthetics-and-decorations:3.2","parent_key":"aesthetics-and-decorations:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8f710ef6778e78892555a3a38eef239e78a1ec5fb747da153f7990c26c5e0292","has_figures":true,"extraction":"text"},{"ordinal":15,"depth":1,"kind":"rule","number":"3.3","title":"Examples of Approved finishes","body":"Pictures from Master Uley ©\n\nPicture from Black Dog Armoury ©","page_from":8,"page_to":8,"stable_key":"aesthetics-and-decorations:3.3","parent_key":"aesthetics-and-decorations:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9c64c6d5bb542ec5751f33ae4c55775156ea9267d468b377181c378e90e1e3f5","has_figures":true,"extraction":"text"},{"ordinal":16,"depth":0,"kind":"section","number":"4","title":"Mirror Polish","body":"","page_from":9,"page_to":9,"stable_key":"aesthetics-and-decorations:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7fa3404ea9089274931bf6769a087f9cd17a8ce10a66e8d9e2abbad3969644bb","has_figures":true,"extraction":"text"},{"ordinal":17,"depth":1,"kind":"rule","number":"4.1","title":"Mirror polish definition and sources","body":"A late-period polishing technique that gained popularity in the 15th century. Metal plates are polished with progressively finer grit until polishing marks are not visible, resulting in a reflective sheen. This finish requires high maintenance to keep it looking its best. Armors are polished with multiple grinding grits reaching into the 1000 grid to obtain a beautiful reflective finish.\n\nIt is approved for 14th-century, Transitional armors and 15th-century armors..\n\nSigismund von Tirol\n\nArmor of Sigismund von Tirol, Kunsthistorisches Museum Wien - 1484 - Austria","page_from":9,"page_to":9,"stable_key":"aesthetics-and-decorations:4.1","parent_key":"aesthetics-and-decorations:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b7bc6a09d4bf344e6cefb41441a6ce18e0e05c52e02946462e44eafad897fc96","has_figures":true,"extraction":"text"},{"ordinal":18,"depth":1,"kind":"rule","number":"4.2","title":"Specific requirements","body":"● The whole armor must be satin polished or a mix of satin and mirror polished.\n● It is denied to have an armor set mixing black/blued polishing parts with mirror polishing parts.\n● Mirror polish can be used with other decoration techniques, such as etching, engraving, gilding or plating.","page_from":9,"page_to":9,"stable_key":"aesthetics-and-decorations:4.2","parent_key":"aesthetics-and-decorations:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"cba22774d0f1cfd304051ca2550c4e83ec95a4210a0171d5d9a5d9957f7ca4f3","has_figures":true,"extraction":"text"},{"ordinal":19,"depth":1,"kind":"rule","number":"4.3","title":"Examples of Approved finishes","body":"Pictures from Master Uley ©\n\nPictures from J. Amiot ©","page_from":10,"page_to":10,"stable_key":"aesthetics-and-decorations:4.3","parent_key":"aesthetics-and-decorations:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0e4f1a731b48a12740d844dcf9f8ae3758e38afbe03ec69c5947cf53eca70244","has_figures":true,"extraction":"text"},{"ordinal":20,"depth":0,"kind":"section","number":"5","title":"Blackening and Bluing","body":"","page_from":11,"page_to":11,"stable_key":"aesthetics-and-decorations:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"94bf7d252944b11ef61fbdbe297c1ca3806b607d5d10aaaa7df76bff57025d54","has_figures":true,"extraction":"text"},{"ordinal":21,"depth":1,"kind":"rule","number":"5.1","title":"Blackening and Bluing definition and sources","body":"Finishing method appearing in the mid-15th century sources, the metal plates are carefully heated to high temperatures to obtain a black or blue finish by treating the steel with oils.\n\nIt is approved for 15th-century armors.\nIt is denied for 14th-century and Transitional armors.\n\nAcceptable methods of blackening/Bluing are as followed:\n● Temperature Bluing: The metal plates are carefully heated to adequate temperatures to obtain a blue oxide finish on the surface of the steel.\n● Oil Blackening: This technique involves applying oils, such as linseed oil, to steel, which is then baked in an oven or applied to heated steel at relatively low temperatures. The process results in a deep black, protective finish. However, it requires regular touch-ups to maintain its appearance and protective qualities.\n● Chemical blackening/bluing: Modern chemicals normally intended for use on firearms are permitted for armor. Hot-blue treatment is preferred, as it results in a deeper and more durable finish, but be mindful of how this could affect heat-treated steel. Cold-blue can be repeatedly applied to darken the surface of the steel and also to touch up hot-blued steel.\n\nGreenwich Armour replica (1595) Plates formed by Robert MacPherson & Jeff Wasson, decoration and finishing by Chris Gilman\n\nA B\n\nC\n\nA: 'Georgsaltar' (Meister der Georgslegende), Köln, Wallraf-Richartz-Museum - 1460-1465 - Germany B: Armet, German - 1550 - Metropolitan Museum of Arts C: Foot combat armor, Royal Armouries 1591 - England","page_from":11,"page_to":12,"stable_key":"aesthetics-and-decorations:5.1","parent_key":"aesthetics-and-decorations:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3406350369a4ff70f531189450f94b6ed7dab6c11bf1d6e0cd6eea2a9bf9604f","has_figures":true,"extraction":"text"},{"ordinal":22,"depth":1,"kind":"rule","number":"5.2","title":"Specific requirements","body":"● The whole armor must be of the same method of blackening/bluing.\n● It is denied to have an armor set mixing black/blued polishing parts with other aesthetics.\n● Blackening/bluing finish can be used with other decoration techniques, such as etching, engraving, gilding, or plating.\n● It is denied to use paint to reproduce a black/blued finish.","page_from":13,"page_to":13,"stable_key":"aesthetics-and-decorations:5.2","parent_key":"aesthetics-and-decorations:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"358db1fa0fc3916ba764b7df1e72c181b7228270b9eb89a29f2db3e31fd04b46","has_figures":true,"extraction":"text"},{"ordinal":23,"depth":1,"kind":"rule","number":"5.3","title":"Examples of Approved Finishes","body":"Pictures from Master Uley ©","page_from":13,"page_to":13,"stable_key":"aesthetics-and-decorations:5.3","parent_key":"aesthetics-and-decorations:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a99981996e1b150e3307f4aeb33733b0871e3958c2e0c0243f81795820b46ec3","has_figures":true,"extraction":"text"},{"ordinal":24,"depth":1,"kind":"rule","number":"5.4","title":"Examples of Denied Finishes","body":"Unpolished helmet, trying to imitate proper blackening.\n14th century helmets that can’t have blackening finish.\nPictures from The Medieval Things ©","page_from":13,"page_to":13,"stable_key":"aesthetics-and-decorations:5.4","parent_key":"aesthetics-and-decorations:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"93a912f0e352c3bf5f423645d95308d12f430f8aa325fa146457336de9329d89","has_figures":true,"extraction":"text"},{"ordinal":25,"depth":0,"kind":"section","number":"6","title":"Decorations","body":"","page_from":14,"page_to":14,"stable_key":"aesthetics-and-decorations:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"898793fc683ed18ee4994db2dfbb8040926eaae81dcc0f09767d2851d37f11a0","has_figures":true,"extraction":"text"},{"ordinal":26,"depth":1,"kind":"rule","number":"6.1","title":"Definition and sources","body":"Armors were often decorated with different methods to display the owner’s status. The following decoration methods are documented by historical sources: etching, engraving, plating and gilding.\nHelmets were decorated with fabric or metal elements such as crest, burlet, torse and orle.\n\nIt is approved for 14th-century armors, Transitional armors and 15th-century armors.\n\nSir William Phelip, Lord Bardolph - 1441 - England\n\nBL Royal 20 C VII Chroniques de France ou de St Denis\n- 1380/1400 - France\n\nLate 14th century, MET Museum","page_from":14,"page_to":14,"stable_key":"aesthetics-and-decorations:6.1","parent_key":"aesthetics-and-decorations:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1371d89ece46a8e07a292f66aef45c18e6673fadf527c2176a070f6733fe2d08","has_figures":true,"extraction":"text"},{"ordinal":27,"depth":1,"kind":"rule","number":"6.2","title":"Specific requirements","body":"Decoration must be based on historical sources. It is allowed to combine different decorations in a coherent way. Any decoration must not represent any offensive symbols, words, or sentence of any type. All political messages must not be used as decoration on armor and weapons. Any logo must be stylized to reach the middle-ages aesthetics and designs.","page_from":15,"page_to":15,"stable_key":"aesthetics-and-decorations:6.2","parent_key":"aesthetics-and-decorations:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a79a2e10fa23bcc8ce69c51b478d6efa69d8d67d6247c8943854d6deaefa8e55","has_figures":false,"extraction":"text"},{"ordinal":28,"depth":1,"kind":"rule","number":"6.3","title":null,"body":"The following decorations techniques are allowed:\n● Etching: It is allowed to etch historical symbols and written words with etching techniques.\nArmor parts and weapons can be decorated this way.\n\n● Engraving: It is allowed to engrave historical symbols and written words with engraving techniques. Engraving can be done by hand or mechanically. Armor parts and weapons can be decorated this way.\n\n● Plating: It is allowed to decorate the edges of an armor part with metal plates. The following materials can be used:\n○ Copper ○ Brass ○ Gold ○ Silver ○ And any other metal that can be documented by historical sources.\n\n● Gilding: It is allowed to use gilding as a decoration on armor and weapons. The following materials can be used:\n○ Copper ○ Brass ○ Gold ○ Silver ○ And any other metal that can be documented by historical sources.\n\n● Helmet decorations: it is allowed to decorate a helmet in the medieval spirit. It must be based on historical sources. Any textile or leather part must conform with the Textiles and Leather document.","page_from":15,"page_to":15,"stable_key":"aesthetics-and-decorations:6.3","parent_key":"aesthetics-and-decorations:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7c305cee0f7004abac548e2eb459aaf2bfc6593d7618aceb102e27cb0c65d0e3","has_figures":false,"extraction":"text"},{"ordinal":29,"depth":1,"kind":"rule","number":"6.4","title":"Examples of Approved Decorations","body":"Pictures from The Medieval Things ©","page_from":16,"page_to":16,"stable_key":"aesthetics-and-decorations:6.4","parent_key":"aesthetics-and-decorations:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"848096e77f6d8927dcb61cb2497930149983800ccd91a9b449b4b59a302718df","has_figures":true,"extraction":"text"},{"ordinal":30,"depth":1,"kind":"rule","number":"6.5","title":"Examples of Denied Decorations","body":"Painted helmets\n\nPictures from The Medieval Things ©","page_from":16,"page_to":16,"stable_key":"aesthetics-and-decorations:6.5","parent_key":"aesthetics-and-decorations:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4d85bc91700d5b5dd109e3d959cf66a3c59ac954b616519b1cedcf6bb6cdf6b0","has_figures":true,"extraction":"text"},{"ordinal":31,"depth":0,"kind":"section","number":"7","title":"Repairs","body":"","page_from":17,"page_to":17,"stable_key":"aesthetics-and-decorations:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"bd57acf667c7bf440591562b9e7134f2909131f50514310d4e4a4b2b71d4f281","has_figures":false,"extraction":"text"},{"ordinal":32,"depth":1,"kind":"rule","number":"7.1","title":"Definition and sources","body":"Armors were sometimes repaired to increase its durability. In the Middle Ages, the most common way to repair an armor was to rivet a metal plate from beneath. From a buhurt point of view, it will be important to respect period techniques for visible repairs. It is approved for 14th-century armors, Transitional armors, and 15th-century armors.","page_from":17,"page_to":17,"stable_key":"aesthetics-and-decorations:7.1","parent_key":"aesthetics-and-decorations:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6dbdaa575016ad1229c20cc5a529da43a4426dfef1e2ab44bd4125db110f8580","has_figures":false,"extraction":"text"},{"ordinal":33,"depth":1,"kind":"rule","number":"7.2","title":"Specific requirements","body":"● Visible repairs must be executed with period techniques, for example with a riveted patch installed on the inside of the armor part and riveted.\n● Repairs must be clean and not dangerous for other equipment elements.\n● Any modern reparation is allowed if properly concealed. Any type of welding must be grinded/filed and polished on the outside.","page_from":17,"page_to":17,"stable_key":"aesthetics-and-decorations:7.2","parent_key":"aesthetics-and-decorations:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d8c410c40eb1fdccc3ab7ff34ca9281811ba4a2d555e2f282598f3c68bb589d9","has_figures":false,"extraction":"text"},{"ordinal":34,"depth":0,"kind":"note","number":"8","title":"Change log","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\n11-Nov-2024: -Add Document has been created","page_from":18,"page_to":18,"stable_key":"aesthetics-and-decorations:8","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"4cddc47bd8189cdef09dcb288b548a846ba3e1ced9918c6b06762ad85273c619","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_historical_version($rules${"governing_body":"Buhurt International","history":"archive-2026-10-06","inventory_key":"authenticity/aventails","version":{"version":"2025.02","title":"Aventails 2025.02","published_on":null,"effective_from":null,"note":"Title \"Aventails\"; cover \"VER. 2025.02\". Its change log heads the latest entry \"February-2025 (V2025.03)\": the cover and the change log disagree; the label is the cover's, the disagreement is recorded. Entries Dec-2024 and Feb-2025 are both in the current 26.1 change log.","source_url":"https://drive.google.com/file/d/1UzW6euMy0kVpODmyjPaC9M26DcJnPfpO/view","source_sha256":"dcc5ba335e3b1a4266ba6c97cd4fb97af39f517136dc1f7aaff295b0d9c3a9de","retrieved_at":null,"page_count":17,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 1 page(s) without a text layer","content_sha256":"be83a969119a33ad10e1648ed89b219fbf035355f8880c6b9fafa9074490024e","detected":{"version":"2025.02","date":null},"confirmed_by":"Claude Code (Pack 22 historical import), read from the archived PDF: cover (OCR of the page image), footers and change log","historical":true,"edition_seq":1,"edition_evidence":"Title \"Aventails\"; cover \"VER. 2025.02\". Its change log heads the latest entry \"February-2025 (V2025.03)\": the cover and the change log disagree; the label is the cover's, the disagreement is recorded. Entries Dec-2024 and Feb-2025 are both in the current 26.1 change log.","source_files":[{"file":"Authenticity/Archive/Aventails.docx.pdf","archive":"Authenticity","sha256":"dcc5ba335e3b1a4266ba6c97cd4fb97af39f517136dc1f7aaff295b0d9c3a9de","drive_file_id":"1UzW6euMy0kVpODmyjPaC9M26DcJnPfpO"}],"reconciliation":{"ok":true,"errors":[],"warnings":[],"pages":17,"source_lines":184,"assigned_lines":367,"furniture_lines":46,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99591,"provisions":27,"numbered":26,"needs_review":0,"verified":0,"empty_pages":[],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":4,"picture_text_lines":2,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 2025.02\n\nAuthenticity\n\nAuthenticity Rules - Aventails","page_from":1,"page_to":3,"stable_key":"aventails:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"f4c10d0e2a24d69adf211d829119f06e6d6ac18fac5f9642fee54083810331b6","has_figures":true,"extraction":"mixed"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Definition and general requirements","body":"","page_from":3,"page_to":3,"stable_key":"aventails:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"df9d4b4971cd1ada36b96ec4e6602cd5f968c25814a104728b68a69b7ffb6242","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":1,"kind":"rule","number":"1.1","title":"Definition","body":"● An aventail, also called a camail, is a flexible neck defense attached to a helmet, typically made from chainmail. Scales aventails also appear in period art. The purpose of the aventail is to protect the neck, throat, and shoulders of the wearer by draping over the shoulders and upper chest. It typically hangs from the lower edge of the helmet and was popular from the 13th to 15th centuries, providing flexible but effective protection.\n● By the turn of the 15th century, aventails were commonly sewn onto a leather band that ran around the base of the helmet. This was secured with cords to studs known as vervelles. Beneath the aventail, a padded liner called a pelerine extended from the helmet liner to cushion and distribute the impact of strikes. The outer edge of the aventail’s rings was stitched to the pelerine for stability and to prevent shifting during combat.\n● Aventails were primarily seen on bascinet-style helmets but could be adapted for other helmets like great helms or kettle hats. Many aventails were elaborately decorated, featuring quilted covers with heraldic designs as well as decorative chainmail rings and latten vervelle covers.","page_from":3,"page_to":3,"stable_key":"aventails:1.1","parent_key":"aventails:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6aefa1074afb4fe1ff95b9bcaf7682278362ad59307e67a30d67398aed5d56f3","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"1.2","title":"Aventails description","body":"Aventails can be:\n● Chainmail Aventail: Aventails made from chainmail elements, attached to the helmet with a suspension system.\n● Scales Aventail: Aventails made of metal scales riveted to the pelerine.\n● Fabric Aventail: Aventails made from fabric, used to display heraldry and must be decorated.","page_from":3,"page_to":3,"stable_key":"aventails:1.2","parent_key":"aventails:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d317fcb3e59d775cafa234be080b25343cb6f544646a01baef057bf81a841535","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"1.3","title":"General Requirements","body":"All types of aventails must respect the following requirements :\n● Must be based on historical sources.\n● Must be firmly attached to the helmet with a vervelle and leather system.\n● Must be appropriately sized for the wearer, as depicted in historical sources.\n● It is not allowed to combine two or more different types of aventails (e.g., chainmail and fabric) unless documented by historical sources.\n\nEach helmet-related document will explain what types of aventail are allowed and denied.","page_from":3,"page_to":3,"stable_key":"aventails:1.3","parent_key":"aventails:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"71a56a7815a194d017dd3215c9045f68e01c232af57e54168e21494f0277db6d","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":0,"kind":"section","number":"2","title":"Chainmail Aventail","body":"","page_from":4,"page_to":4,"stable_key":"aventails:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f551df6ce810432f0394c7baa337c045919d48cbab787b93175c578f98cefe69","has_figures":true,"extraction":"text"},{"ordinal":7,"depth":1,"kind":"rule","number":"2.1","title":"Historical Sources and Datation","body":"Chainmail aventails have been part of armor since the earliest helmets. By the 14th and 15th centuries, it was almost impossible to have a helmet without a chainmail aventail.\n\nThey are Approved for 14th-century, transitional, and 15th-century armors.\n\nBook of the Queen - 1410/1414 - France Wallace Collection - 1390/1410 - UK","page_from":4,"page_to":4,"stable_key":"aventails:2.1","parent_key":"aventails:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c0fd9600b97b8a802b3b34b91d4dd0d7b86f469acb76d10f9f2152c6459e6516","has_figures":true,"extraction":"text"},{"ordinal":8,"depth":1,"kind":"rule","number":"2.2","title":"Specific Requirements","body":"● The outer edge of the chainmail aventail must be securely stitched to a padded pelerine to prevent displacement.\n● The aventail must cover the shoulders, throat, and neck at all times without gaps.\n● Chainmail aventails must be properly maintained: damaged rings must be replaced, rust must be removed, etc.\n● Chainmail Aventails must follow the general requirements (1.3)","page_from":4,"page_to":4,"stable_key":"aventails:2.2","parent_key":"aventails:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a7a9ceb4d577917f7884787c9c8f48fb244d1062fa85f5eb2ff66f7a355099e7","has_figures":true,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"2.3","title":"Examples of Approved Reproductions","body":"Picture from Master Uley© Picture from The Medieval Things\n\nPicture from The Medieval Things ©","page_from":5,"page_to":5,"stable_key":"aventails:2.3","parent_key":"aventails:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"465f7bc8896e362b3a812249819be68db92ee0b2ea4764d9a6723532ed22b3f2","has_figures":true,"extraction":"text"},{"ordinal":10,"depth":1,"kind":"rule","number":"2.4","title":"Examples of Denied Reproductions","body":"Incomplete aventails\n\nPoorly made aventails\n\nPictures from The Medieval Things ©","page_from":6,"page_to":6,"stable_key":"aventails:2.4","parent_key":"aventails:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3947d20f18db63cb28773ea2110e782cee13cfa7e1facb4a3b4e2e7d37401cbb","has_figures":true,"extraction":"text"},{"ordinal":11,"depth":0,"kind":"section","number":"3","title":"Scales Aventail","body":"","page_from":7,"page_to":7,"stable_key":"aventails:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"91bd06bc507c3d812d10aa7747ba597f06854f8af823929df3a4056f658bb530","has_figures":true,"extraction":"text"},{"ordinal":12,"depth":1,"kind":"rule","number":"3.1","title":"Historical Sources and Datation","body":"Scales aventails consist of metal scales riveted to a leather or fabric base. Though no artifacts remain, they can be documented in manuscripts.\n\nThey are Approved for 14th-century, transitional, and 15th-century armors.\n\nBook of Hours - 1425/1435 - France Concerning the Fates of Illustrious Men and Women - 1415 - France\n\nSint-Martinusbasiliek - 1409 - Belgium","page_from":7,"page_to":7,"stable_key":"aventails:3.1","parent_key":"aventails:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"fa3371d1be35329aea12440df207eea66eb2df414033c106c1f50640b4bf05af","has_figures":true,"extraction":"text"},{"ordinal":13,"depth":1,"kind":"rule","number":"3.2","title":"Specific Requirements","body":"● Scales must be contoured (not flat) and securely riveted to the pelerine for a proper fit and protection.\n● Allowed shapes include square, triangular, and semicircular designs.\n● Scales must lay evenly and overlap slightly to ensure full protection with no gaps.\n● Scales Aventails must follow the general requirements (1.3)","page_from":7,"page_to":7,"stable_key":"aventails:3.2","parent_key":"aventails:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"45dfdd6fcb1694e758963a94b2a12978bab5bfe6788b7b34458fb922bc5f3418","has_figures":true,"extraction":"text"},{"ordinal":14,"depth":1,"kind":"rule","number":"3.3","title":"Examples of Approved Reproductions","body":"Pictures from The Medieval Things ©\n\nPicture from Forge of Svan ©","page_from":8,"page_to":8,"stable_key":"aventails:3.3","parent_key":"aventails:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"229f56cbf5ffafb317bc67fff054ae4904d3374371a7d18c45c807ff31c37760","has_figures":true,"extraction":"text"},{"ordinal":15,"depth":1,"kind":"rule","number":"3.4","title":"Examples of Denied Reproductions","body":"Poorly made scales aventail\n\nPicture from The Medieval Things ©","page_from":9,"page_to":9,"stable_key":"aventails:3.4","parent_key":"aventails:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c827b6653155f532f975b17f8965ee10d6f5154b6644b22d0e84c4de53d8c7aa","has_figures":true,"extraction":"text"},{"ordinal":16,"depth":0,"kind":"section","number":"4","title":"Fabric Aventails","body":"","page_from":10,"page_to":10,"stable_key":"aventails:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ea0ef6bac9d27e2e829c476c552de1230be830e1cdbf8f63e94eef94eddecff5","has_figures":true,"extraction":"text"},{"ordinal":17,"depth":1,"kind":"rule","number":"4.1","title":"Historical Sources and Datation","body":"Fabric aventails, often displayed over chainmail aventails, serve decorative purposes. They may feature multi-colored designs, decorative stitching, embroidery, and coats of arms. While this type of aventail is documented by sources from the 14th century, there is no evidence of fabric aventail later on. The mail present with other 15th helmets like barbutes and sallets are not aventail but mail standards/collars.\n\nThey are Approved for 14th-century and Transitional armors.\n\nThey are Denied for 15th century armors.\n\nDe Bello Civili - 1373 - Italy Weltchronik - 1385 - Germany\n\nChurch of St Georges, Schenna - 1380/1400 - Italy Runkelstein Castle, Ritten- 1395/1405 - Italy","page_from":10,"page_to":10,"stable_key":"aventails:4.1","parent_key":"aventails:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b88ad6e8279623eef61cbf0b567f6b203ce2d46b2d7a91b788a36802f0743be2","has_figures":true,"extraction":"text"},{"ordinal":18,"depth":1,"kind":"rule","number":"4.2","title":"Specific Requirements","body":"● Fabric aventails must consist of at least one layer of fabric, attached to the helmet using the same suspension method as other aventails (see 6.).\n● Fabric aventail must conform to the Textiles and Leather document.\n● Fabric aventails must follow the general requirements (1.3)\n\nFabric aventails must include at least one of the approved decoration methods, such as:\n● Multi-color base (at least 2 distinct colors)\n● Embroidery\n● Stitching\n● Stamp-printing\n● Decorations must be inspired by medieval images and not be offensive.\n● Any additional plates must be concealed when standing.\n● It is recommended to sew the fabric aventail to the pelerine.","page_from":11,"page_to":11,"stable_key":"aventails:4.2","parent_key":"aventails:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["6"],"content_sha256":"c8ce2e1d3b0ea0a1ce55e967dabdc7e5946a25cee1ce0afb90b30cde60ce592a","has_figures":true,"extraction":"text"},{"ordinal":19,"depth":1,"kind":"rule","number":"4.3","title":"Examples of Approved Reproductions","body":"Pictures from The Medieval Things ©","page_from":11,"page_to":11,"stable_key":"aventails:4.3","parent_key":"aventails:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c121d617758623e26bf653356a623b8901e02dbc57435c94dfb1b2535211f138","has_figures":true,"extraction":"text"},{"ordinal":20,"depth":1,"kind":"rule","number":"4.4","title":"Examples of Denied Reproductions","body":"Only 1 color with no decoration Mix of chainmail and fabric aventails\n\nMetal plates must be concealed\n\nOnly 1 color, and floppy aventail Pictures from The Medieval Things","page_from":12,"page_to":12,"stable_key":"aventails:4.4","parent_key":"aventails:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"33ef5291ace15270a5993cbda169d25c7962c3d80858a4a274a12acee7b9e493","has_figures":true,"extraction":"text"},{"ordinal":21,"depth":0,"kind":"section","number":"5","title":"Suspension System","body":"","page_from":13,"page_to":13,"stable_key":"aventails:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"38869b16cdd41b07330b7fc0aa36ce052f21044d3d14839956c018c7755b29fc","has_figures":true,"extraction":"text"},{"ordinal":22,"depth":1,"kind":"rule","number":"5.1","title":"Historical Sources and Datation","body":"From the first bascinets of the 14th century until the late armets, aventails were attached to helmets using a suspension system made of vervelles and leather. This system was used from the 14th to the 16th centuries.\n\nIt is Approved for 14th-century, transitional, and 15th-century armors.\n\nBascinet Royal Armouries, Leeds - 1380/1400 - Italy","page_from":13,"page_to":13,"stable_key":"aventails:5.1","parent_key":"aventails:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"76f42181e17810cd45a36596830ff2bf00917bcf347f93bf0dafde57621d44e3","has_figures":true,"extraction":"text"},{"ordinal":23,"depth":1,"kind":"rule","number":"5.2","title":null,"body":"Examples of suspension systems:\n\nVervelles\n\nPiece of leather\n\nThread\n\nExamples of vervelles","page_from":14,"page_to":14,"stable_key":"aventails:5.2","parent_key":"aventails:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f321f70c46cbac04f946189ba59806bb5dedb6973df56088dfbd9109e237d485","has_figures":true,"extraction":"text"},{"ordinal":24,"depth":1,"kind":"rule","number":"5.3","title":"Specific Requirements","body":"The suspension system consists of vervelles, a piece of leather, and thread.\n\n● Vervelles: These are metal components with a hole, allowing threads (metal or leather) to pass through.\n● Leather Piece: The aventail (chainmail neck guard) is attached to a leather piece, which can be riveted or sewn.\n● Thread: The thread, made of either metal or leather (or materials that replicate their look), passes through the vervelles to secure the leather piece to the helmet.\n\nAlternative Method for fabric aventail: the aventail can be sewn directly to the helmet’s edge.","page_from":15,"page_to":15,"stable_key":"aventails:5.3","parent_key":"aventails:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8a8f2ea641d1f718a87e9c09e58767f8e32b701b9a1e5686a49485d3bd9a61f3","has_figures":false,"extraction":"text"},{"ordinal":25,"depth":1,"kind":"rule","number":"5.4","title":"Materials Requirements","body":"All materials used in the suspension system must comfort with the following documents\n● Metal Parts: armors and weapons aesthetics and decoration.\n● Fabric and Leather Parts: textiles and leather.","page_from":15,"page_to":15,"stable_key":"aventails:5.4","parent_key":"aventails:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"193d70b0be068350125e418e5b0bef81b2abca60b3a18f9e4dfe5d8a079d1cdd","has_figures":false,"extraction":"text"},{"ordinal":26,"depth":1,"kind":"rule","number":"5.5","title":"Examples of Approved Reproductions","body":"Leather and vervelle system Pictures from The Medieval Things©","page_from":16,"page_to":16,"stable_key":"aventails:5.5","parent_key":"aventails:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1dbf565dae327014ad3c3619338722b1d497987536ec0c51e285af0beb6cdbe3","has_figures":true,"extraction":"text"},{"ordinal":27,"depth":0,"kind":"note","number":"6","title":"Change log","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nFebruary-2025 (V2025.03) Clarification: 4.1 Format: Grammar and Formatting\n\nDecember-2024: -Add Document has been created","page_from":17,"page_to":17,"stable_key":"aventails:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"172f37199ecfe3790323c2146cc8f3a684f4b8d025400d0419e6119b56cc359b","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
