om":1,"page_to":1,"stable_key":"belt-flag-s:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"91cc874cc0c2306e0ce50ffd6d96f3b0ed6424411ad0724ce818c906154971d9","has_figures":true,"extraction":"ocr"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Authenticity rules Belt Flag","body":"","page_from":3,"page_to":3,"stable_key":"belt-flag-s:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2c7c584fc7e378efd75408f677c62b5ef09e016c2fa2d2f290de933958682580","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":1,"kind":"rule","number":"1.1","title":"Definition and general requirements","body":"● A competitor must have a belt flag with your number on it that identifies you\n● A competitor may have a second belt flag that is decorative symbols and decorations used for this must be based on historical sources. Any clearly modern symbol or decoration is denied.\n● No more than two belt flags may be worn by a competitor Examples: Warhammer logo, movies or TV show imagery, modern slogan etc\n● Belt flag is an element hung on a belt designed to show your belt number in the list.\n● Belt flag must be made of fabric or leather.\n● Belt flag must conform with the Textiles and Leather rules document.\n● Belt flag consists of a base and a number.\n● Base must respect the following requirements:\n○ Base shape can be square, rectangular or triangular.\n○ Base must have a trim to be worn with a belt.\n○ Base must be made of one main color.\n○ Some decoration can be added on the edges of the base.\n○ Such decoration must not interfere with the readability of the belt flag.\n● Number must respect the following requirements:\n○ Individual figures must be from 0 to 9.\n○ Numbers must be from 01 to 99.\n○ Number must be written in Arabic numerals.\n○ Number must be 13 cm tall as a minimum.\n○ Number can be of any color, contrasting with the base main color.\n● All Belt flags must respect the following dimensions:\n○ Length: from 26 cm to 36 cm.\n○ Width: from 14 cm to 18 cm.","page_from":3,"page_to":3,"stable_key":"belt-flag-s:1.1","parent_key":"belt-flag-s:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d86d32a751ed1312e0257cb70613f6b5a961c7f0bfa6143c7269f4c521ec4d98","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"1.2","title":"Examples of Approved reproductions","body":"Picture by Zoom en Lice Pictures by The Medieval Things","page_from":3,"page_to":3,"stable_key":"belt-flag-s:1.2","parent_key":"belt-flag-s:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"cac327ad98913f3a6daea0073423a9b87160c200806f09d30f01f1e42e47e248","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":0,"kind":"note","number":"2","title":"Change log","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\n11-Nov-2024: -add Document has been created","page_from":4,"page_to":4,"stable_key":"belt-flag-s:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"bbda7e20ee58611ccadf1a49dca6b30610f6378523fe799641a9387bda1d0d1c","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_historical_version($rules${"governing_body":"Buhurt International","history":"archive-2026-10-06","inventory_key":"authenticity/eyebars","version":{"version":"2024.12","title":"Eyebars 2024.12","published_on":null,"effective_from":null,"note":"Title \"Eyebars\"; cover \"VER. 2024.12\"; change log only \"December-2024: Document has been created\". Older than the current 26.1.","source_url":"https://drive.google.com/file/d/1WU2uGVz4giun-pOs8YRND6xN7OQ4m8fU/view","source_sha256":"45bda44ac3e67d68e69364b2028f0581c0e46f97dbcba1346a0767e4fb663a10","retrieved_at":null,"page_count":8,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 1 page(s) without a text layer","content_sha256":"df18b44bca2ea550f3ff1839b1e5f35753f419394672fd076294a012efda99aa","detected":{"version":"2024.12","date":null},"confirmed_by":"Claude Code (Pack 22 historical import), read from the archived PDF: cover (OCR of the page image), footers and change log","historical":true,"edition_seq":1,"edition_evidence":"Title \"Eyebars\"; cover \"VER. 2024.12\"; change log only \"December-2024: Document has been created\". Older than the current 26.1.","source_files":[{"file":"Authenticity/Archive/Eyebars V2024.12.docx.pdf","archive":"Authenticity","sha256":"45bda44ac3e67d68e69364b2028f0581c0e46f97dbcba1346a0767e4fb663a10","drive_file_id":"1WU2uGVz4giun-pOs8YRND6xN7OQ4m8fU"}],"reconciliation":{"ok":true,"errors":[],"warnings":[],"pages":8,"source_lines":85,"assigned_lines":129,"furniture_lines":30,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99389,"provisions":15,"numbered":14,"needs_review":0,"verified":0,"empty_pages":[],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":11,"picture_text_lines":9,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 2024.12\n\nAuthenticity","page_from":1,"page_to":1,"stable_key":"eyebars:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"91cc874cc0c2306e0ce50ffd6d96f3b0ed6424411ad0724ce818c906154971d9","has_figures":true,"extraction":"ocr"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Definition and General Requirements","body":"","page_from":3,"page_to":3,"stable_key":"eyebars:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"16f6f8920e5eb6836999f83839be69d2e96e3a5b5fa2ec8b8a840d9f67bd81fe","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":1,"kind":"rule","number":"1.1","title":"Definition","body":"● Eye Bars are the term used to describe additional protection for the eye slots of a helmet.\n● Rare historical sources display some additional eye protection, mainly for great helms.\n● However, it is permitted to add eye bars that do not rely on historical sources to increase the safety of helmets. The number and type of permitted eye bars are displayed in each helmet rules document","page_from":3,"page_to":3,"stable_key":"eyebars:1.1","parent_key":"eyebars:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"be0e1e2a7ea5de69fa454080084940e88e3a20d5f128fcd35e3f2e1dea1bd852","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"1.2","title":"Eye bars description","body":"Eye bars can be:\n\n● Externally Riveted Eye Bars This type of eye bar is documented by historical sources. It consists of metal plates riveted externally.\n● Buhurt “Optimized” Eye Bars This type of eye bar is not documented by historical sources. It consists of metal plates riveted or welded to the inside of a helmet.","page_from":3,"page_to":3,"stable_key":"eyebars:1.2","parent_key":"eyebars:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a6f334f5977f4b128d851ba4204ca354c8acef382f2d12dc18667944820277b9","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"1.3","title":"General requirements","body":"All types of eye bars must respect the following requirements\n\n● Be firmly attached to prevent any breakage and maintain a high level of protection in any situation.\n● Protect the whole eye slot from top to bottom.\n\nRecommended: Eye slots should not exceed an opening of 25 mm","page_from":3,"page_to":3,"stable_key":"eyebars:1.3","parent_key":"eyebars:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"988393e21950d8be79116063ed5fccb64935a7b92f79442e70f25f1c9f3c9fca","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":0,"kind":"section","number":"2","title":"Externally Riveted Eye Bars","body":"","page_from":4,"page_to":4,"stable_key":"eyebars:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d82403d6da6882bacef61d16ff555b3e2dd4178e96ca9b79e0ebcc95049538bb","has_figures":true,"extraction":"text"},{"ordinal":7,"depth":1,"kind":"rule","number":"2.1","title":"Historical Sources and Dating","body":"A few historical sources display this type of eye bar.\nThe main source is the Great Helm from Nuremberg (1350).\n\nDespite its rarity, it is approved for 14th-century, transitional, and 15th-century armors.","page_from":4,"page_to":4,"stable_key":"eyebars:2.1","parent_key":"eyebars:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e124e2e33a3b7e4637c54d442f1825613609493dc9980e73f54e2234e18a1379","has_figures":true,"extraction":"text"},{"ordinal":8,"depth":1,"kind":"rule","number":"2.2","title":"Specific Requirements","body":"● Externally riveted eye bars must conform with the general requirements (1.3)\n● Externally riveted eye bars must be firmly riveted to the outside of the eye slot.\n● Externally riveted eye bars must resemble the historical sources and not exceed a width of 30mm.\n● Externally riveted eye bars must be made of metal.","page_from":4,"page_to":4,"stable_key":"eyebars:2.2","parent_key":"eyebars:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a5ccfedbfb311c10f9cd3dd66e6c64fc26b469339a84b044ae55606b6a07f7dd","has_figures":true,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"2.3","title":"Examples of Approved reproductions","body":"Picture by Zoom en Lice ©","page_from":5,"page_to":5,"stable_key":"eyebars:2.3","parent_key":"eyebars:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"be6b3cd0087f2771426d9a7661d7de35ce542a9f436e43f835bfb141c239f7d2","has_figures":true,"extraction":"text"},{"ordinal":10,"depth":0,"kind":"section","number":"3","title":"Buhurt “Optimized” Eye Bars","body":"","page_from":6,"page_to":6,"stable_key":"eyebars:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"80380b26d420fa2c494d13cfc1e9ea0df3442de4ec3e5370e500a23eed5abab3","has_figures":true,"extraction":"text"},{"ordinal":11,"depth":1,"kind":"rule","number":"3.1","title":"Historical Sources and Dating","body":"There are no historical sources for eye bars welded onto eye slots.\nNevertheless, for safety reasons, they are approved for 14th-century, transitional, and 15th-century armor.","page_from":6,"page_to":6,"stable_key":"eyebars:3.1","parent_key":"eyebars:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"00e7f90080cc0634ebe24676ee89f8c95b1d6709bd8a9af171ca0951978def97","has_figures":true,"extraction":"text"},{"ordinal":12,"depth":1,"kind":"rule","number":"3.2","title":"Specific Requirements","body":"● Buhurt-optimized eye bars must conform with the general requirements (1.3)\n● Buhurt-optimized eye bars must be welded or riveted from the inside of the helm.\n● Buhurt-optimized eye bars must be strong enough to endure full-contact fights.\n● Buhurt-optimized eye bars must be painted black.","page_from":6,"page_to":6,"stable_key":"eyebars:3.2","parent_key":"eyebars:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ba2a8851c1e30bd7b5922a5b9f24d2d623ee8a53da02f8b70e9bc21be7429a40","has_figures":true,"extraction":"text"},{"ordinal":13,"depth":1,"kind":"rule","number":"3.3","title":"Examples of Approved Reproductions","body":"Pictures from The Medieval Things ©","page_from":6,"page_to":6,"stable_key":"eyebars:3.3","parent_key":"eyebars:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a1130db5edf777b376e9569c379053eba7b176dabdc15d499d5ff24f22276fd2","has_figures":true,"extraction":"text"},{"ordinal":14,"depth":1,"kind":"rule","number":"3.4","title":"Examples of Denied Reproductions","body":"Too much eyebars\n\nPictures from The Medieval Things ©","page_from":7,"page_to":7,"stable_key":"eyebars:3.4","parent_key":"eyebars:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"acff33f676cf3f2a0de9453283e91c030809fecbc8c4dde92f53ad5122e93f9c","has_figures":true,"extraction":"text"},{"ordinal":15,"depth":0,"kind":"note","number":"4","title":"Change log","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nDecember-2024: -add Document has been created","page_from":8,"page_to":8,"stable_key":"eyebars:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"d1a65e57aa9ae1fde0d4ca7cd6c4970c925a72393fc04f35254a4d1c387650bd","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_historical_version($rules${"governing_body":"Buhurt International","history":"archive-2026-10-06","inventory_key":"authenticity/great-helms","version":{"version":"2024.12","title":"Helmet - Great Helms 2024.12","published_on":null,"effective_from":null,"note":"Title \"Helmet - Great Helms\"; cover \"VER. 2024.12\"; change log only \"December-2024: Document has been created\". Older than the current 26.1.","source_url":"https://drive.google.com/file/d/1gL21GwNUYlvSAZo4naNJPe2j4UiV_1t4/view","source_sha256":"9264f54892f263c5c3824c4e3868695d8d6d0f02bb71c31b27e5a83edf7d87d4","retrieved_at":null,"page_count":9,"extractor":"pdftotext unknown -layout -enc UTF-8","content_sha256":"5620ebf944728b7ad289ba7cb85d50c1c97d8210df89624507404731a522ed2e","detected":{"version":null,"date":null},"confirmed_by":"Claude Code (Pack 22 historical import), read from the archived PDF: cover (OCR of the page image), footers and change log","historical":true,"edition_seq":1,"edition_evidence":"Title \"Helmet - Great Helms\"; cover \"VER. 2024.12\"; change log only \"December-2024: Document has been created\". Older than the current 26.1.","source_files":[{"file":"Authenticity/Archive/Helmet - Great Helms 2024.12.docx.pdf","archive":"Authenticity","sha256":"9264f54892f263c5c3824c4e3868695d8d6d0f02bb71c31b27e5a83edf7d87d4","drive_file_id":"1gL21GwNUYlvSAZo4naNJPe2j4UiV_1t4"}],"reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1","1 provision(s) need review against the official document"],"pages":9,"source_lines":86,"assigned_lines":134,"furniture_lines":20,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99638,"provisions":13,"numbered":11,"needs_review":1,"verified":0,"empty_pages":[1],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":0,"picture_text_lines":0,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"great-helms:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"note","number":null,"title":null,"body":"Great Helms","page_from":2,"page_to":2,"stable_key":"great-helms:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"b4c633e2221fa6c044344fe0139a3b6a8ee7cfeeead40ca36d41d2173b0690d9","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":0,"kind":"section","number":"1","title":"Definition","body":"● Great Helms are a popular head defense formerly known as “Chapel de fer” from the 12th to the 14th centuries. Characterized by its cylindrical design and large size, it provided maximum protection for the face and neck. Often used as a secondary defense, it was worn over a maille coif, cervelliere, or bascinet.\n● During the 14th century, great helms were used as a primary defense during battle. It was designed to be removed after the early engagements.\n● In the late 14th and during the 15th century, Great Helms evolved to be suitable for tournaments only.\nTheir latest version is called “Frogmouth” and is designed for jousting.\n● Great Helms are approved for 14th century transitional armors, and 15th century armors.","page_from":3,"page_to":3,"stable_key":"great-helms:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d16e5d36924628758b4ec1198b4e421e44b1149ab74a0749df1bc8b4159f5a0f","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":0,"kind":"section","number":"2","title":"Historical Sources and Datation","body":"A   B   C\n\nD   E   F\n\nA: Schweizerisches Landesmuseum - 1325/1350 - Switzerland B: Germanisches National Museum - 1350 - Germany C: Pembridge Helm, National Museum of Scotland - 1350/1375 - Scotland D: Gerhard von Rieneck, Ederbach - 1382 - Germany E: Sir Nicholas Hawkberk Helm - 1407 - England F: “Frogmouth” helmet, The Art Institute of Chicago - 1490","page_from":4,"page_to":4,"stable_key":"great-helms:2","parent_key":null,"review_status":"needs_review","review_note":"layout looks like a table or columns: compare with the official page","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"47ad20ab711970b402de4c0ba07ae6843d8877deed3ec98add3ae8309a7aa464","has_figures":true,"extraction":"text"},{"ordinal":5,"depth":0,"kind":"section","number":"3","title":"Requirements","body":"","page_from":5,"page_to":5,"stable_key":"great-helms:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"475f60c10a2f0b6b9f5aaf68ce12eb9a12457aeafff595062e0babfbd5af33a1","has_figures":true,"extraction":"text"},{"ordinal":6,"depth":1,"kind":"rule","number":"3.1","title":"General Requirements","body":"● Reproductions must closely resemble the appearance and proportions of the sources.\n● Any metal part of the helmet must conform to the Armors and weapons Aesthetics and decorations document.\n● Any textile or leather part of the helmet must conform to the Textiles and Leather document.","page_from":5,"page_to":5,"stable_key":"great-helms:3.1","parent_key":"great-helms:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8d1adc84eaa67b5f3ed41ac23bece4190d285a788ee5880a2eae758c9baa423e","has_figures":true,"extraction":"text"},{"ordinal":7,"depth":1,"kind":"rule","number":"3.2","title":"Visor Requirements","body":"● The visor must not be too long or too short, it must respect the proportions of historical sources.\n● Breath holes should be round and consistently sized unless documented by the source.\nBreath holes must not be so numerous that they compromise the helm’s structural integrity. It is acceptable to mirror breath holes to both sides.","page_from":5,"page_to":5,"stable_key":"great-helms:3.2","parent_key":"great-helms:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8e045829372ccc8762227932da402853f1219f7d1f8e03069e9a18d7be843a09","has_figures":true,"extraction":"text"},{"ordinal":8,"depth":1,"kind":"rule","number":"3.3","title":"Eye Slots","body":"● Eye slots should resemble sources for the visor.\n● Eye slots should not exceed 25mm tall to prevent any injury..\\\n● Great helms with two (2) eye slots are permitted to add up to two (2) externally riveted eye bars or buhurt-optimized internal eye bars per eye slot.\n● Great helms with a single eye slot are allowed to add up to five (5) buhurt-optimization eyebars: one (1) in the middle and two (2) on each side.\n● It is not possible to mix externally riveted eyebars and buhurt-optimization eyebars on the same helmet. Only one type of eyebar is allowed.\n● Eyebars must conform to the Eyebars Rules document.","page_from":5,"page_to":5,"stable_key":"great-helms:3.3","parent_key":"great-helms:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"52ed591ba6dd3e784119b43ddfc70559ba88758e556febd07848dca8c0d0d3f8","has_figures":true,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"3.4","title":"Aventail","body":"● Great helms can be worn with chainmail or scale aventails. Fabric aventails are not allowed.\n● Aventails must conform to the Aventail Rules.\n● Great helms can not have a suspension system made of vervelles and leather. Chainmail should be affixed to the interior of the helmet.\n● Protective plates covering the cervical spine must be hidden under the aventail.","page_from":6,"page_to":6,"stable_key":"great-helms:3.4","parent_key":"great-helms:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a382adc80abc56cc71b7c52d60a431c01cec13d60e93b13cca4301438a3d7571","has_figures":false,"extraction":"text"},{"ordinal":10,"depth":1,"kind":"rule","number":"3.5","title":"Others","body":"● Great helms may be decorated in the spirit of medieval styles, such as an orle, torse, decorated aventails (with copper/brass chainmail rings) coat of arms badges, etc.\n● Such decoration must be made in coherence with historical sources.\n● Using modern and/or offensive imagery and slogans is prohibited.","page_from":6,"page_to":6,"stable_key":"great-helms:3.5","parent_key":"great-helms:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"03fcd0356dec2e958d63d49f5fa5104f8746446f5e207aa46979fd5672d4bf2d","has_figures":false,"extraction":"text"},{"ordinal":11,"depth":0,"kind":"section","number":"4","title":"Approved reproductions","body":"Picture from J. Gries © Picture from The Medieval Things ©","page_from":7,"page_to":7,"stable_key":"great-helms:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b979cbf6450abbbdaf16af6a9d1a2210c68746d1873b6dac1f62e8d2502cd6c8","has_figures":true,"extraction":"text"},{"ordinal":12,"depth":0,"kind":"section","number":"5","title":"Denied reproductions","body":"Design of the bottom of the visor does not reproduce historical sources.\n\nDesign of the top of the helmet does not reproduce historical sources.\n\nPictures from The Medieval Things ©","page_from":8,"page_to":8,"stable_key":"great-helms:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6aa8b57d2c3c0485650b67d4d322186274680c5dae3713f866fcbcec249433ab","has_figures":true,"extraction":"text"},{"ordinal":13,"depth":0,"kind":"note","number":"6","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nDecember-2024: -add Document has been created","page_from":9,"page_to":9,"stable_key":"great-helms:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"de0ac0b3e8bf0301bc01863caf758bf4d1e55852afb4b5301722baf1d66ff13c","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_historical_version($rules${"governing_body":"Buhurt International","history":"archive-2026-10-06","inventory_key":"authenticity/greaves","version":{"version":"2025.03","title":"Greaves 2025.03","published_on":null,"effective_from":null,"note":"Title \"Greaves\"; cover \"VER. 2025.03\"; change log latest \"March-2025 (V2025.03)\" after \"December-2024: created\". Older than the current 26.1.","source_url":"https://drive.google.com/file/d/16GRE7qyStPEIWtiT36V8erOF3QcFALPi/view","source_sha256":"498c79e15c93619fd51fc812afccadbc777c73b43283d2065c1e87f9b40a59c4","retrieved_at":null,"page_count":19,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 1 page(s) without a text layer","content_sha256":"e6c294c0c5cc0be7a7775a599c30a1b056e35f01301ae4340beeeca4b3e48a2d","detected":{"version":"2025.03","date":null},"confirmed_by":"Claude Code (Pack 22 historical import), read from the archived PDF: cover (OCR of the page image), footers and change log","historical":true,"edition_seq":1,"edition_evidence":"Title \"Greaves\"; cover \"VER. 2025.03\"; change log latest \"March-2025 (V2025.03)\" after \"December-2024: created\". Older than the current 26.1.","source_files":[{"file":"Authenticity/Archive/Greaves.pdf","archive":"Authenticity","sha256":"498c79e15c93619fd51fc812afccadbc777c73b43283d2065c1e87f9b40a59c4","drive_file_id":"16GRE7qyStPEIWtiT36V8erOF3QcFALPi"}],"reconciliation":{"ok":true,"errors":[],"warnings":["6 line(s) looked like a numbered heading but did not fit the sequence"],"pages":19,"source_lines":238,"assigned_lines":434,"furniture_lines":67,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99436,"provisions":38,"numbered":37,"needs_review":0,"verified":0,"empty_pages":[],"rejected_numbers":6,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":11,"picture_text_lines":9,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 2025.03\n\nAuthenticity Authenticity rules - Greaves","page_from":1,"page_to":2,"stable_key":"greaves:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"494544af240ca3cedfaf687fbc5c9832bfff0be7504058bb8137c7d9d26fa567","has_figures":true,"extraction":"mixed"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Definition and General Requirements","body":"","page_from":3,"page_to":3,"stable_key":"greaves:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"16f6f8920e5eb6836999f83839be69d2e96e3a5b5fa2ec8b8a840d9f67bd81fe","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Definition and general requirements","body":"Greaves is the term used to describe all lower leg protections.\n\n1.1. Types of Greaves\n\n1-Panel Greaves (Half-Greaves)\n● Made of 1 plate of metal forged to the shape of the lower leg.\n● Attached by a leather strap at the back of the calf.\n\n2-Panel Greaves (Cased Greaves)\n● Made of 2 plates of metal built to protect the lower leg at 360°.\n● The plates are built with hinges and attached by a leather strap at the inner side of the lower leg.\n\n3-Panel Greaves\n● Made of 3 plates of metal attached with leather.\n\n3/4 Greaves\n● The front side of the lower leg is protected by a metal plate.\n● The outside of the lower leg is protected by a half-plate of metal, leaving the inner side of the lower leg unprotected.\n\nSplinted Greaves\n● Metal plates riveted to a leather base.\n● The plates are alternately outside and inside the leather.\n\nBrigand Greaves\n● Metal plates riveted to a fabric base.\n● The plates are covered by the fabric.\n\nEastern Greaves\n● Due to very few historical sources, it is allowed to use eastern stylization of European greaves.\n● Allowed designs are displayed in the document “Eastern Armors.”\n\n1.2. General Requirements for All Greaves\n\n1.2.1. Historical Basis: Must be based on historical sources.\n1.2.2. Anatomical Shape: Must have the anatomical shape of the lower leg.\n1.2.3. Proportions: Must reproduce the proportions based on historical sources.\n1.2.4. Malleolus Protection: Must protect the malleolus bone.\n\n2. One Panel Greaves (Half-Greaves)","page_from":3,"page_to":4,"stable_key":"greaves:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"94f4206949f25070d459c8cc53d6be982608da4d52edc68d36165d5d178bbb0f","has_figures":true,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"2.1","title":"Historical Sources and Datation","body":"● The 1-panel greave is the earliest form of lower leg protection available for knights, originating in the early 14th century.\n● Approved for 14th-century and Transitional armors.\n● Denied for 15th-century armor.\n\n● Historical References\n● Crucifixion, Niederhaslach – 1360, France (A)\n● J. von Falkenstein – 1365, Germany (B)\n\n(A) (B)","page_from":4,"page_to":4,"stable_key":"greaves:2.1","parent_key":"greaves:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9d7b0c58195ba4333c9f70d12894016719a0de3efd1cf3aea9313f2b22245d85","has_figures":true,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"2.2","title":"Specific Requirements for One Panel Greaves (Half-Greaves)","body":"● must conform to the general requirements outlined in article 3\n● The entire front of the lower leg must be covered by the greaves","page_from":4,"page_to":4,"stable_key":"greaves:2.2","parent_key":"greaves:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"073780a2143d8fadee2966d1b3f9fb0a4e8958a42b29d27d73654889f16e5d2b","has_figures":true,"extraction":"text"},{"ordinal":6,"depth":1,"kind":"rule","number":"2.3","title":"Examples of Approved reproductions","body":"Picture from Forge of Svan © Picture from Age of Craft ©","page_from":4,"page_to":4,"stable_key":"greaves:2.3","parent_key":"greaves:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"db6fc3a26389b0c7694890957fd0e5e74d9d74a2b3d34650f3411dbeca7c18f7","has_figures":true,"extraction":"text"},{"ordinal":7,"depth":1,"kind":"rule","number":"2.4","title":"Examples of Denied reproductions","body":"Non-anatomic shape\n\nPictures from The Medieval Things ©","page_from":5,"page_to":5,"stable_key":"greaves:2.4","parent_key":"greaves:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"11216e3f380bc6383aec44e4740f2012b07cdbced23d0974a65a83c1a8478219","has_figures":true,"extraction":"text"},{"ordinal":8,"depth":0,"kind":"section","number":"3","title":"Two panels-graves (cased greaves)","body":"","page_from":6,"page_to":6,"stable_key":"greaves:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"734f3101deeb6cfdd3b4c057552ebc7b8ebcb19fa7b944e413b1204ae87cc8b5","has_figures":true,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"3.1","title":"Historical Sources and Datation","body":"● 2-panel greaves, also known as cased greaves, were the most common form of lower leg protection from 1370 to 1600 and later. They provided superior protection for competitors by covering the entire lower leg from all sides.\n● Approved for 14th-century, Transitional, and 15th-century armors.\n\nMetropolitan Museum of Arts - 1450 Brescia - 1470/1480 - Ital","page_from":6,"page_to":6,"stable_key":"greaves:3.1","parent_key":"greaves:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d27bc9b1abc2361aee63958dd644e6fffce822d3bb626c03a9c71663ae18299d","has_figures":true,"extraction":"text"},{"ordinal":10,"depth":1,"kind":"rule","number":"3.2","title":"Specific Requirements","body":"must conform to the general requirements outlined in article 3\n\nArticulated Plates\n\nPermitted:\n● Articulated plates are allowed if worn with the adequate armor style from the 15th century.\nDenied:\n● Articulated plates at the bottom or top of the greaves are not allowed for 14th-century and Transitional-style armors.","page_from":6,"page_to":6,"stable_key":"greaves:3.2","parent_key":"greaves:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"1cfe7bcf7398b76ccc23d0fedcb6fb5a6c9d31a62739076809e9e8ceb9758d40","has_figures":true,"extraction":"text"},{"ordinal":11,"depth":1,"kind":"rule","number":"3.3","title":"Examples of Articulation","body":"Fully enclosed greaves (with heel-protection) appear in the late 15th century only. They are denied for 14th century and Transitional style armors.\n\nExamples of fully enclosed greaves:","page_from":7,"page_to":7,"stable_key":"greaves:3.3","parent_key":"greaves:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b1837f0fef6d3fd9d0ab1dfc9a0c77e16d479217b14f4140090cc9880a1cdd4d","has_figures":true,"extraction":"text"},{"ordinal":12,"depth":1,"kind":"rule","number":"3.4","title":"Examples of Approved reproductions","body":"","page_from":7,"page_to":7,"stable_key":"greaves:3.4","parent_key":"greaves:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"820b692214ad54790763ac23cef3f414e21c659117b9ea43130c93cff80dc1a9","has_figures":true,"extraction":"text"},{"ordinal":13,"depth":1,"kind":"rule","number":"3.5","title":"Examples of Denied reproductions","body":"Non-anatomic design Greaves with riveted ankle part (not based on historical sources) Pictures from The Medieval Things ©","page_from":8,"page_to":8,"stable_key":"greaves:3.5","parent_key":"greaves:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"581e96501d3f181278794b90c5ca9cbba24d70201598624036bab3715043f881","has_figures":false,"extraction":"text"},{"ordinal":14,"depth":0,"kind":"section","number":"4","title":"Three Panel Greaves","body":"","page_from":9,"page_to":9,"stable_key":"greaves:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d3e74b151dd72e23ddfcb49759497c831e62d1fc9c01d6b4f0b6425fa1bd0bce","has_figures":true,"extraction":"text"},{"ordinal":15,"depth":1,"kind":"rule","number":"4.1","title":"Historical Sources and Datation","body":"3 panel greaves are mainly represented in Germany from 1360 to 1380. They consist of one front panel and two side panels, articulated by leather straps.\n\n● Approved for 14th-century and Transitional armors.\n● Denied for 15th-century armors.","page_from":9,"page_to":9,"stable_key":"greaves:4.1","parent_key":"greaves:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"aa0f9fb39cf148dc2749a233e38fd24cf6a257f1f3988fadc2b2071349f93de4","has_figures":true,"extraction":"text"},{"ordinal":16,"depth":1,"kind":"rule","number":"4.2","title":null,"body":"Historical Example:\n● Sir Burchard von Steinberg – 1376, Germany (A)","page_from":9,"page_to":9,"stable_key":"greaves:4.2","parent_key":"greaves:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"dc4306bd8e583ed88f845f3165192ac43e759f5a233a6cb3edfa0d0c4b7799e1","has_figures":true,"extraction":"text"},{"ordinal":17,"depth":1,"kind":"rule","number":"4.3","title":"Specific Requirements","body":"● must conform to the general requirements article 3\n● The side panels must protect both sides of the lower leg, including the malleolus bone.\n● The panels can be articulated with leather straps or a piece of leather between each panel.\n● It is allowed to extend the width of the side panels to cover the back of the calf, despite this not being based on historical proportions.\n● It is allowed to use hinges instead of leather despite it not being documented by historical sources.","page_from":9,"page_to":9,"stable_key":"greaves:4.3","parent_key":"greaves:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"4bd96372d3c0451d2083e57a8c693ea781af82178911f656596fb4d56f272a93","has_figures":true,"extraction":"text"},{"ordinal":18,"depth":1,"kind":"rule","number":"4.4","title":"Examples of approved reproductions","body":"Side panels that are based on historical proportion Wider size panels for safety\n\nPicture from Age of Craft © Picture from Medieval Extreme ©\n\nPicture from The Medieval Things ©","page_from":10,"page_to":10,"stable_key":"greaves:4.4","parent_key":"greaves:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a13c67ac18123490bdcc128c03105d0729e93246a38cde4ebf874544afc983ed","has_figures":true,"extraction":"text"},{"ordinal":19,"depth":1,"kind":"rule","number":"4.5","title":"Examples of denied reproductions","body":"Side panels lack of shaping Does not adequately protect the malleolus bone, rule 1.2.4 Pictures from The Medieval Things ©","page_from":11,"page_to":11,"stable_key":"greaves:4.5","parent_key":"greaves:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["1.2.4"],"content_sha256":"de84ca11ae6ac44dad2cc72c5e4454312705392b047ea55ca77856d48fa38032","has_figures":false,"extraction":"text"},{"ordinal":20,"depth":0,"kind":"section","number":"5","title":"Three Quarters Greaves","body":"","page_from":12,"page_to":12,"stable_key":"greaves:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e0e9bd84e1f6cfa7c1515478317f068451693c91c86ddf11df8fd707c4c00206","has_figures":true,"extraction":"text"},{"ordinal":21,"depth":1,"kind":"rule","number":"5.1","title":"Historical Sources and Datation","body":"3/4 greaves first appeared in the 15th century.\n\n● Approved for Transitional and 15th-century armors.\n● Denied for 14th-century armors.\n\n● Historical Example\n● Metropolitan Museum of Art – 1550, Italy (A)\n\n(A)","page_from":12,"page_to":12,"stable_key":"greaves:5.1","parent_key":"greaves:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"edc67107e792c48b3215f2d76104e8ec430c0749b17b5b728cacf3072cce7a61","has_figures":true,"extraction":"text"},{"ordinal":22,"depth":1,"kind":"rule","number":"5.2","title":"Specific Requirements","body":"● must conform to the general requirements article 3.\n● The side panel must cover at least half of the back of the calf.","page_from":12,"page_to":12,"stable_key":"greaves:5.2","parent_key":"greaves:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"ba97246e30ecfb7cb346eaf18511d7ccc1f6760e7e3df7426dc07cc5a7b14b2d","has_figures":true,"extraction":"text"},{"ordinal":23,"depth":1,"kind":"rule","number":"5.3","title":"Examples of approved reproductions","body":"Picture from Age of Craft © Picture from The Medieval Things ©","page_from":13,"page_to":13,"stable_key":"greaves:5.3","parent_key":"greaves:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d93dae95ce902d9c392cf683cdb9c831f72ef34cafa7b048cc21907e894f2727","has_figures":true,"extraction":"text"},{"ordinal":24,"depth":1,"kind":"rule","number":"5.4","title":"Examples of denied reproductions","body":"","page_from":13,"page_to":13,"stable_key":"greaves:5.4","parent_key":"greaves:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4d91689b78cd0031f6b74cfb95a7ee38bec0d8fbf3e5888cc2a37bf541321c49","has_figures":true,"extraction":"text"},{"ordinal":25,"depth":0,"kind":"section","number":"6","title":"Splinted Greaves","body":"","page_from":14,"page_to":14,"stable_key":"greaves:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"52a66e7797a76a6a9bc08c4feb6a738b49aaa2e7115681aed801ebc5df70cda1","has_figures":true,"extraction":"text"},{"ordinal":26,"depth":1,"kind":"rule","number":"6.1","title":"Historical Sources and Datation","body":"● Introduction: Splinted greaves are represented in Europe from 1350 to 1380. They consist of metal plates riveted to a leather base.\n● Approved for 14th-century and Transitional armor.\n● Denied for 15th-century armor\n\n● Historical Examples:\n● Louis Thys – 1365, Belgium (A)\n● G. von Schwarzburg – 1349, Germany (B)\n\n(A) (B)","page_from":14,"page_to":14,"stable_key":"greaves:6.1","parent_key":"greaves:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"03bcc68bf7c362c15a8bc1e8428757da0d1dccb46604e835e841c29bcc430fda","has_figures":true,"extraction":"text"},{"ordinal":27,"depth":1,"kind":"rule","number":"6.2","title":"Specific Requirements for Splinted Greaves","body":"● must conform to the general requirements outlined in article 3.\n● Must be made of metal plates with the following features:\n● Rectangular shape.\n● Firmly riveted to a leather base.\n● Plates must be riveted alternatively inside and outside the leather base.\n● Plates must conform to the anatomical shape of the lower leg.","page_from":14,"page_to":14,"stable_key":"greaves:6.2","parent_key":"greaves:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"06a0e07ec18f28d8a7e0348f132cbbd563fc65a2e755d2aadfa041286c713f8b","has_figures":true,"extraction":"text"},{"ordinal":28,"depth":1,"kind":"rule","number":"6.3","title":"Examples of approved reproductions","body":"Picture from Medieval Extreme ©","page_from":15,"page_to":15,"stable_key":"greaves:6.3","parent_key":"greaves:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2d5d0ded144d44729377a82e71465f24731e61c08a05a0b6d637e8cf0925667c","has_figures":true,"extraction":"text"},{"ordinal":29,"depth":1,"kind":"rule","number":"6.4","title":"Examples of denied reproductions","body":"Fantasy designs and Non-anatomical shape","page_from":15,"page_to":15,"stable_key":"greaves:6.4","parent_key":"greaves:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"54560f24fdee8d94951f718f1a18bc0a3a67206d5ce77f9c74176d0c8632d763","has_figures":true,"extraction":"text"},{"ordinal":30,"depth":0,"kind":"section","number":"7","title":"Brigand Greaves","body":"","page_from":16,"page_to":16,"stable_key":"greaves:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"99f9ab7a417796153651a085184ca476ec3fda9b413d210e9d3c15daac62ea30","has_figures":true,"extraction":"text"},{"ordinal":31,"depth":1,"kind":"rule","number":"7.1","title":"Historical Sources and Datation","body":"Brigand greaves are represented in Europe from 1350 to 1380. They consist of metal plates riveted to a fabric base.\n● Approved for 14th-century and Transitional armors.\n● Denied for 15th-century armors.","page_from":16,"page_to":16,"stable_key":"greaves:7.1","parent_key":"greaves:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a4f81c38d9badb2b238fbd53a0d884a999b62dae4d1ff3f51c6ae917e7e33c3f","has_figures":true,"extraction":"text"},{"ordinal":32,"depth":1,"kind":"rule","number":"7.2","title":"Specific Requirements for Brigand Greaves","body":"● must conform to the general requirements outlined in section 1.3.\n● Must be made of metal plates with the following features:\n● Rectangular shape.\n● Firmly riveted to a fabric base.\n● Plates must be riveted inside the fabric, not outside.\n● Plates must conform to the anatomical shape of the lower leg.","page_from":16,"page_to":16,"stable_key":"greaves:7.2","parent_key":"greaves:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["1.3"],"content_sha256":"8fa0e5853752912943c2ae17c69765552c266486a99e735b086b1e68c547908e","has_figures":true,"extraction":"text"},{"ordinal":33,"depth":1,"kind":"rule","number":"7.3","title":"Examples of approved reproductions","body":"Picture from Forge of Svan ©","page_from":16,"page_to":16,"stable_key":"greaves:7.3","parent_key":"greaves:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"81531eb36849409a04562cc2d6c17cbd16b9da42052a758189b5d764f963dbca","has_figures":true,"extraction":"text"},{"ordinal":34,"depth":1,"kind":"rule","number":"7.4","title":"Examples of denied reproductions","body":"Non-anatomical shape Picture from The Medieval Things ©","page_from":17,"page_to":17,"stable_key":"greaves:7.4","parent_key":"greaves:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"02d0364fd977cb4ffcb3145bc6bf959d40911a1e60599fcec4ea2b7d41712b57","has_figures":true,"extraction":"text"},{"ordinal":35,"depth":0,"kind":"section","number":"8","title":"Other denied items","body":"","page_from":18,"page_to":18,"stable_key":"greaves:8","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ce272185c8636e5304687d103329c5c6101c6630f9b0f27112a98cf54204944f","has_figures":true,"extraction":"text"},{"ordinal":36,"depth":1,"kind":"rule","number":"8.1","title":"4 or 5 panels greaves","body":"This type of greaves is not based on historical sources.\nTo get an approved piece, the 4th plate can be removed. The closest alternative would be the 3-panels greaves.","page_from":18,"page_to":18,"stable_key":"greaves:8.1","parent_key":"greaves:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1dbbbdb89bd3438c2f9d55aa81c7016b351d787b6e46a8a66be9cbd802e34f2b","has_figures":true,"extraction":"text"},{"ordinal":37,"depth":1,"kind":"rule","number":"8.2","title":null,"body":"Examples of denied reproductions:\n\nPicture from The Medieval Things ©","page_from":18,"page_to":18,"stable_key":"greaves:8.2","parent_key":"greaves:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e2f8733546d2b9123127d4b19cfa199ea9744441771631ee33d8d9397104d8f5","has_figures":true,"extraction":"text"},{"ordinal":38,"depth":0,"kind":"note","number":"9","title":"Change log","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nMarch-2025 (V2025.03)\n- Formatting: Overall grammar and formatting\n- add: 8.1: the 4th plate can be removed\n- add: 4.5: Side panels lack shaping, Does not adequately protect the malleolus bone, rule 1.2.\n- add: 3.5: Greaves with riveted ankle part (not based on historical sources)\n\nDecember-2024: -add Document has been created","page_from":19,"page_to":19,"stable_key":"greaves:9","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":["1.2"],"content_sha256":"cce3b84b0954dcb6e555c39040b001d8016d97192ad2b2753b14a2d0d8640ab8","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_historical_version($rules${"governing_body":"Buhurt International","history":"archive-2026-10-06","inventory_key":"authenticity/infractions","version":{"version":"2025.02","title":"Infraction classification and application 2025.02","published_on":null,"effective_from":null,"note":"Title \"Infraction classification and application\"; cover \"VER. 2025.02\"; change log latest \"February - 2025\" (green card rule) after \"December 2024: created\". ","source_url":"https://drive.google.com/file/d/1k0ZoaIIzpVHgzJql2wv3_R4NL-twMXZC/view","source_sha256":"3fd1e811a7a114279be6116094c99ead0f647cd38f82e164f9cc25d7ea26dcb5","retrieved_at":null,"page_count":5,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 1 page(s) without a text layer","content_sha256":"192e3175dfaaa9c9c212ee2b009a4b5b44b242f53f3b34b0290cf8f0ee0d2b6c","detected":{"version":"2025.02","date":null},"confirmed_by":"Claude Code (Pack 22 historical import), read from the archived PDF: cover (OCR of the page image), footers and change log","historical":true,"edition_seq":1,"edition_evidence":"Title \"Infraction classification and application\"; cover \"VER. 2025.02\"; change log latest \"February - 2025\" (green card rule) after \"December 2024: created\". ","source_files":[{"file":"Authenticity/Archive/Infraction classification and application.pdf","archive":"Authenticity","sha256":"3fd1e811a7a114279be6116094c99ead0f647cd38f82e164f9cc25d7ea26dcb5","drive_file_id":"1k0ZoaIIzpVHgzJql2wv3_R4NL-twMXZC"}],"reconciliation":{"ok":true,"errors":[],"warnings":[],"pages":5,"source_lines":93,"assigned_lines":116,"furniture_lines":17,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99704,"provisions":12,"numbered":11,"needs_review":0,"verified":0,"empty_pages":[],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":3,"picture_text_lines":1,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 2025.02\n\nAuthenticity\n\nInfraction classification and application","page_from":1,"page_to":3,"stable_key":"infractions:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"5a51e949ab055f026f2735147aebcf99357a463f1834e7859989c15cd8a081c6","has_figures":true,"extraction":"mixed"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Definition","body":"If we read the current rules, if a fighter enters the list with equipment (armor, shield, or weapon) that fails the authenticity check, he/she receives a green card the fighter enters the list but only once per tournament.\n\nAuthenticity Committee think this rule is too punishing as we understand some fighters are not supported by any authenticity committee members, or have difficulties to purchase armor that match aesthetic standards of Buhurt International. Therefore, we would like to propose both clarification and softening of how authenticity rules are applied.\n\nAuthenticity rules are meant to be followed by all competitors attending Buhurt International tournaments, no matter the category. If a competitor shows up with an armor, shield or weapon that does not comply with the Authenticity rules, he/she risks a penalty.","page_from":3,"page_to":3,"stable_key":"infractions:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2a816decec2c659ca6540b2b97d1b917f6f86c6eb8188fcbb2ece9f9a939b107","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Infraction classification","body":"During Authenticity Check, Authenticity officers will evaluate the entire equipment of competitors before the start of the tournament. Any violation of the Authenticity rules will result in an infraction.\nInfractions can be classified under 3 different levels:","page_from":3,"page_to":3,"stable_key":"infractions:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"b185e7122ba0f92c43395827110be9da00a6fb7c60e0671fcdc18d1fab2e7b75","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"2.1","title":"Minor infraction","body":"It is a small detail not easy to see, and it does not affect the coherence of the whole armor (small traces of rust, hammering marks, little datation difference between 2 parts etc.).","page_from":3,"page_to":3,"stable_key":"infractions:2.1","parent_key":"infractions:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"65621c4deccd4960002be4af4bc963b89be3f2bb98d05da3be1d54f85104f9f8","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"2.2","title":"Moderate Infraction","body":"It is something forbidden by the Authenticity rules (i.e badly designed helmet, over numerous eye bars etc.). Not respecting the rules can't be accepted, thus it is not severe enough to prevent the fighter from entering the list.","page_from":3,"page_to":3,"stable_key":"infractions:2.2","parent_key":"infractions:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b9a295548c8136aafd80a7b305933099ecf3e78bc1b5417813ad994d0dbf5e47","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":1,"kind":"rule","number":"2.3","title":"Major infraction","body":"Fantasy armor or totally inaccurate equipment, that prevent the fighter from entering the list and damage the image of the sport, the teams and Buhurt International.","page_from":3,"page_to":3,"stable_key":"infractions:2.3","parent_key":"infractions:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6fc515e5b9ba0154bec59e4cacdc7cda92046be6e0474c88601c13063f239150","has_figures":false,"extraction":"text"},{"ordinal":7,"depth":0,"kind":"section","number":"3","title":"Application of the rules","body":"● A violation of the authenticity rules will result in a green card. Depending on the rank of tournament, infraction will be applied differently.\n\n● A green card combined with a yellow card will result in a red card and the competitor will be disqualified from the tournament.\n\n● A competitor can receive only 1 green card per tournament, no matter how many infractions they have.","page_from":4,"page_to":4,"stable_key":"infractions:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"fab5e8bd4b98cc45aa13c1e4257d68f710917ffac0c75c5798450ff6eac1ba00","has_figures":false,"extraction":"text"},{"ordinal":8,"depth":1,"kind":"rule","number":"3.1","title":"Source","body":"No authenticity check required.\nAuthenticity members on site will be able to give advice and guidance.","page_from":4,"page_to":4,"stable_key":"infractions:3.1","parent_key":"infractions:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5a6e64701bb448476d1d46a9ea6a22106826049387e0d935aca5f04164401ab1","has_figures":false,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"3.2","title":"Classic","body":"Authenticity check is mandatory prior to the start of the tournament.\nA competitor is allowed to enter the list if they respects the following cumulative criterias.\n● Have no more than 3 minors infraction (if they have 4 or more, they will receive a green card).\n● Have no more than 1 moderate infraction (if they have 2 or more, they will receive a green card.\n● Have no major infraction.","page_from":4,"page_to":4,"stable_key":"infractions:3.2","parent_key":"infractions:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9cf36949de42451be1fc1d0fae10220ca8069b3968ec88f7b75fbf8f1b062b9a","has_figures":false,"extraction":"text"},{"ordinal":10,"depth":1,"kind":"rule","number":"3.3","title":"Regional","body":"Authenticity check is mandatory prior to the start of the tournament.\nA competitor is allowed to enter the list if they respects the following cumulative criterias.\n● Have no more than 2 minors infraction, if you have 3 or more, then they will receive a green card.\n● Have no moderate infraction. If they have 1 or more, they will receive a green card.\n● Have no major infraction.","page_from":4,"page_to":4,"stable_key":"infractions:3.3","parent_key":"infractions:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9ab34a74c78765b735bc0afbac8135f8a3c400de427d30730e7eb833a587b634","has_figures":false,"extraction":"text"},{"ordinal":11,"depth":1,"kind":"rule","number":"3.4","title":"Conference","body":"Authenticity check is mandatory prior to the start of the tournament.\nA competitor is allowed to enter the list if they respects the following cumulative criterias.\n● Have no more than 1 minor infraction, if you have 2 or more, then they will receive a green card.\n● Have no moderate infraction.\n● Have no major infraction.\n\nNote: as an exceptional measure, for season 2025, tournaments of Conference level will be considered as Regional regarding Authenticity rules. It means a competitor with 1 moderate infraction will be allowed to fight, but will receive a green card.","page_from":4,"page_to":4,"stable_key":"infractions:3.4","parent_key":"infractions:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0b72676880bb7690b08484300ced742cc0f2d2d0cd5dcd844a3deff85400efef","has_figures":false,"extraction":"text"},{"ordinal":12,"depth":0,"kind":"note","number":"4","title":"Change log","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nFebruary - 2025:\n- Replaced: 1. (After vote) introducing the green card rule\n- Replaced: 2. Members | Officers || Fighters | Competitors\n- Add: 2. Any violation of the Authenticity rules will result in an infraction\n- Replaced: 3. violation breach of | greenYellow card remains the sanction for Aany” with “A violation of\n- Rephrased: 3. (After vote) to clarify the green card rule.\n- Add: 3.3 If they have 1 or more, they will receive a green card.\n- Add: 3.4: Note\n\nDecember 2024:\n-add Document has been created","page_from":5,"page_to":5,"stable_key":"infractions:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"a66c5bb4a0e838b8a845fe378268e9a5696bce02c36a0d08b4bc54f76491f9da","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_historical_version($rules${"governing_body":"Buhurt International","history":"archive-2026-10-06","inventory_key":"authenticity/infractions","version":{"version":"26.1","title":"Infraction classification and application 26.1","published_on":null,"effective_from":null,"note":"Title \"Infraction classification and application\"; cover \"VER. 26.1\", footer \"Infractions Classification and Application V. 26.1\"; change log \"January - 2026 (V. 26.1)\" above the February-2025 entries of edition 2025.02. Older than the current 26.4.","source_url":"https://drive.google.com/file/d/1o0qSAF7ZO4VXES-H2-vR3Szy9F_JAXdr/view","source_sha256":"e296e2023efc8aa32339ecd44a0f72adbf92cc8817b27d18ee5d333a01f4a852","retrieved_at":null,"page_count":5,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 5 page(s) without a text layer","content_sha256":"1f07f7493110b35a990e826d88485e8320eeaf4272b412507cf46b1ae334edcb","detected":{"version":"26.1","date":null},"confirmed_by":"Claude Code (Pack 22 historical import), read from the archived PDF: cover (OCR of the page image), footers and change log","historical":true,"edition_seq":2,"edition_evidence":"Title \"Infraction classification and application\"; cover \"VER. 26.1\", footer \"Infractions Classification and Application V. 26.1\"; change log \"January - 2026 (V. 26.1)\" above the February-2025 entries of edition 2025.02. Older than the current 26.4.","source_files":[{"file":"Authenticity/Archive/Infractions Classification and Application.pdf","archive":"Authenticity","sha256":"e296e2023efc8aa32339ecd44a0f72adbf92cc8817b27d18ee5d333a01f4a852","drive_file_id":"1o0qSAF7ZO4VXES-H2-vR3Szy9F_JAXdr"}],"reconciliation":{"ok":true,"errors":[],"warnings":[],"pages":5,"source_lines":78,"assigned_lines":109,"furniture_lines":10,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99672,"provisions":12,"numbered":11,"needs_review":0,"verified":0,"empty_pages":[],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":78,"picture_text_lines":1,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 26.1\n\nAuthenticity","page_from":1,"page_to":1,"stable_key":"infractions:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"b3cd075ee5755a5513c4f726dcdef54be200038fbb1071b0c1257f4b18b0c3f9","has_figures":true,"extraction":"ocr"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Definition","body":"Authenticity rules are meant to be followed by all competitors attending Buhurt International tournaments, no matter the category. If a competitor shows up with an armor, shield or weapon that does not comply with the Authenticity rules, he/she risks a penalty.","page_from":3,"page_to":3,"stable_key":"infractions:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2d7b293b69b1334db19526e86381ac857d05a567da947a4ca235ab6eff1c619e","has_figures":false,"extraction":"ocr"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Infraction Classification","body":"During Authenticity Check, Authenticity officers will evaluate the entire equipment of competitors before the start of the tournament. Any violation of the Authenticity rules will result in an infraction. Infractions can be classified under 3 different levels:","page_from":3,"page_to":3,"stable_key":"infractions:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"e08f51ed6a1a5538806971181c3c57e85637965f8dcb7310b51dd7d083232f95","has_figures":false,"extraction":"ocr"},{"ordinal":4,"depth":1,"kind":"rule","number":"2.1","title":"Minor infraction","body":"It is a small detail not easy to see, and it does not affect the coherence of the whole armor (small traces of rust, hammering marks, little datation difference between 2 parts etc.).","page_from":3,"page_to":3,"stable_key":"infractions:2.1","parent_key":"infractions:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"65621c4deccd4960002be4af4bc963b89be3f2bb98d05da3be1d54f85104f9f8","has_figures":false,"extraction":"ocr"},{"ordinal":5,"depth":1,"kind":"rule","number":"2.2","title":"Moderate Infraction","body":"It is something forbidden by the Authenticity rules (i.e badly designed helmet, over numerous eye bars etc.). Not respecting the rules can't be accepted, thus it is not severe enough to prevent the fighter from entering the list.","page_from":3,"page_to":3,"stable_key":"infractions:2.2","parent_key":"infractions:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b9a295548c8136aafd80a7b305933099ecf3e78bc1b5417813ad994d0dbf5e47","has_figures":false,"extraction":"ocr"},{"ordinal":6,"depth":1,"kind":"rule","number":"2.3","title":"Major infraction","body":"Fantasy armor or totally inaccurate equipment, that prevent the fighter from entering the list and damage the image of the sport, the teams and Buhurt International.","page_from":3,"page_to":3,"stable_key":"infractions:2.3","parent_key":"infractions:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6fc515e5b9ba0154bec59e4cacdc7cda92046be6e0474c88601c13063f239150","has_figures":false,"extraction":"ocr"},{"ordinal":7,"depth":0,"kind":"section","number":"3","title":"Application of the Rules","body":"A violation of the authenticity rules will result in a green card. Depending on the rank of tournament, infraction will be applied differently.\n\nA green card combined with a yellow card will result in a red card and the competitor will be disqualified from the tournament.\n\nA competitor can receive only 1 green card per tournament, no matter how many infractions they have.","page_from":4,"page_to":4,"stable_key":"infractions:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7d20383598d46d9a34458eb0afe34ddf3cdf1c3c185c9a1ca9b0251328a69f4f","has_figures":false,"extraction":"ocr"},{"ordinal":8,"depth":1,"kind":"rule","number":"3.1","title":"Source","body":"No authenticity check required.\nAuthenticity members on site will be able to give advice and guidance.","page_from":4,"page_to":4,"stable_key":"infractions:3.1","parent_key":"infractions:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5a6e64701bb448476d1d46a9ea6a22106826049387e0d935aca5f04164401ab1","has_figures":false,"extraction":"ocr"},{"ordinal":9,"depth":1,"kind":"rule","number":"3.2","title":"Classic","body":"Authenticity check is mandatory prior to the start of the tournament.\nA competitor is allowed to enter the list if they respect the following cumulative criterias:\n\n● Have no more than 3 minors infraction (if they have 4 or more, they will receive a green card).\n● Have no more than 1 moderate infraction (if they have 2 or more, they will receive a green card.\n● Have no major infraction.","page_from":4,"page_to":4,"stable_key":"infractions:3.2","parent_key":"infractions:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"61ba2b621db23b295f260c50cfe5f3720280f06b1413f34d68eee1c4a9a32a1d","has_figures":false,"extraction":"ocr"},{"ordinal":10,"depth":1,"kind":"rule","number":"3.3","title":"Regional","body":"Authenticity check is mandatory prior to the start of the tournament.\n\nA competitor is allowed to enter the list if they respect the following cumulative criterias.\n● Have no more than 2 minors infraction, if you have 3 or more, then they will receive a green card.\n● Have no moderate infraction. If they have 1 or more, they will receive a green card.\n● Have no major infraction.","page_from":4,"page_to":4,"stable_key":"infractions:3.3","parent_key":"infractions:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"cf319e3a308efa5369b065c6bbfde879b46a3d98c58a7a9836dee4fd3a93330f","has_figures":false,"extraction":"ocr"},{"ordinal":11,"depth":1,"kind":"rule","number":"3.4","title":"Conference","body":"Authenticity check is mandatory prior to the start of the tournament.\n\nA competitor is allowed to enter the list if they respect the following cumulative criterias.\n● Have no more than 1 minor infraction, if you have 2 or more, then they will receive a green card.\n● Have no moderate infraction.\n● Have no major infraction.\n\nNote: as an exceptional measure, for season 2025, tournaments of Conference level will be considered as Regional regarding Authenticity rules. It means a competitor with 1 moderate infraction will be allowed to fight, but will receive a green card.","page_from":4,"page_to":4,"stable_key":"infractions:3.4","parent_key":"infractions:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1c7824db89d461f22b0d14efa423cae580a92f2d4f68934358f26d7f6a4823d0","has_figures":false,"extraction":"ocr"},{"ordinal":12,"depth":0,"kind":"note","number":"4","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nJanuary - 2026 (V. 26.1) Formatting redone for consistency and readability. Except points listed below, no content changes.\n\nSuppression:\n- 2 first paragraphs of “2. Definition” as they were outdated.\n\nFebruary - 2025:\n\n- Replaced: 1. (After vote) introducing the green card rule\n\n- Replaced: 2. Members | Officers || Fighters | Competitors\n\n- Add: 2. Any violation of the Authenticity rules will result in an infraction\n\n- Replaced: 3. violation breach of | greenYellow card remains the sanction for Aany” with “A violation of\n\n- Rephrased: 3. (After vote) to clarify the green card rule.\n\n- Add: 3.3 If they have 1 or more, they will receive a green card.\n\n- Add: 3.4: Note\n\nDecember 2024:\n-add Document has been created","page_from":5,"page_to":5,"stable_key":"infractions:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"5af5ad783689373471b8bf9b0e64effdf77e9e1d22a6b20b557a7ef8d4d852f5","has_figures":false,"extraction":"ocr"}]}$rules$::jsonb);
select private.rules_import_historical_version($rules${"governing_body":"Buhurt International","history":"archive-2026-10-06","inventory_key":"authenticity/klappvisors","version":{"version":"2025.03","title":"Klappvisors 2025.03","published_on":null,"effective_from":null,"note":"Title \"Klappvisors\"; cover \"VER. 2025.03\"; change log latest \"March-2025\" after \"11-Nov-2024: created\". Older than the current 26.1.","source_url":"https://drive.google.com/file/d/19ZeGQzmqj6sGHY5gYph6rQ9hmvoRFYDc/view","source_sha256":"1b6eb01a6244c99ac28227a15dbc4a9848598cf79dd563511d99f51fa2ced30b","retrieved_at":null,"page_count":12,"extractor":"pdftotext unknown -layout -enc UTF-8","content_sha256":"578541fe7a2b1d8e5716a1c0b1802a7b8c63b0be3ecd6c3162de9609f7ab07b8","detected":{"version":null,"date":null},"confirmed_by":"Claude Code (Pack 22 historical import), read from the archived PDF: cover (OCR of the page image), footers and change log","historical":true,"edition_seq":1,"edition_evidence":"Title \"Klappvisors\"; cover \"VER. 2025.03\"; change log latest \"March-2025\" after \"11-Nov-2024: created\". Older than the current 26.1.","source_files":[{"file":"Authenticity/Archive/Klappvisors.pdf","archive":"Authenticity","sha256":"1b6eb01a6244c99ac28227a15dbc4a9848598cf79dd563511d99f51fa2ced30b","drive_file_id":"19ZeGQzmqj6sGHY5gYph6rQ9hmvoRFYDc"}],"reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1"],"pages":12,"source_lines":119,"assigned_lines":213,"furniture_lines":26,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99838,"provisions":16,"numbered":14,"needs_review":0,"verified":0,"empty_pages":[1],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":0,"picture_text_lines":0,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"klappvisors:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"note","number":null,"title":null,"body":"Helmet Klappvisors","page_from":2,"page_to":2,"stable_key":"klappvisors:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"8d149b76f6f8148cd8ab694da1c296a9c1edef63e12b6c13fbe25297ee443020","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":0,"kind":"section","number":"1","title":"Definition","body":"● Klappvisor Bascinet is a medieval helmet that originated in the 14th century.\n\"Klappvisor\" is German and translates to \"folding visor.\" The single brow-mounted hinge is a distinctive feature of early bascinet visor designs. These bascinet visors were often low profile to fit underneath a great helm, but would also serve as a primary defense on their own.\n● Klappvisor uses a solid metal visor to protect the face, attached on the forehead by a piece of metal, the “spoon”.\n● Klappvisor was used from 1340 to 1400, mainly in Germany and Italy.\n● Klappvisor is approved for 14th century and Transitional armors.\n● Klappvisor is denied for 15th century armors.","page_from":3,"page_to":3,"stable_key":"klappvisors:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"003a02ccf064ae4e8d740f71d0514c4a3cac850a9d06f02abd2281a30d7f8f25","has_figures":true,"extraction":"text"},{"ordinal":4,"depth":0,"kind":"section","number":"2","title":"Historical sources and datation","body":"","page_from":4,"page_to":4,"stable_key":"klappvisors:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"20e6c835010eb8c701a15af9df6bf96f8575b5e4e79f43a96095268e39809372","has_figures":true,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"2.1","title":"German-Style Klappvisors","body":"A B\n\nC D\n\nA:“Sitten Klappvisor” - 1390 - Switzerland, Picture from Musées cantonaux du Valais, Sion(Jean-Yves Glassey, Martigny) © B: “Bavarian Klappvisor” - unknown datation, probably late 14th cent.- Bavarian Army Museum, Munich, Germany C: Nuremberg Museum - 1370/1380 - Germany D: Coburg helmet - 1380/1390 - Germany\n\nBerlin Museum - 1350 - Germany","page_from":4,"page_to":5,"stable_key":"klappvisors:2.1","parent_key":"klappvisors:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0497599e249950d49009bed480005383f43d06702bebcb34aa8d2362f8480506","has_figures":true,"extraction":"text"},{"ordinal":6,"depth":1,"kind":"rule","number":"2.2","title":"Italian style Klappvisor","body":"A B\n\nA: 14th century (datation unknown) - Italy B: 1350 - Italy C: Milan Klappvisor, Museo Stibbert,1390/1400 - Italy\n\nC","page_from":6,"page_to":6,"stable_key":"klappvisors:2.2","parent_key":"klappvisors:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"644594b755776f76853793524caf8bcc528c286d538be29d131d6153c92f7e80","has_figures":true,"extraction":"text"},{"ordinal":7,"depth":1,"kind":"rule","number":"2.3","title":"Other style Klappvisor","body":"1375 - Netherlands B\n\nLeeds Armouries - 1350/1380 - England","page_from":7,"page_to":7,"stable_key":"klappvisors:2.3","parent_key":"klappvisors:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8d65b8ee9bbf26b96ee5ecff32c420610c97bec440b1c38223dc76e5d31853ff","has_figures":true,"extraction":"text"},{"ordinal":8,"depth":0,"kind":"section","number":"3","title":"Requirements","body":"","page_from":8,"page_to":8,"stable_key":"klappvisors:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"475f60c10a2f0b6b9f5aaf68ce12eb9a12457aeafff595062e0babfbd5af33a1","has_figures":false,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"3.1","title":"General Requirements","body":"● Reproductions must closely resemble the appearance and proportions of a Klappvisor source.\n● Any metal part of the helmet must conform to the Armors and weapons Aesthetics and decorations document.\n● Any textile or leather part of the helmet must conform to the Textiles and Leather document.","page_from":8,"page_to":8,"stable_key":"klappvisors:3.1","parent_key":"klappvisors:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b422756e448963d7f97ca042b8af4bf556db4b7a92d88396ed031a22d09f7e28","has_figures":false,"extraction":"text"},{"ordinal":10,"depth":1,"kind":"rule","number":"3.2","title":"Visor Requirements","body":"● Visor must not be too long or too short, it must respect the proportions of historical sources.\n● The hinge must be reproduced as per historical sources.\n● It is allowed to weld the hinge. Welded hinges must resemble a functional hinge.\n● It is allowed to weld the visor down. Welded visor must resemble a functional removable visor.\n● It is allowed to add a metal plate to protect the throat. Such a plate must be strong enough to endure full contact fight and must be concealed under the aventail.\n● A leather strap can be used to secure the visor down.\n● Breath holes should be round and must not exceed a diameter of 10mm. Breath holes must not be so numerous that they compromise the helm’s structural integrity. It is acceptable to mirror breath holes to both sides.\n● Breath holes of another shape must be documented by historical sources to be allowed.","page_from":8,"page_to":8,"stable_key":"klappvisors:3.2","parent_key":"klappvisors:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3bea7ae335dc8c711dedb1da8cd0c5106c097c1e32f86a2cc76b8d1d7d6bed4f","has_figures":false,"extraction":"text"},{"ordinal":11,"depth":1,"kind":"rule","number":"3.3","title":"Eye-slots","body":"● Eye slots should resemble sources for the visor.\n● Eye slots should not exceed 25mm tall to prevent any injury.\n● Klappvisor with 2 eye slots are allowed to add up to two (2) safety eye bars per eye slot.\n● Klappvisor may have integrated Eye bars. Such eye bars must be made accordingly with historical sources, in terms of proportion, numbers and aesthetic.\n● Eye bars must conform to the Eye bars rules document.","page_from":8,"page_to":8,"stable_key":"klappvisors:3.3","parent_key":"klappvisors:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3fba0753d8e850d8b4d84d73a435ec63fba60095313080d2a3d2c36006886811","has_figures":false,"extraction":"text"},{"ordinal":12,"depth":1,"kind":"rule","number":"3.4","title":"Aventail","body":"● Klappvisors must be worn with chainmail aventails, fabric aventails, or scales aventails.\n● Aventails must conform to the Aventails document.\n● Aventails must be attached to the bascinet by a system of leather and vervelles.\n\n● The aventail must be fastened down to the edge of a padded pelerine attached to the helmet liner.\n● Protective plates covering the cervical spine must be hidden under the aventail.","page_from":8,"page_to":9,"stable_key":"klappvisors:3.4","parent_key":"klappvisors:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4d70e57423609d6f637f3b0a6ce85c4337a8640a9ec73887b06cfa708f463883","has_figures":false,"extraction":"text"},{"ordinal":13,"depth":1,"kind":"rule","number":"3.5","title":"Others","body":"● Klappvisors may be decorated in the spirit of medieval styles, such as orle, torse, decorated aventails (with cooper/brass chainmail rings), vervelle covers and coat of arms badges etc.\n● Such decoration must be made in coherence with historical sources.\n● Using modern and/or offensive imagery and slogans is prohibited.","page_from":9,"page_to":9,"stable_key":"klappvisors:3.5","parent_key":"klappvisors:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"cdb4480281d9a6dca523814cb46d2e83aedf801ec223d8135833a008eb0e0d58","has_figures":false,"extraction":"text"},{"ordinal":14,"depth":0,"kind":"section","number":"4","title":"Approved Reproductions","body":"Pictures from The Medieval Things ©\n\nPictures from Medieval Extreme ©","page_from":10,"page_to":10,"stable_key":"klappvisors:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d808bd90218a2191faa1ae81be69c0e227518926782d293e945f994239156535","has_figures":true,"extraction":"text"},{"ordinal":15,"depth":0,"kind":"section","number":"5","title":"Denied Reproductions","body":"Integrated eye bars out of historical proportions Visor not based on historical sources + incomplete aventail\n\nPictures from The Medieval Things ©","page_from":11,"page_to":11,"stable_key":"klappvisors:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"41b32612988d4ae6543b8735c11e722eca0f47e18a0b03c033d33da6f7989b01","has_figures":true,"extraction":"text"},{"ordinal":16,"depth":0,"kind":"note","number":"6","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\nMarch-2025:\nFormatting: Grammar and Formatting Add: 3.3 Klappvisor may have integrated Eye bars. Such eye bars must be made accordingly with historical sources, in terms of proportion, numbers and aesthetic.\n\n11-Nov-2024: -Add Document has been created","page_from":12,"page_to":12,"stable_key":"klappvisors:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"c3480750c6900c180f5a914cd0722d375823697e4f86ae516de4934f8be90159","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_historical_version($rules${"governing_body":"Buhurt International","history":"archive-2026-10-06","inventory_key":"authenticity/nasals-and-breteches","version":{"version":"2025.03","title":"Helmet - Nasal and Breteche 2025.03","published_on":null,"effective_from":null,"note":"Title \"Helmet - Nasal and Breteche\" (the current document is \"Nasal and Breteche\"); cover \"VER. 2025.03\"; change log latest \"February-2025 (2025.03)\". Older than the current 26.1.","source_url":"https://drive.google.com/file/d/1wVY-Rub5qPGcno4tRZj9xV5YzO6t-Mt2/view","source_sha256":"09824e8d5387146c5b4b87506fea3e33dadedd3d7d47970c396018f1125fe0ad","retrieved_at":null,"page_count":11,"extractor":"pdftotext unknown -layout -enc UTF-8","content_sha256":"3c2473566a0dec5b2df6bc061a32a42f77451de57e68122a2b7787183adc0af3","detected":{"version":null,"date":null},"confirmed_by":"Claude Code (Pack 22 historical import), read from the archived PDF: cover (OCR of the page image), footers and change log","historical":true,"edition_seq":1,"edition_evidence":"Title \"Helmet - Nasal and Breteche\" (the current document is \"Nasal and Breteche\"); cover \"VER. 2025.03\"; change log latest \"February-2025 (2025.03)\". Older than the current 26.1.","source_files":[{"file":"Authenticity/Archive/Nasal and Breteche.pdf","archive":"Authenticity","sha256":"09824e8d5387146c5b4b87506fea3e33dadedd3d7d47970c396018f1125fe0ad","drive_file_id":"1wVY-Rub5qPGcno4tRZj9xV5YzO6t-Mt2"}],"reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1"],"pages":11,"source_lines":109,"assigned_lines":210,"furniture_lines":23,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99824,"provisions":15,"numbered":13,"needs_review":0,"verified":0,"empty_pages":[1],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":0,"picture_text_lines":0,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"nasals-and-breteches:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"note","number":null,"title":null,"body":"Helmet Nasal and Breteche","page_from":2,"page_to":2,"stable_key":"nasals-and-breteches:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"5d2256007879abae11edb7bdb5777339f1cb70aa89d099fdb959584a18e346d9","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":0,"kind":"section","number":"1","title":"Definition","body":"● Nasal and breteche bascinets are medieval helmets that originated in the early 14th century. They are an evolution of simple bascinets worn with chainmail. The chainmail aventail is attached to the front of the helmet to increase its face protection.\n● Nasal bascinet uses a solid metal nasal to protect the nose, attached on the forehead by a piece of metal, the “spoon”.\n● Breteche bascinet uses chainmail to protect the nose, attached on the forehead by a piece of metal, the “cross”.\n● Both helmets were used from 1340 to the late 14th century in Western Europe.\n● Nasal and breteche bascinets are approved for 14th century and Transitional armors.\n● Nasal and breteche bascinets are denied for 15th century armors.","page_from":3,"page_to":3,"stable_key":"nasals-and-breteches:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8105ad57b217dc3461a3ae90f77052b1801fcaaa3a35c245ba63bb20c7d71087","has_figures":true,"extraction":"text"},{"ordinal":4,"depth":0,"kind":"section","number":"2","title":"Historical sources and datation","body":"","page_from":4,"page_to":4,"stable_key":"nasals-and-breteches:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"20e6c835010eb8c701a15af9df6bf96f8575b5e4e79f43a96095268e39809372","has_figures":true,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"2.1","title":"Nasal Helmet","body":"A B\n\nC\n\nD\n\nA: Second half of the 14th century (datation unknown) - France B: BKE Cod. 339 Der Passionstraktat des Nikolaus Schulmeister - 1396 - Switzerland C: Günther XXI. von Schwarzburg - 1349 - Germany D: Galeotto Malaspina - 1367 - Italy","page_from":4,"page_to":4,"stable_key":"nasals-and-breteches:2.1","parent_key":"nasals-and-breteches:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"31c2bd00a61a93662914df3617bb044a39990d1204d0a7d2a631bc72ce994e39","has_figures":true,"extraction":"text"},{"ordinal":6,"depth":1,"kind":"rule","number":"2.2","title":"Breteche Helmet","body":"A A\n\nB C\n\nA: Museo Stibbert, Florence - Second half of the 14th century (datation unknown) - Italy * B: Doge’s Palace, Venice - 1350/1370 - Italy C: Klosterneuburg Stiftsmuseum - 1335/1340 - Austria\n\n* Note: this artifact may not be 100% original, as the founder of the museum commissioned some fiorentina armorers in 1881 to adapt and repair the skull, to create the cross and the chainmail (maybe original pieces of mail were patched up).","page_from":5,"page_to":5,"stable_key":"nasals-and-breteches:2.2","parent_key":"nasals-and-breteches:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5008a2114cc7ddaa728d0e7ef3ed9718275c2cb984829d7bfdd8851185b42034","has_figures":true,"extraction":"text"},{"ordinal":7,"depth":0,"kind":"section","number":"3","title":"Requirements","body":"","page_from":6,"page_to":6,"stable_key":"nasals-and-breteches:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"475f60c10a2f0b6b9f5aaf68ce12eb9a12457aeafff595062e0babfbd5af33a1","has_figures":false,"extraction":"text"},{"ordinal":8,"depth":1,"kind":"rule","number":"3.1","title":"General Requirements","body":"● Reproductions must closely resemble the appearance and proportions of a Klappvisor source.\n● Any metal part of the helmet must conform to the Armors and weapons Aesthetics and decorations document.\n● Any textile or leather part of the helmet must conform to the Textiles and Leather document.","page_from":6,"page_to":6,"stable_key":"nasals-and-breteches:3.1","parent_key":"nasals-and-breteches:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b422756e448963d7f97ca042b8af4bf556db4b7a92d88396ed031a22d09f7e28","has_figures":false,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"3.2","title":"Visor Requirements","body":"● Visor must be made of metal grill or plates, concealed under chainmail.\n● Chainmail must be properly attached to the visor with metal, leather or fabric thread.\n● Visor must not be too long or too short and respect the proportions of historical sources.\n● Nasal helmet visor bottom line must end between nose and chin.\n● The fixation system must be reproduced as per historical sources (“spoon” or “cross”).\n● It is allowed to add a metal plate to protect the throat. Such a plate must be strong enough to endure full contact fight and must be concealed under the aventail.","page_from":6,"page_to":6,"stable_key":"nasals-and-breteches:3.2","parent_key":"nasals-and-breteches:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ff299944d613d6f79c54307080cfad174a6f66c7dbf5cd2b22bed49e1661205e","has_figures":false,"extraction":"text"},{"ordinal":10,"depth":1,"kind":"rule","number":"3.3","title":"Eye-slots","body":"● Eye slots should resemble sources for the visor.\n● Eye slots should not exceed 25mm tall to prevent any injury.\n● It is allowed to add up to two (2) safety eyebars per eye-slot.\n● Eyebars must conform to the Eyebars rules document.","page_from":6,"page_to":6,"stable_key":"nasals-and-breteches:3.3","parent_key":"nasals-and-breteches:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"80422a1beca76c41aba3af20882a462d88f5ba85be9b6238028ccbbae0c513f7","has_figures":false,"extraction":"text"},{"ordinal":11,"depth":1,"kind":"rule","number":"3.4","title":"Aventail","body":"● Nasal and breteche helmets must be worn with chainmail aventails. Fabric or scales aventails are not allowed.\n● Aventails must conform to the Aventails document.\n● Aventails must be attached to the bascinet by a suspension system made of vervelles and leather.\n● The aventail must be fastened down to the edge of a padded pelerine attached to the helmet liner.\n● Protective plates covering the cervical spine must be hidden under the aventail.","page_from":6,"page_to":6,"stable_key":"nasals-and-breteches:3.4","parent_key":"nasals-and-breteches:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"576183ad211de177a5f8cba8c0a55e28d6afd68128236e34ae44fe1e76c6c516","has_figures":false,"extraction":"text"},{"ordinal":12,"depth":1,"kind":"rule","number":"3.5","title":"Others","body":"● Nasal and breteche helmets may be decorated in the spirit of medieval styles, such as orle, torse, decorated aventails (with copper/brass chainmail rings), vervelle covers and coat of arms badges etc.\n● Such decoration must be made in coherence with historical sources.\n\n● Using modern and/or offensive imagery and slogans is prohibited.","page_from":6,"page_to":7,"stable_key":"nasals-and-breteches:3.5","parent_key":"nasals-and-breteches:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3fac3734854cbd8eccede36793e9fe5df1fc93ff7fac0702366122e2321c3cef","has_figures":false,"extraction":"text"},{"ordinal":13,"depth":0,"kind":"section","number":"4","title":"Approved Reproductions","body":"Example of approved welded spoon\n\nPictures from The Medieval Things ©\n\nPicture from M. Leclere ©\n\nPictures from The Medieval Things ©","page_from":8,"page_to":9,"stable_key":"nasals-and-breteches:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c7f1714522c85dea1d36cdb6937b3521add4eef2ed6f14b69ed06b60695fa97f","has_figures":true,"extraction":"text"},{"ordinal":14,"depth":0,"kind":"section","number":"5","title":"Denied Reproductions","body":"Eyebars not painted in black\n\nChainmail not attached properly\n\n=>\n\n<= Aventail mixing fabric and chainmail\n\nPictures from The Medieval Things ©","page_from":10,"page_to":10,"stable_key":"nasals-and-breteches:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8627fb580c2f4f6fa7ed1fcb5b35fd97fa09feacf970f3fa5e5bdc9fb9607eee","has_figures":true,"extraction":"text"},{"ordinal":15,"depth":0,"kind":"note","number":"6","title":"Change log","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nFebruary-2025 (2025.03) Formatting: grammar and formatting\n\nDecember-2024: -Add Document has been created","page_from":11,"page_to":11,"stable_key":"nasals-and-breteches:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"5cb9c6561e0592e10cd2b0515b8efd3f9f08b00156a188bf0acfdde2fd600c0c","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_historical_version($rules${"governing_body":"Buhurt International","history":"archive-2026-10-06","inventory_key":"authenticity/neck-protection","version":{"version":"2025.02","title":"Neck Protection 2025.02","published_on":null,"effective_from":null,"note":"Title \"Neck Protection\"; cover \"VER. 2025.02\"; change log latest \"February-2025 (V2025.02)\". Older than the current 26.1.","source_url":"https://drive.google.com/file/d/1ff09KZ8se0qxnK9cZepyUQdiDD7dgdRW/view","source_sha256":"33574884f8962d1f396bcdc437e63667cc6ce14557915838ab1bdd75f83b8c99","retrieved_at":null,"page_count":12,"extractor":"pdftotext unknown -layout -enc UTF-8","content_sha256":"ca42566fa29c8b13846b859073b4c482048c6dd6d4dfd1118776e059ed2dab3e","detected":{"version":null,"date":null},"confirmed_by":"Claude Code (Pack 22 historical import), read from the archived PDF: cover (OCR of the page image), footers and change log","historical":true,"edition_seq":1,"edition_evidence":"Title \"Neck Protection\"; cover \"VER. 2025.02\"; change log latest \"February-2025 (V2025.02)\". Older than the current 26.1.","source_files":[{"file":"Authenticity/Archive/Neck Protection.pdf","archive":"Authenticity","sha256":"33574884f8962d1f396bcdc437e63667cc6ce14557915838ab1bdd75f83b8c99","drive_file_id":"1ff09KZ8se0qxnK9cZepyUQdiDD7dgdRW"}],"reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1","1 provision(s) need review against the official document"],"pages":12,"source_lines":157,"assigned_lines":249,"furniture_lines":37,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99884,"provisions":27,"numbered":25,"needs_review":1,"verified":0,"empty_pages":[1],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":0,"picture_text_lines":0,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"neck-protection:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"note","number":null,"title":null,"body":"Neck Protection","page_from":2,"page_to":2,"stable_key":"neck-protection:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"818fa5c26e47037a9b3cfdf8b8ec5d30efd3fbad26caff2287e0242d8d88233c","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":0,"kind":"section","number":"1","title":"Definition and general requirements","body":"","page_from":3,"page_to":3,"stable_key":"neck-protection:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"df9d4b4971cd1ada36b96ec4e6602cd5f968c25814a104728b68a69b7ffb6242","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"1.1","title":"Definition","body":"● Neck protection is the term to describe all historical and adapted protection for neck, shoulders and throat. In buhurt, those protections are mandatory to ensure the safety of competitors.\n● Neck protection can be worn upon the aventail or not, depending on the type of protection.","page_from":3,"page_to":3,"stable_key":"neck-protection:1.1","parent_key":"neck-protection:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a52e3dab98fbe07d1f411ec7e2ee444c0129859e222354ae7529120bf2033533","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"1.2","title":"Neck protection description","body":"Neck protection can be:\n● Neck shield : Metal plates that replicate the shape of a heater shield. It is allowed to be worn upon the aventail.\n● Lobster tail : Articulated metal plates designed as a lobster tail. It is allowed to be worn upon the aventail.\n● Gorget : A gorget is a plate protection that covers the neck, shoulders and throat. It is allowed to be visible and worn with the proper armor set.\n● Concealed neck plates : Metal plates directly sewn to the gambeson or the aventail.\nThey must be hidden under the aventail.","page_from":3,"page_to":3,"stable_key":"neck-protection:1.2","parent_key":"neck-protection:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f82fd1ddb246e91952005b407f39f1a92647acc8a55382707d0f97253d8de283","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":1,"kind":"rule","number":"1.3","title":"General requirements","body":"All types of neck protection must respect the following requirements :\n● Be based on historical sources if they are visible.\n● Be concealed if they are not based on historical sources.\n● Be firmly attached to prevent any breakage and maintain a high level of protection in any case.\n● Any metal part of the neck protection must conform to the Armors and weapons Aesthetics and decorations document.\n● Any textile or leather part of the neck protection must conform to the Textiles and Leather document.","page_from":3,"page_to":3,"stable_key":"neck-protection:1.3","parent_key":"neck-protection:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b99e5ca3e419d05b3d242e3d4d5ad261b6e7c10ae33b7265f03e598705c64b9c","has_figures":false,"extraction":"text"},{"ordinal":7,"depth":1,"kind":"rule","number":"1.4","title":"Recommendations","body":"● It is recommended to wear a protection sewn to your gambeson. This protection covers your neck no matter the position of your helmet (bent or twisted during wrestling).\n● Protections relying on your aventail can be damaged during fights and may be removed if not firmly attached to the aventail. It is recommended to ensure those protections are well attached and will not be removed easily.","page_from":3,"page_to":3,"stable_key":"neck-protection:1.4","parent_key":"neck-protection:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ef208189e5654b47d5c136b7b55484df1e726ea20f157a6dce4b1ce61ac6e792","has_figures":false,"extraction":"text"},{"ordinal":8,"depth":0,"kind":"section","number":"2","title":"Neck shield","body":"","page_from":4,"page_to":4,"stable_key":"neck-protection:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c5e3b26af95b9b5310be666f727ca46eefc2629ad75c3a0720d04d7f4a961531","has_figures":true,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"2.1","title":"Historical sources and datation","body":"● Miniatures sometimes display a small shield attached to the aventail, mainly during the 14th century. Those shields were supposed to show the heraldry of the wearer. Thus, as neck protection is mandatory in our sport, such neck shields can be allowed to be worn on the aventail.\n● They are approved for 14th century, Transitional and 15th century armors.\n\nBook of Hours - 1320 - The Netherlands","page_from":4,"page_to":4,"stable_key":"neck-protection:2.1","parent_key":"neck-protection:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"94cfd101daae7ae464f2c59bf6f94b210eb848513c98aa8f1854f3e13beac3ed","has_figures":true,"extraction":"text"},{"ordinal":10,"depth":1,"kind":"rule","number":"2.2","title":"Specific requirements","body":"● Neck shield must conform to the general requirements (1.3).\n● Neck shield can be worn upon the aventail. It must be firmly attached to the aventail.\n● Neck shield must have a shape inspired by the heater shield.\n● Neck shield cannot exceed 15x17cm.\n● Neck shield can be painted.\n● Painted neck shield must respect Armor aspect and decoration rules.","page_from":4,"page_to":4,"stable_key":"neck-protection:2.2","parent_key":"neck-protection:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"64b92ccf92dd832d5fd510a005abb6cb1819176b96a6845cf62696f4256b90ec","has_figures":true,"extraction":"text"},{"ordinal":11,"depth":1,"kind":"rule","number":"2.3","title":"Examples of Approved reproductions","body":"","page_from":5,"page_to":5,"stable_key":"neck-protection:2.3","parent_key":"neck-protection:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"603ab8fb5827421eb9ff4a2607832d04c7499dcf37fe13a5f23d9db96fa2c52b","has_figures":true,"extraction":"text"},{"ordinal":12,"depth":1,"kind":"rule","number":"2.4","title":"Examples of Denied reproductions","body":"Oversized neck shield, it risks being ripped off during wrestling.\n\nRound shape is not allowed, it must be concealed under the aventail.\n\nPictures from The Medieval Things ©","page_from":5,"page_to":5,"stable_key":"neck-protection:2.4","parent_key":"neck-protection:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f2cacccd886fbc29c399ec87f76acfbb535845f00f1287eb64690bea8905a28d","has_figures":true,"extraction":"text"},{"ordinal":13,"depth":0,"kind":"section","number":"3","title":"Lobster tail","body":"","page_from":6,"page_to":6,"stable_key":"neck-protection:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a16fecb6d85f932471f393535b7cf0529c55519f7d959ff154d460d0ab796b56","has_figures":false,"extraction":"text"},{"ordinal":14,"depth":1,"kind":"rule","number":"3.1","title":"Historical sources and datation","body":"● Lobster tail is a lobster-shape neck protection made of articulated metal plates. It is depicted in manuscript and art from the late 14th century to the 15th century.\n● They are approved for 14th century, Transitional and 15th century armors.\n\nA   B   C\n\nA: Paduan Bible - 1400 - Italy B: Le Livre et le vraye hystoire du bon roy Alixandre - 1400/1420 - France C: Altar of St James, Pistoia - 1380/1400 - Italy","page_from":6,"page_to":6,"stable_key":"neck-protection:3.1","parent_key":"neck-protection:3","review_status":"needs_review","review_note":"layout looks like a table or columns: compare with the official page","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b5ee16f1e1040b67518cdce2a0c1c960496593c2557a0b470352ca494be88b5d","has_figures":false,"extraction":"text"},{"ordinal":15,"depth":1,"kind":"rule","number":"3.2","title":"Specific requirements","body":"● Lobster tail can be worn upon the aventail. It must be firmly attached to the aventail.\n● Lobster tail cannot be painted if they are worn upon the aventail.\n● Lobster tail must be articulated and consist of at least 3 parts.\n● Lobster tail cannot exceed 15 x 25 cm.","page_from":6,"page_to":6,"stable_key":"neck-protection:3.2","parent_key":"neck-protection:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1985391cdc3bff6e70f6d9f3e38d68b6e7f96c6fa5249b8184d7e2c345edfbca","has_figures":false,"extraction":"text"},{"ordinal":16,"depth":1,"kind":"rule","number":"3.3","title":"Examples of Approved reproductions","body":"Pictures from Gohurt ©","page_from":7,"page_to":7,"stable_key":"neck-protection:3.3","parent_key":"neck-protection:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2a9ec163ea715d851b9ec7195f53677c868a7d1f96fe72cc062ed8b1e0f1fe5c","has_figures":true,"extraction":"text"},{"ordinal":17,"depth":1,"kind":"rule","number":"3.4","title":"Examples of Denied reproductions","body":"Oversized\n\nPictures from The Medieval Things ©","page_from":7,"page_to":7,"stable_key":"neck-protection:3.4","parent_key":"neck-protection:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"efb01e2fd3790019f2c2838d717a50ecd89c7ecadac7e4dea1f3809d81763c06","has_figures":true,"extraction":"text"},{"ordinal":18,"depth":0,"kind":"section","number":"4","title":"Gorget","body":"","page_from":8,"page_to":8,"stable_key":"neck-protection:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"fd454c098d7fa420d3db760103734218a8bd1fbdf124b8180d2b9979fa28d2ac","has_figures":true,"extraction":"text"},{"ordinal":19,"depth":1,"kind":"rule","number":"4.1","title":"Historical sources and datation","body":"● A gorget was a type of neck protection worn over the neck, clavicles, and shoulders. It evolved from earlier forms of neck defenses, which often relied on chainmail or padded fabrics like the aventail. By the late 15th century, as plate armor became more refined, the gorget emerged as a key piece of protection for the throat and neck, made primarily from steel plates. Gorgets were most common in the 16th century but evidence exists of gorgets and plate collars.\n● They are denied for 14th century and Transitional armors\n● They are approved for 15th century armors\n\nWade Allen collection - 1510 - Italy","page_from":8,"page_to":8,"stable_key":"neck-protection:4.1","parent_key":"neck-protection:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ea84d467efec986c62b8f58ce8ede1b0add9868ceb4e3e24b15195f703757bf5","has_figures":true,"extraction":"text"},{"ordinal":20,"depth":1,"kind":"rule","number":"4.2","title":"Specific requirements","body":"● Gorget must conform to the general requirements (1.3)\n● Gorget must be constructed from plates.\n● Gorget must cover the clavicles and back of the neck. The throat should have a low profile, be articulated or otherwise fitted in such a way that it doesn’t choke the wearer when their head is tilted forward.\n● Gorget must be worn with appropriate armor styles and match historical sources in function and appearance.","page_from":8,"page_to":8,"stable_key":"neck-protection:4.2","parent_key":"neck-protection:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8cb7f913168928bcfdbfcf4106e86babef1d0524902d53c1b591aba639cf6e88","has_figures":true,"extraction":"text"},{"ordinal":21,"depth":1,"kind":"rule","number":"4.3","title":"Examples of Approved reproductions","body":"Pictures from The Medieval Things ©","page_from":9,"page_to":9,"stable_key":"neck-protection:4.3","parent_key":"neck-protection:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"bbe18c40488cb2c8438c13660b0ff541ad56c40281727c6dc7ac4b9f6811b4b6","has_figures":true,"extraction":"text"},{"ordinal":22,"depth":0,"kind":"section","number":"5","title":"Concealed neck plates","body":"","page_from":10,"page_to":10,"stable_key":"neck-protection:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"79667937e2beeeb254add7842ba62b7f5a7561ca812ab45c7ce8a03d5a6fc18e","has_figures":true,"extraction":"text"},{"ordinal":23,"depth":1,"kind":"rule","number":"5.1","title":"Historical sources and datation","body":"● There are no historical sources nor datation for such armor elements. Nevertheless, it is approved to reinforce your neck armor with concealed plates.","page_from":10,"page_to":10,"stable_key":"neck-protection:5.1","parent_key":"neck-protection:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"77e220a630f56f3438520eaa70600294b6da623af3bcc4f4f801a92a27677357","has_figures":true,"extraction":"text"},{"ordinal":24,"depth":1,"kind":"rule","number":"5.2","title":"Specific requirements","body":"● Concealed neck plates must conform to the general requirements (1.3)\n● Concealed neck plates must be made of metal.\n● Concealed neck plates must be hidden under the aventail.\n● Concealed neck plates must be firmly attached.\n● Edges of concealed neck plates must be smooth with no sharp edges.\n● It is recommended to paint concealed neck plates with anti rust paint. Such paint must be a neutral color (grey, black) and do not interfere with the aesthetic of the armor.","page_from":10,"page_to":10,"stable_key":"neck-protection:5.2","parent_key":"neck-protection:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ddd4ded96a89ce84869ba619c55e090660169d02a4eb06bc4c480b61436f1004","has_figures":true,"extraction":"text"},{"ordinal":25,"depth":1,"kind":"rule","number":"5.3","title":"Examples of Approved reproductions","body":"Pictures from Medieval Extreme ©","page_from":10,"page_to":10,"stable_key":"neck-protection:5.3","parent_key":"neck-protection:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"df1f38e26b1066cc70bde6b8e5ad15d5ba8593d767b9f1a0985f66e7a95fe69c","has_figures":true,"extraction":"text"},{"ordinal":26,"depth":1,"kind":"rule","number":"5.4","title":"Examples of Denied reproductions","body":"Metal plates visible\n\nPictures from The Medieval Things ©","page_from":11,"page_to":11,"stable_key":"neck-protection:5.4","parent_key":"neck-protection:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4eaa8ed2e5e1537be56cf64d6c2ae5a44c8a87ae0d83bf9396f9ebf9885b1f13","has_figures":true,"extraction":"text"},{"ordinal":27,"depth":0,"kind":"note","number":"6","title":"Change log","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nFebruary-2025 (V2025.02)\n- formatting: overall grammar and formatting\n- add: 4.1 They are denied for 14th century and Transitional armors\n\nDecember-2024: -Add Document has been created","page_from":12,"page_to":12,"stable_key":"neck-protection:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"e67a056f1ea236259537314dc6d4ff52eeeb40dd13cf4784c0d472ba05fbf29f","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_historical_version($rules${"governing_body":"Buhurt International","history":"archive-2026-10-06","inventory_key":"authenticity/perforated-visor-bascinets","version":{"version":"26.1","title":"Perforated Visor Bascinets 26.1","published_on":null,"effective_from":null,"note":"Title and footer \"Perforated Visor Bascinets V. 26.1\"; cover \"VER. 26.1\"; change log \"January - 2026 (V. 26.1) Document has been created\". Older than the current 26.4.","source_url":"https://drive.google.com/file/d/1n5ZX8l8j0d5duRtCMTrwYQNtd_7PJiIF/view","source_sha256":"691f1b945d0c2abed9d8ff593cb33e82a5276e4b8326a691516ae117b50847c2","retrieved_at":null,"page_count":11,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 11 page(s) without a text layer","content_sha256":"6a8bf65e64c4c35b2448b9174b98cc23e16997c816644ce1ecd5fb185be51bd9","detected":{"version":"26.1","date":null},"confirmed_by":"Claude Code (Pack 22 historical import), read from the archived PDF: cover (OCR of the page image), footers and change log","historical":true,"edition_seq":1,"edition_evidence":"Title and footer \"Perforated Visor Bascinets V. 26.1\"; cover \"VER. 26.1\"; change log \"January - 2026 (V. 26.1) Document has been created\". Older than the current 26.4.","source_files":[{"file":"Authenticity/Archive/Perforated Visor Bascinets.pdf","archive":"Authenticity","sha256":"691f1b945d0c2abed9d8ff593cb33e82a5276e4b8326a691516ae117b50847c2","drive_file_id":"1n5ZX8l8j0d5duRtCMTrwYQNtd_7PJiIF"}],"reconciliation":{"ok":true,"errors":[],"warnings":["1 provision(s) need review against the official document"],"pages":11,"source_lines":140,"assigned_lines":182,"furniture_lines":36,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99722,"provisions":16,"numbered":15,"needs_review":1,"verified":0,"empty_pages":[],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":140,"picture_text_lines":9,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 26.1\n\nAuthenticity","page_from":1,"page_to":1,"stable_key":"perforated-visor-bascinets:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"b3cd075ee5755a5513c4f726dcdef54be200038fbb1071b0c1257f4b18b0c3f9","has_figures":true,"extraction":"ocr"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Implementation","body":"The document has been created and approved by the General Assembly of 29.11.2025.\nThe document and its rules will be implemented from the 2029 season (01/01/2029).\nCompetitors will have 3 seasons to align their equipment with this document and its rules.","page_from":3,"page_to":3,"stable_key":"perforated-visor-bascinets:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1e215a7d2edf407991399a96ef4f69da15cc1358d2842fc3bb9fc959292569ef","has_figures":true,"extraction":"ocr"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Definition","body":"Bascinets with perforated visors are helmets with movable perforated visors. Such visors do not include Eye slots.\nThis type of visor is depicted in some rare manuscripts in Western Europe from the late 14th century and early 15th century. A handful of later designs showing this kind of visor still survive through the 15th century.\nThere is no consensus among armor experts where such manuscripts depict actual perforated visors or badly drawn regular helmets (hundskulls for example).\nThose helmets use a solid metal visor to protect the face, attached by 2 different system:\n\n● Attached on the forehead by a movable piece of metal, similar to the “spoon” from Klappvisor,\n\n● Attached to the dome with hinges at the temples, similar to Pivoting visored Bascinets.\n\nSpoon","page_from":3,"page_to":3,"stable_key":"perforated-visor-bascinets:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3864421630f28ac8b732055f071825d0a5389b063976df8b7238cdd08d9d8717","has_figures":true,"extraction":"ocr"},{"ordinal":4,"depth":0,"kind":"section","number":"3","title":"Historical Sources and Datation","body":"","page_from":4,"page_to":4,"stable_key":"perforated-visor-bascinets:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"04e42d373a22b64d239d42d339423dfe562a290d68219f938a8fe993f807be48","has_figures":true,"extraction":"ocr"},{"ordinal":5,"depth":1,"kind":"rule","number":"3.1","title":"Bascinets with perforated and forehead attached visor","body":"The term “Bascinets with perforated and forehead attached visor” will be abbreviated to “Perforated Klappvisor Bascinets’ for the remainder of the document.\n\nPerforated Klappvisor Bascinets can be seen in a couple of manuscripts, from 1389 to 1420/1430.\n\nPerforated Klappvisor Bascinets can have a visor with a rounded profile or a sharp profile. The shape of the profile does not change the approved and denied time periods.\n\nPerforated Klappvisor Bascinets are Approved for Transitional armors.\nPerforated Klappvisor Bascinets are Denied for 14th century armors.\n\nPerforated Klappvisor Bascinets can be Approved for 15th century armors with a coherent project.\nWe strongly recommend sending an email to authenticity@buhurtinternational.com before placing an order for such armor.\n\nVindobonensis 2762, Wenzel Bible - 1389 - Austria Pal.lat.1888 - 1430 - Germany\n\nGéttinger MS Philos. 63 Bellifortis - 1405 - Germany","page_from":4,"page_to":4,"stable_key":"perforated-visor-bascinets:3.1","parent_key":"perforated-visor-bascinets:3","review_status":"needs_review","review_note":"OCR could not read some words with confidence: Bascinets’, Géttinger","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"97229065803e8778f97d1ac822f4e5cca9e281e9e708f0b6f1bf156dff179bce","has_figures":true,"extraction":"ocr"},{"ordinal":6,"depth":1,"kind":"rule","number":"3.2","title":"Bascinets with perforated side-hinged attached visor","body":"The term “Bascinets with perforated side-hinged attached visor” will be abbreviated to “Side-hinged Perforated Bascinets’” for the remainder of the document.\n\nSide-hinged Perforated Bascinets must have a visor with a rounded profile Side-hinged Perforated Bascinets are Approved for Transitional armors.\n\nSide-hinged Perforated Bascinets are Denied for 14th century and 15th century armors.\n\nVindobonensis 2762, Wenzel Bible - 1389 - Austria\n\nWenceslas Bible - 1390/1400 - Germany","page_from":5,"page_to":5,"stable_key":"perforated-visor-bascinets:3.2","parent_key":"perforated-visor-bascinets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"51a5826f2e3575fbc93bd9537774c5366215213312b27445cff15b26ae0e5be5","has_figures":true,"extraction":"ocr"},{"ordinal":7,"depth":1,"kind":"rule","number":"3.3","title":"Great Bascinets with perforated visor","body":"Later during the 15th-century, a handful of contemporary designs show the use of perforated visors, despite a great lack of representation in art.\n\nGreat Bascinets with perforated visors must have a visor with a rounded profile.\nGreat Bascinets with perforated visors are Approved for 15th century armors.\n\nGreat Bascinets with perforated visors are Denied for 14th century and Transitional armors.\n\nGerman Great Bascinet, MET\n\nGrand Bacinet private collection - 1450/1475- southern Germany or Austria","page_from":6,"page_to":6,"stable_key":"perforated-visor-bascinets:3.3","parent_key":"perforated-visor-bascinets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3991eec7cfb9e6c4f16fabdf13fabf8e7cb724c4b568c5f46c8fafa48fd09161","has_figures":true,"extraction":"ocr"},{"ordinal":8,"depth":1,"kind":"rule","number":"3.4","title":"Bicoques with perforated visor","body":"Later during the 15th century, a handful of contemporary designs show the use of perforated visor, despite a great lack of representation in art.\n\nBicoques with perforated visors must have a visor with a rounded profile.\nBicoques with perforated visors Approved for 15th century armors.\n\nBicoques with perforated visors are Denied for 14th century and Transitional armors.\n\nBicoque ref_arm_1929_015 W1012 Goll - 1440-50","page_from":7,"page_to":7,"stable_key":"perforated-visor-bascinets:3.4","parent_key":"perforated-visor-bascinets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b9e5164bfbe1d176fe33513129bd0257fb74bb49042cacaddcee9ae57edc0b79","has_figures":true,"extraction":"ocr"},{"ordinal":9,"depth":0,"kind":"section","number":"4","title":"Requirements","body":"","page_from":8,"page_to":8,"stable_key":"perforated-visor-bascinets:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3d29162d60c0bc9bb8627f4598539b543cc6f853f7106b801fe7a3673a60cc4b","has_figures":false,"extraction":"ocr"},{"ordinal":10,"depth":1,"kind":"rule","number":"4.1","title":"General Requirements","body":"Reproductions must closely resemble the appearance and proportions of either bascinets, great bascinets or bicoque respective sources.\n\nAny metal part of the helmet must conform to the “Armors and Weapons Aesthetics and Decorations document.\n\nAny textile or leather part of the helmet must conform to the “Textiles and Leather” document.","page_from":8,"page_to":8,"stable_key":"perforated-visor-bascinets:4.1","parent_key":"perforated-visor-bascinets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"18ab07820e6fcb70b0dc07511232c0282f00c47b9e4fa6c326490a6a711cc38e","has_figures":false,"extraction":"ocr"},{"ordinal":11,"depth":1,"kind":"rule","number":"4.2","title":"Visor","body":"The visor must not be too long or too short, it must respect the proportions of historical sources.\n\nIt is allowed to add a metal plate to protect the throat. Such a plate must be strong enough to endure full contact fight and must be concealed under the aventail.\n\nA leather strap can be used to secure the visor down.\nIt is permitted to weld the visor down. Welded visors must resemble a functional removable visor.\nThe hinge must be reproduced as per historical sources.\n\nBreath holes should be round and must not exceed a diameter of 10mm. Breath holes must not be so numerous that they compromise the helm’s structural integrity. It is acceptable to mirror breath holes to both sides.\n\nBreath holes of another shape must be documented by historical sources to be allowed.\n\nProfile of visors:\n\n● Sharp-profile visors Visors with a sharp profile must clearly present a pointy profile.\n\n● Rounded-profile visors Visors with a rounded profile must clearly present a globose profile.","page_from":8,"page_to":8,"stable_key":"perforated-visor-bascinets:4.2","parent_key":"perforated-visor-bascinets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c92dda28c327a8d7d93053adb2cac9cec62cf3a12169c7bb5c79ce3f4f912a4c","has_figures":false,"extraction":"ocr"},{"ordinal":12,"depth":1,"kind":"rule","number":"4.3","title":"Aventails","body":"Bascinets with perforated visors must be worn with chainmail aventails, fabric aventails, or scales aventails.\n\nGreat Bascinets and Bicoques can not be worn with chainmail aventails, fabric aventails or scales aventails.\n\nAventails must conform to the “Aventails” document.\n\nAventails must be attached to the bascinet by a system of leather and vervelles.\n\nThe aventail must be fastened down to the edge of a padded pelerine attached to the helmet liner.\nAny additional protective plates covering the cervical spine must be hidden under the aventail.","page_from":8,"page_to":8,"stable_key":"perforated-visor-bascinets:4.3","parent_key":"perforated-visor-bascinets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"dab68fb197fad30623e34c252a8610b5b999e0a8eaef1cae1a381c88267343d9","has_figures":false,"extraction":"ocr"},{"ordinal":13,"depth":1,"kind":"rule","number":"4.4","title":"Others","body":"All helmets with perforated visors may be decorated in the spirit of medieval styles, such as orle, torse, decorated aventails (with copper/brass chainmail rings), vervelle covers and coat of arms badges etc.\n\nSuch decoration must be made in coherence with historical sources.\nUsing modern and/or offensive imagery and slogans is prohibited.","page_from":8,"page_to":8,"stable_key":"perforated-visor-bascinets:4.4","parent_key":"perforated-visor-bascinets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e244e736f6741953b242ee147d57188abe321ffc8a8db8ae12a6dbea79968607","has_figures":false,"extraction":"ocr"},{"ordinal":14,"depth":0,"kind":"section","number":"5","title":"Examples of Approved Reproductions","body":"Pictures from The Medieval Things ©","page_from":9,"page_to":9,"stable_key":"perforated-visor-bascinets:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1224f9c071bc04c751e872ce74a9712541a97269efe09bf62af4c75077148c22","has_figures":true,"extraction":"ocr"},{"ordinal":15,"depth":0,"kind":"section","number":"6","title":"Examples of Reproductions","body":"Visor lack of pointiness Visor lack of curvature and leaf instead of a spoon\n\nEyes holes do not match approved pattern\n\nPictures from The Medieval Things ©","page_from":10,"page_to":10,"stable_key":"perforated-visor-bascinets:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5a2c47d03ad60a5ddf7496ca5bbf4797d3a2314c5b1191bf3c29c37cf904ee92","has_figures":true,"extraction":"ocr"},{"ordinal":16,"depth":0,"kind":"note","number":"7","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nJanuary - 2026 (V. 26.1) Document has been created","page_from":11,"page_to":11,"stable_key":"perforated-visor-bascinets:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"fc2fa3307e16c0384a9b98ebb44a708756a26d706adfaee6c3daf9247418b1a1","has_figures":false,"extraction":"ocr"}]}$rules$::jsonb);
select private.rules_import_historical_version($rules${"governing_body":"Buhurt International","history":"archive-2026-10-06","inventory_key":"authenticity/sabatons","version":{"version":"2025.01","title":"Sabatons 2025.01","published_on":null,"effective_from":null,"note":"Title \"Sabatons\"; cover \"VER. 2025.01\" although the file is named \"V2024.12\" and the change log has only \"December-2024: created\". The label is the cover's; the file name and change log are recorded. Older than the current 26.1.","source_url":"https://drive.google.com/file/d/1U1EJxNVxjcY6BRZZP99ZoyhuqWclImXt/view","source_sha256":"19e7d8866c748cf66bccb738191f72df4d01c632ecc9f70f98450736dc762c5d","retrieved_at":null,"page_count":13,"extractor":"pdftotext unknown -layout -enc UTF-8","content_sha256":"001d927434e9f60b0711e8a1fbc4ef139e52400f58aad66a46f61d1d932ff00b","detected":{"version":null,"date":null},"confirmed_by":"Claude Code (Pack 22 historical import), read from the archived PDF: cover (OCR of the page image), footers and change log","historical":true,"edition_seq":1,"edition_evidence":"Title \"Sabatons\"; cover \"VER. 2025.01\" although the file is named \"V2024.12\" and the change log has only \"December-2024: created\". The label is the cover's; the file name and change log are recorded. Older than the current 26.1.","source_files":[{"file":"Authenticity/Archive/Sabatons V2024.12.pdf","archive":"Authenticity","sha256":"19e7d8866c748cf66bccb738191f72df4d01c632ecc9f70f98450736dc762c5d","drive_file_id":"1U1EJxNVxjcY6BRZZP99ZoyhuqWclImXt"}],"reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1","1 provision(s) need review against the official document"],"pages":13,"source_lines":131,"assigned_lines":215,"furniture_lines":34,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99857,"provisions":23,"numbered":21,"needs_review":1,"verified":0,"empty_pages":[1],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":0,"picture_text_lines":0,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"sabatons:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"note","number":null,"title":null,"body":"Sabatons","page_from":2,"page_to":2,"stable_key":"sabatons:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"5f713ce80e7fdb3fcae3b322ffd65cc37686b5b9d5d0574bc671deb6e81214f5","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":0,"kind":"section","number":"1","title":"Definition and general requirements","body":"","page_from":3,"page_to":3,"stable_key":"sabatons:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"df9d4b4971cd1ada36b96ec4e6602cd5f968c25814a104728b68a69b7ffb6242","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"1.1","title":"Definition","body":"● Sabatons is the terms used to describe all foot protections.","page_from":3,"page_to":3,"stable_key":"sabatons:1.1","parent_key":"sabatons:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"49dbbc62b8b3636bf5d842f6e9b7edd4c52c0364c8f091f9dbff4ee6b6537a98","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"1.2","title":"Sabatons description","body":"Sabatons can be:\n● Plate sabatons : Made of metal plates riveted together, it is the most effective and the most common foot protection over all middle ages.\n● Brigand sabatons : Made of metal plates riveted to a leather base. This protection is not commonly represented in historical sources. The plates are covered by the leather.\n● Scales sabatons : Made of small scales riveted upon a leather base. This protection is not commonly represented in historical sources.\n● Chainmail sabatons : The protection of the foot is ensured by chainmail. This is the earliest foot protection documented by historical sources.\n● Eastern sabatons : Due to very few historical sources, we allow eastern stylization of European sabatons. Allowed designs are displayed in the document “Eastern Armors”.","page_from":3,"page_to":3,"stable_key":"sabatons:1.2","parent_key":"sabatons:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"202d46d52ba7d3b996ce0fcb79eec0d1c1726940282c7efefc49e891259526e7","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":1,"kind":"rule","number":"1.3","title":"General requirements","body":"All types of sabatons must respect the following requirements :\n● Be based on historical sources.\n● Have an anatomical shape of the foot.\n● Must reproduce the proportions based on historical sources.\n● Any metal part of the sabatons must conform to the Armors and weapons Aesthetics and decorations document.\n● Any textile or leather part of the sabatons must conform to the Textiles and Leather document.","page_from":3,"page_to":3,"stable_key":"sabatons:1.3","parent_key":"sabatons:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4663c75e8953e2960fdff6bda821b669bee6798732eb7b13bae435b9d495569a","has_figures":false,"extraction":"text"},{"ordinal":7,"depth":0,"kind":"section","number":"2","title":"Plate sabatons","body":"","page_from":4,"page_to":4,"stable_key":"sabatons:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a2ef0ba5756ab272e113ff331eb9d5b2d5f918b73a8ec325002a81257a8f4287","has_figures":true,"extraction":"text"},{"ordinal":8,"depth":1,"kind":"rule","number":"2.1","title":"Historical sources and datation","body":"● Plate sabatons are mainly represented from the mid 14th century to very late armors of 15Ith century.\n● They are approved for 14th century, Transitional and 15th century armors.\n\nA   B   C\n\nA: Köln - 1375 - Germany B: E. of Woodstock - 1376 - England C: BL Sloane 2683 Book of Hours - 1390/1399 - Belgium","page_from":4,"page_to":4,"stable_key":"sabatons:2.1","parent_key":"sabatons:2","review_status":"needs_review","review_note":"layout looks like a table or columns: compare with the official page","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"de35c533db1e02bb0890f352404bcfbd673c50d918e5ee3cba6df515c0bc4b64","has_figures":true,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"2.2","title":"Specific requirements","body":"● Plate sabatons must conform to the general requirements (1.3).\n● Plate sabatons must have at least 5 segments\n\n● It is allowed to add heel protection.\n\n● Plate sabatons must have a pointed shape.\n\n● Maximilian style armors of the 16th century can have a square shape.","page_from":4,"page_to":5,"stable_key":"sabatons:2.2","parent_key":"sabatons:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b3288b9102f9b3980e34637f8bcc433172169da7fdc677ccb137560f5dcc1fbe","has_figures":true,"extraction":"text"},{"ordinal":10,"depth":1,"kind":"rule","number":"2.3","title":"Examples of Approved reproductions","body":"Picture from Medieval Extreme © Picture from Age of Craft ©","page_from":6,"page_to":6,"stable_key":"sabatons:2.3","parent_key":"sabatons:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3a3c66511a028653b9fbfe741b34436658f48cd28ec5dd37d22e2f8e4c526a1a","has_figures":true,"extraction":"text"},{"ordinal":11,"depth":0,"kind":"section","number":"3","title":"Brigand sabatons","body":"","page_from":7,"page_to":7,"stable_key":"sabatons:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a9c7411dcdea022b1832fbf11a16ef171e2c46c685ccdd1a2a3b6014ec116cc7","has_figures":true,"extraction":"text"},{"ordinal":12,"depth":1,"kind":"rule","number":"3.1","title":"Historical sources and datation","body":"● Brigand sabatons are not well represented in historical sources. They are displayed in sources from the middle of the 14th century.\n● They are approved for 14th century armors.\n● They are denied for Transitional and 15th century armors.\n\nG. von Schwarzburg - 1349 - Germany","page_from":7,"page_to":7,"stable_key":"sabatons:3.1","parent_key":"sabatons:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"39effd25fb554060d013d4fdddcfd1cca92a7495e270acd18341805ea115dd08","has_figures":true,"extraction":"text"},{"ordinal":13,"depth":1,"kind":"rule","number":"3.2","title":"Specific requirements","body":"● Brigand sabatons must conform to the general requirements (1.3).\n● Brigand sabatons must be made of metal plates.\n● The plates must be firmly-riveted to a leather base.\n● The plates must be riveted from the inside of the leather base.","page_from":7,"page_to":7,"stable_key":"sabatons:3.2","parent_key":"sabatons:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"05287997a77931342f4c2b95da9909859f5453a2d09b40a5b03e78efca6a84ac","has_figures":true,"extraction":"text"},{"ordinal":14,"depth":1,"kind":"rule","number":"3.3","title":"Examples of Approved reproductions","body":"Picture from Medieval Extreme ©","page_from":8,"page_to":8,"stable_key":"sabatons:3.3","parent_key":"sabatons:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"79551c7c0ef16a25b37b4ee36ec8b4cb2dac31b5a93b94ae72e53e5d9a1e0220","has_figures":true,"extraction":"text"},{"ordinal":15,"depth":0,"kind":"section","number":"4","title":"Scale sabatons","body":"","page_from":9,"page_to":9,"stable_key":"sabatons:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e63c2ab138f1f6457b8fe7fde27da6125a6f7aef1d100632f341adcfe46eb679","has_figures":true,"extraction":"text"},{"ordinal":16,"depth":1,"kind":"rule","number":"4.1","title":"Historical sources and datation","body":"● Scales sabatons are not well represented in historical sources. They are displayed in sources from 1350 to 1395.\n● They are approved for 14th century and Transitional armors.\n● They are denied for 15th century armor.\n● Their construction makes scale sabatons less protective than plate sabatons.\nTherefore, we do not recommend such sabatons in any category.\n\nJ. von Falkenstein- 1365 - Germany Guda von Bellersheim - 1394 - Germany","page_from":9,"page_to":9,"stable_key":"sabatons:4.1","parent_key":"sabatons:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"622a61a168fd13376a0976a90c25fca85266c085271e078c3bd3be05f43456d8","has_figures":true,"extraction":"text"},{"ordinal":17,"depth":1,"kind":"rule","number":"4.2","title":"Specific requirements","body":"● Scales sabatons must conform to the general requirements (1.3).\n● The scales can have a rectangular shape or a rounded shape.\n● The scales must be firmly attached to the shoe with rivets or leather thread\n● Scale sabatons must have a pointed shape.","page_from":9,"page_to":9,"stable_key":"sabatons:4.2","parent_key":"sabatons:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ecafb424cfafc641107eec1d787324c38754b2182e2a5f3a6d1d8127199a844d","has_figures":true,"extraction":"text"},{"ordinal":18,"depth":1,"kind":"rule","number":"4.3","title":"Examples of Approved reproductions","body":"Picture from Medieval Extreme ©","page_from":10,"page_to":10,"stable_key":"sabatons:4.3","parent_key":"sabatons:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9205e4f3614b7e49830ffa342c18d9a836e9fb874c7fda9d6c8e62f272881a79","has_figures":true,"extraction":"text"},{"ordinal":19,"depth":0,"kind":"section","number":"5","title":"Chainmail sabatons","body":"","page_from":11,"page_to":11,"stable_key":"sabatons:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"74c6a3510cc21e5a4ebac9f3469529a9d9d2cc51b0deed04af52fd1c2b487910","has_figures":false,"extraction":"text"},{"ordinal":20,"depth":1,"kind":"rule","number":"5.1","title":"Historical sources and datation","body":"● Chainmail sabatons are the earliest foot protection. They were popular in the XIIIth and early 14th century, and were replaced by more protective sabatons around the middle of the 14th century. They are still in use in very rare cases during the 15th century.\n● They are approved for 14th century armors and Transitional.\n● They are approved for 15th century armors if documented by sources. We encourage you to send an email to the authenticity committee before purchasing such sabatons and armors.\n● Their construction makes chainmail sabatons less protective than plate sabatons.\nTherefore, we do not recommend such sabatons in any category.\n\nPfarr- und Klosterkirche Sankt Lampert, Seeon-Seebruck, Bavaria - 1395 - Germany","page_from":11,"page_to":11,"stable_key":"sabatons:5.1","parent_key":"sabatons:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9e1dffbd426d61a7dc78b2043e51602abd7fe848d85cc6324685b6c65c2adf24","has_figures":false,"extraction":"text"},{"ordinal":21,"depth":1,"kind":"rule","number":"5.2","title":"Specific requirements","body":"● Chainmail sabatons must conform to the general requirements (1.3).\n● It is mandatory to use plate segments as the main protection, and use chainmail only for articulation purposes.\n● It is strongly recommended to use plate sabatons as it is the best protection you can use for your foot.","page_from":11,"page_to":11,"stable_key":"sabatons:5.2","parent_key":"sabatons:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1c67eb87eca3e0cbc9d58d278afb6cdd239d9fd08022abce2ce0b1d4abedd08f","has_figures":false,"extraction":"text"},{"ordinal":22,"depth":1,"kind":"rule","number":"5.3","title":"Examples of Approved reproductions","body":"Picture from Medieval Extreme ©","page_from":12,"page_to":12,"stable_key":"sabatons:5.3","parent_key":"sabatons:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"868abacce12d0a697a95b9483685a2afaade7d811fa1af760c4588d3e865412b","has_figures":true,"extraction":"text"},{"ordinal":23,"depth":0,"kind":"note","number":"6","title":"Change log","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nDecember-2024: -Add Document has been created","page_from":13,"page_to":13,"stable_key":"sabatons:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"24a5d9012e7ea5de58f8db1be93b49aa57a32ca2285e039cef368d514a6e1402","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_historical_version($rules${"governing_body":"Buhurt International","history":"archive-2026-10-06","inventory_key":"authenticity/shields-and-bucklers","version":{"version":"2025.03","title":"Shields and Bucklers 2025.03","published_on":null,"effective_from":null,"note":"Title \"Shields and Bucklers\"; cover \"VER. 2025.03\" while the change log heads its latest entry \"March-2025 (V2025.02)\": the label is the cover's, the disagreement is recorded. The 26.1 edition's change log continues from this \"March-2025 (V2025.02)\" entry.","source_url":"https://drive.google.com/file/d/1WKbfFL90sGiWeAKBLalCkoPQMO5jHc33/view","source_sha256":"a38d3d82e956cbe5f92f98d688d91dd1a6ebf236f2d14fafe455ca666c43afe9","retrieved_at":null,"page_count":23,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 1 page(s) without a text layer","content_sha256":"7276b1b8fb6e5a643e762088332d79ab19ecc75d093e353c72c720a898932587","detected":{"version":null,"date":null},"confirmed_by":"Claude Code (Pack 22 historical import), read from the archived PDF: cover (OCR of the page image), footers and change log","historical":true,"edition_seq":1,"edition_evidence":"Title \"Shields and Bucklers\"; cover \"VER. 2025.03\" while the change log heads its latest entry \"March-2025 (V2025.02)\": the label is the cover's, the disagreement is recorded. The 26.1 edition's change log continues from this \"March-2025 (V2025.02)\" entry.","source_files":[{"file":"Authenticity/Archive/Shields and Bucklers(1).pdf","archive":"Authenticity","sha256":"a38d3d82e956cbe5f92f98d688d91dd1a6ebf236f2d14fafe455ca666c43afe9","drive_file_id":"1WKbfFL90sGiWeAKBLalCkoPQMO5jHc33"}],"reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1"],"pages":23,"source_lines":240,"assigned_lines":372,"furniture_lines":32,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99918,"provisions":33,"numbered":31,"needs_review":0,"verified":0,"empty_pages":[1],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":5,"picture_text_lines":0,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"shields-and-bucklers:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"note","number":null,"title":null,"body":"Shields and Bucklers","page_from":2,"page_to":2,"stable_key":"shields-and-bucklers:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"98124e9162324d28d3190477ed44e42d4655a0527afe6e4974d6bc50317b111b","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":0,"kind":"section","number":"1","title":"Definition and general requirements","body":"","page_from":3,"page_to":3,"stable_key":"shields-and-bucklers:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"df9d4b4971cd1ada36b96ec4e6602cd5f968c25814a104728b68a69b7ffb6242","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"1.1","title":"Definition","body":"● Shields and bucklers are the terms used to describe every protection made of wood or steel and designed to protect yourself.","page_from":3,"page_to":3,"stable_key":"shields-and-bucklers:1.1","parent_key":"shields-and-bucklers:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2a90b2cffa3bb19e98a48e792666fb62188b9b36f65693996ded206858fbebf6","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"1.2","title":"Shields and bucklers description","body":"Shields and bucklers can be:\n● Heater shields : Shields made of triangular shape, the most common shape of shields from the XIIIth century and beyond. They must be made of wood.\n● Punch shields : Punch shields primarily designed to hit the opponent. It includes a wide variety of shapes. They must be made of wood.\n● Round shields : Shields made of a round shape, very common throughout the middle ages.\nThey can be made of wood or metal.\n● Bucklers : Small round shape shields with central handle, mainly used in duels and as a secondary equipment for close defense. They can be made of wood or metal.","page_from":3,"page_to":3,"stable_key":"shields-and-bucklers:1.2","parent_key":"shields-and-bucklers:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f73af5b9a083a8719c64655b81da919f58eeec16a848b02db1e3f5cc35df71e9","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":1,"kind":"rule","number":"1.3","title":"General requirements","body":"All types of shields and bucklers must respect the following requirements :\n● Be based on historical sources\n● Must reproduce the proportions and curves based on historical sources\n● Must be made of wood or metal. Any other material must be approved by the Authenticity Committee to be allowed in Buhurt International events.\n● Must match the style of the armor kit of the competitor.\n● All images, drawings, and paintings on shields must be stylized in accordance with the style of the armor kit of the competitor.\n● It is prohibited to decorate shields with images that are clearly modern and/or offensive.\n● The weight of all shields and bucklers must not exceed 5 kg.\n● It is allowed to use bolts and nuts to fasten straps.\n○ Nuts must not protrude the screw.\n○ Bolts and nuts must be painted in black or concealed with leather or fabric.\n● All straps must be made of leather.\n● Any metal part of the shield or buckler must conform to the Armors and weapons Aesthetics and decorations document.\n● Any textile or leather part of the shield or buckler must conform to the Textiles and Leather document.","page_from":3,"page_to":3,"stable_key":"shields-and-bucklers:1.3","parent_key":"shields-and-bucklers:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"aab1324510095af3a01a548f94667451f7175b6a137c528c10ee5d01041b65fc","has_figures":false,"extraction":"text"},{"ordinal":7,"depth":1,"kind":"rule","number":"1.4","title":"Wooden shields requirements","body":"● The entire edge must be covered with either a band of strong leather, or with at least three or more layers of fabric.\n● A leather band must be glued, sewn or riveted, to the shield. Any rivets must be neatly finished, the edge of the rivet should not stick out.\n● The flat outside wooden shields must be covered with leather or fabric.\n● The handles must be made of leather.\n● Wooden bucklers and Heater shields with a central handle must have a handle made of wood.\n● Shield boss (umbo) made of metal must conform to the Armors and weapons Aesthetics and decorations document.","page_from":4,"page_to":4,"stable_key":"shields-and-bucklers:1.4","parent_key":"shields-and-bucklers:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3c87f940adc8b3b5bacf17f2aea4fd9245392ed52300f0d3e66c26ae95522d6f","has_figures":true,"extraction":"text"},{"ordinal":8,"depth":1,"kind":"rule","number":"1.5","title":"Metal shields requirements","body":"● Must be of round shapes, based on historical sources, and repeat the form of the original in all three dimensions.\n● The entire edge of metal shields must be rolled to the thickness of a minimum of 4 mm or more.\n● The handles must be made of metal and or wood\n● Metal shields and shield boss (umbo) must conform to the Armors and weapons Aesthetics and decorations document.\n● It is allowed to blacken the back part of a metal shield or metal buckler. Example:\n\nPicture from O. Haguenstein ©","page_from":4,"page_to":4,"stable_key":"shields-and-bucklers:1.5","parent_key":"shields-and-bucklers:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"fe72b4b6422aff003b5cb7452e734e1c29f3d66c62a95b1576e234ad42bb9594","has_figures":true,"extraction":"text"},{"ordinal":9,"depth":0,"kind":"section","number":"2","title":"Heater shield","body":"","page_from":5,"page_to":5,"stable_key":"shields-and-bucklers:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d73efccaf2e3fc18f9a70a9ca2003f73436aa0b913a18617f4ccd1b0d4bbc996","has_figures":true,"extraction":"text"},{"ordinal":10,"depth":1,"kind":"rule","number":"2.1","title":"Historical sources and datation","body":"● Heater shields are the main shield shape for knights of the middle ages. Its triangular shape is typical of the 14th century. The shape goes thinner as the armors become more effective.\n● They are approved for 14th century, Transitional and 15th century armors.\n\nShield of Loew von Steinfurth - 1380 - Germany Grande Chroniques de France - 1400 - France\n\nPolitica & Economica - 1376 - France Ab Urbe Condita - 1390/1400 - France","page_from":5,"page_to":5,"stable_key":"shields-and-bucklers:2.1","parent_key":"shields-and-bucklers:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"39382e0baf5705eb85878611d3dc03684779d39e9fb8b759788778891c9a28cc","has_figures":true,"extraction":"text"},{"ordinal":11,"depth":1,"kind":"rule","number":"2.2","title":"Specific requirements","body":"● Heater shield must conform to the general requirements (1.3) and wooden shields requirements (1.4)\n● Heater shield must be made of wood.\n● Shape must be rectangular with a pointy shape at the bottom.\n\n● Heater shield must be curved, not flat.\n\n● Length must be from 55 cm to 75 cm.\n● Width must be from 30 cm to 65 cm.\n● Handles must be made of leather\n\nExample of leather handles\n\nPicture from O. Haguenstein ©\n\n● It is allowed to add a shield boss (umbo) on a Heater shield with a central handle, as documented by historical sources.\n● Central handle must be made of wood.","page_from":6,"page_to":7,"stable_key":"shields-and-bucklers:2.2","parent_key":"shields-and-bucklers:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"59ab70c091fc93f10851e0c5c054d0bd8bd016a72ad39448148891ef3752c2e3","has_figures":true,"extraction":"text"},{"ordinal":12,"depth":1,"kind":"rule","number":"2.3","title":"Examples of Approved reproductions","body":"Pictures from The Medieval Things ©","page_from":8,"page_to":8,"stable_key":"shields-and-bucklers:2.3","parent_key":"shields-and-bucklers:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3705146961bc83782cdeb237a29a71485cf28a27eb5052c8a8519f802c2cf638","has_figures":true,"extraction":"text"},{"ordinal":13,"depth":1,"kind":"rule","number":"2.4","title":"Examples of Denied reproductions","body":"This shape (oval) is not based on historical sources for shield with central handle.\nPictures from The Medieval Things ©","page_from":8,"page_to":8,"stable_key":"shields-and-bucklers:2.4","parent_key":"shields-and-bucklers:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0e60fcb3893ab6920cea7af51fc3e8c9718381cc21252c0d71bc02ab7aa7d6d4","has_figures":true,"extraction":"text"},{"ordinal":14,"depth":0,"kind":"section","number":"3","title":"Punch shield","body":"","page_from":9,"page_to":9,"stable_key":"shields-and-bucklers:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"91e34188eeff4235b01ebad21539bdebb6a299be475de31ab35f3f560884af01","has_figures":true,"extraction":"text"},{"ordinal":15,"depth":1,"kind":"rule","number":"3.1","title":"Historical sources and datation","body":"● Punch shields are designed to strike with the edge. The handles and straps allow you to wear them in a striking position. Their shape may vary depending on the time and place.\nMost common shapes are rectangular, trapezoid and oval.\n● Their ultimate evolution is the pavese of the 15th century. This type of shield has a rectangular shape and a gutter in the middle.\n● All shapes except Pavese shape are approved for 14th century, Transitional armors, and 15th century armors.\n● Pavese shape is denied for 14th century and Transitional armors, and approved for 15th century armors.\n\nCastello di Avio - 1350 - Italy\n\nwith gutter in the middle\n\nDeutsches Historisches Museum (Berlin) 1480 - Germany\n\nWien Museum 1480 - Austria\n\nPaduan Bible - 1400 - Italy","page_from":9,"page_to":10,"stable_key":"shields-and-bucklers:3.1","parent_key":"shields-and-bucklers:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"49e3de8b8e5667441512deee9afe8f04f59a81020527beb8d292054e11201683","has_figures":true,"extraction":"mixed"},{"ordinal":16,"depth":1,"kind":"rule","number":"3.2","title":"Specific requirements","body":"● Punch shield must conform to the general requirements (1.3) and wooden shields requirements (1.4)\n● Punch shield must be made of wood.\n● Shape must be rectangular, oval or pointed.\n\n● Length must be from 55 cm to 75 cm.\n● Width must be from 30 cm to 50 cm.\n● Punch shield must not be flat and conform to a curve.\n\n● By exception of 3.2.6, pavese shape can be flat if they conform to historical designs.\n\n● Striking area can be rounded or flat.\n\n● Rounded striking area must conform to a curve of 7cm diameter.\n● Flat striking area must be 7cm wide as a minimum.\n\n7 cm wide\n\n● It is not allowed to add a shield boss (umbo) on a Punch shield.\n● Handles must be made of leather (see examples in 2.2).\n● It is allowed to add a metal sheet on the shield to increase its resilience.\n○ Additional metal sheets must be covered by leather or fabric as another part of the outside of the shield.\n○ Additional metal sheets must have no sharp edges nor pointy parts.\n○ Additional metal sheets must be properly attached to the wooden core of the shield, by rivets, nails or strong glue.","page_from":11,"page_to":12,"stable_key":"shields-and-bucklers:3.2","parent_key":"shields-and-bucklers:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["2.2"],"content_sha256":"c757459ade0e4ba182d4160005822fc953bea9ec23add1f36972c6ddbb96c814","has_figures":true,"extraction":"text"},{"ordinal":17,"depth":1,"kind":"rule","number":"3.3","title":"Examples of Approved reproductions","body":"Pictures from The Medieval Things ©","page_from":13,"page_to":13,"stable_key":"shields-and-bucklers:3.3","parent_key":"shields-and-bucklers:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0a4776ab2ce99988787327f41508672a9f1a5b159e33e961660afd5e7f4a3c07","has_figures":true,"extraction":"text"},{"ordinal":18,"depth":1,"kind":"rule","number":"3.4","title":"Examples of Denied reproductions","body":"Flat Shield\n\nAbsence of leather or 3 layers of fabric on the edge\n\nPictures from The Medieval Things ©","page_from":14,"page_to":14,"stable_key":"shields-and-bucklers:3.4","parent_key":"shields-and-bucklers:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"67ba239334664158554d0bc43a25c9a63d80ea20a32e9aaebb974e54d5b0df81","has_figures":true,"extraction":"text"},{"ordinal":19,"depth":0,"kind":"section","number":"4","title":"Round shield","body":"","page_from":15,"page_to":15,"stable_key":"shields-and-bucklers:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f57fe5fa6faabac0da56c869f3827b0e50397a0fd5ff7cba7c89ee8fb70a4897","has_figures":true,"extraction":"text"},{"ordinal":20,"depth":1,"kind":"rule","number":"4.1","title":"Historical sources and datation","body":"● Round shields were very common in the early 14th century, and became rare while other designs spread. They are mainly made of wood. Some examples of metal round shields exist but they are parade shields and should be worn only with the proper set of armor of the late 15th century.\n● Round shields are worn with straps made of leather.\n● They are approved for 14th century and Transitional armors.\n● They are denied for 15th century armors unless historical sources are provided.\n\nCathedral of Strasbourg - 1340 - France Roman de la Rose - 1350 - France","page_from":15,"page_to":15,"stable_key":"shields-and-bucklers:4.1","parent_key":"shields-and-bucklers:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8362cfff2f1adc43f6a7a60e312928762d6d16928bf81cf54fe65009dc4593f5","has_figures":true,"extraction":"text"},{"ordinal":21,"depth":1,"kind":"rule","number":"4.2","title":"Specific requirements","body":"● Round shields must conform to the general requirements (1.3) and either wooden shields requirements (1.4) or metal shields requirements (1.5) depending on material.\n● Round shields can be made of wood or metal.\n● Any metal round shields must be approved by the Authenticity Committee to be allowed in Buhurt International events.\n● Diameter must be from 25 cm to 70 cm.\n● Round shields may be flat or have a concave curve.\n● The handles must be made of leather (see examples in 2.2).\n● It is not allowed to add a shield boss (umbo) on a round shield unless documented by historical sources.","page_from":16,"page_to":16,"stable_key":"shields-and-bucklers:4.2","parent_key":"shields-and-bucklers:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["2.2"],"content_sha256":"c41692c6671bf1a9f8f69f24e3ba11f1dc2185508c2187811b55c481bd2cdb91","has_figures":true,"extraction":"text"},{"ordinal":22,"depth":1,"kind":"rule","number":"4.3","title":"Examples of Approved reproductions","body":"Pictures from The Medieval Things ©","page_from":16,"page_to":16,"stable_key":"shields-and-bucklers:4.3","parent_key":"shields-and-bucklers:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"bbe18c40488cb2c8438c13660b0ff541ad56c40281727c6dc7ac4b9f6811b4b6","has_figures":true,"extraction":"text"},{"ordinal":23,"depth":1,"kind":"rule","number":"4.4","title":"Examples of Denied reproductions","body":"Round shield with shield boss (umbo)","page_from":17,"page_to":17,"stable_key":"shields-and-bucklers:4.4","parent_key":"shields-and-bucklers:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f5bf8adcf4f6a9a7a67a2e2c0230e687f47ce61a33adf17776f25a18a5920820","has_figures":true,"extraction":"text"},{"ordinal":24,"depth":0,"kind":"section","number":"5","title":"Bucklers","body":"","page_from":18,"page_to":18,"stable_key":"shields-and-bucklers:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"fd6a3987a9a1fdaebbb5c16ac47a6ef3398ac62e6e20f365b81561b6ed8fba11","has_figures":true,"extraction":"text"},{"ordinal":25,"depth":1,"kind":"rule","number":"5.1","title":"Historical sources and datation","body":"● Buckler is a small round shield made of wood or metal. It does not have straps but a rigid handle and a shield boss (umbo).\n● They are approved for 14th century, Transitional armors and 15th century armors.\n\nWeltchronik in Versen - 1370 - Germany","page_from":18,"page_to":18,"stable_key":"shields-and-bucklers:5.1","parent_key":"shields-and-bucklers:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3a7ad676f69829011aa56647b1732d53b67e495ed2f7427e12f58fdceca8450a","has_figures":true,"extraction":"text"},{"ordinal":26,"depth":1,"kind":"rule","number":"5.2","title":"Specific requirements","body":"● Bucklers must conform to the general requirements (1.3) and either wooden shields requirements (1.4), or metal shield requirements (1.5), depending on the material of the buckler.\n● Bucklers must be made of wood or metal.\n● Buckler must have a shield boss (umbo).\n○ Shield boss must be made of metal.\n○ Shield boss can be riveted or forged.\n● Diameter of a buckler must be from 20 cm to 40 cm.\n● Bucklers can be flat or curved depending on historical sources.\n\n● If the buckler is made of wood, the handle must be made of wood.\n● If the buckler is made of metal, the handle must be made of metal.\n● A strap can be added to secure the buckler in punch position. This strap must be made of leather.","page_from":18,"page_to":19,"stable_key":"shields-and-bucklers:5.2","parent_key":"shields-and-bucklers:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"43263665cf7b832780e1f0f12029053d167b81190d9d1a912d66465498ede674","has_figures":true,"extraction":"text"},{"ordinal":27,"depth":1,"kind":"rule","number":"5.3","title":"Examples of Approved reproductions","body":"Pictures from Black Dog Armoury ©\n\nWooden buckler\n\nPicture from The Medieval Things © Additional leather strap\n\nPicture from Medieval Extreme","page_from":19,"page_to":20,"stable_key":"shields-and-bucklers:5.3","parent_key":"shields-and-bucklers:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4318c82c429a7a0ca2b41fccbd12a2ad15b6c06b215cb0f7707d69269be6d335","has_figures":true,"extraction":"text"},{"ordinal":28,"depth":1,"kind":"rule","number":"5.4","title":"Examples of Denied reproductions","body":"Black painting is not allowed as per Armors and Weapons Aesthetics and Decoration.\n\nPictures from The Medieval Things ©","page_from":20,"page_to":20,"stable_key":"shields-and-bucklers:5.4","parent_key":"shields-and-bucklers:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9d8f979086916ffca480d3fa1882bfbe0fc338c2d1a984958af0bbb9cbc9f5eb","has_figures":false,"extraction":"text"},{"ordinal":29,"depth":0,"kind":"section","number":"6","title":"Fastening systems","body":"","page_from":21,"page_to":21,"stable_key":"shields-and-bucklers:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6d80278a40a4eef0fc03d3f732263e343c2a40080b91f786b1404a82a228ce28","has_figures":true,"extraction":"text"},{"ordinal":30,"depth":1,"kind":"rule","number":"6.1","title":"Historical sources and datation","body":"● Leather straps were fastened with nails or rivets.\n● The following methods are approved for 14th century, Transitional armors and 15th century armors:\n○ Nails ○ Rivets ○ Modern nuts and bolt\n\nNails Rivet with metal plate Pictures from Black Dog Armoury ©","page_from":21,"page_to":21,"stable_key":"shields-and-bucklers:6.1","parent_key":"shields-and-bucklers:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9233040d94241152638890ac97a3708315b58ea1f652ced19ed375cf4cea7bcf","has_figures":true,"extraction":"text"},{"ordinal":31,"depth":1,"kind":"rule","number":"6.2","title":"Specific requirements","body":"● Nails and rivets can be left visible.\n● Modern nuts and bolts must be concealed by one of the following methods:\n○ Covered by a piece of leather nailed to the shield.\n○ Painted in black or any other color to make it concealed.\n○ Hexagonal unpainted bolts must be ground to a rounded shape, replicating a rivet aesthetic.\n● Bolts must not protrude from the nuts.","page_from":21,"page_to":21,"stable_key":"shields-and-bucklers:6.2","parent_key":"shields-and-bucklers:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"578e910b92b498c5f3cb5976e61bc1179137d315244d18df02ffc00acd22fac3","has_figures":true,"extraction":"text"},{"ordinal":32,"depth":1,"kind":"rule","number":"6.3","title":"Examples of Approved systems","body":"Rivets can be visible Modern nuts and bolts, painted black\n\nPictures from Medieval Extreme ©","page_from":22,"page_to":22,"stable_key":"shields-and-bucklers:6.3","parent_key":"shields-and-bucklers:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5393bb2b4b84d785ca064aea96d674bdc1a025a39ae3def99f730c7d1efd4bbb","has_figures":true,"extraction":"text"},{"ordinal":33,"depth":0,"kind":"note","number":"7","title":"Change log","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nMarch-2025 (V2025.02)\n- clarification : 6.2\n- format: Grammar and Formatting\n\nDecember-2024: -Add Document has been created","page_from":23,"page_to":23,"stable_key":"shields-and-bucklers:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"511167732c2360fd54f31c3b4e8ada3ac637ab13204de666c23470147ece6185","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_historical_version($rules${"governing_body":"Buhurt International","history":"archive-2026-10-06","inventory_key":"authenticity/shields-and-bucklers","version":{"version":"26.1","title":"Shields and Bucklers 26.1","published_on":null,"effective_from":null,"note":"Title \"Shields and Bucklers\"; cover \"VER. 26.1\"; change log \"January - 2026 (V. 26.1)\" above \"March-2025 (V2025.02)\".","source_url":"https://drive.google.com/file/d/1ZoCscErZc7IryIshSt2H-_SAtNW-Ob40/view","source_sha256":"5211df463ccf6c3f90a98e6304438868f47a0f3cbb02d01fbf985dea4b963a16","retrieved_at":null,"page_count":19,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 19 page(s) without a text layer","content_sha256":"dec7ada641399c8671ea01081860365ab1d77d5e0d1d1531bf6573df539e603a","detected":{"version":"26.1","date":null},"confirmed_by":"Claude Code (Pack 22 historical import), read from the archived PDF: cover (OCR of the page image), footers and change log","historical":true,"edition_seq":2,"edition_evidence":"Title \"Shields and Bucklers\"; cover \"VER. 26.1\"; change log \"January - 2026 (V. 26.1)\" above \"March-2025 (V2025.02)\".","source_files":[{"file":"Authenticity/Archive/Shields and Bucklers.pdf","archive":"Authenticity","sha256":"5211df463ccf6c3f90a98e6304438868f47a0f3cbb02d01fbf985dea4b963a16","drive_file_id":"1ZoCscErZc7IryIshSt2H-_SAtNW-Ob40"}],"reconciliation":{"ok":true,"errors":[],"warnings":["5 provision(s) need review against the official document"],"pages":19,"source_lines":295,"assigned_lines":389,"furniture_lines":65,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.9961,"provisions":31,"numbered":30,"needs_review":5,"verified":0,"empty_pages":[],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":295,"picture_text_lines":16,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 26.1\n\nAuthenticity","page_from":1,"page_to":1,"stable_key":"shields-and-bucklers:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"b3cd075ee5755a5513c4f726dcdef54be200038fbb1071b0c1257f4b18b0c3f9","has_figures":true,"extraction":"ocr"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Implementation","body":"The document has been created and approved by the General Assembly of 09.11.2024.\nThe document and its rules have been implemented since the 2025 season.","page_from":3,"page_to":3,"stable_key":"shields-and-bucklers:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7e35b5946ae02907f8e065d2e3656f914639f40e08c6eb5efd4d1160c27157d4","has_figures":false,"extraction":"ocr"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Definition","body":"“Shields and Bucklers” are the terms used to describe every protection made of wood or steel and designed to protect yourself.\n\nShields and Bucklers can be:\n● Heater Shields\n\nShields made of triangular shape, the most common shape of Shields from the Xlllth century and beyond. They must be made of wood.\n\n● Punch Shields\n\nPunch Shields are primarily designed to hit the opponent. It includes a wide variety of shapes. They must be made of wood.\n\n● Round Shields\n\nShields made of a round shape, very common throughout the middle ages. They can be made of wood or metal.\n\n● Bucklers\n\nSmall round shape Shields with central handle, mainly used in duels and as a secondary equipment for close defense. They can be made of wood or metal.","page_from":3,"page_to":3,"stable_key":"shields-and-bucklers:2","parent_key":null,"review_status":"needs_review","review_note":"OCR could not read some words with confidence: Xlllth","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"379b34960550afdc75748351f8b549197c50692177fd8e8e4d1ae1cadfabd9c3","has_figures":false,"extraction":"ocr"},{"ordinal":4,"depth":0,"kind":"section","number":"3","title":"General Requirements","body":"All types of Shields and Bucklers must respect the following requirements:\n\n● be based on historical sources,\n\n● must reproduce the proportions and curves based on historical sources,\n\n● must be made of wood or metal. Any other material must be approved by the Authenticity Committee to be allowed in Buhurt International events,\n\n● must match the style of the armor kit of the competitor.\n\nAll images, drawings, and paintings on Shields must be stylized in accordance with the style of the armor kit of the competitor.\n\nIt is prohibited to decorate Shields and Bucklers with images that are clearly modern and/or offensive.\nThe weight of all Shields and Bucklers must not exceed 5 kg.\nIt is allowed to use bolts and nuts to fasten straps:\n\n● nuts must not protrude the screw,\n● bolts and nuts must be painted in black or concealed with leather or fabric.\n\nAll straps must be made of leather.\n\nAny metal part of the Shield or Buckler must conform to the “Armors and Weapons Aesthetics and Decorations’ document.\n\nAny textile or leather part of the Shield or Buckler must conform to the “Textiles and Leather’ document.","page_from":3,"page_to":3,"stable_key":"shields-and-bucklers:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"72ccab3c89692eea93f993b5b60201f9b323ffb1b07d298e0f9bf53673e95bd9","has_figures":false,"extraction":"ocr"},{"ordinal":5,"depth":0,"kind":"section","number":"4","title":"Wooden Shields Requirements","body":"The entire edge must be covered with either a band of strong leather, or with at least three or more layers of fabric.\n\nA leather band must be glued, sewn or riveted, to the Shield. Any rivets must be neatly finished, the edge of the rivet should not stick out.\n\nThe flat outside a wooden Shield must be covered with leather or fabric.\nThe handles must be made of leather.\nWooden Buckler and Heater Shield with a central handle must have a handle made of wood.\n\nShield boss (umbo) made of metal must conform to the “Armors and Weapons Aesthetics and Decorations” document.","page_from":4,"page_to":4,"stable_key":"shields-and-bucklers:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4801800788ab335f337b7da8ed31d182b51ef4003e6aebad70ed825b32a01970","has_figures":true,"extraction":"ocr"},{"ordinal":6,"depth":0,"kind":"section","number":"5","title":"Metal Shields Requirements","body":"Must be of round shapes, based on historical sources, and repeat the form of the original in all three dimensions.\n\nThe entire edge of metal Shields must be rolled to the thickness of a minimum of 4 mm or more.\nThe handles must be made of metal and or wood\n\nMetal Shield and Shield boss (umbo) must conform to the “Armors and Weapons Aesthetics and Decorations” document.\n\nIt is allowed to blacken the back part of a metal Shield or metal Buckler.\nExample:\n\nPicture from O. Haguenstein ©","page_from":4,"page_to":4,"stable_key":"shields-and-bucklers:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"01f6ec246c76424d25cd9a7709b1a250dc8917523bf992a5017f998b1535368b","has_figures":true,"extraction":"ocr"},{"ordinal":7,"depth":0,"kind":"section","number":"6","title":"Heater Shields","body":"","page_from":5,"page_to":5,"stable_key":"shields-and-bucklers:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"19a588ef6abd5379334147570c2e633975db534de166b4fd52de2bac7449636d","has_figures":true,"extraction":"ocr"},{"ordinal":8,"depth":1,"kind":"rule","number":"6.1","title":"Historical Sources and Datation","body":"The Heater Shield the main Shield shape for knights of the Middle Ages. Its triangular shape is typical of the 14th century. The shape goes thinner as the armors become more effective.\n\nThey are Approved for 14th century, Transitional and 15th century armors.\n\nShield of Loew von Steinfurth - 1380 - Germany Grande Chroniques de France - 1400 - France\n\nPolitica & Economica - 1376 - France Ab Urbe Condita - 1390/1400 - France","page_from":5,"page_to":5,"stable_key":"shields-and-bucklers:6.1","parent_key":"shields-and-bucklers:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ea9f298d2c430db7edacedd3192650d81e8e0987ab48c20ba06428ae6380f79c","has_figures":true,"extraction":"ocr"},{"ordinal":9,"depth":1,"kind":"rule","number":"6.2","title":"Specific Requirements","body":"Heater Shields must:\n\n● conform to the General Requirements and Wooden Shield requirements (see Sections 3 and 4 above),\n\n● be made of wood,\n\n● have a rectangular shape with a pointy shape at the bottom:\n\n● becurved, not flat:\n\n4 mK\n\n● have a length of 55 cm to 75 cm,\n\n● have a width of 30 cm to 65 cm,\n\n● have handles made of leather:\nExample:\n\nPicture from O. Haguenstein ©\n\nIt is allowed to add a Shield boss (umbo) on a Heater Shield with a central handle, as documented by historical sources.\n\nCentral handles must be made of wood.","page_from":6,"page_to":6,"stable_key":"shields-and-bucklers:6.2","parent_key":"shields-and-bucklers:6","review_status":"needs_review","review_note":"OCR could not read some words with confidence: rectangular, Example:","topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"659625e6b716095c9ddb1d3bc077f9150e01ba804b766897b3106d1970beaa6d","has_figures":true,"extraction":"ocr"},{"ordinal":10,"depth":1,"kind":"rule","number":"6.3","title":"Examples of Approved Reproductions","body":"Pictures from The Medieval Things ©","page_from":7,"page_to":7,"stable_key":"shields-and-bucklers:6.3","parent_key":"shields-and-bucklers:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4f1cd9b5432108c0555278d395c5d5f4631b90033f061a2d1771b9e116698028","has_figures":true,"extraction":"ocr"},{"ordinal":11,"depth":1,"kind":"rule","number":"6.4","title":"Examples of Reproductions","body":"This shape (oval) is not based on historical sources for Shield with a central handle.\n\nPicture from The Medieval Things ©","page_from":7,"page_to":7,"stable_key":"shields-and-bucklers:6.4","parent_key":"shields-and-bucklers:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c3dcbb4305fe9772942b60b19e479e3d0a148611a586a9cf1dbf350ddd84d1d8","has_figures":true,"extraction":"ocr"},{"ordinal":12,"depth":0,"kind":"section","number":"7","title":"Punch Shields","body":"","page_from":8,"page_to":8,"stable_key":"shields-and-bucklers:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"792203dbdde516f31e936f10edb96cbbcf6169d2a31d91e7644c7d4ea1eb638c","has_figures":true,"extraction":"ocr"},{"ordinal":13,"depth":1,"kind":"rule","number":"7.1","title":"Historical Sources and Datation","body":"Punch Shields are designed to strike with the edge. The handles and straps allow you to wear them ina striking position. Their shape may vary depending on the time and place. Most common shapes are rectangular, trapezoid and oval.\n\nTheir ultimate evolution is the Pavese of the 15th century. This type of Shield has a rectangular shape and a gutter in the middle.\n\nAll shapes except the Pavese are Approved for 14th century, Transitional and 15th century armors.\nPavese shape is Approved for 15th century armors.\nPavese shape is Denied for 14th century and Transitional armors.\n\nCastello di Avio - 1350 - Italy\n\nShield of Order Teutonicus Great Master - 1320 - Germany\n\nPavese shape with gutter in the middle\n\nDeutsches Historisches Museum (Berlin) - 1480 - Germany Wien Museum -\n\n1480 - Austria\n\nPaduan Bible - 1400 - Italy","page_from":8,"page_to":9,"stable_key":"shields-and-bucklers:7.1","parent_key":"shields-and-bucklers:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e742c5f53a732a6d2a08ceb8bc98bc10b9ce7221e568e21caa46cbd043f6d867","has_figures":true,"extraction":"ocr"},{"ordinal":14,"depth":1,"kind":"rule","number":"7.2","title":"Specific Requirements","body":"Punch Shield must:\n\n● conform to the General Requirements and Wooden Shield requirements (see Sections 3 and 4 above),\n\n● be made of wood,\n\n● have a shape rectangular, oval or pointed:\n\n700 000\n\n● becurved, not flat:\n\n○ Except for Pavese shape, that can be flat if they conform to historical designs:\n\n● have a length of 55 cm to 75 cm,\n● have a width of 30 cm to 50 cm,\n● have handles made of leather (see example in 6.2. Punch Shield).\n\nThe striking area can be rounded or flat.\nThe rounded striking area must conform to a curve of 7 cm diameter.\nFlat striking area must be 7 cm wide as a minimum.\n\nIt is not allowed to add a Shield boss (umbo) on a Punch Shield.\nIt is allowed to add a metal sheet on the Shield to increase its resilience. In this case:\n\n● Additional metal sheets must be covered by leather or fabric as another part of the outside of the Shield.\n\n● Additional metal sheets must have no sharp edges nor pointy parts.\n\n● Additional metal sheets must be properly attached to the wooden core of the Shield, by rivets, nails or strong glue.","page_from":10,"page_to":11,"stable_key":"shields-and-bucklers:7.2","parent_key":"shields-and-bucklers:7","review_status":"needs_review","review_note":"OCR could not read some words with confidence: shape, length","topics":[],"keywords":[],"cross_refs":["3","6.2"],"content_sha256":"4302c7104b4dc52964e0348cb66eb214926d319b3250b15dfd60678e8046ea5c","has_figures":true,"extraction":"ocr"},{"ordinal":15,"depth":1,"kind":"rule","number":"7.3","title":"Examples of Approved Reproductions","body":"Pictures from The Medieval Things ©","page_from":11,"page_to":12,"stable_key":"shields-and-bucklers:7.3","parent_key":"shields-and-bucklers:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"517cefe2f22b30fd1ef599996381df272eeb5b23dcef2ea2bbe33af6090248b9","has_figures":true,"extraction":"ocr"},{"ordinal":16,"depth":1,"kind":"rule","number":"7.4","title":"Examples of Denied Reproductions","body":"Flat Shield\n\nAbsence of leather or 3 layers of fabric on the edge\n\nPictures from The Medieval Things ©","page_from":13,"page_to":13,"stable_key":"shields-and-bucklers:7.4","parent_key":"shields-and-bucklers:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"dd9f26a633aa8e96861618576aed40dfd4fc6c2fc10df1d671e78bf9cb48db86","has_figures":true,"extraction":"ocr"},{"ordinal":17,"depth":0,"kind":"section","number":"8","title":"Round Shields","body":"","page_from":14,"page_to":14,"stable_key":"shields-and-bucklers:8","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a42d52ceba6fbf7f81727c933c40e18c0b0cc60fb9ce0516ebb1b9c262f42d9e","has_figures":true,"extraction":"ocr"},{"ordinal":18,"depth":1,"kind":"rule","number":"8.1","title":"Historical Sources and Datation","body":"Round Shields were very common in the early 14th century, and became rare while other designs spread.\nThey are mainly made of wood. Some examples of metal round Shields exist but they are parade Shields and should be worn only with the proper set of armor of the late 15th century.\n\nRound Shields are worn with straps made of leather.\nThey are Approved for 14th century and Transitional armors.\nThey are Denied for 15th century armors unless historical sources are provided.\n\nRoman de la Rose - 1350 - France\n\nCathedral of Strasbourg - 1340 - France","page_from":14,"page_to":14,"stable_key":"shields-and-bucklers:8.1","parent_key":"shields-and-bucklers:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d5cd3a3d92cd8bf5fcfd866d6406aec5c4c0a5e9305b7b6fb93c20d6004cc882","has_figures":true,"extraction":"ocr"},{"ordinal":19,"depth":1,"kind":"rule","number":"8.2","title":"Specific Requirements","body":"Round Shield must:\n\n● conform to the General Requirements and either the Wooden Shield Requirements or the Metal Shield Requirements (see Sections 3, 4 and 5 above),\n● be made of wood or metal, ○ Any metal Round Shields must be approved by the Authenticity Committee to be allowed in Buhurt International events.\n● have a diameter:\n○ for Buhurt: from 25 cm to 70 cm, ○ for Duels: from 25 cm to 35 cm,\n● be flat or have a concave curve,\n● have handles made of leather (see example in 6.2. Punch Shield).\n\nIt is not allowed to add a Shield boss (umbo) on a Round Shield unless documented by historical sources.","page_from":14,"page_to":14,"stable_key":"shields-and-bucklers:8.2","parent_key":"shields-and-bucklers:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3","6.2"],"content_sha256":"ec9ae426c1a283e12f08e9b22025313e3d95eb937641707f49f0bd28660e7869","has_figures":true,"extraction":"ocr"},{"ordinal":20,"depth":1,"kind":"rule","number":"8.3","title":"Examples of Approved Reproductions","body":"Pictures from The Medieval Things ©","page_from":15,"page_to":15,"stable_key":"shields-and-bucklers:8.3","parent_key":"shields-and-bucklers:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ddc2d3bcb465208219c2ed2be320328c0155cbeb5ad60af4701054a023ad723a","has_figures":true,"extraction":"ocr"},{"ordinal":21,"depth":1,"kind":"rule","number":"8.4","title":"Examples of Reproductions","body":"Round Shield with Shield boss (umbo)","page_from":15,"page_to":15,"stable_key":"shields-and-bucklers:8.4","parent_key":"shields-and-bucklers:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"32121b3a406691175fdf56a052868b7f811d10559c958bb81867d2ffcfdc4fde","has_figures":true,"extraction":"ocr"},{"ordinal":22,"depth":0,"kind":"section","number":"9","title":"Bucklers","body":"","page_from":16,"page_to":16,"stable_key":"shields-and-bucklers:9","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1cde0147c799cce7f9727ae6ca36fd4aad1af1d643aef5f1615ad50e0f7eed9d","has_figures":true,"extraction":"ocr"},{"ordinal":23,"depth":1,"kind":"rule","number":"9.1","title":"Historical Sources and Datation","body":"Bucklers are small round Shields made of wood or metal. They do not have straps but a rigid handle and a Shield boss (umbo).\n\nThey are Approved for 14th century, Transitional and 15th century armors.\n\nWeltchronik in Versen - 1370 - Germany","page_from":16,"page_to":16,"stable_key":"shields-and-bucklers:9.1","parent_key":"shields-and-bucklers:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d9372ed82e340b88ec11f6f9bf3345e870b40e94f37f5d3de35b4b1332cb2642","has_figures":true,"extraction":"ocr"},{"ordinal":24,"depth":1,"kind":"rule","number":"9.2","title":"Specific Requirements","body":"Bucklers must:\n\n● conform to the General Requirements and either the Wooden Shield Requirements or the Metal Shield Requirements (see Sections 3, 4 and 5 above),\n● be made of wood or metal,\n● have a Shield boss (umbo):\n○ Shield boss must be made of metal.\n○ Shield boss can be riveted or forged.\n● have a diameter:\n○ for Buhurt: from 20 cm to 40 cm, ○ for Duels: from 20 cm to 35 cm,\n● be flat or curved depending on historical sources.\n\nIf the Buckler is made of wood, the handle must be made of wood.\n\nIf the Buckler is made of metal, the handle must be made of metal.\nA strap can be added to secure the Buckler in punch position. This strap must be made of leather.","page_from":16,"page_to":16,"stable_key":"shields-and-bucklers:9.2","parent_key":"shields-and-bucklers:9","review_status":"needs_review","review_note":"OCR could not read some words with confidence: diameter:","topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"522865d7fb6458e378398fa02f7d7303240c7844e9a6d72f47d728952d0f044d","has_figures":true,"extraction":"ocr"},{"ordinal":25,"depth":1,"kind":"rule","number":"9.3","title":"Examples of Reproductions","body":"Forged shield boss Riveted shield boss Reinforced buckler with cross\n\nPicture from Black Dog Armoury ©\n\nWooden Buckler Picture from The Medieval Things © Additional leather strap\n\nPicture from Medieval Extreme ©","page_from":17,"page_to":17,"stable_key":"shields-and-bucklers:9.3","parent_key":"shields-and-bucklers:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"288fa4c331e52c07949e1cdbc370aaa84a4eac1f12cb1e3882a96dba9bdb8998","has_figures":true,"extraction":"ocr"},{"ordinal":26,"depth":1,"kind":"rule","number":"9.4","title":"Examples of Denied Reproductions","body":"Black painting is not allowed as per “Armors and Weapons\n\nAesthetics and Decoration” document.\n\nPicture from The Medieval Things ©","page_from":17,"page_to":17,"stable_key":"shields-and-bucklers:9.4","parent_key":"shields-and-bucklers:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2c98585ad0be65463cec9e63b1faad57cedde902629c4eb49590c6ed96ad5b17","has_figures":true,"extraction":"ocr"},{"ordinal":27,"depth":0,"kind":"section","number":"10","title":"Fastening Systems","body":"","page_from":18,"page_to":18,"stable_key":"shields-and-bucklers:10","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ceefbd5d8215caa7f16c8685313424a3e8e149fb3970aca9844f09c4e971e7fe","has_figures":true,"extraction":"ocr"},{"ordinal":28,"depth":1,"kind":"rule","number":"10.1","title":"Historical Sources and Datation","body":"Leather straps were fastened with nails or rivets.\nThe following methods are Approved for 14th century, Transitional and 15th century armors:\n\n● nails,\n● rivets,\n● modern nuts and bolts.\n\nExamples:\n\nRivet with metal plate Pictures from Black Dog Armoury ©","page_from":18,"page_to":18,"stable_key":"shields-and-bucklers:10.1","parent_key":"shields-and-bucklers:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e734dda388a8194ebc0544e405866c16edf668de3ac09973c72af10e7d2cdd91","has_figures":true,"extraction":"ocr"},{"ordinal":29,"depth":1,"kind":"rule","number":"10.2","title":"Specific requirements","body":"Nails and rivets can be left visible.\nModern nuts and bolts must be concealed by one of the following methods:\n\n● Covered by a piece of leather nailed to the Shield.\n● Painted in black or any other color to make it concealed.\n● Hexagonal unpainted bolts must be ground to a rounded shape, replicating a rivet aesthetic.\n\nBolts must not protrude from the nuts.","page_from":18,"page_to":18,"stable_key":"shields-and-bucklers:10.2","parent_key":"shields-and-bucklers:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"dd01f40374759d4b344c7a34b86b80ea9eb7306480a57b5a16883a10de236f02","has_figures":true,"extraction":"ocr"},{"ordinal":30,"depth":1,"kind":"rule","number":"10.3","title":"Examples of Approved Systems","body":"Rivets can be visible Modern nuts and bolts, painted black\n\nPictures from Medieval Extreme ©","page_from":18,"page_to":18,"stable_key":"shields-and-bucklers:10.3","parent_key":"shields-and-bucklers:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1d43011b06f4514a1046a49ab80787b490be1e3bde01b4a05b35d9a27e06b831","has_figures":true,"extraction":"ocr"},{"ordinal":31,"depth":0,"kind":"note","number":"11","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nJanuary - 2026 (V. 26.1) Formatting redone for consistency and readability. Except points listed below, no content changes.\n\nAdd:\n\n- “1. Implementation” (and subsequent modification of all Title numbers in the document) Clarification:\n\n- Split of “1. Definition and general requirements” in “2. Definition” and “3. General Requirements’.\n- From 1.1. to “4. Wooden Shields requirements” and 1.2. to “5. Metal Shields Requirements”.\n\n- This doesn’t have an impact on the content of the rules.\n\nAdd: “41. Implementation” (and subsequent modification of all Title numbers in the document)\n\n- Modification of diameters for Round shields and Bucklers depending on the type of fight.\n\nMarch-2025 (V2025.02)\n- Clarification : 6.2\n- format: Grammar and Formatting\n\nDecember-2024: Add Document has been created","page_from":19,"page_to":19,"stable_key":"shields-and-bucklers:11","parent_key":null,"review_status":"needs_review","review_note":"OCR could not read some words with confidence: Requirements”., Add","topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"c224e47b9d69fa4b4cc0d7f679370fbc40b7a9de9e03753410919395b639e316","has_figures":false,"extraction":"ocr"}]}$rules$::jsonb);
select private.rules_import_historical_version($rules${"governing_body":"Buhurt International","history":"archive-2026-10-06","inventory_key":"authenticity/shields-and-bucklers","version":{"version":"26.2","title":"Shields and Bucklers 26.2","published_on":null,"effective_from":null,"note":"Title \"Shields and Bucklers 26.2\"; cover \"VER. 26.2\"; change log \"February - 2026 (V. 26.2)\" above \"January - 2026 (V. 26.1)\". Older than the current 26.4.","source_url":"https://drive.google.com/file/d/1x86P3YbsAZPqIZSjWCBVGvDpJyqz3ZXm/view","source_sha256":"c55557f38036e9a6e6914f88f44bc0f779272ada71cb290c6c7dd1de5fb5e3cb","retrieved_at":null,"page_count":19,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 19 page(s) without a text layer","content_sha256":"032d1e9ac37ad572255c5d321a9c77d86dd34c93ab615f097fca90962273b3be","detected":{"version":"26.2","date":null},"confirmed_by":"Claude Code (Pack 22 historical import), read from the archived PDF: cover (OCR of the page image), footers and change log","historical":true,"edition_seq":3,"edition_evidence":"Title \"Shields and Bucklers 26.2\"; cover \"VER. 26.2\"; change log \"February - 2026 (V. 26.2)\" above \"January - 2026 (V. 26.1)\". Older than the current 26.4.","source_files":[{"file":"Authenticity/Archive/Shields_and_Bucklers V26.2.pdf","archive":"Authenticity","sha256":"c55557f38036e9a6e6914f88f44bc0f779272ada71cb290c6c7dd1de5fb5e3cb","drive_file_id":"1x86P3YbsAZPqIZSjWCBVGvDpJyqz3ZXm"}],"reconciliation":{"ok":true,"errors":[],"warnings":["1 line(s) looked like a numbered heading but did not fit the sequence","5 provision(s) need review against the official document"],"pages":19,"source_lines":299,"assigned_lines":395,"furniture_lines":65,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99617,"provisions":31,"numbered":30,"needs_review":5,"verified":0,"empty_pages":[],"rejected_numbers":1,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":299,"picture_text_lines":16,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 26.2\n\nAuthenticity","page_from":1,"page_to":1,"stable_key":"shields-and-bucklers:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"37a828ad8cb950a04ee1323f8779341d0e2faa45dc10269e2a570464a4847869","has_figures":true,"extraction":"ocr"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Implementation","body":"The document has been created and approved by the General Assembly of 09.11.2024.\nThe document and its rules have been implemented since the 2025 season.","page_from":3,"page_to":3,"stable_key":"shields-and-bucklers:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7e35b5946ae02907f8e065d2e3656f914639f40e08c6eb5efd4d1160c27157d4","has_figures":false,"extraction":"ocr"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Definition","body":"“Shields and Bucklers” are the terms used to describe every protection made of wood or steel and designed to protect yourself.\n\nShields and Bucklers can be:\n● Heater Shields\n\nShields made of triangular shape, the most common shape of Shields from the Xlllth century and beyond. They must be made of wood.\n\n● Punch Shields\n\nPunch Shields are primarily designed to hit the opponent. It includes a wide variety of shapes. They must be made of wood.\n\n● Round Shields\n\nShields made of a round shape, very common throughout the middle ages. They can be made of wood or metal.\n\n● Bucklers\n\nSmall round shape Shields with central handle, mainly used in duels and as a secondary equipment for close defense. They can be made of wood or metal.","page_from":3,"page_to":3,"stable_key":"shields-and-bucklers:2","parent_key":null,"review_status":"needs_review","review_note":"OCR could not read some words with confidence: Xlllth","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"379b34960550afdc75748351f8b549197c50692177fd8e8e4d1ae1cadfabd9c3","has_figures":false,"extraction":"ocr"},{"ordinal":4,"depth":0,"kind":"section","number":"3","title":"General Requirements","body":"All types of Shields and Bucklers must respect the following requirements:\n\n● be based on historical sources,\n\n● must reproduce the proportions and curves based on historical sources,\n\n● must be made of wood or metal. Any other material must be approved by the Authenticity Committee to be allowed in Buhurt International events,\n\n● must match the style of the armor kit of the competitor.\n\nAll images, drawings, and paintings on Shields must be stylized in accordance with the style of the armor kit of the competitor.\n\nIt is prohibited to decorate Shields and Bucklers with images that are clearly modern and/or offensive.\nThe weight of all Shields and Bucklers must not exceed 5 kg.\nIt is allowed to use bolts and nuts to fasten straps:\n\n● nuts must not protrude the screw,\n● bolts and nuts must be painted in black or concealed with leather or fabric.\n\nAll straps must be made of leather.\n\nAny metal part of the Shield or Buckler must conform to the “Armors and Weapons Aesthetics and Decorations’ document.\n\nAny textile or leather part of the Shield or Buckler must conform to the “Textiles and Leather’ document.","page_from":3,"page_to":3,"stable_key":"shields-and-bucklers:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"72ccab3c89692eea93f993b5b60201f9b323ffb1b07d298e0f9bf53673e95bd9","has_figures":false,"extraction":"ocr"},{"ordinal":5,"depth":0,"kind":"section","number":"4","title":"Wooden Shields Requirements","body":"The entire edge must be covered with either a band of strong leather, or with at least three or more layers of fabric.\n\nA leather band must be glued, sewn or riveted, to the Shield. Any rivets must be neatly finished, the edge of the rivet should not stick out.\n\nThe flat outside a wooden Shield must be covered with leather or fabric.\nThe handles must be made of leather.\nWooden Buckler and Heater Shield with a central handle must have a handle made of wood.\n\nShield boss (umbo) made of metal must conform to the “Armors and Weapons Aesthetics and Decorations” document.","page_from":4,"page_to":4,"stable_key":"shields-and-bucklers:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4801800788ab335f337b7da8ed31d182b51ef4003e6aebad70ed825b32a01970","has_figures":true,"extraction":"ocr"},{"ordinal":6,"depth":0,"kind":"section","number":"5","title":"Metal Shields Requirements","body":"Must be of round shapes, based on historical sources, and repeat the form of the original in all three dimensions.\n\nThe entire edge of metal Shields must be rolled to the thickness of a minimum of 4 mm or more.\nThe handles must be made of metal and or wood\n\nMetal Shield and Shield boss (umbo) must conform to the “Armors and Weapons Aesthetics and Decorations” document.\n\nIt is allowed to blacken the back part of a metal Shield or metal Buckler.\nExample:\n\nPicture from O. Haguenstein ©","page_from":4,"page_to":4,"stable_key":"shields-and-bucklers:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"01f6ec246c76424d25cd9a7709b1a250dc8917523bf992a5017f998b1535368b","has_figures":true,"extraction":"ocr"},{"ordinal":7,"depth":0,"kind":"section","number":"6","title":"Heater Shields","body":"","page_from":5,"page_to":5,"stable_key":"shields-and-bucklers:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"19a588ef6abd5379334147570c2e633975db534de166b4fd52de2bac7449636d","has_figures":true,"extraction":"ocr"},{"ordinal":8,"depth":1,"kind":"rule","number":"6.1","title":"Historical Sources and Datation","body":"The Heater Shield the main Shield shape for knights of the Middle Ages. Its triangular shape is typical of the 14th century. The shape goes thinner as the armors become more effective.\n\nThey are Approved for 14th century, Transitional and 15th century armors.\n\nShield of Loew von Steinfurth - 1380 - Germany Grande Chroniques de France - 1400 - France\n\nPolitica & Economica - 1376 - France Ab Urbe Condita - 1390/1400 - France","page_from":5,"page_to":5,"stable_key":"shields-and-bucklers:6.1","parent_key":"shields-and-bucklers:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ea9f298d2c430db7edacedd3192650d81e8e0987ab48c20ba06428ae6380f79c","has_figures":true,"extraction":"ocr"},{"ordinal":9,"depth":1,"kind":"rule","number":"6.2","title":"Specific Requirements","body":"Heater Shields must:\n\n● conform to the General Requirements and Wooden Shield requirements (see Sections 3 and 4 above),\n\n● be made of wood,\n\n● have a rectangular shape with a pointy shape at the bottom:\n\n● becurved, not flat:\n\n4 mK\n\n● have a length of 55 cm to 75 cm,\n\n● have a width of 30 cm to 65 cm,\n\n● have handles made of leather:\nExample:\n\nPicture from O. Haguenstein ©\n\nIt is allowed to add a Shield boss (umbo) on a Heater Shield with a central handle, as documented by historical sources.\n\nCentral handles must be made of wood.","page_from":6,"page_to":6,"stable_key":"shields-and-bucklers:6.2","parent_key":"shields-and-bucklers:6","review_status":"needs_review","review_note":"OCR could not read some words with confidence: rectangular, Example:","topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"659625e6b716095c9ddb1d3bc077f9150e01ba804b766897b3106d1970beaa6d","has_figures":true,"extraction":"ocr"},{"ordinal":10,"depth":1,"kind":"rule","number":"6.3","title":"Examples of Approved Reproductions","body":"Pictures from The Medieval Things ©","page_from":7,"page_to":7,"stable_key":"shields-and-bucklers:6.3","parent_key":"shields-and-bucklers:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4f1cd9b5432108c0555278d395c5d5f4631b90033f061a2d1771b9e116698028","has_figures":true,"extraction":"ocr"},{"ordinal":11,"depth":1,"kind":"rule","number":"6.4","title":"Examples of Reproductions","body":"This shape (oval) is not based on historical sources for Shield with a central handle.\n\nPicture from The Medieval Things ©","page_from":7,"page_to":7,"stable_key":"shields-and-bucklers:6.4","parent_key":"shields-and-bucklers:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c3dcbb4305fe9772942b60b19e479e3d0a148611a586a9cf1dbf350ddd84d1d8","has_figures":true,"extraction":"ocr"},{"ordinal":12,"depth":0,"kind":"section","number":"7","title":"Punch Shields","body":"","page_from":8,"page_to":8,"stable_key":"shields-and-bucklers:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"792203dbdde516f31e936f10edb96cbbcf6169d2a31d91e7644c7d4ea1eb638c","has_figures":true,"extraction":"ocr"},{"ordinal":13,"depth":1,"kind":"rule","number":"7.1","title":"Historical Sources and Datation","body":"Punch Shields are designed to strike with the edge. The handles and straps allow you to wear them ina striking position. Their shape may vary depending on the time and place. Most common shapes are rectangular, trapezoid and oval.\n\nTheir ultimate evolution is the Pavese of the 15th century. This type of Shield has a rectangular shape and a gutter in the middle.\n\nAll shapes except the Pavese are Approved for 14th century, Transitional and 15th century armors.\nPavese shape is Approved for 15th century armors.\nPavese shape is Denied for 14th century and Transitional armors.\n\nCastello di Avio - 1350 - Italy\n\nShield of Order Teutonicus Great Master - 1320 - Germany\n\nPavese shape with gutter in the middle\n\nDeutsches Historisches Museum (Berlin) - 1480 - Germany Wien Museum -\n\n1480 - Austria\n\nPaduan Bible - 1400 - Italy","page_from":8,"page_to":9,"stable_key":"shields-and-bucklers:7.1","parent_key":"shields-and-bucklers:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e742c5f53a732a6d2a08ceb8bc98bc10b9ce7221e568e21caa46cbd043f6d867","has_figures":true,"extraction":"ocr"},{"ordinal":14,"depth":1,"kind":"rule","number":"7.2","title":"Specific Requirements","body":"Punch Shield must:\n\n● conform to the General Requirements and Wooden Shield requirements (see Sections 3 and 4 above),\n\n● be made of wood,\n\n● have a shape rectangular, oval or pointed:\n\n700 000\n\n● becurved, not flat:\n\n○ Except for Pavese shape, that can be flat if they conform to historical designs:\n\n● have a length of 55 cm to 75 cm,\n● have a width of 30 cm to 50 cm,\n● have handles made of leather (see example in 6.2. Punch Shield).\n\nThe striking area can be rounded or flat.\nThe rounded striking area must conform to a curve of 7 cm diameter.\nFlat striking area must be 7 cm wide as a minimum.\n\nIt is not allowed to add a Shield boss (umbo) on a Punch Shield.\nIt is allowed to add a metal sheet on the Shield to increase its resilience. In this case:\n\n● Additional metal sheets must be covered by leather or fabric as another part of the outside of the Shield.\n\n● Additional metal sheets must have no sharp edges nor pointy parts.\n\n● Additional metal sheets must be properly attached to the wooden core of the Shield, by rivets, nails or strong glue.","page_from":10,"page_to":11,"stable_key":"shields-and-bucklers:7.2","parent_key":"shields-and-bucklers:7","review_status":"needs_review","review_note":"OCR could not read some words with confidence: shape, length","topics":[],"keywords":[],"cross_refs":["3","6.2"],"content_sha256":"4302c7104b4dc52964e0348cb66eb214926d319b3250b15dfd60678e8046ea5c","has_figures":true,"extraction":"ocr"},{"ordinal":15,"depth":1,"kind":"rule","number":"7.3","title":"Examples of Approved Reproductions","body":"Pictures from The Medieval Things ©","page_from":11,"page_to":12,"stable_key":"shields-and-bucklers:7.3","parent_key":"shields-and-bucklers:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"517cefe2f22b30fd1ef599996381df272eeb5b23dcef2ea2bbe33af6090248b9","has_figures":true,"extraction":"ocr"},{"ordinal":16,"depth":1,"kind":"rule","number":"7.4","title":"Examples of Denied Reproductions","body":"Flat Shield\n\nAbsence of leather or 3 layers of fabric on the edge\n\nPictures from The Medieval Things ©","page_from":13,"page_to":13,"stable_key":"shields-and-bucklers:7.4","parent_key":"shields-and-bucklers:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"dd9f26a633aa8e96861618576aed40dfd4fc6c2fc10df1d671e78bf9cb48db86","has_figures":true,"extraction":"ocr"},{"ordinal":17,"depth":0,"kind":"section","number":"8","title":"Round Shields","body":"","page_from":14,"page_to":14,"stable_key":"shields-and-bucklers:8","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a42d52ceba6fbf7f81727c933c40e18c0b0cc60fb9ce0516ebb1b9c262f42d9e","has_figures":true,"extraction":"ocr"},{"ordinal":18,"depth":1,"kind":"rule","number":"8.1","title":"Historical Sources and Datation","body":"Round Shields were very common in the early 14th century, and became rare while other designs spread.\nThey are mainly made of wood. Some examples of metal round Shields exist but they are parade Shields and should be worn only with the proper set of armor of the late 15th century.\n\nRound Shields are worn with straps made of leather.\nThey are Approved for 14th century and Transitional armors.\nThey are Denied for 15th century armors unless historical sources are provided.\n\nRoman de la Rose - 1350 - France\n\nCathedral of Strasbourg - 1340 - France","page_from":14,"page_to":14,"stable_key":"shields-and-bucklers:8.1","parent_key":"shields-and-bucklers:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d5cd3a3d92cd8bf5fcfd866d6406aec5c4c0a5e9305b7b6fb93c20d6004cc882","has_figures":true,"extraction":"ocr"},{"ordinal":19,"depth":1,"kind":"rule","number":"8.2","title":"Specific Requirements","body":"Round Shield must:\n\n● conform to the General Requirements and either the Wooden Shield Requirements or the Metal Shield Requirements (see Sections 3, 4 and 5 above),\n● be made of wood or metal, ○ Any metal Round Shields must be approved by the Authenticity Committee to be allowed in Buhurt International events.\n● have a diameter:\n○ for Sword and Buckler (Duel): from 25 cm to 35 cm, ○ for Buhurt and Sword and Shield (Duel): from 25 cm to 70 cm,\n● be flat or have a concave curve,\n● have handles made of leather (see example in 6.2. Punch Shield).\n\nIt is not allowed to add a Shield boss (umbo) on a Round Shield unless documented by historical sources.","page_from":14,"page_to":14,"stable_key":"shields-and-bucklers:8.2","parent_key":"shields-and-bucklers:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3","6.2"],"content_sha256":"8b95168f6b4c5b014ad573c1b60955a4e8e420ec07bff49659c5e20d033ac365","has_figures":true,"extraction":"ocr"},{"ordinal":20,"depth":1,"kind":"rule","number":"8.3","title":"Examples of Approved Reproductions","body":"Pictures from The Medieval Things ©","page_from":15,"page_to":15,"stable_key":"shields-and-bucklers:8.3","parent_key":"shields-and-bucklers:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ddc2d3bcb465208219c2ed2be320328c0155cbeb5ad60af4701054a023ad723a","has_figures":true,"extraction":"ocr"},{"ordinal":21,"depth":1,"kind":"rule","number":"8.4","title":"Examples of Reproductions","body":"Round Shield with Shield boss (umbo)","page_from":15,"page_to":15,"stable_key":"shields-and-bucklers:8.4","parent_key":"shields-and-bucklers:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"32121b3a406691175fdf56a052868b7f811d10559c958bb81867d2ffcfdc4fde","has_figures":true,"extraction":"ocr"},{"ordinal":22,"depth":0,"kind":"section","number":"9","title":"Bucklers","body":"","page_from":16,"page_to":16,"stable_key":"shields-and-bucklers:9","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1cde0147c799cce7f9727ae6ca36fd4aad1af1d643aef5f1615ad50e0f7eed9d","has_figures":true,"extraction":"ocr"},{"ordinal":23,"depth":1,"kind":"rule","number":"9.1","title":"Historical Sources and Datation","body":"Bucklers are small round Shields made of wood or metal. They do not have straps but a rigid handle and a Shield boss (umbo).\n\nThey are Approved for 14th century, Transitional and 15th century armors.\n\nWeltchronik in Versen - 1370 - Germany","page_from":16,"page_to":16,"stable_key":"shields-and-bucklers:9.1","parent_key":"shields-and-bucklers:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d9372ed82e340b88ec11f6f9bf3345e870b40e94f37f5d3de35b4b1332cb2642","has_figures":true,"extraction":"ocr"},{"ordinal":24,"depth":1,"kind":"rule","number":"9.2","title":"Specific Requirements","body":"Bucklers must:\n\n● conform to the General Requirements and either the Wooden Shield Requirements or the Metal Shield Requirements (see Sections 3, 4 and 5 above),\n● be made of wood or metal,\n● have a Shield boss (umbo):\n○ Shield boss must be made of metal.\n○ Shield boss can be riveted or forged.\n● have a diameter:\n○ for Buhurt: from 20 cm to 40 cm, ○ for Duels: from 20 cm to 35 cm,\n● be flat or curved depending on historical sources.\n\nIf the Buckler is made of wood, the handle must be made of wood.\n\nIf the Buckler is made of metal, the handle must be made of metal.\nA strap can be added to secure the Buckler in punch position. This strap must be made of leather.","page_from":16,"page_to":16,"stable_key":"shields-and-bucklers:9.2","parent_key":"shields-and-bucklers:9","review_status":"needs_review","review_note":"OCR could not read some words with confidence: diameter:","topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"522865d7fb6458e378398fa02f7d7303240c7844e9a6d72f47d728952d0f044d","has_figures":true,"extraction":"ocr"},{"ordinal":25,"depth":1,"kind":"rule","number":"9.3","title":"Examples of Reproductions","body":"Forged shield boss Riveted shield boss Reinforced buckler with cross\n\nPicture from Black Dog Armoury ©\n\nWooden Buckler Picture from The Medieval Things © Additional leather strap\n\nPicture from Medieval Extreme ©","page_from":17,"page_to":17,"stable_key":"shields-and-bucklers:9.3","parent_key":"shields-and-bucklers:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"288fa4c331e52c07949e1cdbc370aaa84a4eac1f12cb1e3882a96dba9bdb8998","has_figures":true,"extraction":"ocr"},{"ordinal":26,"depth":1,"kind":"rule","number":"9.4","title":"Examples of Denied Reproductions","body":"Black painting is not allowed as per “Armors and Weapons\n\nAesthetics and Decoration” document.\n\nPicture from The Medieval Things ©","page_from":17,"page_to":17,"stable_key":"shields-and-bucklers:9.4","parent_key":"shields-and-bucklers:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2c98585ad0be65463cec9e63b1faad57cedde902629c4eb49590c6ed96ad5b17","has_figures":true,"extraction":"ocr"},{"ordinal":27,"depth":0,"kind":"section","number":"10","title":"Fastening Systems","body":"","page_from":18,"page_to":18,"stable_key":"shields-and-bucklers:10","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ceefbd5d8215caa7f16c8685313424a3e8e149fb3970aca9844f09c4e971e7fe","has_figures":true,"extraction":"ocr"},{"ordinal":28,"depth":1,"kind":"rule","number":"10.1","title":"Historical Sources and Datation","body":"Leather straps were fastened with nails or rivets.\nThe following methods are Approved for 14th century, Transitional and 15th century armors:\n\n● nails,\n● rivets,\n● modern nuts and bolts.\n\nExamples:\n\nRivet with metal plate Pictures from Black Dog Armoury ©","page_from":18,"page_to":18,"stable_key":"shields-and-bucklers:10.1","parent_key":"shields-and-bucklers:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e734dda388a8194ebc0544e405866c16edf668de3ac09973c72af10e7d2cdd91","has_figures":true,"extraction":"ocr"},{"ordinal":29,"depth":1,"kind":"rule","number":"10.2","title":"Specific requirements","body":"Nails and rivets can be left visible.\nModern nuts and bolts must be concealed by one of the following methods:\n\n● Covered by a piece of leather nailed to the Shield.\n● Painted in black or any other color to make it concealed.\n● Hexagonal unpainted bolts must be ground to a rounded shape, replicating a rivet aesthetic.\n\nBolts must not protrude from the nuts.","page_from":18,"page_to":18,"stable_key":"shields-and-bucklers:10.2","parent_key":"shields-and-bucklers:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"dd01f40374759d4b344c7a34b86b80ea9eb7306480a57b5a16883a10de236f02","has_figures":true,"extraction":"ocr"},{"ordinal":30,"depth":1,"kind":"rule","number":"10.3","title":"Examples of Approved Systems","body":"Rivets can be visible Modern nuts and bolts, painted black\n\nPictures from Medieval Extreme ©","page_from":18,"page_to":18,"stable_key":"shields-and-bucklers:10.3","parent_key":"shields-and-bucklers:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1d43011b06f4514a1046a49ab80787b490be1e3bde01b4a05b35d9a27e06b831","has_figures":true,"extraction":"ocr"},{"ordinal":31,"depth":0,"kind":"note","number":"11","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nFebruary - 2026 (V. 26.2) Change:\n\n- 8.2 “Specific Requirements” of Round Shields: Maximum diameter changed from 35 to 70 cm for Sword and Shield (Duel).\n\nJanuary - 2026 (V. 26.1) Formatting redone for consistency and readability. Except points listed below, no content changes.\n\nAdd:\n\n- “41. Implementation” (and subsequent modification of all Title numbers in the document) Clarification:\n\n- Split of “1. Definition and general requirements” in “2. Definition” and “3. General Requirements”.\n- From 1.1. to “4. Wooden Shields requirements” and 1.2. to “5. Metal Shields Requirements’.\n\n- This doesn’t have an impact on the content of the rules.\n\nAdd: “1. Implementation” (and subsequent modification of all Title numbers in the document)\n\n- Modification of diameters for Round shields and Bucklers depending on the type of fight.\n\nMarch-2025 (V2025.02)\n- Clarification : 6.2\n- format: Grammar and Formatting\n\nDecember-2024: SAdd Document has been created","page_from":19,"page_to":19,"stable_key":"shields-and-bucklers:11","parent_key":null,"review_status":"needs_review","review_note":"OCR could not read some words with confidence: Title, SAdd","topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"284a6e9885ad87a2f6ec14a305910f1566d2ec54e6cf385a39e9f492186ed260","has_figures":false,"extraction":"ocr"}]}$rules$::jsonb);
select private.rules_import_historical_version($rules${"governing_body":"Buhurt International","history":"archive-2026-10-06","inventory_key":"authenticity/side-pivoting-visored-bascinets","version":{"version":"2025.01","title":"Side-hinged visored Bascinets 2025.01","published_on":null,"effective_from":null,"note":"\"Side-hinged visored Bascinets\" is this document's earlier name: the current 26.1 change log says \"Replace throughout the document Side-hinged visored Bascinets by Side-pivoting visored Bascinets\" and keeps the same Dec-2024 / Feb-2025 entries. Cover \"VER. 2025.01\" although the file is named \"V2024.12\"; change log only \"December-2024: Add\".","source_url":"https://drive.google.com/file/d/1KjhTpxcwhRgcI_SMBy04Xc6Iqgw5y7vO/view","source_sha256":"daa8d22872dc427dc359e69675e4520d183054225cb0ffff2d1ef58da90eb5e4","retrieved_at":null,"page_count":16,"extractor":"pdftotext unknown -layout -enc UTF-8","content_sha256":"0fe98bcefcd4e85f39b26e49546a65b162e9197bd426ae35363486c8ef031174","detected":{"version":null,"date":null},"confirmed_by":"Claude Code (Pack 22 historical import), read from the archived PDF: cover (OCR of the page image), footers and change log","historical":true,"edition_seq":1,"edition_evidence":"\"Side-hinged visored Bascinets\" is this document's earlier name: the current 26.1 change log says \"Replace throughout the document Side-hinged visored Bascinets by Side-pivoting visored Bascinets\" and keeps the same Dec-2024 / Feb-2025 entries. Cover \"VER. 2025.01\" although the file is named \"V2024.12\"; change log only \"December-2024: Add\".","source_files":[{"file":"Authenticity/Archive/Side-hinged visored Bascinets V2024.12.pdf","archive":"Authenticity","sha256":"daa8d22872dc427dc359e69675e4520d183054225cb0ffff2d1ef58da90eb5e4","drive_file_id":"1KjhTpxcwhRgcI_SMBy04Xc6Iqgw5y7vO"}],"reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1","2 provision(s) need review against the official document"],"pages":16,"source_lines":160,"assigned_lines":291,"furniture_lines":36,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99615,"provisions":22,"numbered":20,"needs_review":2,"verified":0,"empty_pages":[1],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":0,"picture_text_lines":0,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"side-pivoting-visored-bascinets:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"note","number":null,"title":null,"body":"Helmet - Side-hinged Visored Bascinets","page_from":2,"page_to":2,"stable_key":"side-pivoting-visored-bascinets:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"c2765ed5e68da00174c91d3f091dd79230bf102175d7df75ed5397de43406ac3","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":0,"kind":"section","number":"1","title":"Definition","body":"● Side-hinged visored bascinets are helmets with movable visors attached to the dome with hinges at the temples, in contrast to center-mounted hinges on the forehead. This type of helmet was very popular in Western Europe from 1350 to 1450. Such helmets are designed to be worn as primary head protection, and the design of the visor is made to deflect strikes.\n● Side-hinged visored bascinets use a solid metal visor to protect the face, attached on the sides by hinges.\n● Side-hinged visored bascinets were used from the early 14th century to 1450 across all of Western Europe. The shape of the visor will evolve throughout time..","page_from":3,"page_to":3,"stable_key":"side-pivoting-visored-bascinets:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e3cf7522d9e2619791e05914e05712090d7a4273a95d25897dd1b2d13e577a80","has_figures":true,"extraction":"text"},{"ordinal":4,"depth":0,"kind":"section","number":"2","title":"Historical Sources and Datation","body":"","page_from":4,"page_to":4,"stable_key":"side-pivoting-visored-bascinets:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3eb54a2b08cc1965411982ae8e72cc3da5990185a4c37bbc71af699038bcac04","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"2.1","title":"Sugarloaf","body":"● Sugarloaf helmets are one of the earliest types of side-hinged visored bascinets. It appears in the beginning of the 14th century and includes a solid chin protection, derived from Great Helms design.\n● Sugarloaf helmets are approved for 14th-century armor.\n● Sugarloaf helmets are denied for transitional armor and 15th-century armor.\n\nBL Royal 6 E IX Address in verse to Robert of Anjou, King of Naples - 1335/1340 - Italy","page_from":4,"page_to":4,"stable_key":"side-pivoting-visored-bascinets:2.1","parent_key":"side-pivoting-visored-bascinets:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9d56766e6ed6603e207dde6041727369b699224050bc38636bd1f0cf70108126","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":1,"kind":"rule","number":"2.2","title":"Transitional Style Helmets","body":"● In the middle of the 14th century, bascinets with a side-hinged visor began to be depicted in miniatures and art. They include a longer visor with no chin plate (such as sugarloaf) and will represent the majority of helmets until the middle of the 15th century.\n● Transitional style helmets are approved for 14th-century and transitional armor.\n● Transitional style helmets are denied for 15th-century armor.","page_from":5,"page_to":5,"stable_key":"side-pivoting-visored-bascinets:2.2","parent_key":"side-pivoting-visored-bascinets:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"aafc30193af9febbe32b2f792ab3ddf5b864decf67c3d8b6fc6ea3873c8bfa80","has_figures":true,"extraction":"text"},{"ordinal":7,"depth":2,"kind":"rule","number":"2.2.1","title":"Romance of Alexander, Spoleto, and Other Flat-faced Bascinets","body":"These helmets are based on period art:\n\nA   B   C\n\nD E\n\nA: Spoleto church - 1370/1380 - Italy B: Codex Balduini Trevirensis - 1341 - Germany C: Morgan Library - 1390-1399 - France D: Holkham Bible - 1327/1335 - England E: Romance of Alexander- 1338 - England","page_from":5,"page_to":5,"stable_key":"side-pivoting-visored-bascinets:2.2.1","parent_key":"side-pivoting-visored-bascinets:2.2","review_status":"needs_review","review_note":"layout looks like a table or columns: compare with the official page","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"69682b9fe8f15fdcab826807ebb3614cd453c0686acdf84f9ecb47c5f09dd679","has_figures":true,"extraction":"text"},{"ordinal":8,"depth":2,"kind":"rule","number":"2.2.2","title":"Houndskull/Hundsgugel Style Bascinets","body":"These helmets are very common at this time. Many originals survived and are displayed in museums.\n\n1400-1410 - Kunsthistorisches Museum Wien - Austria 1390-1410 - Churburg - Italy\n\nLes Grandes Chroniques de France - 1400/1425 - France\n\nBodleian Library - 1400/1425 - England","page_from":6,"page_to":6,"stable_key":"side-pivoting-visored-bascinets:2.2.2","parent_key":"side-pivoting-visored-bascinets:2.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6c45eaef237403df0fd40afa99925e2eb1b707557384afc38a708bcaf308b3f2","has_figures":true,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"2.3","title":"15th-century Style Helmets","body":"At the edge of the 15th century, an evolution of previous bascinets was developed. The great bascinet encompasses an increased neck protection that makes itvery safe. Some extant artifacts are displayed in museums.\n\nA   B   C\n\nA: Musée de l’Armée, Paris - 1400/1420 - France B: Musées des Beaux Arts, Dijon - 1400/1420 - France C: Doges Palace, Venice - 1380/1390 - Italy","page_from":7,"page_to":7,"stable_key":"side-pivoting-visored-bascinets:2.3","parent_key":"side-pivoting-visored-bascinets:2","review_status":"needs_review","review_note":"layout looks like a table or columns: compare with the official page","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5944ed8700165e7ab16daf60e3d58af3b752255815ffc5d61dc95b3fcf2be0fa","has_figures":true,"extraction":"text"},{"ordinal":10,"depth":0,"kind":"section","number":"3","title":"Requirements","body":"","page_from":8,"page_to":8,"stable_key":"side-pivoting-visored-bascinets:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"475f60c10a2f0b6b9f5aaf68ce12eb9a12457aeafff595062e0babfbd5af33a1","has_figures":true,"extraction":"text"},{"ordinal":11,"depth":1,"kind":"rule","number":"3.1","title":"General Requirements","body":"● Reproductions must closely resemble the appearance and proportions of a side-hinged bascinet source.\n● Any metal part of the helmet must conform to the Armors and weapons Aesthetics and decorations document.\n● Any textile or leather part of the helmet must conform to the Textiles and Leather document.","page_from":8,"page_to":8,"stable_key":"side-pivoting-visored-bascinets:3.1","parent_key":"side-pivoting-visored-bascinets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4987f243d26b335a3b967fb649301010c3815cb9fbbb650f85c18b87d2be401c","has_figures":true,"extraction":"text"},{"ordinal":12,"depth":1,"kind":"rule","number":"3.2","title":"Visor requirements","body":"● The visor must not be too long or too short, it must conform to the proportions of historical sources.\n● The hinges must be reproduced as per historical sources.\n● It is permitted to weld the visor down. A welded visor must resemble a functional removable visor.\n● It is permitted to add metal plates to protect the throat. Such a plate must be strong enough to endure full-contact fighting and must be concealed under the aventail.\n● A leather strap can be used to secure the visor.\n● Breath holes should be round and must not exceed a diameter of 10mm. Breath holes must not be so numerous that they compromise the helm’s structural integrity. It is acceptable to mirror breath holes to both sides.\n● Breath holes of other shapes must be documented by historical sources to be permitted.","page_from":8,"page_to":8,"stable_key":"side-pivoting-visored-bascinets:3.2","parent_key":"side-pivoting-visored-bascinets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"56f661faa980cc0f54b75b692bc42ba92852ce8a43fe8eb20c2997de13f0562a","has_figures":true,"extraction":"text"},{"ordinal":13,"depth":1,"kind":"rule","number":"3.3","title":"Eye Slots","body":"● Eye slots should resemble sources for the visor.\n● Eye slots should not exceed 25mm tall to prevent any injury.\n● Side-hinged visored bascinets with two (2) eye slots are permitted to add up to two (2) externally riveted eye bars or buhurt-optimized internal eye bars per eye slot.\n● Side-hinged visored bascinets with a single eye slot are permitted to add up to five (5) buhurt-optimized eye bars: one (1) in the middle and two (2) on each side.\n\nExample from Medieval Extreme ©\n\n● Eye bars must conform to the Eye Bars rules document.\n\n● It is recommended to use small ocular such as the following:\n\nBL Royal 20 C VII Chroniques de France ou de St Denis 1380/1400 - France","page_from":8,"page_to":9,"stable_key":"side-pivoting-visored-bascinets:3.3","parent_key":"side-pivoting-visored-bascinets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"928f9c5d5e22a49b82c87d71ee8b5c80dd62d01983b9e5fe7312bf1e7bf146d8","has_figures":true,"extraction":"text"},{"ordinal":14,"depth":1,"kind":"rule","number":"3.4","title":"Aventail","body":"● Side-hinged visored bascinets must be worn with chainmail aventails, fabric aventails, or scale aventails.\n● Aventails must conform to the Aventails document.\n● Aventails must be attached to the bascinet by a system of leather and vervelles, or sewn to the edges of the helmet.\n● The aventail must be fastened down to the outer edge of a padded pelerine attached to the helmet liner.\n● Protective plates covering the cervical spine should be hidden under the aventail.\nSupplemental hidden collar plates are permitted.","page_from":9,"page_to":9,"stable_key":"side-pivoting-visored-bascinets:3.4","parent_key":"side-pivoting-visored-bascinets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c4a242f33f19c7284f4f2ac7e34c04fc691d7b6e926a47943b7a64336a9a53e2","has_figures":false,"extraction":"text"},{"ordinal":15,"depth":1,"kind":"rule","number":"3.5","title":"Others","body":"● Side-hinged visored bascinets may be decorated in the spirit of medieval styles, such as an orle, torse, decorated aventails (with copper/brass chainmail rings), vervelle covers, coat of arms badges, etc.\n● Such decoration must be made in coherence with historical sources.\n● Using modern and/or offensive imagery and slogans is prohibited as part of decorations or heraldry.","page_from":9,"page_to":9,"stable_key":"side-pivoting-visored-bascinets:3.5","parent_key":"side-pivoting-visored-bascinets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c31bac297a4a2afe86032a043bd14ea65464d6af1255feeddc685a34f6dba056","has_figures":false,"extraction":"text"},{"ordinal":16,"depth":0,"kind":"section","number":"4","title":"Approved Reproductions","body":"","page_from":10,"page_to":10,"stable_key":"side-pivoting-visored-bascinets:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3cb1950c99b22ad34be64b556168d855992a74325a6b523c668a2708a4910749","has_figures":true,"extraction":"text"},{"ordinal":17,"depth":1,"kind":"rule","number":"4.1","title":"Sugarloaf","body":"Picture from Age of Craft © Picture from Forge of Svan ©","page_from":10,"page_to":10,"stable_key":"side-pivoting-visored-bascinets:4.1","parent_key":"side-pivoting-visored-bascinets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"02eedd316fa9b4f69808b00216336787925c0c048878bc20ce591e347f0cd3f3","has_figures":true,"extraction":"text"},{"ordinal":18,"depth":1,"kind":"rule","number":"4.2","title":"Romance of Alexander, Spoleto, and Other Flat-faced Bascinets","body":"Pictures from Master Uley ©\n\nPictures from Medieval Extreme ©\n\nPictures from The Medieval Things ©\n\nPicture from Zoom en Lice ©","page_from":11,"page_to":12,"stable_key":"side-pivoting-visored-bascinets:4.2","parent_key":"side-pivoting-visored-bascinets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"85c5119217d81b3229df4caacb8d43144add2e67e27ae96a094b8d25d1bc4f40","has_figures":true,"extraction":"text"},{"ordinal":19,"depth":1,"kind":"rule","number":"4.3","title":"Houndskull/Hundsgugel Style Bascinets","body":"Pictures from The Medieval Things ©\n\nPicture from Medieval Extreme ©","page_from":13,"page_to":13,"stable_key":"side-pivoting-visored-bascinets:4.3","parent_key":"side-pivoting-visored-bascinets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"33a5acfca8edd0b91067d0da874651fbe5cfc7b4a3aa21ad175b142d03876df8","has_figures":true,"extraction":"text"},{"ordinal":20,"depth":1,"kind":"rule","number":"4.4","title":"Great Bascinets","body":"Picture from The Medieval Things ©","page_from":14,"page_to":14,"stable_key":"side-pivoting-visored-bascinets:4.4","parent_key":"side-pivoting-visored-bascinets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b98ce5e8a38c51cc59376faeeb1a55f1b6870b3b53054ffd02639aeb13d6eba0","has_figures":true,"extraction":"text"},{"ordinal":21,"depth":0,"kind":"section","number":"5","title":"Denied Reproductions","body":"Design of the bottom of the visor does not reproduce historical sources.\n\nPictures from The Medieval Things ©","page_from":15,"page_to":15,"stable_key":"side-pivoting-visored-bascinets:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"020303b4f1487e1deebb86073701cef7f980d95cccc6837406b664f99e0a54bc","has_figures":true,"extraction":"text"},{"ordinal":22,"depth":0,"kind":"note","number":"6","title":"Change log","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nDecember-2024: -Add Document has been created","page_from":16,"page_to":16,"stable_key":"side-pivoting-visored-bascinets:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"24a5d9012e7ea5de58f8db1be93b49aa57a32ca2285e039cef368d514a6e1402","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_historical_version($rules${"governing_body":"Buhurt International","history":"archive-2026-10-06","inventory_key":"authenticity/side-pivoting-visored-bascinets","version":{"version":"2025.02","title":"Side-hinged visored Bascinets 2025.02","published_on":null,"effective_from":null,"note":"Same document under its earlier name (see edition 2025.01). Cover \"VER. 2025.02\" while the change log heads the latest entry \"February-2025 (V2025.03)\": the label is the cover's, the disagreement is recorded. Newer than 2025.01 (it adds the February-2025 entry); older than the current 26.1.","source_url":"https://drive.google.com/file/d/1gapMtk-p56a-KxOO0ckWUSZOvVbthado/view","source_sha256":"a83827f601b7a06bdf23d75db3c1bdc0c806ab51dd7cc1d743357432a546ab2f","retrieved_at":null,"page_count":16,"extractor":"pdftotext unknown -layout -enc UTF-8","content_sha256":"73678f5bb8adc6b679979b40a4f0c6aac24d8fa8c8b3dedfcb9d6c747cb0caf6","detected":{"version":null,"date":null},"confirmed_by":"Claude Code (Pack 22 historical import), read from the archived PDF: cover (OCR of the page image), footers and change log","historical":true,"edition_seq":2,"edition_evidence":"Same document under its earlier name (see edition 2025.01). Cover \"VER. 2025.02\" while the change log heads the latest entry \"February-2025 (V2025.03)\": the label is the cover's, the disagreement is recorded. Newer than 2025.01 (it adds the February-2025 entry); older than the current 26.1.","source_files":[{"file":"Authenticity/Archive/Side-hinged visored Bascinets.pdf","archive":"Authenticity","sha256":"a83827f601b7a06bdf23d75db3c1bdc0c806ab51dd7cc1d743357432a546ab2f","drive_file_id":"1gapMtk-p56a-KxOO0ckWUSZOvVbthado"}],"reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1","2 provision(s) need review against the official document"],"pages":16,"source_lines":168,"assigned_lines":302,"furniture_lines":36,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99636,"provisions":22,"numbered":20,"needs_review":2,"verified":0,"empty_pages":[1],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":0,"picture_text_lines":0,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"side-pivoting-visored-bascinets:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"note","number":null,"title":null,"body":"Helmet - Side-hinged Visored Bascinets","page_from":2,"page_to":2,"stable_key":"side-pivoting-visored-bascinets:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"c2765ed5e68da00174c91d3f091dd79230bf102175d7df75ed5397de43406ac3","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":0,"kind":"section","number":"1","title":"Definition","body":"● Side-hinged visored bascinets are helmets with movable visors attached to the dome with hinges at the temples, in contrast to center-mounted hinges on the forehead. This type of helmet was very popular in Western Europe from 1350 to 1450. Such helmets are designed to be worn as primary head protection, and the design of the visor is made to deflect strikes.\n● Side-hinged visored bascinets use a solid metal visor to protect the face, attached on the sides by hinges.\n● Side-hinged visored bascinets were used from the early 14th century to 1450 across all of Western Europe. The shape of the visor will evolve throughout time..","page_from":3,"page_to":3,"stable_key":"side-pivoting-visored-bascinets:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e3cf7522d9e2619791e05914e05712090d7a4273a95d25897dd1b2d13e577a80","has_figures":true,"extraction":"text"},{"ordinal":4,"depth":0,"kind":"section","number":"2","title":"Historical Sources and Datation","body":"","page_from":4,"page_to":4,"stable_key":"side-pivoting-visored-bascinets:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3eb54a2b08cc1965411982ae8e72cc3da5990185a4c37bbc71af699038bcac04","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"2.1","title":"14th Century Sugarloaf Helmets","body":"● Sugarloaf helmets are one of the earliest types of side-hinged visored bascinets. It appeared at the beginning of the 14th century and includes a solid chin protection, derived from Great Helms design.\n● Sugarloaf helmets are approved for 14th-century armor.\n● Sugarloaf helmets are denied for transitional armor and 15th-century armor.\n\nBL Royal 6 E IX Address in verse to Robert of Anjou, King of Naples - 1335/1340 - Italy","page_from":4,"page_to":4,"stable_key":"side-pivoting-visored-bascinets:2.1","parent_key":"side-pivoting-visored-bascinets:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"be70603a2647f39c12db7adf7c6d5fd497d19983d72e4331fe2347510c5f0c3c","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":1,"kind":"rule","number":"2.2","title":"Transitional Style Helmets","body":"● In the middle of the 14th century, bascinets with a side-hinged visor began to be depicted in miniatures and art. They include a longer visor with no chin plate (such as sugarloaf) and will represent the majority of helmets until the middle of the 15th century.\n● Transitional style helmets are approved for 14th-century and transitional armor.\n● Transitional style helmets are denied for 15th-century armor.","page_from":5,"page_to":5,"stable_key":"side-pivoting-visored-bascinets:2.2","parent_key":"side-pivoting-visored-bascinets:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"aafc30193af9febbe32b2f792ab3ddf5b864decf67c3d8b6fc6ea3873c8bfa80","has_figures":true,"extraction":"text"},{"ordinal":7,"depth":2,"kind":"rule","number":"2.2.1","title":"Romance of Alexander, Spoleto, and Other Flat-faced Bascinets","body":"These helmets are based on period art:\n\nA   B   C\n\nD E\n\nA: Spoleto church - 1370/1380 - Italy B: Codex Balduini Trevirensis - 1341 - Germany C: Morgan Library - 1390-1399 - France D: Holkham Bible - 1327/1335 - England E: Romance of Alexander- 1338 - England","page_from":5,"page_to":5,"stable_key":"side-pivoting-visored-bascinets:2.2.1","parent_key":"side-pivoting-visored-bascinets:2.2","review_status":"needs_review","review_note":"layout looks like a table or columns: compare with the official page","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"69682b9fe8f15fdcab826807ebb3614cd453c0686acdf84f9ecb47c5f09dd679","has_figures":true,"extraction":"text"},{"ordinal":8,"depth":2,"kind":"rule","number":"2.2.2","title":"Houndskull/Hundsgugel Style Bascinets","body":"These helmets are very common at this time. Many originals survived and are displayed in museums.\n\n1400-1410 - Kunsthistorisches Museum Wien - Austria 1390-1410 - Churburg - Italy\n\nLes Grandes Chroniques de France - 1400/1425 - France\n\nBodleian Library - 1400/1425 - England","page_from":6,"page_to":6,"stable_key":"side-pivoting-visored-bascinets:2.2.2","parent_key":"side-pivoting-visored-bascinets:2.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6c45eaef237403df0fd40afa99925e2eb1b707557384afc38a708bcaf308b3f2","has_figures":true,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"2.3","title":"15th-century Style Helmets","body":"At the edge of the 15th century, an evolution of previous bascinets was developed. The great bascinet encompasses an increased neck protection that makes it very safe. Some extant artifacts are displayed in museums.\n\nA   B   C\n\nA: Musée de l’Armée, Paris - 1400/1420 - France B: Musées des Beaux Arts, Dijon - 1400/1420 - France C: Doges Palace, Venice - 1380/1390 - Italy","page_from":7,"page_to":7,"stable_key":"side-pivoting-visored-bascinets:2.3","parent_key":"side-pivoting-visored-bascinets:2","review_status":"needs_review","review_note":"layout looks like a table or columns: compare with the official page","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e228e1e2a30d09cb682e28af4923a8787d1ab47dec9ecf26bd929852c18f9839","has_figures":true,"extraction":"text"},{"ordinal":10,"depth":0,"kind":"section","number":"3","title":"Requirements","body":"","page_from":8,"page_to":8,"stable_key":"side-pivoting-visored-bascinets:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"475f60c10a2f0b6b9f5aaf68ce12eb9a12457aeafff595062e0babfbd5af33a1","has_figures":true,"extraction":"text"},{"ordinal":11,"depth":1,"kind":"rule","number":"3.1","title":"General Requirements","body":"● Reproductions must closely resemble the appearance and proportions of a side-hinged bascinet source.\n● Any metal part of the helmet must conform to the Armors and Weapons aesthetics and decorations document.\n● Any textile or leather part of the helmet must conform to the Textiles and Leather document.","page_from":8,"page_to":8,"stable_key":"side-pivoting-visored-bascinets:3.1","parent_key":"side-pivoting-visored-bascinets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ddbd5554350aa144e5f0218442829a01c9b7e1373d532354b3bee9adb30c79ff","has_figures":true,"extraction":"text"},{"ordinal":12,"depth":1,"kind":"rule","number":"3.2","title":"Visor requirements","body":"● The visor must not be too long or too short, it must conform to the proportions of historical sources.\n● The hinges must be reproduced as per historical sources.\n● It is permitted to weld the visor down. A welded visor must resemble a functional removable visor.\n● It is permitted to add metal plates to protect the throat. Such a plate must be strong enough to endure full-contact fighting and must be concealed under the aventail.\n● A leather strap can be used to secure the visor.\n● Breath holes should be round and must not exceed a diameter of 10mm. Breath holes must not be so numerous that they compromise the helm’s structural integrity. It is acceptable to mirror breath holes to both sides.\n● Breath holes of other shapes must be documented by historical sources to be permitted.","page_from":8,"page_to":8,"stable_key":"side-pivoting-visored-bascinets:3.2","parent_key":"side-pivoting-visored-bascinets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"56f661faa980cc0f54b75b692bc42ba92852ce8a43fe8eb20c2997de13f0562a","has_figures":true,"extraction":"text"},{"ordinal":13,"depth":1,"kind":"rule","number":"3.3","title":"Eye Slots","body":"● Eye slots should resemble sources for the visor.\n● Eye slots should not exceed 25mm tall to prevent any injury.\n● Side-hinged visored bascinets with historical evidence of externally riveted eye bars can add up to two (2) externally riveted eye bars ○ Helmets that are currently documented with externally riveted eye bars are Sugarloaf and Romance of Alexander.\n● Side-hinged visored bascinets with two (2) eye slots are permitted to add up to two (2) safety internal eye bars per eye slot.\n● Side-hinged visored bascinets with a single eye slot are permitted to add up to five (5) safety eye bars: one (1) in the middle and two (2) on each side.\n\nExample from Medieval Extreme ©\n\n● Side-hinged visored bascinets with historical evidence of integrated eye bars can use some, such as the following:\n\nBL Royal 20 C VII Chroniques de France ou de St Denis 1380/1400 - France\n\n● Eye bars must conform to the Eye Bars rules document","page_from":8,"page_to":9,"stable_key":"side-pivoting-visored-bascinets:3.3","parent_key":"side-pivoting-visored-bascinets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4c711f706d735a5ff892dcf63b7863204f37b8e480afe12a0093b521960d9b17","has_figures":true,"extraction":"text"},{"ordinal":14,"depth":1,"kind":"rule","number":"3.4","title":"Aventail","body":"● Side-hinged visored bascinets must be worn with chainmail aventails, fabric aventails, or scale aventails.\n● Aventails must conform to the Aventails document.\n● Aventails must be attached to the bascinet by a system of leather and vervelles, or sewn to the edges of the helmet.\n● The aventail must be fastened down to the outer edge of a padded pelerine attached to the helmet liner.\n● Protective plates covering the cervical spine should be hidden under the aventail.\nSupplemental hidden collar plates are permitted.","page_from":9,"page_to":9,"stable_key":"side-pivoting-visored-bascinets:3.4","parent_key":"side-pivoting-visored-bascinets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c4a242f33f19c7284f4f2ac7e34c04fc691d7b6e926a47943b7a64336a9a53e2","has_figures":false,"extraction":"text"},{"ordinal":15,"depth":1,"kind":"rule","number":"3.5","title":"Others","body":"● Side-hinged visored bascinets may be decorated in the spirit of medieval styles, such as an orle, torse, decorated aventails (with copper/brass chainmail rings), vervelle covers, coat of arms badges, etc.\n● Such decoration must be made in coherence with historical sources.\n● Using modern and/or offensive imagery and slogans is prohibited as part of decorations or heraldry.","page_from":9,"page_to":9,"stable_key":"side-pivoting-visored-bascinets:3.5","parent_key":"side-pivoting-visored-bascinets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c31bac297a4a2afe86032a043bd14ea65464d6af1255feeddc685a34f6dba056","has_figures":false,"extraction":"text"},{"ordinal":16,"depth":0,"kind":"section","number":"4","title":"Approved Reproductions","body":"","page_from":10,"page_to":10,"stable_key":"side-pivoting-visored-bascinets:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3cb1950c99b22ad34be64b556168d855992a74325a6b523c668a2708a4910749","has_figures":true,"extraction":"text"},{"ordinal":17,"depth":1,"kind":"rule","number":"4.1","title":"Sugarloaf","body":"Picture from Age of Craft © Picture from Forge of Svan ©","page_from":10,"page_to":10,"stable_key":"side-pivoting-visored-bascinets:4.1","parent_key":"side-pivoting-visored-bascinets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"02eedd316fa9b4f69808b00216336787925c0c048878bc20ce591e347f0cd3f3","has_figures":true,"extraction":"text"},{"ordinal":18,"depth":1,"kind":"rule","number":"4.2","title":"Romance of Alexander, Spoleto, and Other Flat-faced Bascinets","body":"Pictures from Master Uley ©\n\nPictures from Medieval Extreme ©\n\nPictures from The Medieval Things ©\n\nPicture from Zoom en Lice ©","page_from":11,"page_to":12,"stable_key":"side-pivoting-visored-bascinets:4.2","parent_key":"side-pivoting-visored-bascinets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"85c5119217d81b3229df4caacb8d43144add2e67e27ae96a094b8d25d1bc4f40","has_figures":true,"extraction":"text"},{"ordinal":19,"depth":1,"kind":"rule","number":"4.3","title":"Houndskull/Hundsgugel Style Bascinets","body":"Pictures from The Medieval Things ©\n\nPicture from Medieval Extreme ©","page_from":13,"page_to":13,"stable_key":"side-pivoting-visored-bascinets:4.3","parent_key":"side-pivoting-visored-bascinets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"33a5acfca8edd0b91067d0da874651fbe5cfc7b4a3aa21ad175b142d03876df8","has_figures":true,"extraction":"text"},{"ordinal":20,"depth":1,"kind":"rule","number":"4.4","title":"Great Bascinets","body":"Picture from The Medieval Things ©","page_from":14,"page_to":14,"stable_key":"side-pivoting-visored-bascinets:4.4","parent_key":"side-pivoting-visored-bascinets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b98ce5e8a38c51cc59376faeeb1a55f1b6870b3b53054ffd02639aeb13d6eba0","has_figures":true,"extraction":"text"},{"ordinal":21,"depth":0,"kind":"section","number":"5","title":"Denied Reproductions","body":"Design of the bottom of the visor does not reproduce historical sources.\n\nPictures from The Medieval Things ©","page_from":15,"page_to":15,"stable_key":"side-pivoting-visored-bascinets:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"020303b4f1487e1deebb86073701cef7f980d95cccc6837406b664f99e0a54bc","has_figures":true,"extraction":"text"},{"ordinal":22,"depth":0,"kind":"note","number":"6","title":"Change log","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nFebruary-2025 (V2025.03)\n- clarification: 3.3\n- formatting: Grammar and Formatting December-2024: -Add Document has been created","page_from":16,"page_to":16,"stable_key":"side-pivoting-visored-bascinets:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"5bdb95c94eb8b2ed4cdcf7d93ce4999fc47b2a4e3ef245f077c1fafa97de3d4b","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_historical_version($rules${"governing_body":"Buhurt International","history":"archive-2026-10-06","inventory_key":"authenticity/tabards","version":{"version":"2024.12","title":"Tabards 2024.12","published_on":null,"effective_from":null,"note":"Title \"Tabards\"; cover \"VER. 2024.12\"; change log only \"December-2024: created\". Older than the current 26.1.","source_url":"https://drive.google.com/file/d/11jBp_HunL_rFdlHaAk09ryNxhRrlcfZK/view","source_sha256":"9873607afbf3713917d5db4d159eb0dede126d23503147240525533314d590b4","retrieved_at":null,"page_count":14,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 1 page(s) without a text layer","content_sha256":"06ac4472f26ae6f4d0f8d7ea1a07537babf3ac53b2e2e4c53af90651db5adbfc","detected":{"version":"2024.12","date":null},"confirmed_by":"Claude Code (Pack 22 historical import), read from the archived PDF: cover (OCR of the page image), footers and change log","historical":true,"edition_seq":1,"edition_evidence":"Title \"Tabards\"; cover \"VER. 2024.12\"; change log only \"December-2024: created\". Older than the current 26.1.","source_files":[{"file":"Authenticity/Archive/Tabards V2024.12.pdf","archive":"Authenticity","sha256":"9873607afbf3713917d5db4d159eb0dede126d23503147240525533314d590b4","drive_file_id":"11jBp_HunL_rFdlHaAk09ryNxhRrlcfZK"}],"reconciliation":{"ok":true,"errors":[],"warnings":["4 provision(s) need review against the official document"],"pages":14,"source_lines":188,"assigned_lines":295,"furniture_lines":42,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99876,"provisions":29,"numbered":28,"needs_review":4,"verified":0,"empty_pages":[],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":3,"picture_text_lines":1,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 2024.12\n\nAuthenticity Tabards","page_from":1,"page_to":2,"stable_key":"tabards:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"eb247d35a1ecb7ff8f661ae577ece0a66a3e64ce647851675fd44cce2f3eb4a1","has_figures":true,"extraction":"mixed"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Definition and general requirements","body":"","page_from":3,"page_to":3,"stable_key":"tabards:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"df9d4b4971cd1ada36b96ec4e6602cd5f968c25814a104728b68a69b7ffb6242","has_figures":true,"extraction":"text"},{"ordinal":3,"depth":1,"kind":"rule","number":"1.1","title":"Definition","body":"● Tabards is a generic term used to describe the cloth worn upon the armor. It is made to show the heraldry of the wearer and prove your wealth and status on the battlefield, or in the list.\n● Nowadays, tabards have the same function as a sports jersey: to indicate the team you belong to.","page_from":3,"page_to":3,"stable_key":"tabards:1.1","parent_key":"tabards:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"914d9a4ad7c0b2042cf51f82750d989125b891b9e690a05782096c12fdce0f35","has_figures":true,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"1.2","title":"Types of tabards","body":"● Sleeveless tabard : Tabards without sleeves. Simple design, common in the 13th century and 14th century. Tend to be rare in the 15th century.\n● Short-sleeves tabard : Tabards with short sleeves that can go up to the elbow.\nCommon design in the 14th century. Tend to be rare in the 15th century.\n● Long-sleeves tabard : Tabards with long sleeves that cover the whole arms, from shoulder to hand. Common design in the 14th and the 15th century.\n● Eastern tabard : We do not have many historical references for eastern tabard. It is allowed to use the same tabard as European armors. Eastern stylization of tabard are displayed in the document “Eastern Armors”.\n● Exception for full plates armors : Wearing full plates armor makes the use of tabard not practical. Therefore, it is allowed to wear only a scarf. Scarf must follow the general requirements (1.3).\n\nExample of scarf:\n\nPicture from The Medieval Things ©","page_from":3,"page_to":3,"stable_key":"tabards:1.2","parent_key":"tabards:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0bdac85b66d2e0c4b8978257e6d0dbd271697691629cb2f53cc1c89b782b8fe4","has_figures":true,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"1.3","title":"Material requirements","body":"All tabards and scarf must must respect the following requirements:\n● Shapes, decorations and designs must be based on historical sources.\n● Tabards must conform to the Textiles and Leather rules document.\n● Tabards can be made of the following materials:\n○ Wool ○ Linen ○ Silk ○ Coton ○ Any other material based on historical sources.\n● Tabards can be made of modern materials in the following cases:\n○ The modern material replicates the aesthetic of an approved material listed in","page_from":4,"page_to":4,"stable_key":"tabards:1.3","parent_key":"tabards:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"afc3a447a171984200e38be65e8b097561e13d5bf3c6db4f93f9408554e4102e","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":2,"kind":"rule","number":"1.3.2","title":"○ The modern material is strong enough to endure full contact fights and to not be","body":"damaged too easily.\n○ We recommend asking for approval of the Authenticity Committee regarding tabard made of modern materials before placing an order.","page_from":4,"page_to":4,"stable_key":"tabards:1.3.2","parent_key":"tabards:1.3","review_status":"needs_review","review_note":"numbering skips to 1.3.2 (expected 1.3.1): check the official document for a missing provision","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3a7c1e6b27e40b9fe6b6c399961dc27e2ee9555c4657c9c922065a91ca5b518e","has_figures":false,"extraction":"text"},{"ordinal":7,"depth":1,"kind":"rule","number":"1.4","title":"Fastening systems requirements","body":"● Tabards can be tied with the following systems:\n○ Buttons made of fabric, wood, bone, or metal.\n○ Laces, made of leather, rope or fabric.\n○ Any other system based on historical sources.\n○ Any modern fastening system is denied. (Zips, snap buttons, velcro, paracord, nylon rope etc.)\n● Tabards can be open on the side, tied with laces.\n● Tabards can be open on the front, and tied with buttons.","page_from":4,"page_to":4,"stable_key":"tabards:1.4","parent_key":"tabards:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c9191df4b5715a5b13baddb9e12392fe1b837b12e5d1bc0ff34e7c3441e1d2c3","has_figures":false,"extraction":"text"},{"ordinal":8,"depth":1,"kind":"rule","number":"1.5","title":"Colors requirements","body":"● Colors used for tabards must be based on historical sources. Any clearly modern color is denied. (Neon pink, fluorescent yellow etc.)\n● For the Marshal's safety, the use of yellow as a main color of a tabard is denied. Yellow color must represent less than 50% of the tabard colors. The combination of black and yellow must not be inspired by Marshal’s uniforms.","page_from":4,"page_to":4,"stable_key":"tabards:1.5","parent_key":"tabards:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d4173fbd3a29caca6006dcf811ea60253d65712d115ee851ce8335f11ce80f24","has_figures":false,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"1.6","title":"Symbols and decorations requirements","body":"● Symbols and decorations used for tabards must be based on historical sources. Any clearly modern symbol or decoration is denied. (Warhammer logo, movies or TV show imagery, modern slogan etc.)\n● We recommend taking inspiration from middle ages manuscripts to create your symbols.\n\n● Symbols and decorations used for tabards must be made with the following techniques:\n○ Embroidery.\n○ Painting: can be by hand or by stamp.\n○ Sewing a patchwork of clothes to create a design.\n○ Any other techniques based on historical sources.","page_from":4,"page_to":5,"stable_key":"tabards:1.6","parent_key":"tabards:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"51065a4c97ff8d9789dcd6e4c531b23eff3d7a1fd3e7b6a1809841c05d61c2a0","has_figures":true,"extraction":"text"},{"ordinal":10,"depth":1,"kind":"rule","number":"1.7","title":"Exception for cuirass","body":"● When wearing a cuirass, it is allowed to wear the tabard under it. In this case, it is also allowed to wear the pauldrons upon the tabard.\n● Example :\n\nPicture from Helli ©","page_from":5,"page_to":5,"stable_key":"tabards:1.7","parent_key":"tabards:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2cfee206bdeadfa4331746dc1a36fe95314698a4144a28ba47e34966ff85e863","has_figures":true,"extraction":"text"},{"ordinal":11,"depth":0,"kind":"section","number":"2","title":"Sleeveless tabard","body":"","page_from":6,"page_to":6,"stable_key":"tabards:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4f98dfec2ed271d841831191ed37ea472bcd95e010dbd3d1ca3fe86877825583","has_figures":true,"extraction":"text"},{"ordinal":12,"depth":1,"kind":"rule","number":"2.1","title":"Historical sources and datation","body":"● Sleeveless tabard is an easy way to display your heraldic. This type of tabard has been used all along the middle-ages, from knight templars to late 15th century armors.\n● They are approved for 14th century, Transitional and 15th century armors.\n\nA   B   C\n\nA: Life of Eustace and Other Saints - 1300 - France B: Weltchronik - 1360 - Germany C: Bibliothèque de Besançon - 1410 - France","page_from":6,"page_to":6,"stable_key":"tabards:2.1","parent_key":"tabards:2","review_status":"needs_review","review_note":"layout looks like a table or columns: compare with the official page","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"19a1066959d5dc75f016c973cf3542b6ec102900c5febba77f0912a85c749c6f","has_figures":true,"extraction":"text"},{"ordinal":13,"depth":1,"kind":"rule","number":"2.2","title":"Specific requirements","body":"● Sleeveless tabard must follow the general requirements\n● Sleeveless tabard must not be too long.\n● Knee is the limit, tabard must not go below.","page_from":6,"page_to":6,"stable_key":"tabards:2.2","parent_key":"tabards:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"10736df73e7208c9720c15f04c5bc04ebee11e8f7ec9043a47bc59c4692d2468","has_figures":true,"extraction":"text"},{"ordinal":14,"depth":1,"kind":"rule","number":"2.3","title":"Examples of Approved reproductions","body":"Pictures from Age of Craft ©","page_from":7,"page_to":7,"stable_key":"tabards:2.3","parent_key":"tabards:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e6da873905e4e0b6b01fc97eb5bf9c043c49b20b374c8c4be637781b3ba5f8b9","has_figures":true,"extraction":"text"},{"ordinal":15,"depth":1,"kind":"rule","number":"2.4","title":"Examples of Denied reproductions","body":"Yellow as a main color Over long tabard","page_from":7,"page_to":7,"stable_key":"tabards:2.4","parent_key":"tabards:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"552d84f20392842c93337153f65b2112e58cececf6a542e20e532ef15fe210fd","has_figures":true,"extraction":"text"},{"ordinal":16,"depth":0,"kind":"section","number":"3","title":"Short-sleeves tabard","body":"","page_from":8,"page_to":8,"stable_key":"tabards:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"50fc2c3792d4bcbef135ecb3f354a40d2bf377c03927d9526b2d9b49beb329f0","has_figures":false,"extraction":"text"},{"ordinal":17,"depth":1,"kind":"rule","number":"3.1","title":"Historical sources and datation","body":"● Short-sleeves tabard is the main design of the 14th century and later. Its simple shape makes it easy to craft and to wear. Many different designs can be documented by historical sources\n● They are approved for 14th century, Transitional and 15th century armors.\n\nA   B   C\n\nA: Bible historiale - 1360 - France B: Weltchronik - 1360 - Germany C: Office of the Feast of Corpus Christi - 1403 - Austria","page_from":8,"page_to":8,"stable_key":"tabards:3.1","parent_key":"tabards:3","review_status":"needs_review","review_note":"layout looks like a table or columns: compare with the official page","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5d4a5622624a14125d03ddd1233851cfe1f578c0c41a3210f888fa309594d028","has_figures":false,"extraction":"text"},{"ordinal":18,"depth":1,"kind":"rule","number":"3.2","title":"Specific requirements","body":"● Short-sleeves tabard must follow the general requirements\n● Short-sleeves tabard must not be too long. Knee is the limit.\n● The sleeves must not be too long. Elbow is the limit, unless it can be documented by historical sources.\n● The sleeves can be open or plain (as a shirt).\n\nOpen sleeves Plain sleeves\n\nOpen sleeve Plain sleeve","page_from":9,"page_to":9,"stable_key":"tabards:3.2","parent_key":"tabards:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"79d75017b044c58013d0fe48053bcddc1d05fb02ac8bac1b0f27eb7bc95ab5e7","has_figures":true,"extraction":"text"},{"ordinal":19,"depth":1,"kind":"rule","number":"3.3","title":"Examples of Approved reproductions","body":"Pictures from Gohurt ©","page_from":9,"page_to":9,"stable_key":"tabards:3.3","parent_key":"tabards:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2a9ec163ea715d851b9ec7195f53677c868a7d1f96fe72cc062ed8b1e0f1fe5c","has_figures":true,"extraction":"text"},{"ordinal":20,"depth":0,"kind":"section","number":"4","title":"Long-Sleeves tabard","body":"","page_from":10,"page_to":10,"stable_key":"tabards:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"956a89b6d9a034a903e40b10603f217fe05a68d03cabea0e3039169ff45e8801","has_figures":true,"extraction":"text"},{"ordinal":21,"depth":1,"kind":"rule","number":"4.1","title":"Historical sources and datation","body":"● Long-sleeves tabard combine the role of exposing your heraldry and protecting your armor. The sleeves often cover the whole arm, up to the wrist, but can be shorter (up to mid-forearm). Many different designs can be documented by historical sources.\n● They are approved for 14th century, Transitional and 15th century armors.\n\nA B C D\n\nA: Guiron le Courtois - 1380 - France B: Knebel von Katzenelnbogen - 1401 - Germany C: Bible historiale, BL Royal 15 D III - 1420 - France D: Le Livre et le vraye hystoire du bon roy Alixandre - 1420 - France","page_from":10,"page_to":10,"stable_key":"tabards:4.1","parent_key":"tabards:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8fbc21e39d9504a455845cd2d93292d4605b700795b37d8ba395e075bae701d2","has_figures":true,"extraction":"text"},{"ordinal":22,"depth":1,"kind":"rule","number":"4.2","title":"Specific requirements","body":"● Long-sleeves tabard must follow the general requirements\n● Long-sleeves tabard must not be too long. Knee is the limit.\n● The sleeves must cover the arm up to the middle of the forearm as a minimum.\n● The sleeves must be plain (as a shirt).","page_from":10,"page_to":10,"stable_key":"tabards:4.2","parent_key":"tabards:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"914fca651e0d648a50710f026ec45b832e8254fc0930b6dae852615870026aab","has_figures":true,"extraction":"text"},{"ordinal":23,"depth":1,"kind":"rule","number":"4.3","title":"Examples of Approved reproductions","body":"Pictures from The Medieval Things ©","page_from":11,"page_to":11,"stable_key":"tabards:4.3","parent_key":"tabards:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"bbe18c40488cb2c8438c13660b0ff541ad56c40281727c6dc7ac4b9f6811b4b6","has_figures":true,"extraction":"text"},{"ordinal":24,"depth":1,"kind":"rule","number":"4.4","title":"Examples of Denied reproductions","body":"Yellow as the main colour Pictures from The Medieval Things ©","page_from":11,"page_to":11,"stable_key":"tabards:4.4","parent_key":"tabards:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"dad1032ec33fded06753a7589252b629e738900c78cfb0c4b7cb6556ad58f948","has_figures":true,"extraction":"text"},{"ordinal":25,"depth":0,"kind":"section","number":"5","title":"Examples of Approved designs and decorations","body":"","page_from":12,"page_to":12,"stable_key":"tabards:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1abc1b0754f815b872a6ef22e9c614c4b3f337620bcac00f596af09bb93e9433","has_figures":true,"extraction":"text"},{"ordinal":26,"depth":0,"kind":"section","number":"6","title":"Fastening systems","body":"","page_from":13,"page_to":13,"stable_key":"tabards:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6d80278a40a4eef0fc03d3f732263e343c2a40080b91f786b1404a82a228ce28","has_figures":true,"extraction":"text"},{"ordinal":27,"depth":1,"kind":"rule","number":"6.1","title":"Examples of Approved systems","body":"Metal buttons covered with fabric Wood buttons Laces Pictures from\nS.Bier ©   A. Labat ©   The Medieval Thing ©","page_from":13,"page_to":13,"stable_key":"tabards:6.1","parent_key":"tabards:6","review_status":"needs_review","review_note":"layout looks like a table or columns: compare with the official page","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0c62fd88f3ed9c9fa8bb525040204270b70ae2d1b052a99e4911cd4b4a481a52","has_figures":true,"extraction":"text"},{"ordinal":28,"depth":1,"kind":"rule","number":"6.2","title":"Examples of Denied systems","body":"Velcro Picture from The Medieval Thing ©","page_from":13,"page_to":13,"stable_key":"tabards:6.2","parent_key":"tabards:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b4fd7a90b6b4a7307931920f8d433c91a7240af13deae11e46eb47898e998260","has_figures":true,"extraction":"text"},{"ordinal":29,"depth":0,"kind":"note","number":"7","title":"Change log","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nDecember-2024: -Add Document has been created","page_from":14,"page_to":14,"stable_key":"tabards:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"f5d5e5e7e860519943c29ad62213a6ed7b5f7b9ddccea66c4a946bd2f329569d","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_historical_version($rules${"governing_body":"Buhurt International","history":"archive-2026-10-06","inventory_key":"authenticity/textile-and-leather","version":{"version":"2024.12","title":"Textiles and Leather 2024.12","published_on":null,"effective_from":null,"note":"Title \"Textiles and Leather\"; cover \"VER. 2024.12\"; change log only \"December-2024: created\". Older than the current 26.1.","source_url":"https://drive.google.com/file/d/19IA0DIduObyOuU1wuLRFn37KNCny1guf/view","source_sha256":"07e19e7dca46ccb66961d444a00954a3cc0c5ce0f10c706ab853ec59f2eb213e","retrieved_at":null,"page_count":8,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 1 page(s) without a text layer","content_sha256":"0c9e9392731ae1ea75e90f3873faa17f31ab75ecbeeb1d06d2b6e9a0174d6495","detected":{"version":"2024.12","date":null},"confirmed_by":"Claude Code (Pack 22 historical import), read from the archived PDF: cover (OCR of the page image), footers and change log","historical":true,"edition_seq":1,"edition_evidence":"Title \"Textiles and Leather\"; cover \"VER. 2024.12\"; change log only \"December-2024: created\". Older than the current 26.1.","source_files":[{"file":"Authenticity/Archive/Textiles and Leather V2024.12.pdf","archive":"Authenticity","sha256":"07e19e7dca46ccb66961d444a00954a3cc0c5ce0f10c706ab853ec59f2eb213e","drive_file_id":"19IA0DIduObyOuU1wuLRFn37KNCny1guf"}],"reconciliation":{"ok":true,"errors":[],"warnings":["1 line(s) looked like a numbered heading but did not fit the sequence"],"pages":8,"source_lines":123,"assigned_lines":170,"furniture_lines":34,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99876,"provisions":15,"numbered":14,"needs_review":0,"verified":0,"empty_pages":[],"rejected_numbers":1,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":14,"picture_text_lines":12,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 2024.12\n\nAuthenticity Textile and Leather","page_from":1,"page_to":2,"stable_key":"textile-and-leather:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"4a4a8b9623a6bfd1e5c7a5afa50541390ccd6fb79f87120677b210929f579c1e","has_figures":true,"extraction":"mixed"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Definition and general requirements","body":"","page_from":3,"page_to":3,"stable_key":"textile-and-leather:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"df9d4b4971cd1ada36b96ec4e6602cd5f968c25814a104728b68a69b7ffb6242","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":1,"kind":"rule","number":"1.1","title":"Importance of aesthetics","body":"● Armors and weapons aesthetics are very important for the fighters' appearance and sports representation. The development of our sport will be easier with well-maintained and properly finished armor and weapons.","page_from":3,"page_to":3,"stable_key":"textile-and-leather:1.1","parent_key":"textile-and-leather:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b358cbf31ce376887e3e4105f17e74093ea559cd6395f58a5695e6a10fa18270","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"1.2","title":"Textiles and leather","body":"● Textiles and leather are part of a knightly appearance. Tabards are made of fabric (linen, wool, silk…), coats of plates are covered with fabric, leather is mainly used for armor (helmet suspension, belts, pouches, straps), etc. All skin must be covered.","page_from":3,"page_to":3,"stable_key":"textile-and-leather:1.2","parent_key":"textile-and-leather:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"de99df328bbfb1c2ecc2692841501e007212a19c07fb1bee56ca9fe2a2e53acd","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"1.3","title":"Requirements","body":"● Be based on historical sources.\n● Not be of a clearly modern color (I.E neon or fluorescent)\n● Be maintained in a good shape prior to any Buhurt International Event.\n● Not be decorated with modern images, offensive logos, etc.","page_from":3,"page_to":3,"stable_key":"textile-and-leather:1.3","parent_key":"textile-and-leather:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"643d9ec782cde3792ae1bd1ffac7d51da1995f0cdfd7bd0baeb809aca6ebe885","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":0,"kind":"section","number":"2","title":"Textiles","body":"","page_from":4,"page_to":4,"stable_key":"textile-and-leather:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"62ea9becade7627e5d69b67ada738161d5d06980951c02eee321cbf394fbd4b2","has_figures":false,"extraction":"text"},{"ordinal":7,"depth":1,"kind":"rule","number":"2.1","title":"Historical sources and datation","body":"● The sources provide the following available materials during the middle ages:\n○ Linen ○ Wool ○ Silk ○ Coton.\n● Those materials are approved for 14th-century, Transitional armors and 15th-century armors.\n● Depending on the area and time-period, other textiles fibers may be available. Any other material based on historical sources can be accepted.\n● Textiles were used in many applications, such as:\n○ Tabard ○ Covering a coat of plates, corazzina or brigantine ○ Gambesons ○ Chausses ○ Helmet decoration (burlet, torse, orle, crest etc.).","page_from":4,"page_to":4,"stable_key":"textile-and-leather:2.1","parent_key":"textile-and-leather:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ae98cdd05495158303308def21dd20234fb9fc46d93110a6481c700f81ecb6a7","has_figures":false,"extraction":"text"},{"ordinal":8,"depth":1,"kind":"rule","number":"2.2","title":"Specific requirements","body":"● Any material listed in 2.1 is allowed.\n● Any material based on historical sources thus not listed in 2.1 is allowed.\n● It is allowed to use a modern material under the following conditions:\n○ The modern material replicates the aesthetic of an approved material listed in 2.1 ○ The modern material is strong enough to endure full contact fights and to not be damaged too easily ○ We recommend asking for approval of Authenticity regarding modern materials before placing an order of an item made of such material.\n● Any clearly modern cloth element, such as underpants, sport legging, knee pad etc., must not be visible from any position.","page_from":4,"page_to":4,"stable_key":"textile-and-leather:2.2","parent_key":"textile-and-leather:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["2.1"],"content_sha256":"ae34de23769efd24e78f071bbb5d9a59baa0645734503c3fda589dfa7f7b5c92","has_figures":false,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"2.3","title":"Examples of Approved reproductions","body":"Pictures from The Medieval Things ©","page_from":5,"page_to":5,"stable_key":"textile-and-leather:2.3","parent_key":"textile-and-leather:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3705146961bc83782cdeb237a29a71485cf28a27eb5052c8a8519f802c2cf638","has_figures":true,"extraction":"text"},{"ordinal":10,"depth":1,"kind":"rule","number":"2.4","title":"Examples of Denied reproductions","body":"Visible modern clothes / butt protection\n\nModern legging Pictures from The Medieval Things ©","page_from":5,"page_to":5,"stable_key":"textile-and-leather:2.4","parent_key":"textile-and-leather:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"17ed6997470c2f4c72e3bc050a0c13cfdb6579061f17e79377b99ed3ca9be919","has_figures":true,"extraction":"text"},{"ordinal":11,"depth":0,"kind":"section","number":"3","title":"Leather","body":"","page_from":6,"page_to":6,"stable_key":"textile-and-leather:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2fa655f7acb121ec1c5abaeb54a29cbbb2ea60aee45b28cedbe113d71285c479","has_figures":true,"extraction":"text"},{"ordinal":12,"depth":1,"kind":"rule","number":"3.1","title":"Historical sources and datation","body":"● The sources provide a numerous amount of information about the use of leather.\nLeather can be decorated or not.\n● The use of leather is approved for 14th-century, Transitional armors and 15th-century armors.\n● Leather was used in many applications, such as:\n○ Covering a coat of plates, corazzina or brigantine ○ Gambesons ○ Helmet element (suspension system, straps etc.) ○ Belts ○ Pouches ○ Shoes ○ Etc.\n\nReproduction of a medieval shoes - 1300/1350 - Archeologisch Museum Haarlem\n\nLeather glove Metropolitan Museum of Art","page_from":6,"page_to":6,"stable_key":"textile-and-leather:3.1","parent_key":"textile-and-leather:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5968e0663273570a0c2dc7f848c23ae1cbbe212e9e518041d7ed282a35644c3a","has_figures":true,"extraction":"text"},{"ordinal":13,"depth":1,"kind":"rule","number":"3.2","title":"Specific requirements","body":"● Any natural leather is allowed.\n● It is allowed to use a modern material under the following conditions:\n○ The modern material replicates the aesthetic of natural leather.\n○ The modern material is strong enough to endure full contact fights and to not be damaged too easily.\n○ We recommend asking for approval of Authenticity regarding modern materials before placing an order of an item made of such material.\n● Specific requirements for boots and shoes ○ Boots and shoes must be based on historical sources.\n○ Boots and shoes must be fastened by leather laces, fabric laces or any historically plausible mechanism.","page_from":7,"page_to":7,"stable_key":"textile-and-leather:3.2","parent_key":"textile-and-leather:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"789ec409fe5fe8621b072c6f1a9483398311a71f5dc227ec2a6fea66dbc7e0c4","has_figures":true,"extraction":"text"},{"ordinal":14,"depth":1,"kind":"rule","number":"3.3","title":"Examples of Approved reproductions","body":"Picture from Age of Craft © Picture from GoHurt ©","page_from":7,"page_to":7,"stable_key":"textile-and-leather:3.3","parent_key":"textile-and-leather:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6a7716c7406f4f7119d1b6913fee57bc58d4123df7db6bc38d1819dac80aae27","has_figures":true,"extraction":"text"},{"ordinal":15,"depth":0,"kind":"note","number":"4","title":"Change log","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nDecember-2024: -Add Document has been created","page_from":8,"page_to":8,"stable_key":"textile-and-leather:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"a3c0c1200b4bedbea681187a83868d1e233d4fa08d4c87594c025d852930cff3","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_historical_version($rules${"governing_body":"Buhurt International","history":"archive-2026-10-06","inventory_key":"authenticity/weapon-requirements","version":{"version":"26.1","title":"Technical Requirements for Weapons 26.1","published_on":null,"effective_from":null,"note":"Title and footer \"Technical Requirements for Weapons V. 26.1\" — the current document's footer reads \"Technical Requirements for Weapons V. 26.4\" (file title \"Weapons requirements\"); cover \"VER. 26.1\". Older than the current 26.4.","source_url":"https://drive.google.com/file/d/1feO0GYKq3wRzksAYr03fff9z95AVccdE/view","source_sha256":"54eddb12c8eb3af317a05c78e0a8cf6e4eec8b4484836de7f4deba5a9d8df3d3","retrieved_at":null,"page_count":14,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 14 page(s) without a text layer","content_sha256":"768c84faad681cdf4079f1f154f354aa8d981c3a328d098ef400130dabc30bff","detected":{"version":"26.1","date":null},"confirmed_by":"Claude Code (Pack 22 historical import), read from the archived PDF: cover (OCR of the page image), footers and change log","historical":true,"edition_seq":1,"edition_evidence":"Title and footer \"Technical Requirements for Weapons V. 26.1\" — the current document's footer reads \"Technical Requirements for Weapons V. 26.4\" (file title \"Weapons requirements\"); cover \"VER. 26.1\". Older than the current 26.4.","source_files":[{"file":"Authenticity/Archive/Technical Requirements for Weapons.pdf","archive":"Authenticity","sha256":"54eddb12c8eb3af317a05c78e0a8cf6e4eec8b4484836de7f4deba5a9d8df3d3","drive_file_id":"1feO0GYKq3wRzksAYr03fff9z95AVccdE"}],"reconciliation":{"ok":true,"errors":[],"warnings":["2 line(s) looked like a numbered heading but did not fit the sequence","4 provision(s) need review against the official document"],"pages":14,"source_lines":321,"assigned_lines":431,"furniture_lines":68,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99557,"provisions":43,"numbered":42,"needs_review":4,"verified":0,"empty_pages":[],"rejected_numbers":2,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":321,"picture_text_lines":10,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 26.1\n\nAuthenticity","page_from":1,"page_to":1,"stable_key":"weapon-requirements:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"b3cd075ee5755a5513c4f726dcdef54be200038fbb1071b0c1257f4b18b0c3f9","has_figures":true,"extraction":"ocr"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Introduction and Definitions","body":"This document will display all requirements for armors, shields, and Weapons used in any category.\nEvery competitor is solely responsible for the quality of his/her equipment. Marshals and Authenticity Officers are responsible for the correct application of this document.","page_from":3,"page_to":3,"stable_key":"weapon-requirements:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a648e2555c19c78f2b099ca710e00712759875c6cb239fc39fdda93fa640663d","has_figures":true,"extraction":"ocr"},{"ordinal":3,"depth":1,"kind":"rule","number":"1.1","title":"Equipment","body":"Armors, clothes, shields and Weapons used by a competitor.","page_from":3,"page_to":3,"stable_key":"weapon-requirements:1.1","parent_key":"weapon-requirements:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a32d0e89b2f3ec4759f22eab33e8bc32e368336b42410c3277c657fdd3557843","has_figures":true,"extraction":"ocr"},{"ordinal":4,"depth":1,"kind":"rule","number":"1.2","title":"List","body":"Place where the fights occur.","page_from":3,"page_to":3,"stable_key":"weapon-requirements:1.2","parent_key":"weapon-requirements:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6a3b9108fce5da206e5d3123df37f9d4eee2ae2e945c9ea5d30402531a976946","has_figures":true,"extraction":"ocr"},{"ordinal":5,"depth":1,"kind":"rule","number":"1.3","title":"Categories","body":"● Duel\n\n1v1 sword and shield, sword and buckler, longsword, polearm.\n● Buhurt\n\nGroup fight, 5v5, 12v12, 30v30.\n● Outrance","page_from":3,"page_to":3,"stable_key":"weapon-requirements:1.3","parent_key":"weapon-requirements:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e95c48379a6b815141f9f28b5a9dd13552616abf99fd388e6581fdb95e0de01d","has_figures":true,"extraction":"ocr"},{"ordinal":6,"depth":1,"kind":"rule","number":"1.4","title":"Striking Edge / Non-striking Edge (of the Weapon)","body":"Striking Edge is a part of the Weapon designed to hit an opponent.\nNon-striking edge is a part of the Weapon not designed to hit an opponent.\n\nHere are some examples with the striking edge being red","page_from":3,"page_to":3,"stable_key":"weapon-requirements:1.4","parent_key":"weapon-requirements:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e911cf1fd0808a9f6a124d3bc98aac6fe18b7ec84748aeb723bba8b476ffbaa4","has_figures":true,"extraction":"ocr"},{"ordinal":7,"depth":1,"kind":"rule","number":"1.5","title":"Historical Sources","body":"It is the result of research to conclude the plausibility of the item had existed. Historical sources can be primary (artifacts, museum originals...) or secondary (images, paintings, statues, description, writings...).\nAny historical source must be analyzed through criticism and logic.","page_from":3,"page_to":3,"stable_key":"weapon-requirements:1.5","parent_key":"weapon-requirements:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d6e469f9ba234a8c82ae902b33f2c93decdd3504e68f31428670b26035d7cee7","has_figures":true,"extraction":"ocr"},{"ordinal":8,"depth":0,"kind":"section","number":"2","title":"Historical Consistency Requirements","body":"","page_from":4,"page_to":4,"stable_key":"weapon-requirements:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d31c28382ccb21c1059e6d4305309e504fac888cd55f5f7d19f8b6c065042fda","has_figures":false,"extraction":"ocr"},{"ordinal":9,"depth":1,"kind":"rule","number":"2.1","title":"Equipment from Historical Sources","body":"Only Weapons derived from historical sources are permitted for use.\nWeapons must align with Authenticity Rules documents.","page_from":4,"page_to":4,"stable_key":"weapon-requirements:2.1","parent_key":"weapon-requirements:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2547f2b5f93a0f77375666d0164e1dd2519a346eda97a9739ddeac1ccfa86c39","has_figures":false,"extraction":"ocr"},{"ordinal":10,"depth":1,"kind":"rule","number":"2.2","title":"Dates of Sources","body":"Weapons must align with sources dating between the 14th (1300) and 17th (1600) centuries.\n\nFor safety considerations, reproductions of armors predating the 13th century are prohibited, as are Weapons of the same period.","page_from":4,"page_to":4,"stable_key":"weapon-requirements:2.2","parent_key":"weapon-requirements:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a2e0086b83b64387a7b51262b77e2e3b966ed0eb7a436a07c7bc6849eb893d6f","has_figures":false,"extraction":"ocr"},{"ordinal":11,"depth":1,"kind":"rule","number":"2.3","title":"Prohibited Features","body":"Prohibited features encompass evident indications of modern materials or manufacturing techniques including: neon colors, obvious nylon cords, plastic ties, visible welded seams, heat-induced discoloration and other visible modern equipment.","page_from":4,"page_to":4,"stable_key":"weapon-requirements:2.3","parent_key":"weapon-requirements:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"152a00392d6f005c9e0e4dacb22396b772f573726c2bc4c2627d1d38549f951a","has_figures":false,"extraction":"ocr"},{"ordinal":12,"depth":1,"kind":"rule","number":"2.4","title":"Consistency in Equipment","body":"Armors, shields and Weapons must consist of pieces from the same style. Distinct styles are defined in modern-day terms as:","page_from":4,"page_to":4,"stable_key":"weapon-requirements:2.4","parent_key":"weapon-requirements:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7350f87f0717a4cae739a0baaa4375d5c08786ee9f0c3c1dad3945058a2cf8d0","has_figures":false,"extraction":"ocr"},{"ordinal":13,"depth":2,"kind":"rule","number":"2.4.1","title":"| Western Europe Style","body":"● 14th century: from 1300 to 1380\n\n● Transitional: from 1380 to 1420\n\n● 15th century: from 1420 to 1500. 15th century style armor must be approved by the Authenticity Committee. We recommended seeking approval before buying such armor.\n\nWestern Europe includes the following modern countries: Great Britain, Ireland, France, Portugal, Spain, Germany, Italy, Norway, Denmark, Sweden, Finland, Austria, Switzerland, Belgium, and the Netherlands","page_from":4,"page_to":4,"stable_key":"weapon-requirements:2.4.1","parent_key":"weapon-requirements:2.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ed54646f2feb9605824adb4bd14aa717de7529e37413e4d6376930792ec914bb","has_figures":false,"extraction":"ocr"},{"ordinal":14,"depth":2,"kind":"rule","number":"2.4.2","title":"Slavic Influence","body":"● Central Europe 14th: from 1300 to 1400\n● Russian late armors: from 1500 to 1700\n\nSlavic Influence includes the following modern countries: Czech Republic, Romania, Hungary, Poland, Slovakia, Slovenia, Croatia, Latvia, Estonia, Moldova, Serbia, Ukraine, Russia, and Belarus.","page_from":4,"page_to":4,"stable_key":"weapon-requirements:2.4.2","parent_key":"weapon-requirements:2.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"cf382388c7478028ecd9afc1d1e8f01897466eb1d31f253807bb10e1eab09c26","has_figures":false,"extraction":"ocr"},{"ordinal":15,"depth":2,"kind":"rule","number":"2.4.3","title":"Eastern Influence","body":"● Chinese style: from 1300 to 1600\n● Japanese samurai style: from 1400 to 1700\n● Middle-East style: from 1300 to 1700\n\nEastern influence includes the following modern countries: China, Japan, India, Korea, Iran, Iraq, Turkey, Egypt.","page_from":4,"page_to":4,"stable_key":"weapon-requirements:2.4.3","parent_key":"weapon-requirements:2.4","review_status":"needs_review","review_note":"OCR could not read some words with confidence: Iran,","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"fad764fc0868d7c855bffb06873c8ea61d5bc63a5d1cfbc9e74e3089420d6748","has_figures":false,"extraction":"ocr"},{"ordinal":16,"depth":2,"kind":"rule","number":"2.4.4","title":"Authorized Deviations","body":"Competitors may deviate from these specified styles if they provide sources supporting their equipment choices.\n\nCompetitors who deviate from these’ specified styles must send an_= email to authenticity@buhurtinternational.com to obtain validation of their armor.","page_from":5,"page_to":5,"stable_key":"weapon-requirements:2.4.4","parent_key":"weapon-requirements:2.4","review_status":"needs_review","review_note":"OCR could not read some words with confidence: these’, an_=, email","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"09710c07ec50df9825a367c64ed2918b351ed9f7a148100bd90a90e26e017ad3","has_figures":false,"extraction":"ocr"},{"ordinal":17,"depth":0,"kind":"section","number":"3","title":"General Requirements","body":"","page_from":5,"page_to":5,"stable_key":"weapon-requirements:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b8295fe2bc4208d485f0e4d62f112a839e3bfc08e2b952098f2a20793db34314","has_figures":false,"extraction":"ocr"},{"ordinal":18,"depth":1,"kind":"rule","number":"3.1","title":"Competitor Responsibility","body":"Every competitor is responsible for the quality and the safety of his/her equipment.","page_from":5,"page_to":5,"stable_key":"weapon-requirements:3.1","parent_key":"weapon-requirements:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ecb1e84d661b9eff26c4d7d798592eb5051f07a5cb22c97ebf08110d719841de","has_figures":false,"extraction":"ocr"},{"ordinal":19,"depth":1,"kind":"rule","number":"3.2","title":"Quality Equipment","body":"All Weapon parts must be made of strong materials able to endure full contact fights.\nPoor quality equipment is not allowed in any category.\n\nPoor quality Weapon examples: loose guard, pommel or other element of a Weapon that may break, dented blade, cracks in metal part etc.","page_from":5,"page_to":5,"stable_key":"weapon-requirements:3.2","parent_key":"weapon-requirements:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9070ab6dfb6f7f6e872a0dfe86d3d27c67f0abc77173cba639e030abdaa30c28","has_figures":false,"extraction":"ocr"},{"ordinal":20,"depth":1,"kind":"rule","number":"3.3","title":"Access to the List","body":"Marshals are allowed to deny any competitor with clearly poor quality equipment to enter the list.","page_from":5,"page_to":5,"stable_key":"weapon-requirements:3.3","parent_key":"weapon-requirements:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7f4574270a5d5d374e69d852a1994cb7a089e6d66e733bdadcf55c179c972df7","has_figures":false,"extraction":"ocr"},{"ordinal":21,"depth":0,"kind":"section","number":"4","title":"Weapons Definitions","body":"","page_from":6,"page_to":6,"stable_key":"weapon-requirements:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ec6bcb8aba8b10b84d9227bd0f94dff25c7f7f49121656107054186491468263","has_figures":false,"extraction":"ocr"},{"ordinal":22,"depth":1,"kind":"rule","number":"4.1","title":"Types of Weapons","body":"There are 2 types of Weapons:","page_from":6,"page_to":6,"stable_key":"weapon-requirements:4.1","parent_key":"weapon-requirements:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"cef2bad260bc2873df785b2c3b803431700b130d264dafd1990145c42503c120","has_figures":false,"extraction":"ocr"},{"ordinal":23,"depth":2,"kind":"rule","number":"4.1.1","title":"Bladed Weapons","body":"Weapon with a long metal blade and a hilt with a hand guard.\nExamples of Bladed Weapons:\n● swords,\n● falchions,\n● longswords,\n● etc...","page_from":6,"page_to":6,"stable_key":"weapon-requirements:4.1.1","parent_key":"weapon-requirements:4.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"61ce1c650054e1675507281251eb9346876a1ff607bc74f5eee4906a380f447a","has_figures":false,"extraction":"ocr"},{"ordinal":24,"depth":2,"kind":"rule","number":"4.1.2","title":"| Hafted Weapons","body":"Weapon which the main fighting part of the Weapon is fitted to the end of a long shaft Examples of Hafted Weapons:\n● axe,\n● polearm,\n● glaive,\n● maces,","page_from":6,"page_to":6,"stable_key":"weapon-requirements:4.1.2","parent_key":"weapon-requirements:4.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4a4028ded8d90e16ca4b8d975539cc093b7bae0adaf6ff8fedcf1d33172529d8","has_figures":false,"extraction":"ocr"},{"ordinal":25,"depth":1,"kind":"rule","number":"4.2","title":"Subgenres of Weapons","body":"","page_from":6,"page_to":6,"stable_key":"weapon-requirements:4.2","parent_key":"weapon-requirements:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5a21f0affb335afd88ce7eac7850def25d16526532cf6851a77faf5f6b405d03","has_figures":false,"extraction":"ocr"},{"ordinal":26,"depth":2,"kind":"rule","number":"4.2.1","title":"Duels","body":"● Duels Sword\n● Duels Longsword\n● Duels Polearm","page_from":6,"page_to":6,"stable_key":"weapon-requirements:4.2.1","parent_key":"weapon-requirements:4.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b225b3d4347bc9d02b4163afed50ea68302b8cf32b9b5438b314edc0067734ad","has_figures":false,"extraction":"ocr"},{"ordinal":27,"depth":2,"kind":"rule","number":"4.2.2","title":"| Group (3v3,5v5 etc...)","body":"● Type 1 Bladed\n\n● Type 2 Bladed\n\n● Type 3 Bladed\n\n● Type 1 Hafted (mace)\n\n● Type 2 Hafted (axe)\n\n● Type 3 Hafted\n\n● Type 4 Hafted","page_from":6,"page_to":6,"stable_key":"weapon-requirements:4.2.2","parent_key":"weapon-requirements:4.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4dd6c719f6a83be20fcaec03064e00d349d592de5fadce143ffe1d25fedb0f5d","has_figures":false,"extraction":"ocr"},{"ordinal":28,"depth":0,"kind":"section","number":"5","title":"Safety Requirements","body":"All Weapons must be able to endure full contact fights.\nAll edges of all Weapons must be rebated in compliance with this document.\n\nThe edge of both striking and non-striking edges must be rebated and have a thickness of 2 mm or more.\n\nThe radius of striking and non-striking edges must be more than 10mm.\nWeapons constructed solely for stabbing are prohibited (spears for example) Weight permissible upward error for Weapons is 100 grams\n\nAny heavier Weapon, including permissible upward error, is prohibited.\n\nIt is allowed to use leather thread to secure the Weapon in hand. Such leather thread must conform to the “Textiles and Leather’ document .\n\nEvery Weapon to be used at a tournament must be first approved for safety by the Marshals and Authenticity Officers during Weapons check.","page_from":7,"page_to":7,"stable_key":"weapon-requirements:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"dc04ca0bc0bd7b41a276d8db06b34d9a1356801ff7130834db04cfedf8d2f658","has_figures":false,"extraction":"ocr"},{"ordinal":29,"depth":0,"kind":"section","number":"6","title":"Authenticity Requirements","body":"All Weapons must be based on historical sources and repeat the form of the original in all three dimensions.\n\nAll Weapons must match the style of the armor kit of the competitor.\n\nAll decorations on Weapons must be stylized in accordance with the style of the armor kit of the competitor.\n\nIt is prohibited to decorate Weapons with images that are clearly modern and/or offensive.\nAll decorations must conform to the “Armors and Weapons Aesthetics and Decorations’ document .\nWeapons must conform to Authenticity Rules documents","page_from":7,"page_to":7,"stable_key":"weapon-requirements:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"992aa3d84c9a4b8205dcde7982d301b7833b62e3aa6a51766454226a41c5d681","has_figures":false,"extraction":"ocr"},{"ordinal":30,"depth":0,"kind":"section","number":"7","title":"Specific Requirements","body":"","page_from":8,"page_to":8,"stable_key":"weapon-requirements:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ae3096ef92a3b95e91c0c022a6d0057fd5ec4311ea517ab2dc3830760d93361e","has_figures":true,"extraction":"ocr"},{"ordinal":31,"depth":1,"kind":"rule","number":"7.1","title":"Bladed Weapons","body":"The Bladed Weapon must be made of the following elements:\n\n● Blade: it is the main striking edge of the Weapon,\n\n● Hilt: it is composed of:\n○ Pommel: it is a striking edge, ○ Handle: only place where you're allowed to hold the Weapon, ○ Guard: it is a striking edge.\n\nWhen holding the Bladed Weapon firmly, the guard is not allowed to extend the gauntlet of the bearer for more than 3.5 cm.","page_from":8,"page_to":8,"stable_key":"weapon-requirements:7.1","parent_key":"weapon-requirements:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"40046fe315094426f88e723997807814548bd3373c05ac299c6959eb6f4a8de6","has_figures":true,"extraction":"ocr"},{"ordinal":32,"depth":1,"kind":"rule","number":"7.2","title":"Hafted Weapons","body":"","page_from":8,"page_to":8,"stable_key":"weapon-requirements:7.2","parent_key":"weapon-requirements:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"62d23038ca2f81bf286b34ea99c509f2822971b54fd33d7fd814dc46f7aff162","has_figures":true,"extraction":"ocr"},{"ordinal":33,"depth":2,"kind":"rule","number":"7.2.1","title":"Components","body":"Hafted Weapon must be made of the following elements:\n● Head: it is composed of:\n○ Blade: it is the main striking edge of the Weapon, ○ Back of the head: it is a striking edge but hitting an opponent with this part is prohibited,\n● Haft: the main handle,\n● Bottom: the lower part of the haft. It is a striking edge.\nNote: a mace does not have a back of the head. Each blade of a flanged mace is considered as a striking edge.\n\nThe head of any Hafted Weapon must be secured to the haft by at least 2 different methods.\nAllowed methods are:\n\n● wedges,\n\n● straps,\n\n● glue,\n\n● rivets or nails,\n● langets.\n\nWeapons with sharp corners (Less than 90 degrees) and corners that can be considered dangerous are prohibited.\n\nAny point on the Striking Edge of the Weapon must have an angle more than 90 degrees.\n\nA Hafted Weapon may have a rebated hook or hammerhead on the non-striking part. Any strikes with these elements are strictly prohibited.\n\nAny rebated hook or hammerhead must not present any sharp or pointed edge.","page_from":8,"page_to":9,"stable_key":"weapon-requirements:7.2.1","parent_key":"weapon-requirements:7.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"df0010548604486439f66848cd65e5912787841702506e457b3b382035b342be","has_figures":true,"extraction":"ocr"},{"ordinal":34,"depth":2,"kind":"rule","number":"7.2.2","title":"Haft Requirements","body":"Haft must be made of strong wood or modern material that replicate the wood’s properties in terms of aspect, handling and stiffness.\n\nIt is forbidden to use soft or flexible material for haft, such as rattan.\nIt is forbidden to use metal haft for Hafted Weapons.\nIt is allowed to use a covering with the following materials:\n\n● neutral rope with glue,\n● linen thread with glue,\n● neutral color textile tape (I.E black, brown, grey).\n\nAny covering with a clearly modern appearance are prohibited It is not allowed to enter the list with a damaged covering.\nThe general appearance of the covering will be examined by Authenticity Officers.\n\nIt is allowed to decorate hafts with colored tape. Such decorations can not reproduce modern patterns.\nTeam or country flags colors are allowed.\n\nAny covering must conform with the “Textile and Leather’ document.\n\nExamples:\n\nPictures from The Medieval Things ©\n\nThe bottom of the haft can be protected by a metal part. It must be rounded as per Striking Edge rules.\n\nHaft can be protected with metal plates. Such plates must be firmly attached to the haft and must not present any sharp edge.\n\nWeapons with poorly secured heads are prohibited.","page_from":9,"page_to":10,"stable_key":"weapon-requirements:7.2.2","parent_key":"weapon-requirements:7.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"95dd5292385cc9b7f6574026974f49952116f2f704f298e9e91a6b6bbd6defaa","has_figures":true,"extraction":"ocr"},{"ordinal":35,"depth":0,"kind":"section","number":"8","title":"Duels Weapons","body":"Duels Weapons are built with the intent of agility and swordsmanship vs striking and punishment.\nException: all Type 3 Hafted Weapons are permitted for Polearm Category. Any Weapons not shown below must be approved by Marshal and Authenticity Committee Representatives.","page_from":11,"page_to":11,"stable_key":"weapon-requirements:8","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"20ccbd49d67cc01263e0c69f6b68c48262a184a2eed59a693fd6e97b9923326f","has_figures":true,"extraction":"ocr"},{"ordinal":36,"depth":1,"kind":"rule","number":"8.1","title":"Sword and Shield / Sword and Buckler Category","body":"Allowed Weapons: Type 1 Bladed","page_from":11,"page_to":11,"stable_key":"weapon-requirements:8.1","parent_key":"weapon-requirements:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"17aee05517ee44bcc8da3db7e6c4d875bb64ebb43a2c0a77c4e12732d4a33007","has_figures":true,"extraction":"ocr"},{"ordinal":37,"depth":1,"kind":"rule","number":"8.2","title":"Longsword category","body":"Allowed Weapons: Type 2 Bladed","page_from":11,"page_to":11,"stable_key":"weapon-requirements:8.2","parent_key":"weapon-requirements:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c946cde65b374bd02cf68fd6a0404d7dc16bace25a309fa4e0fa08bec1afe4a5","has_figures":true,"extraction":"ocr"},{"ordinal":38,"depth":1,"kind":"rule","number":"8.3","title":"Polearm category","body":"Allowed Weapons:\n\n● Type 3 Hafted\n● Type 4 Hafted","page_from":11,"page_to":11,"stable_key":"weapon-requirements:8.3","parent_key":"weapon-requirements:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5329dccc366e41218f26721fac2c2608a9840774413e7aea8c2c79e20744c365","has_figures":true,"extraction":"ocr"},{"ordinal":39,"depth":0,"kind":"section","number":"9","title":"Outrance Weapons","body":"Outrance Weapons are any Weapon that passes the measurement requirements from Duels or Buhurt categories.\n\nWeapons used in outrance fights must respect their classification requirements (l.e: a sword must respect the Bladed Weapons requirements).\n\nPoint of Balance\n\nThe Point of Balance of Outrance Bladed Weapons must be:\n● 15cm from the top edge of the handle for men fights,\n● 10cm from the top edge of the handle for women fights.\n\nPoint of Balance is the precise point on a blade where its weight is equally distributed to each side.","page_from":12,"page_to":12,"stable_key":"weapon-requirements:9","parent_key":null,"review_status":"needs_review","review_note":"OCR could not read some words with confidence: (l.e:","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"83e551f54146be4dd62bd4473435aa0df251875b13803b56265103539fb46d8b","has_figures":false,"extraction":"ocr"},{"ordinal":40,"depth":0,"kind":"section","number":"10","title":"Buhurt/Group Weapons","body":"Buhurt/Group Weapons may use Duels specific Weapons and any shapes that are _ historically documentable to the timeframe of the sport. Please reference the “Weapons/Shield Chart’ document for weights and sizing.","page_from":13,"page_to":13,"stable_key":"weapon-requirements:10","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"93b081a0b842d2635462f9edb2ce41dd2334d7f77ca4dc10a39ceb753ef22b15","has_figures":true,"extraction":"ocr"},{"ordinal":41,"depth":1,"kind":"rule","number":"10.1","title":"Type 2 & 3 Bladed","body":"These are examples for type 2 & 3:\n\n● longswords,\n● 2-handed falchions,\n● zweihanders,\n\n● etc.","page_from":13,"page_to":13,"stable_key":"weapon-requirements:10.1","parent_key":"weapon-requirements:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"47ef97308fcb140a4b71be58acf7c12c13940915e973e7f56fa835d059a66a75","has_figures":true,"extraction":"ocr"},{"ordinal":42,"depth":1,"kind":"rule","number":"10.2","title":"Type 2 & 3 Hafted","body":"These are examples:\n\n● Type 2 Hafted: Axe\n● Type 3 Hafted: Longaxe\n\nPP =F Ww = pg Ww wr","page_from":13,"page_to":13,"stable_key":"weapon-requirements:10.2","parent_key":"weapon-requirements:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"56f9292666e3a37293f2fe2f58b4a371a22ae28bc4ed1c39c4cc40b61949d924","has_figures":true,"extraction":"ocr"},{"ordinal":43,"depth":0,"kind":"note","number":"11","title":"Changelog","body":"This will be the change log of this document. It will be updated regularly and we will display what has been removed/added/reworded/formatted. This way we keep transparent communication and clarity about the rules\n\nJanuary - 2026 (V. 26.1) Formatting redone for consistency and readability. Except points listed below, no content changes.\n\nClarification:\n\n- Restructuration of the document to make it more easy to read,\n\n- Minor grammatical/formating corrections,\n\n- Those clarifications have no impact on the document content, except for those listed in this Changelog.\n\nReplace:\n\n- In 5.4.1 Components: An image has been changed\n\nSuppression:\n\n- In 5.4.2 Haft Requirements: “If a haft is not made of wood, it is mandatory to use a covering for the whole haft (from head to bottom) one end must be exposed so it can be verified what the material is” Add:\n\n- In 7.2.2. Haft Requirements:\n\n- “It is allowed to decorate hafts with colored tape. Such decorations can not reproduce modern patterns. Team or country flags colors are allowed. Any covering must conform with “Textile and Leather’ document.”\n\n- “Haft can be protected with metal plates. Such plates must be firmly attached to the haft and must not present any sharp edge.”\n\nClarification:\n- Addition of a subsection about polearm in “Duel Weapons’.\n\n(Version update from 2024.03 to 2024.12.13)\n\nUpdate date: December-2024\n- changed: Upwards weight error from 100,200,300 has been limited to 100 grams for all Weapons\n\nThe subgenres of Weapons,Duels,Duels Sword,Duels Longsword,Duels Polearm,\n\nGroup: Type 1 Bladed, Type 2 Bladed, Type 3 Bladed, Type 1 Hafted (axe), Type 1 Hafted (mace), Type 2 Hafted, Type 3 hafte, Removeds\\(Has been moved to document: (Weapon/Shield requirements excel)\n\n4.4.1 Specific requirements\n\nReémoved|(Has been moved to document: (Weapon/Shield requirements excel)\n\n4.4.2 Weights and measurements\n\nUpdate date: March-2024\n\n- format: new design format, document will be used from now on.\n- Update document based on my document (16/05/2024)\n\n- Update document (format)","page_from":14,"page_to":14,"stable_key":"weapon-requirements:11","parent_key":null,"review_status":"needs_review","review_note":"OCR could not read some words with confidence: “It, Removeds\\(Has, Reémoved|(Has","topics":["changelog"],"keywords":[],"cross_refs":["5.4.1","5.4.2","7.2.2"],"content_sha256":"b26164762b963525a431860e9e54798a67308cb7f9ef749a9a47e2e0086282bd","has_figures":false,"extraction":"ocr"}]}$rules$::jsonb);
select private.rules_import_historical_version($rules${"governing_body":"Buhurt International","history":"archive-2026-10-06","inventory_key":"authenticity/wolfribs","version":{"version":"2025.02","title":"Helmet - Wolf Ribs 2025.02","published_on":null,"effective_from":null,"note":"Title \"Helmet - Wolf Ribs\"; cover \"VER. 2025.02\" while the change log lists \"March - 2025 (V2025.03)\" above \"February - 2025 (V2025.02)\": the label is the cover's, the disagreement is recorded. Older than the current 26.1.","source_url":"https://drive.google.com/file/d/16xuitAlJc-FuHx363f5s5SFFgfR2c1QB/view","source_sha256":"fc959c05280842b660fe1e96ec792b23eb1893ef7b8a83731c8fd6921bdb4032","retrieved_at":null,"page_count":10,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 1 page(s) without a text layer","content_sha256":"b72f8a90e05c1d4c6dc6cbd78053252c877d48b9bca89f2fad58b744dc3bfb88","detected":{"version":null,"date":null},"confirmed_by":"Claude Code (Pack 22 historical import), read from the archived PDF: cover (OCR of the page image), footers and change log","historical":true,"edition_seq":1,"edition_evidence":"Title \"Helmet - Wolf Ribs\"; cover \"VER. 2025.02\" while the change log lists \"March - 2025 (V2025.03)\" above \"February - 2025 (V2025.02)\": the label is the cover's, the disagreement is recorded. Older than the current 26.1.","source_files":[{"file":"Authenticity/Archive/Wolf Ribs.pdf","archive":"Authenticity","sha256":"fc959c05280842b660fe1e96ec792b23eb1893ef7b8a83731c8fd6921bdb4032","drive_file_id":"16xuitAlJc-FuHx363f5s5SFFgfR2c1QB"}],"reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1"],"pages":10,"source_lines":98,"assigned_lines":155,"furniture_lines":19,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99813,"provisions":13,"numbered":11,"needs_review":0,"verified":0,"empty_pages":[1],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":6,"picture_text_lines":0,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"wolfribs:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"note","number":null,"title":null,"body":"Wolf Ribs Helmet","page_from":2,"page_to":2,"stable_key":"wolfribs:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"11fb205895c844473755d51fde9a38d877123f472214fc101845bd65c7112adc","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":0,"kind":"section","number":"1","title":"Definition","body":"● Wolf ribs helmets are bascinet-based helmets topped by a central-pivot facial grill. The few available sources are paintings from the Czech Republic and Germany. The primary sources are dated from 1380 and 1450.\n● The helmet is very similar to other bascinets. It is constructed with a center-hinge visor (such as Klappvisor), locked with a “spoon”, and is worn with an aventail.\n● Wolf ribs helmets are approved for 14th-century and transitional armor.\n● Wolf ribs helmets with bascinet shape are denied for 15th century armors.","page_from":3,"page_to":3,"stable_key":"wolfribs:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"aa3f5d1a0d6dcc4522413156fbd0ff03040f73159e7cc938ae1e5f6bf7de7971","has_figures":true,"extraction":"text"},{"ordinal":4,"depth":0,"kind":"section","number":"2","title":"Historical sources and datation","body":"Třeboň-altarpiece resurrection, Praha Master of the Karlsruhe Passion - Christ 1380/1385 - Czech Republic Carrying the Cross - 1450/1474 - Germany","page_from":4,"page_to":4,"stable_key":"wolfribs:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4d89bf1eca0e3608c9ac562e0322fda8a7a996d877bbd49b3c411e4bc8b93b09","has_figures":true,"extraction":"text"},{"ordinal":5,"depth":0,"kind":"section","number":"3","title":"Requirements","body":"","page_from":5,"page_to":5,"stable_key":"wolfribs:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"475f60c10a2f0b6b9f5aaf68ce12eb9a12457aeafff595062e0babfbd5af33a1","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":1,"kind":"rule","number":"3.1","title":"General Requirements","body":"● Reproductions must closely resemble the appearance and proportions of the sources.\n● Any metal part of the helmet must conform to the Armors and weapons Aesthetics and decorations document.\n● Any textile or leather part of the helmet must conform to the Textiles and Leather document.","page_from":5,"page_to":5,"stable_key":"wolfribs:3.1","parent_key":"wolfribs:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8d1adc84eaa67b5f3ed41ac23bece4190d285a788ee5880a2eae758c9baa423e","has_figures":false,"extraction":"text"},{"ordinal":7,"depth":1,"kind":"rule","number":"3.2","title":"Visor Requirements","body":"● The visor must not be too long or too short and respect the proportions of historical sources.\n● The hinge must be reproduced as per historical sources.\n● It is permitted to weld the hinge. Welded hinges must resemble a functional hinge.\n● It is permitted to weld the visor down. A welded visor must resemble a functional removable visor.\n● It is permitted to add a metal plate to protect the throat. Such a plate must be strong enough to endure full contact fight and must be concealed under the aventail.\n● The visor must consist of 5 horizontal ribs.\n● Ribs must be round or bar-shaped.\n● Ribs can not be made of flat sheets.","page_from":5,"page_to":5,"stable_key":"wolfribs:3.2","parent_key":"wolfribs:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a52e95a9539616c917a34433b6afebd49f60617be960a7ba457bb96b0b744fa9","has_figures":false,"extraction":"text"},{"ordinal":8,"depth":1,"kind":"rule","number":"3.3","title":"Eye-slots","body":"● It is not recommended to have oversized eye slots (over 30x50mm).\n● It is permitted to add up to four (4) vertical safety eyebars on the visor: two (2) on each side of the visor.\n● Eyebars must conform to the Eye Bars rules document.","page_from":5,"page_to":5,"stable_key":"wolfribs:3.3","parent_key":"wolfribs:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1f254b29588372b0bed44a3e28ab92d1a4dc5daaf3f90546e2ff65e518a5aa58","has_figures":false,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"3.4","title":"Aventail","body":"● Wolf ribs helmets can be worn with chainmail or fabric aventails. Scale aventails are not permitted.\n● Aventails must conform to the Aventails document.\n● The aventail must be fastened down to the outer edge of a padded pelerine attached to the helmet liner.\n● Protective plates covering the cervical spine should be hidden under the aventail.\nSupplemental hidden collar plates are permitted.","page_from":5,"page_to":5,"stable_key":"wolfribs:3.4","parent_key":"wolfribs:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a1d497cb022906480ca0fb8c280f952b779ddb2d5c28cef5166aae33a27b63ef","has_figures":false,"extraction":"text"},{"ordinal":10,"depth":1,"kind":"rule","number":"3.5","title":"Others","body":"● Wolf ribs helmets may be decorated in the spirit of medieval styles, such as an orle, torse, decorated aventails (with copper/brass chainmail rings), vervelle covers, coat of arms badges, etc.\n● Such decoration must be made in coherence with historical sources.\n● Using modern and/or offensive imagery and slogans is prohibited.\n\nSpoon Fixation\n\n5 Horizontal Ribs / Not Flat Ribs\n\nVertical Eye Bars\n\nRecommendations for Eyes slots :\n\nEyeSlot\n\n50mm","page_from":5,"page_to":6,"stable_key":"wolfribs:3.5","parent_key":"wolfribs:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"058c5f3b0c5f14ed624e0143ccd6939004f7ecffb1d92724d7b12f5c351acd02","has_figures":true,"extraction":"mixed"},{"ordinal":11,"depth":0,"kind":"section","number":"4","title":"Approved Reproductions","body":"Picture from I. Zadesenets ©\n\nPictures from V. Mishurin ©","page_from":7,"page_to":7,"stable_key":"wolfribs:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"84ec5aa7f6c4db71b973c1ca7fc6367993c55992405ee15fa7764562d5c2a3cf","has_figures":true,"extraction":"text"},{"ordinal":12,"depth":0,"kind":"section","number":"5","title":"Denied Reproductions","body":"More than 5 horizontal ribs Flat ribs\n\nFrame around visor, not based on historical sources Welding spot visible\n\nEyebars not black-painted\n\nNeck protection is visible, it must be concealed under the aventail Pictures from The Medieval Things ©","page_from":8,"page_to":9,"stable_key":"wolfribs:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e803a8767ff3944b8b2074f7901e6ca0e3dc999ea3ea393c4561c7b6fdace062","has_figures":true,"extraction":"text"},{"ordinal":13,"depth":0,"kind":"note","number":"6","title":"Change log","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\nMarch - 2025 (V2025.03)\n- Clarification: Wolf ribs helmets with bascinet shape are denied for 15th century armors\n\nFebruary - 2025 (V2025.02)\n- Format: formatting and grammar improvements\n- Replaced: 3.3 It is permitted to add up to four (4) vertical Buhurt Optimized eyebars on the visor: two (2) on each side of the visor. || It is permitted to add up to four (4) vertical safety eyebars on the visor: two (2) on each side of the visor.\n\nDecember - 2024 (V2024.12) -Add: Document has been created","page_from":10,"page_to":10,"stable_key":"wolfribs:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"b3e52568b73457353e37b251f5e6da419f82f7647b41eb1c9b679010e0ba0718","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_historical_version($rules${"governing_body":"Buhurt International","history":"archive-2026-10-06","inventory_key":"marshal/buhurt-rules","version":{"version":"2024.12.13","title":"Buhurt Rules 2024.12.13","published_on":null,"effective_from":null,"note":"Title \"Buhurt Rules\", footer \"Buhurt Rules\"; cover \"VER. 2024.12.13\". Older than 2026.1.1 and the current 26.4.1.","source_url":"https://drive.google.com/file/d/1d6jQfvTjw7bN3ypC7ZpiCSEdJwNxn1L2/view","source_sha256":"de16344f2507084e6e07216344689308e5d57a796221e047c81e0c794aab4b1a","retrieved_at":null,"page_count":18,"extractor":"pdftotext unknown -layout -enc UTF-8","content_sha256":"146930539b1db304e51142212147d673147306f57d4502e1fc41aaa3998fe36a","detected":{"version":null,"date":null},"confirmed_by":"Claude Code (Pack 22 historical import), read from the archived PDF: cover (OCR of the page image), footers and change log","historical":true,"edition_seq":1,"edition_evidence":"Title \"Buhurt Rules\", footer \"Buhurt Rules\"; cover \"VER. 2024.12.13\". Older than 2026.1.1 and the current 26.4.1.","source_files":[{"file":"Marshal/Archive/Buhurt Rules 2024.12.13.pdf","archive":"Marshal","sha256":"de16344f2507084e6e07216344689308e5d57a796221e047c81e0c794aab4b1a","drive_file_id":"1d6jQfvTjw7bN3ypC7ZpiCSEdJwNxn1L2"}],"reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1"],"pages":18,"source_lines":396,"assigned_lines":468,"furniture_lines":86,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99939,"provisions":70,"numbered":68,"needs_review":0,"verified":0,"empty_pages":[1],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":0,"picture_text_lines":0,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"buhurt-rules:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"note","number":null,"title":null,"body":"Buhurt Rules The following rules are regulating group battle categories of Buhurt International.","page_from":2,"page_to":2,"stable_key":"buhurt-rules:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"1d0937f7f8a85e944a658225ceda042af2e6a4ffff2c5cbfc81628b370f5b28f","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":0,"kind":"section","number":"1","title":"General Provisions","body":"","page_from":5,"page_to":5,"stable_key":"buhurt-rules:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d3460a1bce22168eb4fc581713c7f54838f7f6aa5be599e1b9b2b4e8ddc14938","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"1.1","title":"Criteria for participation","body":"","page_from":5,"page_to":5,"stable_key":"buhurt-rules:1.1","parent_key":"buhurt-rules:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"373698c1b24f28d33b0a0f3c40b233518100d961420e67e7510286f462344b15","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":2,"kind":"rule","number":"1.1.1","title":"Competitors must be of legal age in their country and the tournament hosting","body":"country.","page_from":5,"page_to":5,"stable_key":"buhurt-rules:1.1.1","parent_key":"buhurt-rules:1.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b460518a6b724c47b02e1701ca56c8310aa6b16fa91bd3fa9020deeb75bd153d","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":2,"kind":"rule","number":"1.1.2","title":null,"body":"Declare they are medically fit to fight prior to participation in the fight.","page_from":5,"page_to":5,"stable_key":"buhurt-rules:1.1.2","parent_key":"buhurt-rules:1.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8983547f0957c4ca4f7bbe24ca34480614a0f2d966f1b332328a627425e3939b","has_figures":false,"extraction":"text"},{"ordinal":7,"depth":2,"kind":"rule","number":"1.1.3","title":"A competitor must sign the disclaimer document (which states that the fighter is","body":"aware of the risks associated with participation and acknowledges that the organizer provides no warranties, that they have read the rules and agree to comply).","page_from":5,"page_to":5,"stable_key":"buhurt-rules:1.1.3","parent_key":"buhurt-rules:1.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6c15815efb6cbb96ed685d255095438fdcc6eb70224fef669749294eb9f81c78","has_figures":false,"extraction":"text"},{"ordinal":8,"depth":1,"kind":"rule","number":"1.2","title":"Scoring System Overview","body":"The grounded position of all the opposing team fighters is the main victory criteria in group battles.","page_from":5,"page_to":5,"stable_key":"buhurt-rules:1.2","parent_key":"buhurt-rules:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2bd1e2b198f5ab7f9fc08fafccc53d700a61c5bd6a5c1efa94d875d0a820e790","has_figures":false,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"1.3","title":"Grounded Competitor","body":"","page_from":5,"page_to":5,"stable_key":"buhurt-rules:1.3","parent_key":"buhurt-rules:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"59f0480d5897d8ad2a7af9ddcf49d7e017ae00cfd2af1712a0812b0b51eaf07e","has_figures":false,"extraction":"text"},{"ordinal":10,"depth":2,"kind":"rule","number":"1.3.1","title":null,"body":"The competitor is grounded in the following cases:\n● Touches the ground with torso, hip, arm, hand, knee, flat of shield except with their two feet.\n● Touches a grounded fighter for support with downward pressure.\n● If the list has no bottom rail touching the ground, and the fighter fell or stepped with both feet completely out/under the list. Marshals visually determine the boundary of the list.\n● Armour failure: if an element of the equipment cannot perform its protective function or is lost, the fighter shall be grounded by marshals. This includes helmet, neck protection (gorget), torso protection (a brigandine, a breastplate, etc), shoulder, elbow, forearm defense, gauntlet, groin protection, shin, thigh, a sabaton, knee-cop, upper arm defense.\n● While not carrying a weapon in your hand you're not allowed to engage in offensive actions like striking, pushing, grappling, or tripping, directed at an opponent. Holding a shield is not considered holding a weapon.\n● Took a reserve weapon from a squire beyond an allocated weapon distribution zone, or inside of the fenced list area, or, if the list has a wide top bar, collected it in any way other than picking it up from the surface of the bar in the allocated area.\n● If the list is a wide top bar, the fighter has their full body and legs on top of the list.\n● Was grounded by a marshal as a result of the rules violation. (see article 8) Yielded by kneeling, voluntarily withdrawing from a fight.","page_from":5,"page_to":5,"stable_key":"buhurt-rules:1.3.1","parent_key":"buhurt-rules:1.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["8"],"content_sha256":"53fed00fd49d28159c05b5f0c37df67142ede4c50cf918403eb272d5cf7af937","has_figures":false,"extraction":"text"},{"ordinal":11,"depth":2,"kind":"rule","number":"1.3.2","title":null,"body":"The competitor is not grounded in the following cases:\n● They touch the ground during or immediately after a successful takedown with one of the following cases.\n○ Edge of their shield (not a flat part) ○ Hand (open hand) ○ Fist (closed hand)\n● They touch their immediate opponent (a fighter they are grappling/falling together with) with any point of contact except for their torso, hips, or buttocks immediately after a successful throw.\n● If the remaining protective elements can compensate for an armor failure.\n● If the armor failure occurs to buttocks protection, cuisses that are supplementing a skirt or back elements of a greave.\n\n● Any part of a polearm, a sword blade or mace is not considered as contacting the ground.","page_from":6,"page_to":6,"stable_key":"buhurt-rules:1.3.2","parent_key":"buhurt-rules:1.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"42bb5a034f152c6fbfb9650ba936f7b7e4a834025bbb98911486f545f3c6c397","has_figures":false,"extraction":"text"},{"ordinal":12,"depth":0,"kind":"section","number":"2","title":"Marshals Committee","body":"Marshals Committee of a tournament should consist of","page_from":7,"page_to":7,"stable_key":"buhurt-rules:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"16a3503ddcedd598cbd1aacf7c6fd7de44dc4d8d3a067d54c3db9fab748cf781","has_figures":false,"extraction":"text"},{"ordinal":13,"depth":1,"kind":"rule","number":"2.1","title":"The Knight Marshal (Chief Official)","body":"● Is appointed by the Tournament Organizer.\n● Shall make the final decision in the case of any disagreement.\n● The Knight Marshal supervises the course of the fight and assesses the team’s interactions.\n● The Knight Marshal can return a fighter who was grounded by unauthorized technique to the fight, or withdraw the fighter who is ‘out of battle’.\n● Shall break inactive clinches with the “Break” local command and a yellow flag between the helmets of the fighters. The fighters must stop fighting immediately and take two steps apart.\n● Only the knight marshal is allowed to use the command “Start fight” and a signal with a flag that will start the round.\n● Only the knight marshal is allowed to use the command “Stop fight” and a signal with a flag that will stop the round.\n● Only the knight Marshal is allowed to use the command “All rise” verbally.","page_from":7,"page_to":7,"stable_key":"buhurt-rules:2.1","parent_key":"buhurt-rules:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2a13b008684432fa982b8eed9b74c45d45217bbd778871a31feb1142451db0f4","has_figures":false,"extraction":"text"},{"ordinal":14,"depth":1,"kind":"rule","number":"2.2","title":"Field Marshals","body":"● Shall break inactive clinches with the “Break” local command and a yellow flag between the helmets of the fighters. The fighters must stop fighting immediately and take two steps apart.\n● Local command “Fight” and a signal with a flag of the same marshal who announced the break indicates the recommencement of the fight for the fighters pulled out of the clinch, and a continuation of the fight in general.\n● Local commands “Break” and “Fight” are effective only for the fighters in the clinch.\nAfter the “Fight” command, any fighter can continue the fight with the same opponent or attack another opponent.\n● Will stop a fight on the command of the Knight Marshal “Stop fight” the line marshals will stop the fight with verbal commands and a yellow flag","page_from":7,"page_to":7,"stable_key":"buhurt-rules:2.2","parent_key":"buhurt-rules:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f74e00e44832c208967c1ca7ec3e31194915fe0258f2f40558e03546f5095dbe","has_figures":false,"extraction":"text"},{"ordinal":15,"depth":1,"kind":"rule","number":"2.3","title":"Line Marshals","body":"● There are between 4 and 8 Line Marshals.\nLine Marshals are the external eyes of the Knight Marshal and Field Marshals in Buhurt. They look for and report rule’s violations, armour malfunctions and any other situation in the list to the Knight Marshal or Field Marshal during the fight. Particular Line Marshals will keep watch of the allocated weapon distribution zone and inform the Knight Marshal or Field Marshals of any rule’s violation. Line Marshals do not intervene directly in the battle unless there is an extreme circumstance such as an injurie or potential injury. After the round, the Line Marshal is to report any relevant information to the Knight Marshal.","page_from":8,"page_to":8,"stable_key":"buhurt-rules:2.3","parent_key":"buhurt-rules:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8ef10c61c04adbbf884352723a2e311862769b040b93dc59bfec88c781bfbfef","has_figures":false,"extraction":"text"},{"ordinal":16,"depth":1,"kind":"rule","number":"2.4","title":"One (1) Secretary","body":"● Shall document the course and results of fights\n● Shall compile the tournament ladders, and determine the winner of the group stage based on registered results of the individual fights.\n● For the countries/regions with a certification system in place, a secretary must hold a certificate issued by a local/regional/international Tournament committee.","page_from":8,"page_to":8,"stable_key":"buhurt-rules:2.4","parent_key":"buhurt-rules:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6bedfb1706898c36a4a0513852014855d30da7d4a43e70063eb0d87ed02bb7cd","has_figures":false,"extraction":"text"},{"ordinal":17,"depth":1,"kind":"rule","number":"2.5","title":"One (1) Authenticity Committee Representative (AC rep)","body":"","page_from":8,"page_to":8,"stable_key":"buhurt-rules:2.5","parent_key":"buhurt-rules:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b1d4f825984a10042e0f37b3f25eba0bc457cd006945c01e9a5afce6f9c279bd","has_figures":false,"extraction":"text"},{"ordinal":18,"depth":1,"kind":"rule","number":"2.6","title":"Number of Marshals","body":"The number of marshals is determined separately for each tournament, depending on its form.","page_from":8,"page_to":8,"stable_key":"buhurt-rules:2.6","parent_key":"buhurt-rules:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0751af86dd958a5b68bb1e42cc8ec259594385d9f7a4412deed59339f2fb7e62","has_figures":false,"extraction":"text"},{"ordinal":19,"depth":0,"kind":"section","number":"3","title":"Authorized Equipment","body":"These rules aim to ensure a high standard of authenticity, safety, and historical accuracy in the equipment and conduct of the participants","page_from":9,"page_to":9,"stable_key":"buhurt-rules:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"141d0d45735ccdafda91934d86b5ebabfb256efe206a6ab1af57545d63fac9f2","has_figures":false,"extraction":"text"},{"ordinal":20,"depth":1,"kind":"rule","number":"3.1","title":"General Requirements","body":"","page_from":9,"page_to":9,"stable_key":"buhurt-rules:3.1","parent_key":"buhurt-rules:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"807639e9d5aa11ea0f5af6394a9f4c51ffd3e765914f57255201f7a553f7679f","has_figures":false,"extraction":"text"},{"ordinal":21,"depth":2,"kind":"rule","number":"3.1.1","title":"Technical and Authentic Compliance","body":"● All equipment must meet Buhurt International technical and authentic requirements.\n● Reference ”Weapons requirements” for all the rules\n● Reference “Weapons/Shield Chart” for sizes and weights","page_from":9,"page_to":9,"stable_key":"buhurt-rules:3.1.1","parent_key":"buhurt-rules:3.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d2bfd115dba99eec0b88e467f06c53b26f921e0f9db504ccb8ea019886e90e53","has_figures":false,"extraction":"text"},{"ordinal":22,"depth":2,"kind":"rule","number":"3.1.2","title":"Competitor Eligibility","body":"● Competitors are not allowed unless they have passed technical and authenticity checks.","page_from":9,"page_to":9,"stable_key":"buhurt-rules:3.1.2","parent_key":"buhurt-rules:3.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"23789af6f3225a1b771d2f572e5bf8a6b6f307ff6e7a9e5c5f89d4d010f1c0c6","has_figures":false,"extraction":"text"},{"ordinal":23,"depth":2,"kind":"rule","number":"3.1.3","title":"Weapon Requirements","body":"● Weapons must meet the Technical Requirement for Permitted Weapons.\n● Low-quality, dirty, rusty, or historically implausible weapons are not allowed.","page_from":9,"page_to":9,"stable_key":"buhurt-rules:3.1.3","parent_key":"buhurt-rules:3.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5a713078953b1863282c09f1aaf99091b8f9d8f7f5d7e604fa2d65503ea8cae8","has_figures":false,"extraction":"text"},{"ordinal":24,"depth":2,"kind":"rule","number":"3.1.4","title":"Footwear","body":"● Modern boots or medieval shoes with explicitly modern outsoles are not allowed.","page_from":9,"page_to":9,"stable_key":"buhurt-rules:3.1.4","parent_key":"buhurt-rules:3.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"14da441b7dba8ec13461c3103ee73478de5035329fcc39ad627acc49e78128c7","has_figures":false,"extraction":"text"},{"ordinal":25,"depth":2,"kind":"rule","number":"3.1.5","title":"Materials","body":"● Modern adhesive tape, plastic ties, and other visible modern materials are not permitted.\n● Textile adhesive tape of neutral colors for kit repair is an exception.","page_from":9,"page_to":9,"stable_key":"buhurt-rules:3.1.5","parent_key":"buhurt-rules:3.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f14a736e4554af114ae0ae83c86d50cab537ba1921f553ac953c3fe97613cc1c","has_figures":false,"extraction":"text"},{"ordinal":26,"depth":2,"kind":"rule","number":"3.1.6","title":"Decorations","body":"● Slogans and imagery on equipment should be historically plausible and not derogatory.\n● No modern equipment or decorations are allowed.","page_from":9,"page_to":9,"stable_key":"buhurt-rules:3.1.6","parent_key":"buhurt-rules:3.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7e19f796841b7dd3812d4ce6364edcf57c902f48d8e915cbc7bdfd73e1e989b5","has_figures":false,"extraction":"text"},{"ordinal":27,"depth":1,"kind":"rule","number":"3.2","title":"Specifics on Weapons and Shields","body":"● All Buhurt International weapons and shields are permitted.\n● Any combination of these weapons is allowed.","page_from":9,"page_to":9,"stable_key":"buhurt-rules:3.2","parent_key":"buhurt-rules:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7d6fab2559cb6209fd001d2d01fd9df3435a0353bddda90127105fdd82b3a8d3","has_figures":false,"extraction":"text"},{"ordinal":28,"depth":1,"kind":"rule","number":"3.3","title":"Equipment Changes","body":"● Participants are allowed to change elements of equipment (armor or weapon) during intervals or due to breakage.\n● Technical Marshal supervision is required for equipment changes.","page_from":10,"page_to":10,"stable_key":"buhurt-rules:3.3","parent_key":"buhurt-rules:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"12e03d110f28515618e38c0f128730da22cbdc834de547d76cd1af2c40e0a7de","has_figures":false,"extraction":"text"},{"ordinal":29,"depth":1,"kind":"rule","number":"3.4","title":"Marshal Authority","body":"● The Head Marshal and Authenticity have the authority to demand changes to any element of armor or weapon for safety, aesthetic, or historical accuracy reasons.","page_from":10,"page_to":10,"stable_key":"buhurt-rules:3.4","parent_key":"buhurt-rules:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e31baba444894a5bc595963fe915ca52e1bfccc7002825f522e4259ed4b0db24","has_figures":false,"extraction":"text"},{"ordinal":30,"depth":0,"kind":"section","number":"4","title":"Authorized Fighting Techniques","body":"A fighter must hold a hafted weapon with at least one hand. If a fighter is not holding their weapon with a hand, they are considered disarmed and are not authorized to perform any attacking actions until the grip on the haft is restored.","page_from":11,"page_to":11,"stable_key":"buhurt-rules:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9560ed13021760b36b24b1fd6bd05ea56433f16599b455037ab4c0908be6fe69","has_figures":false,"extraction":"text"},{"ordinal":31,"depth":1,"kind":"rule","number":"4.1","title":"Permitted Strikes","body":"● Strikes are permitted with any part of the weapon, shield, and various body parts (arms, legs and head).\n● A competitor can strike with a free hand provided they have a weapon in the other hand.\n● A competitor can strike an opponent who has lost their weapon.\n● A competitor can strike an out of balance opponent before they are grounded.","page_from":11,"page_to":11,"stable_key":"buhurt-rules:4.1","parent_key":"buhurt-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1b8a135b8d7ce579edaaa57f8b9df38ec70ef8e13fc0c79fffbbd0319984053e","has_figures":false,"extraction":"text"},{"ordinal":32,"depth":1,"kind":"rule","number":"4.2","title":"Strike Zones","body":"● Strikes are allowed to any area not mentioned as a prohibited strike zone (refer to section 5. Prohibited Fighting Techniques).","page_from":11,"page_to":11,"stable_key":"buhurt-rules:4.2","parent_key":"buhurt-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["5"],"content_sha256":"2dbd8b80636d9071be50d4a3033f8cf86787d59f8f474708942fb4754ed1c600","has_figures":false,"extraction":"text"},{"ordinal":33,"depth":1,"kind":"rule","number":"4.3","title":"Weapon-Grabbing","body":"● Grabbing the opponent's weapon (except the blade) or shield with a free hand is permitted.","page_from":11,"page_to":11,"stable_key":"buhurt-rules:4.3","parent_key":"buhurt-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"16effae8b4eb74ea738211d50df4fb2f66f21c053fa3be695f1485e43e22308e","has_figures":false,"extraction":"text"},{"ordinal":34,"depth":1,"kind":"rule","number":"4.4","title":"Techniques and Moves","body":"● Back heels (tripping), wrestling throws, and clinching are allowed.\n● Any movement in the list, leaning on the barrier of the list, any holds and grips of the barrier of the list.\n● A competitor can disarm any opponent by any authorized action, excluding blade holds\n● A competitor can take away a weapon from the belt of the opponent, provided the fighter holds their weapon. The fighter is then allowed to use the opponent’s weapon until the end of the round, and then it must be surrendered back to the opponent.\n● Opposing fighters can take or knock down reserve weapons that are placed on a wide top bar list as long as the squire is not holding them.\n● Grappling the base of the skull but not the bottom edge of the helmet is permitted.","page_from":11,"page_to":11,"stable_key":"buhurt-rules:4.4","parent_key":"buhurt-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d9506d17bd3fe2c1bc31c01be7200bcdad396ebf98b78e22a3b028cc50491c1d","has_figures":false,"extraction":"text"},{"ordinal":35,"depth":1,"kind":"rule","number":"4.5","title":"Weapon loss","body":"A fighter who has lost their weapon is allowed to:\n● Protect themself from the strikes without performing any offensive actions or holds.\n● Take a reserve weapon they had with them.\n● Take a reserve weapon from an ungrounded teammate in the list.\n● Take a reserve weapon from their teammate located in the allocated weapon distribution zone.\n● Grab a polearm which leans against the top rail of the barrier or its ungrounded teammate’s/owner’s body. In this case, it is not considered lying on the surface of the list.\n● Yield by kneeling.","page_from":12,"page_to":12,"stable_key":"buhurt-rules:4.5","parent_key":"buhurt-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6f4bfaf15c0f8c22b01e18effa37b7fdd23bd6648eb7fd3475f808bc9cb6c04f","has_figures":false,"extraction":"text"},{"ordinal":36,"depth":1,"kind":"rule","number":"4.6","title":"Reserve Weapons","body":"","page_from":12,"page_to":12,"stable_key":"buhurt-rules:4.6","parent_key":"buhurt-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7534ffaa51096f866a248118dd15919472cadc80b46a5d41cf499d24b2e101f5","has_figures":false,"extraction":"text"},{"ordinal":37,"depth":2,"kind":"rule","number":"4.6.1","title":"Wide top bar list","body":"● Reserve weapons must be placed on the top of the bar in the designated area for a fighter to pick up themselves. It is prohibited to pass a weapon to the fighter or hold the weapon when a fighter is taking it. This will impose a penalty (See article 5 in “Buhurt Regulations”)","page_from":12,"page_to":12,"stable_key":"buhurt-rules:4.6.1","parent_key":"buhurt-rules:4.6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["5"],"content_sha256":"5968c349fb23c9ffab3250c49cb91431009abe1b666f89cb51edd96260dc1d98","has_figures":false,"extraction":"text"},{"ordinal":38,"depth":2,"kind":"rule","number":"4.6.2","title":"No top bar list","body":"● Reserve weapons may be passed to the fighter from above the top rail of the list within the designated area. It is prohibited to pass a weapon below the top rail of the list. This will impose a penalty (See article 5 in “Buhurt Regulations”)","page_from":12,"page_to":12,"stable_key":"buhurt-rules:4.6.2","parent_key":"buhurt-rules:4.6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["5"],"content_sha256":"fe0755633ef755a58e69d85aa53b5b1461a454462e687770e71749ae71a64477","has_figures":false,"extraction":"text"},{"ordinal":39,"depth":0,"kind":"section","number":"5","title":"Prohibited Fighting Techniques","body":"Performance of any prohibited technique is a serious rules violation and is penalized with a verbal warning, yellow or red card. The penalty is imposed regardless of the fighter’s intent.","page_from":13,"page_to":13,"stable_key":"buhurt-rules:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"23b59b06122d1c0c9574094827268ee9943399f3c2d70f6d304e53dd986cebc6","has_figures":false,"extraction":"text"},{"ordinal":40,"depth":1,"kind":"rule","number":"5.1","title":"Unlisted Techniques","body":"● Any actions not listed in section 5 of the rules are prohibited. Only authorized techniques are permitted.","page_from":13,"page_to":13,"stable_key":"buhurt-rules:5.1","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["5"],"content_sha256":"16376b4412463e4b54495096a7a0f2eb1b3dbe0f81e64f9dfa49b64157cf7f7b","has_figures":false,"extraction":"text"},{"ordinal":41,"depth":1,"kind":"rule","number":"5.2","title":"Thrusting Actions","body":"● Any thrusting actions with a weapon are prohibited. Threats of a thrusting action are also prohibited.","page_from":13,"page_to":13,"stable_key":"buhurt-rules:5.2","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1bdbb399b320d439ac543a619a1bb82058c6c96f6e41118ee4bfa8474dc76c44","has_figures":false,"extraction":"text"},{"ordinal":42,"depth":1,"kind":"rule","number":"5.3","title":"Offensive Actions at Prohibited Strike Zones","body":"● Any offensive actions aimed at the prohibited strike zones (See section: 7. Prohibited Strike Zones) are prohibited.","page_from":13,"page_to":13,"stable_key":"buhurt-rules:5.3","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c4936e57670a67b04eb207e95a88ddd09d392261638e51072ad6e28d7ee1951d","has_figures":false,"extraction":"text"},{"ordinal":43,"depth":1,"kind":"rule","number":"5.4","title":"Actions with Foot, Shin and Knee","body":"● Actions with foot, shin, and knee aimed at the knee are prohibited. This includes actions that may cause the knee to hyperextend, such as push kicks to the thigh.","page_from":13,"page_to":13,"stable_key":"buhurt-rules:5.4","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"fb493556e55bdfd2df2e5b97612ee7a52345725fab14a56354a3cea90767574d","has_figures":false,"extraction":"text"},{"ordinal":44,"depth":1,"kind":"rule","number":"5.5","title":"Grappling and Holds","body":"● Grappling and holding with the hand on specific armor elements (aventail, edge of pauldrons, edge of the helmet), pushes on the bottom edge of the helmet and subsequent neck twists are prohibited.","page_from":13,"page_to":13,"stable_key":"buhurt-rules:5.5","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ad4acc49f8055b23d85ca9a20f31d4b50ae86b183370c893698d8bd2e584fc19","has_figures":false,"extraction":"text"},{"ordinal":45,"depth":1,"kind":"rule","number":"5.6","title":"Armor Tampering","body":"● Deliberate attempts to remove any elements of the armor are prohibited.\n● The fighter committing the offense will be sat down and given a yellow card.\n● A fighter who deliberately has their armor so it can be easily removed will receive a yellow card for unsportsmanlike conduct.","page_from":13,"page_to":13,"stable_key":"buhurt-rules:5.6","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4adbb69d57bf89ea71dcb1fdf2c75d7fd3b47b3d2f0122eaa7cf3bf92699d051","has_figures":false,"extraction":"text"},{"ordinal":46,"depth":1,"kind":"rule","number":"5.7","title":"Suffocation Techniques","body":"● Grips, clamps, suffocation techniques with direct pressure on the neck (under or on top of the aventail) using any part of the body, equipment, or weapon are prohibited. A poorly fitted helmet does not count as a suffocating technique.","page_from":13,"page_to":13,"stable_key":"buhurt-rules:5.7","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"92b395ee12a983bd850310d5754ff4833750f5c5d22c21bee966c71aa6f537bf","has_figures":false,"extraction":"text"},{"ordinal":47,"depth":1,"kind":"rule","number":"5.8","title":"Specific Strikes","body":"● Strikes or punching with the head of a one-handed axe are prohibited if the grip of the hand is less than 30 cm away from the blade.\n● Polearm: strikes with hammerheads are prohibited","page_from":13,"page_to":13,"stable_key":"buhurt-rules:5.8","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5e86be4ee00038c3add07fd977c597460549a4e7c1d0701a4786295e390b61f5","has_figures":false,"extraction":"text"},{"ordinal":48,"depth":1,"kind":"rule","number":"5.9","title":"Dangerous Takedowns","body":"● Any takedown that spikes an opponent on their head/neck and suplex (arch throws) variations are prohibited.","page_from":14,"page_to":14,"stable_key":"buhurt-rules:5.9","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c9e28882dde3fe4a09e668638a2b1418f5ddcf4269e8bb30895d47392b4c482c","has_figures":false,"extraction":"text"},{"ordinal":49,"depth":1,"kind":"rule","number":"5.10","title":"Intentional Passivity","body":"● Intentional passivity and stalling of the action (such as an inactive clinch) are prohibited. An inactive clinch is a clinch situation with the fighters performing weak weapon strikes or no grappling techniques aimed at grounding their opponent for 10 seconds or longer. The strikes with a fist, knees, or shield, are not considered.","page_from":14,"page_to":14,"stable_key":"buhurt-rules:5.10","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a5006ec75252ac67540708e312b9d6eed4ea74659f8f0f52e5a1b19fb41d7413","has_figures":false,"extraction":"text"},{"ordinal":50,"depth":1,"kind":"rule","number":"5.11","title":"Joint Locks and Hyperextension","body":"● Arm lock and leg lock techniques, and any actions that may cause a limb to hyperextend, are prohibited.","page_from":14,"page_to":14,"stable_key":"buhurt-rules:5.11","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"be3033b868b0532973ca112ebe7e20a78ab9e9f9cc88fd84494d59ccf72ce013","has_figures":false,"extraction":"text"},{"ordinal":51,"depth":1,"kind":"rule","number":"5.12","title":"Striking Grounded competitors","body":"● Striking a grounded competitor is prohibited.","page_from":14,"page_to":14,"stable_key":"buhurt-rules:5.12","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"395cd74d22fb750d3da0e8cf9af9d7c5a247cd0c03caf952befbeb4321b60962","has_figures":false,"extraction":"text"},{"ordinal":52,"depth":1,"kind":"rule","number":"5.13","title":"Injuring competitor","body":"● Deliberately injuring the fighter who has lost a defensive element of equipment.","page_from":14,"page_to":14,"stable_key":"buhurt-rules:5.13","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e00dbc702b54a0ba09ebc1b7847d8331f7ede7e43f60a22e1519b25d9e70fd96","has_figures":false,"extraction":"text"},{"ordinal":53,"depth":1,"kind":"rule","number":"5.14","title":"Uncontrolled Strikes","body":"● Any uncontrolled strikes and actions with a weapon.","page_from":14,"page_to":14,"stable_key":"buhurt-rules:5.14","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b1f7b0eae0b3333586f27968f41f01ae4d4d9de06289b3e2361fa34e690a90c1","has_figures":false,"extraction":"text"},{"ordinal":54,"depth":1,"kind":"rule","number":"5.15","title":"Weapon Loss","body":"● It is prohibited to pick up a weapon that is lying flat on the ground, to receive a weapon from an already grounded fighter, to receive a weapon from any outside the list except for the squire in the designated area.","page_from":14,"page_to":14,"stable_key":"buhurt-rules:5.15","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8897a6d0496167984b698fa211f40c610479727f9de985e53894194664e2a538","has_figures":false,"extraction":"text"},{"ordinal":55,"depth":0,"kind":"section","number":"6","title":"Other Prohibited Actions","body":"These rules contribute to maintaining the integrity, safety, and orderliness of the event. They cover aspects such as participant behavior, substance use, adherence to commands, and respect for officials and other attendees. The role of the Knight Marshal is highlighted in several instances, emphasizing their authority and responsibility in ensuring the proper conduct of the event.","page_from":15,"page_to":15,"stable_key":"buhurt-rules:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d126392e2309f10ce0cd7359190088ace782de9936ce663b2ab442265a8ffae9","has_figures":false,"extraction":"text"},{"ordinal":56,"depth":1,"kind":"rule","number":"6.1","title":"Leaving Lists","body":"● Intentional leaving of the lists after the command “Start Fight” and before the announcement of the results of the fight is prohibited. Permission to leave must be granted by the Knight Marshal.","page_from":15,"page_to":15,"stable_key":"buhurt-rules:6.1","parent_key":"buhurt-rules:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ad85887b7c33bb681ee4eeebfe82c6d3fddd76a42d0884c4f431747afece15e9","has_figures":false,"extraction":"text"},{"ordinal":57,"depth":1,"kind":"rule","number":"6.2","title":"Interference from grounded competitors","body":"● Grounded fighters must remain on the ground until the “Stop fight” command of the Knight Marshal. They are not allowed to return to a standing position.\n● The grounded fighters are not allowed to physically interfere in the course of the fight.\n● A grounded fighter must maintain a comfortable seated or lying position until the end of the round. A comfortable position is a signal that the fighter is not injured.\n● The grounded competitors are not allowed to change their position in the list unless there is a threat to their safety.","page_from":15,"page_to":15,"stable_key":"buhurt-rules:6.2","parent_key":"buhurt-rules:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b0175d248b54c8516d11c36c863be067cb5b29f5413d5901034e17a522e81827","has_figures":false,"extraction":"text"},{"ordinal":58,"depth":1,"kind":"rule","number":"6.3","title":"Equipment and Weapon Approval","body":"● Competitors are not allowed to use any part of the equipment or any weapon that hasn't been allowed by the Authenticity.","page_from":15,"page_to":15,"stable_key":"buhurt-rules:6.3","parent_key":"buhurt-rules:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"71977f91c1052a0118f2d766f981b10ab277919b4282c1c0b1ca186ee70a6d48","has_figures":false,"extraction":"text"},{"ordinal":59,"depth":1,"kind":"rule","number":"6.4","title":"Substance Use","body":"● It's not allowed for the competitor to be under the influence of alcohol or any psychoactive substances.","page_from":15,"page_to":15,"stable_key":"buhurt-rules:6.4","parent_key":"buhurt-rules:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d8ec345a50f467d8e25a76203206324ba2725200b12b50c6fc1ed026cdbf5849","has_figures":false,"extraction":"text"},{"ordinal":60,"depth":1,"kind":"rule","number":"6.5","title":"Offensive Actions Against Others","body":"● Any offensive actions against marshals, corner support, spectators, or anyone else other than the current opponent are prohibited.","page_from":15,"page_to":15,"stable_key":"buhurt-rules:6.5","parent_key":"buhurt-rules:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d84f9fc29d71fc6382ba96c7ffdf68913982c38005db80398dd93a278742e9e0","has_figures":false,"extraction":"text"},{"ordinal":61,"depth":1,"kind":"rule","number":"6.6","title":"Event Interference","body":"● Any actions made by a competitor or their support that may impede the course of the event are prohibited.\n● For a demonstration of poor sportsmanship, derogatory behavior, obscene language, commentaries directed at marshals, opponents, or spectators.","page_from":15,"page_to":15,"stable_key":"buhurt-rules:6.6","parent_key":"buhurt-rules:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"253cb82ead4bc1d2b8ad588833009a9edc85bcfa76061d75cda561e423fb9775","has_figures":false,"extraction":"text"},{"ordinal":62,"depth":0,"kind":"section","number":"7","title":"Prohibited Strike Zones","body":"These rules are designed to prioritize the safety of the participants by prohibiting strikes to vulnerable and potentially dangerous areas. The specific definitions and considerations for the base of the skull and back of the knee provide clarity on the prohibited strike zones. Striking the foot is allowed under certain circumstances, emphasizing the importance of situational awareness and control during combat. The overall intention is to prevent serious injuries and ensure a fair and safe competition.","page_from":16,"page_to":16,"stable_key":"buhurt-rules:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a95e5886009638c7552bb1ef01db269fcc736b669a6bfde4e97a25f271d2454f","has_figures":true,"extraction":"text"},{"ordinal":63,"depth":1,"kind":"rule","number":"7.1","title":"Back and Front of the Neck","body":"● Strikes to the back and front of the neck are prohibited.","page_from":16,"page_to":16,"stable_key":"buhurt-rules:7.1","parent_key":"buhurt-rules:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"27e9724848359bdf714326056f5e23a19b36993710f120decb14058cbbf13894","has_figures":true,"extraction":"text"},{"ordinal":64,"depth":1,"kind":"rule","number":"7.2","title":"Base of Skull","body":"● The base of the skull is considered a prohibited strike zone, specifically defined as the bottom third of the back of the helmet.","page_from":16,"page_to":16,"stable_key":"buhurt-rules:7.2","parent_key":"buhurt-rules:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b35d3b04e9ac50b48f120ce17bb47ceeee0ec7d2b83892bf1ba1d8406f987959","has_figures":true,"extraction":"text"},{"ordinal":65,"depth":1,"kind":"rule","number":"7.3","title":"Back of Knee","body":"● Strikes to the back of the knee are prohibited. No pressure is to be placed on the back of the knee.","page_from":16,"page_to":16,"stable_key":"buhurt-rules:7.3","parent_key":"buhurt-rules:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"91076ae5c7e69b60527ba95fffbfa8ebbb63a79a2791b58eb6bcf380ed9e6c29","has_figures":true,"extraction":"text"},{"ordinal":66,"depth":1,"kind":"rule","number":"7.4","title":"Groin and Crotch","body":"● Strikes to the groin and crotch are prohibited.","page_from":16,"page_to":16,"stable_key":"buhurt-rules:7.4","parent_key":"buhurt-rules:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f40c2efb874e78667245ec4eaa628142a354920b0900bce61b2f192d7ac5343d","has_figures":true,"extraction":"text"},{"ordinal":67,"depth":1,"kind":"rule","number":"7.5","title":"Feet and Ankle","body":"● Strikes to the feet and ankles are prohibited. However, striking the foot is not considered a prohibited strike if the competitor raises their foot while the strike is already occurring.","page_from":16,"page_to":16,"stable_key":"buhurt-rules:7.5","parent_key":"buhurt-rules:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3491783a24c112fef163dfcfa27b746cc0602ce2d0b4af7e71d4f427442e718a","has_figures":true,"extraction":"text"},{"ordinal":68,"depth":1,"kind":"rule","number":"7.6","title":"Unprotected Body Parts","body":"● Any part of the opponent’s body that has lost its protection is considered a prohibited strike zone.","page_from":16,"page_to":16,"stable_key":"buhurt-rules:7.6","parent_key":"buhurt-rules:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1e2bb95808de3e1f3e59e6179e5366be2a8323ba12c1737e7809388414413e03","has_figures":true,"extraction":"text"},{"ordinal":69,"depth":0,"kind":"section","number":"8","title":"Management of the Fights","body":"Fights of the category are managed under the Buhurt International ‘Buhurt Regulations’ by penalties that are imposed depending on the situation in the list and fighters’ and marshals’ actions.","page_from":17,"page_to":17,"stable_key":"buhurt-rules:8","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e1e5e178fdc56478b7e89aeb0ba9ff68613a4fb9c91db91ed2bd82f1bff239cc","has_figures":false,"extraction":"text"},{"ordinal":70,"depth":0,"kind":"note","number":"9","title":"Change log","body":"This will be the change log of this document. It will be updated regularly and we will display what has been removed/added/reworded/formatted. This way we keep transparent communication and clarity about the rules December 2024 (Version update from 2024.03 to 2024.12)\n\nUpdate date: December-2024 -replaced: “Oral” with “Verbal” -add: 4.6.2 : This will impose a penalty (See article 5 in “Buhurt Regulations”) -add: 4.6.1 : This will impose a penalty (See article 5 in “Buhurt Regulations”) -add: 3.1 Reference ”Weapons requirements” for all the rules -add: 3.1 Reference “Weapons/Shield Chart” for sizes and weights Update date: March-2024\n- format: new design format, document will be used from now on.","page_from":18,"page_to":18,"stable_key":"buhurt-rules:9","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":["5"],"content_sha256":"3763490d9995a5aae7c2c7c3657285816aafabed4bcdc6ba912fa2b286bf2a25","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_historical_version($rules${"governing_body":"Buhurt International","history":"archive-2026-10-06","inventory_key":"marshal/buhurt-rules","version":{"version":"2026.1.1","title":"Buhurt Rules 2026.1.1","published_on":null,"effective_from":null,"note":"Title \"Buhurt Rules\"; cover \"VER. 2026.1.1\" (January 2026). Newer than 2024.12.13, older than the current 26.4.1. Version labels: \"2024.12\" style until 2025, then \"26.1\" = January 2026 (Duel Regulations change log: \"January 2026 (2025.02 to 2026.1)\"; Infractions: \"January - 2026 (V. 26.1)\").","source_url":"https://drive.google.com/file/d/1sSbs6x_Dy5JXqHtX0-03_rzje7svctxr/view","source_sha256":"418c849783cf388b07fffef4ae5acbc7aa65eccceff85fd9f5069a789005c1ed","retrieved_at":null,"page_count":18,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 1 page(s) without a text layer","content_sha256":"4d2896a9b52232170255251dcf1450791e0aa87519fc92114d303f52c3aa81a2","detected":{"version":"2026.1.1","date":null},"confirmed_by":"Claude Code (Pack 22 historical import), read from the archived PDF: cover (OCR of the page image), footers and change log","historical":true,"edition_seq":2,"edition_evidence":"Title \"Buhurt Rules\"; cover \"VER. 2026.1.1\" (January 2026). Newer than 2024.12.13, older than the current 26.4.1. Version labels: \"2024.12\" style until 2025, then \"26.1\" = January 2026 (Duel Regulations change log: \"January 2026 (2025.02 to 2026.1)\"; Infractions: \"January - 2026 (V. 26.1)\").","source_files":[{"file":"Marshal/Archive/Buhurt Rules 2026.1.1.pdf","archive":"Marshal","sha256":"418c849783cf388b07fffef4ae5acbc7aa65eccceff85fd9f5069a789005c1ed","drive_file_id":"1sSbs6x_Dy5JXqHtX0-03_rzje7svctxr"}],"reconciliation":{"ok":true,"errors":[],"warnings":[],"pages":18,"source_lines":413,"assigned_lines":493,"furniture_lines":86,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99941,"provisions":69,"numbered":68,"needs_review":0,"verified":0,"empty_pages":[],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":4,"picture_text_lines":0,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"BUHURT\n\nVER. 2026.1.1\n\nBuhurt Rules Buhurt Rules The following rules are regulating group battle categories of Buhurt International.","page_from":1,"page_to":2,"stable_key":"buhurt-rules:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"abbf78645c71ca568971c2e45ce93b9e7b7fd4099c9c80956a760b8f34a7c5a6","has_figures":true,"extraction":"mixed"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"General Provisions","body":"","page_from":5,"page_to":5,"stable_key":"buhurt-rules:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d3460a1bce22168eb4fc581713c7f54838f7f6aa5be599e1b9b2b4e8ddc14938","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":1,"kind":"rule","number":"1.1","title":"Criteria for participation","body":"","page_from":5,"page_to":5,"stable_key":"buhurt-rules:1.1","parent_key":"buhurt-rules:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"373698c1b24f28d33b0a0f3c40b233518100d961420e67e7510286f462344b15","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":2,"kind":"rule","number":"1.1.1","title":"Competitors must be of legal age in their country and the tournament hosting","body":"country.","page_from":5,"page_to":5,"stable_key":"buhurt-rules:1.1.1","parent_key":"buhurt-rules:1.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b460518a6b724c47b02e1701ca56c8310aa6b16fa91bd3fa9020deeb75bd153d","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":2,"kind":"rule","number":"1.1.2","title":null,"body":"Declare they are medically fit to fight prior to participation in the fight.","page_from":5,"page_to":5,"stable_key":"buhurt-rules:1.1.2","parent_key":"buhurt-rules:1.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8983547f0957c4ca4f7bbe24ca34480614a0f2d966f1b332328a627425e3939b","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":2,"kind":"rule","number":"1.1.3","title":"A competitor must sign the disclaimer document (which states that the fighter is","body":"aware of the risks associated with participation and acknowledges that the organizer provides no warranties, that they have read the rules and agree to comply).","page_from":5,"page_to":5,"stable_key":"buhurt-rules:1.1.3","parent_key":"buhurt-rules:1.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6c15815efb6cbb96ed685d255095438fdcc6eb70224fef669749294eb9f81c78","has_figures":false,"extraction":"text"},{"ordinal":7,"depth":1,"kind":"rule","number":"1.2","title":"Scoring System Overview","body":"The grounded position of all the opposing team fighters is the main victory criteria in group battles.","page_from":5,"page_to":5,"stable_key":"buhurt-rules:1.2","parent_key":"buhurt-rules:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2bd1e2b198f5ab7f9fc08fafccc53d700a61c5bd6a5c1efa94d875d0a820e790","has_figures":false,"extraction":"text"},{"ordinal":8,"depth":1,"kind":"rule","number":"1.3","title":"Grounded Competitor","body":"","page_from":5,"page_to":5,"stable_key":"buhurt-rules:1.3","parent_key":"buhurt-rules:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"59f0480d5897d8ad2a7af9ddcf49d7e017ae00cfd2af1712a0812b0b51eaf07e","has_figures":false,"extraction":"text"},{"ordinal":9,"depth":2,"kind":"rule","number":"1.3.1","title":null,"body":"The competitor is grounded in the following cases:\n● Touches the ground with torso, hip, arm, hand, knee,shield except with their two feet.\n● Touches a grounded fighter for support with downward pressure.\n● If the list has no bottom rail touching the ground, and the fighter fell or stepped with both feet completely out/under the list. Marshals visually determine the boundary of the list.\n● Armour failure: if an element of the equipment cannot perform its protective function or is lost, the fighter shall be grounded by marshals. This includes helmet, neck protection (gorget), torso protection (a brigandine, a breastplate, etc), shoulder, elbow, forearm defense, gauntlet, groin protection, shin, thigh, a sabaton, knee-cop, upper arm defense.\n● While not carrying a weapon in your hand you're not allowed to engage in offensive actions like striking, pushing, grappling, or tripping, directed at an opponent. Holding a shield is not considered holding a weapon.\n● Took a reserve weapon from a squire beyond an allocated weapon distribution zone, or inside of the fenced list area, or, if the list has a wide top bar, collected it in any way other than picking it up from the surface of the bar in the allocated area.\n● If the list is a wide top bar, the fighter has their full body and legs on top of the list.\n● Was grounded by a marshal as a result of the rules violation. (see article 8) Yielded by kneeling, voluntarily withdrawing from a fight.","page_from":5,"page_to":5,"stable_key":"buhurt-rules:1.3.1","parent_key":"buhurt-rules:1.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["8"],"content_sha256":"0dd1ad137db566ae6ab8b339294da5ce6b867bb67ccab4a28a26de2d217e0a76","has_figures":false,"extraction":"text"},{"ordinal":10,"depth":2,"kind":"rule","number":"1.3.2","title":null,"body":"The competitor is not grounded in the following cases:\n● They touch the ground during or immediately after a successful takedown with one of the following cases.\n○ Edge of their shield (not a flat part) ○ Hand (open hand) ○ Fist (closed hand)\n● They touch their immediate opponent (a fighter they are grappling/falling together with) with any point of contact except for their torso, hips, or buttocks immediately after a successful throw.\n● If the remaining protective elements can compensate for an armor failure.\n● If the armor failure occurs to buttocks protection, cuisses that are supplementing a skirt or back elements of a greave.\n\n● Any part of a polearm, a sword blade or mace is not considered as contacting the ground.","page_from":6,"page_to":6,"stable_key":"buhurt-rules:1.3.2","parent_key":"buhurt-rules:1.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"42bb5a034f152c6fbfb9650ba936f7b7e4a834025bbb98911486f545f3c6c397","has_figures":false,"extraction":"text"},{"ordinal":11,"depth":0,"kind":"section","number":"2","title":"Marshals Committee","body":"Marshals Committee of a tournament should consist of:","page_from":7,"page_to":7,"stable_key":"buhurt-rules:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a1cd75ed9ac3df325ce82334e2a32d76c02c04e166cdcc4bdd5b899fb8bdb2b0","has_figures":false,"extraction":"text"},{"ordinal":12,"depth":1,"kind":"rule","number":"2.1","title":"The Knight Marshal (Chief Official)","body":"● Is appointed by the Tournament Organizer.\n● Shall make the final decision in the case of any disagreement.\n● The Knight Marshal supervises the course of the fight and assesses the team’s interactions.\n● The Knight Marshal can return a fighter who was grounded by unauthorized technique to the fight, or withdraw the fighter who is ‘out of battle’.\n● Shall break inactive clinches with the “Break” local command and a yellow flag between the helmets of the fighters. The fighters must stop fighting immediately and take two steps apart.\n● Shall stop rounds with the “Hold” command and yellow flag between helmets of the fighters. The fighters must stop across the entire list and should not move.\n● Only the knight marshal is allowed to use the command “Start fight” and a signal with a flag that will start the round.\n● Only the knight marshal is allowed to use the command “Stop fight” and a signal with a flag that will stop the round.\n● Only the knight Marshal is allowed to use the command “All rise” verbally.","page_from":7,"page_to":7,"stable_key":"buhurt-rules:2.1","parent_key":"buhurt-rules:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"576b4eff452812a76e4712b98132d2899e6247b1d7671cce088c4dfd6e69163b","has_figures":false,"extraction":"text"},{"ordinal":13,"depth":1,"kind":"rule","number":"2.2","title":"Field Marshals","body":"● Shall break inactive clinches with the “Break” local command and a yellow flag between the helmets of the fighters. The fighters must stop fighting immediately and take two steps apart.\n● Local command “Fight” and a signal with a flag of the same marshal who announced the break indicates the recommencement of the fight for the fighters pulled out of the clinch, and a continuation of the fight in general.\n● Local commands “Break” and “Fight” are effective only for the fighters in the clinch.\nAfter the “Fight” command, any fighter can continue the fight with the same opponent or attack another opponent.\n● Will stop a fight on the command of the Knight Marshal “Stop fight” the line marshals will stop the fight with verbal commands and a yellow flag","page_from":7,"page_to":7,"stable_key":"buhurt-rules:2.2","parent_key":"buhurt-rules:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f74e00e44832c208967c1ca7ec3e31194915fe0258f2f40558e03546f5095dbe","has_figures":false,"extraction":"text"},{"ordinal":14,"depth":1,"kind":"rule","number":"2.3","title":"Line Marshals","body":"● There are between 4 and 8 Line Marshals.\nLine Marshals are the external eyes of the Knight Marshal and Field Marshals in Buhurt. They look for and report rule’s violations, armour malfunctions and any other situation in the list to the Knight Marshal or Field Marshal during the fight. Particular Line Marshals will keep watch of the allocated weapon distribution zone and inform the Knight Marshal or Field Marshals of any rule’s violation. Line Marshals do not intervene directly in the battle unless there is an extreme circumstance such as an injurie or potential injury. After the round, the Line Marshal is to report any relevant information to the Knight Marshal.","page_from":8,"page_to":8,"stable_key":"buhurt-rules:2.3","parent_key":"buhurt-rules:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8ef10c61c04adbbf884352723a2e311862769b040b93dc59bfec88c781bfbfef","has_figures":false,"extraction":"text"},{"ordinal":15,"depth":1,"kind":"rule","number":"2.4","title":"One (1) Secretary","body":"● Shall document the course and results of fights.\n● Shall compile the tournament ladders, and determine the winner of the group stage based on registered results of the individual fights.\n● For the countries/regions with a certification system in place, a secretary must hold a certificate issued by a local/regional/international Tournament committee.","page_from":8,"page_to":8,"stable_key":"buhurt-rules:2.4","parent_key":"buhurt-rules:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"894c9f5d7dd49538ca558321549a4e20de4e1bcdeeebb0a0688f2d797e545eb8","has_figures":false,"extraction":"text"},{"ordinal":16,"depth":1,"kind":"rule","number":"2.5","title":"One (1) Authenticity Committee Representative (AC rep)","body":"","page_from":8,"page_to":8,"stable_key":"buhurt-rules:2.5","parent_key":"buhurt-rules:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b1d4f825984a10042e0f37b3f25eba0bc457cd006945c01e9a5afce6f9c279bd","has_figures":false,"extraction":"text"},{"ordinal":17,"depth":1,"kind":"rule","number":"2.6","title":"Number of Marshals","body":"The number of marshals is determined separately for each tournament, depending on its form.","page_from":8,"page_to":8,"stable_key":"buhurt-rules:2.6","parent_key":"buhurt-rules:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0751af86dd958a5b68bb1e42cc8ec259594385d9f7a4412deed59339f2fb7e62","has_figures":false,"extraction":"text"},{"ordinal":18,"depth":0,"kind":"section","number":"3","title":"Authorized Equipment","body":"These rules aim to ensure a high standard of authenticity, safety, and historical accuracy in the equipment and conduct of the participants.","page_from":9,"page_to":9,"stable_key":"buhurt-rules:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"cac30ba0c7e459490e61561451bb8a19b48bb477d8151d30b644f38ce0ac52a3","has_figures":false,"extraction":"text"},{"ordinal":19,"depth":1,"kind":"rule","number":"3.1","title":"General Requirements","body":"","page_from":9,"page_to":9,"stable_key":"buhurt-rules:3.1","parent_key":"buhurt-rules:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"807639e9d5aa11ea0f5af6394a9f4c51ffd3e765914f57255201f7a553f7679f","has_figures":false,"extraction":"text"},{"ordinal":20,"depth":2,"kind":"rule","number":"3.1.1","title":"Technical and Authentic Compliance","body":"● All equipment must meet Buhurt International technical and authentic requirements.\n● Reference ”Weapons requirements” for all the rules.\n● Reference “Weapons/Shield Chart” for sizes and weights.","page_from":9,"page_to":9,"stable_key":"buhurt-rules:3.1.1","parent_key":"buhurt-rules:3.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d081fd87c5561df57f34f8df5c96af4ceb94b17a8f5db564cfbc10dea73fed13","has_figures":false,"extraction":"text"},{"ordinal":21,"depth":2,"kind":"rule","number":"3.1.2","title":"Competitor Eligibility","body":"● Competitors are not allowed unless they have passed technical and authenticity checks.","page_from":9,"page_to":9,"stable_key":"buhurt-rules:3.1.2","parent_key":"buhurt-rules:3.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"23789af6f3225a1b771d2f572e5bf8a6b6f307ff6e7a9e5c5f89d4d010f1c0c6","has_figures":false,"extraction":"text"},{"ordinal":22,"depth":2,"kind":"rule","number":"3.1.3","title":"Weapon Requirements","body":"● Weapons must meet the Technical Requirement for Permitted Weapons.\n● Low-quality, dirty, rusty, or historically implausible weapons are not allowed.","page_from":9,"page_to":9,"stable_key":"buhurt-rules:3.1.3","parent_key":"buhurt-rules:3.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5a713078953b1863282c09f1aaf99091b8f9d8f7f5d7e604fa2d65503ea8cae8","has_figures":false,"extraction":"text"},{"ordinal":23,"depth":2,"kind":"rule","number":"3.1.4","title":"Footwear","body":"● Medieval Shoes with low profile(non lugged/studded/spiked) soles as referenced in Authenticity Standards","page_from":9,"page_to":9,"stable_key":"buhurt-rules:3.1.4","parent_key":"buhurt-rules:3.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"943066b24061e0636604da0ffcaa8e9c3bc8c0764530d1526d2dfa55c1bb68fa","has_figures":false,"extraction":"text"},{"ordinal":24,"depth":2,"kind":"rule","number":"3.1.5","title":"Materials","body":"● Modern adhesive tape, plastic ties, and other visible modern materials are not permitted.\n● Textile adhesive tape of neutral colors for kit repair is an exception.","page_from":9,"page_to":9,"stable_key":"buhurt-rules:3.1.5","parent_key":"buhurt-rules:3.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f14a736e4554af114ae0ae83c86d50cab537ba1921f553ac953c3fe97613cc1c","has_figures":false,"extraction":"text"},{"ordinal":25,"depth":2,"kind":"rule","number":"3.1.6","title":"Decorations","body":"● Slogans and imagery on equipment should be historically plausible and not derogatory.\n● No modern equipment or decorations are allowed.","page_from":9,"page_to":9,"stable_key":"buhurt-rules:3.1.6","parent_key":"buhurt-rules:3.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7e19f796841b7dd3812d4ce6364edcf57c902f48d8e915cbc7bdfd73e1e989b5","has_figures":false,"extraction":"text"},{"ordinal":26,"depth":1,"kind":"rule","number":"3.2","title":"Specifics on Weapons and Shields","body":"● All Buhurt International weapons and shields are permitted.\n● Any combination of these weapons is allowed.","page_from":9,"page_to":9,"stable_key":"buhurt-rules:3.2","parent_key":"buhurt-rules:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7d6fab2559cb6209fd001d2d01fd9df3435a0353bddda90127105fdd82b3a8d3","has_figures":false,"extraction":"text"},{"ordinal":27,"depth":1,"kind":"rule","number":"3.3","title":"Equipment Changes","body":"● Participants are allowed to change elements of equipment (armor or weapon) during the time between rounds and/or matches.\n● Technical Marshal supervision is required for equipment changes.","page_from":10,"page_to":10,"stable_key":"buhurt-rules:3.3","parent_key":"buhurt-rules:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"676d93b0d4fcf0fefaadad73008f0cb7636b8e2712100feacf907137e9b6d4b5","has_figures":false,"extraction":"text"},{"ordinal":28,"depth":1,"kind":"rule","number":"3.4","title":"Marshal Authority","body":"● The Head Marshal and Authenticity Representative have the authority to demand changes to any element of armor or weapon for safety, aesthetic, or historical accuracy reasons.","page_from":10,"page_to":10,"stable_key":"buhurt-rules:3.4","parent_key":"buhurt-rules:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d5ad910dbb6d2da11558d8efa47a230697c527b741848eea4fa37a00dad9b735","has_figures":false,"extraction":"text"},{"ordinal":29,"depth":0,"kind":"section","number":"4","title":"Authorized Fighting Techniques","body":"A fighter must hold a weapon with at least one hand. If a fighter is not holding their weapon with a hand, they are considered disarmed and are not authorized to perform any attacking actions until the grip on the weapon is restored.","page_from":11,"page_to":11,"stable_key":"buhurt-rules:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0af3edca49bf40b48d511fa2e0ccb3e0178e21fd88c643a2cc75b1bc7d6dbb47","has_figures":false,"extraction":"text"},{"ordinal":30,"depth":1,"kind":"rule","number":"4.1","title":"Permitted Strikes","body":"● Strikes are permitted with any part of the weapon, shield, and various body parts (arms, legs and head).\n● A competitor can strike with a free hand provided they have a weapon in the other hand. That is at the ready and unsheathed.\n● A competitor can strike an opponent who has lost their weapon.\n● A competitor can strike an out of balance opponent before they are grounded.","page_from":11,"page_to":11,"stable_key":"buhurt-rules:4.1","parent_key":"buhurt-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"72201015be48914ffffba2105d9708b8ef5abad1f7ae593e4206d7b4ade57140","has_figures":false,"extraction":"text"},{"ordinal":31,"depth":1,"kind":"rule","number":"4.2","title":"Strike Zones","body":"● Strikes are allowed to any area not mentioned as a prohibited strike zone . (refer to section 5. Prohibited Fighting Techniques).","page_from":11,"page_to":11,"stable_key":"buhurt-rules:4.2","parent_key":"buhurt-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["5"],"content_sha256":"6906d9c490154f42fbbb84960ba3c1949d978de2966049be3fc93f6e120a8f64","has_figures":false,"extraction":"text"},{"ordinal":32,"depth":1,"kind":"rule","number":"4.3","title":"Weapon-Grabbing","body":"● Grabbing the opponent's weapon (except the blade) or shield with a free hand is permitted.","page_from":11,"page_to":11,"stable_key":"buhurt-rules:4.3","parent_key":"buhurt-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"16effae8b4eb74ea738211d50df4fb2f66f21c053fa3be695f1485e43e22308e","has_figures":false,"extraction":"text"},{"ordinal":33,"depth":1,"kind":"rule","number":"4.4","title":"Techniques and Moves","body":"● Back heels (tripping), wrestling throws, and clinching are allowed.\n● Any movement in the list, leaning on the barrier of the list, any holds and grips of the barrier of the list.\n● A competitor can disarm any opponent by any authorized action,\n● A competitor can take away a weapon from the belt of the opponent, provided the fighter holds their weapon. The fighter is then allowed to use the opponent’s weapon until the end of the round, and then it must be surrendered back to the opponent.\n● Opposing fighters can take or knock down reserve weapons that are placed on a wide top bar list as long as the squire is not holding them.\n● Grappling the base of the skull but not the bottom edge of the helmet is permitted.","page_from":11,"page_to":11,"stable_key":"buhurt-rules:4.4","parent_key":"buhurt-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ca7de595921864b99ccb99afd21dc4255c97312fb87249790822363872f55bed","has_figures":false,"extraction":"text"},{"ordinal":34,"depth":1,"kind":"rule","number":"4.5","title":"Weapon loss","body":"A fighter who has lost their weapon is allowed to:\n● Protect themself from the strikes without performing any offensive actions or holds.\n● Take a reserve weapon they had with them.\n● Take a reserve weapon from an ungrounded teammate in the list.\n● Take a reserve weapon from their teammate located in the allocated weapon distribution zone.\n● Grab a polearm which leans against the top rail of the barrier or its ungrounded teammate’s/owner’s body. In this case, it is not considered lying on the surface of the list.\n● Yield by kneeling.","page_from":12,"page_to":12,"stable_key":"buhurt-rules:4.5","parent_key":"buhurt-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6f4bfaf15c0f8c22b01e18effa37b7fdd23bd6648eb7fd3475f808bc9cb6c04f","has_figures":false,"extraction":"text"},{"ordinal":35,"depth":1,"kind":"rule","number":"4.6","title":"Reserve Weapons","body":"","page_from":12,"page_to":12,"stable_key":"buhurt-rules:4.6","parent_key":"buhurt-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7534ffaa51096f866a248118dd15919472cadc80b46a5d41cf499d24b2e101f5","has_figures":false,"extraction":"text"},{"ordinal":36,"depth":2,"kind":"rule","number":"4.6.1","title":"Wide top bar list","body":"● Reserve weapons must be placed on the top of the bar in the designated area for a fighter to pick up themselves. It is prohibited to pass a weapon to the fighter or hold the weapon when a fighter is taking it. This will impose a penalty (See article 5 in “Buhurt Regulations”).","page_from":12,"page_to":12,"stable_key":"buhurt-rules:4.6.1","parent_key":"buhurt-rules:4.6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["5"],"content_sha256":"bcc9d0539f632b0b8c64b23c6204911aaf8329276bf05d54def7e73f9a8193a6","has_figures":false,"extraction":"text"},{"ordinal":37,"depth":2,"kind":"rule","number":"4.6.2","title":"No top bar list","body":"● Reserve weapons may be passed to the fighter from above the top rail of the list within the designated area. It is prohibited to pass a weapon below the top rail of the list. This will impose a penalty (See article 5 in “Buhurt Regulations”)","page_from":12,"page_to":12,"stable_key":"buhurt-rules:4.6.2","parent_key":"buhurt-rules:4.6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["5"],"content_sha256":"fe0755633ef755a58e69d85aa53b5b1461a454462e687770e71749ae71a64477","has_figures":false,"extraction":"text"},{"ordinal":38,"depth":0,"kind":"section","number":"5","title":"Prohibited Fighting Techniques","body":"Performance of any prohibited technique is a serious rules violation and is penalized with a verbal warning, yellow or red card. The penalty is imposed regardless of the fighter’s intent.","page_from":13,"page_to":13,"stable_key":"buhurt-rules:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"23b59b06122d1c0c9574094827268ee9943399f3c2d70f6d304e53dd986cebc6","has_figures":false,"extraction":"text"},{"ordinal":39,"depth":1,"kind":"rule","number":"5.1","title":"Unlisted Techniques","body":"● Any actions not listed in section 4 of the rules are prohibited. Only authorized techniques are permitted.","page_from":13,"page_to":13,"stable_key":"buhurt-rules:5.1","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["4"],"content_sha256":"92314017d5df7ed43e8ed4ad9b905561a5aeeb756734985978915f4d3ce316f6","has_figures":false,"extraction":"text"},{"ordinal":40,"depth":1,"kind":"rule","number":"5.2","title":"Thrusting Actions","body":"● Any thrusting actions with a weapon are prohibited. Threats of a thrusting action are also prohibited.","page_from":13,"page_to":13,"stable_key":"buhurt-rules:5.2","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1bdbb399b320d439ac543a619a1bb82058c6c96f6e41118ee4bfa8474dc76c44","has_figures":false,"extraction":"text"},{"ordinal":41,"depth":1,"kind":"rule","number":"5.3","title":"Offensive Actions at Prohibited Strike Zones","body":"● Any offensive actions that land on prohibited strike zones (See section: 7. Prohibited Strike Zones) are prohibited.","page_from":13,"page_to":13,"stable_key":"buhurt-rules:5.3","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9a541c07cc227f05be5c93db181863c097fc1d5050591f25910588a3e93c83f2","has_figures":false,"extraction":"text"},{"ordinal":42,"depth":1,"kind":"rule","number":"5.4","title":"Actions with Foot, Shin and Knee","body":"● Actions with foot, shin, and knee aimed at the knee are prohibited. This includes actions that may cause the knee to hyperextend, such as push kicks to the thigh.","page_from":13,"page_to":13,"stable_key":"buhurt-rules:5.4","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"fb493556e55bdfd2df2e5b97612ee7a52345725fab14a56354a3cea90767574d","has_figures":false,"extraction":"text"},{"ordinal":43,"depth":1,"kind":"rule","number":"5.5","title":"Grappling and Holds","body":"● Grappling and holding with the hand on specific armor elements (aventail, edge of pauldrons, edge of the helmet), pushes on the bottom edge of the helmet and subsequent neck twists are prohibited.","page_from":13,"page_to":13,"stable_key":"buhurt-rules:5.5","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ad4acc49f8055b23d85ca9a20f31d4b50ae86b183370c893698d8bd2e584fc19","has_figures":false,"extraction":"text"},{"ordinal":44,"depth":1,"kind":"rule","number":"5.6","title":"Armor Tampering","body":"● Deliberate attempts to remove any elements of the armor are prohibited.\n● The fighter committing the offense will be sat down and given a yellow card.\n● A fighter who deliberately has their armor so it can be easily removed will receive a yellow card for unsportsmanlike conduct.","page_from":13,"page_to":13,"stable_key":"buhurt-rules:5.6","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4adbb69d57bf89ea71dcb1fdf2c75d7fd3b47b3d2f0122eaa7cf3bf92699d051","has_figures":false,"extraction":"text"},{"ordinal":45,"depth":1,"kind":"rule","number":"5.7","title":"Suffocation Techniques","body":"● Grips, clamps, suffocation techniques with direct pressure on the front, side and back of neck (under or on top of the aventail) using any part of the body, equipment, or weapon are prohibited. A poorly fitted helmet does not count as a suffocating technique.","page_from":13,"page_to":13,"stable_key":"buhurt-rules:5.7","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4df53668798f956a6b0c24e567a44a8382927dc19c945cb3169c9bcb5ef928eb","has_figures":false,"extraction":"text"},{"ordinal":46,"depth":1,"kind":"rule","number":"5.8","title":"Specific Strikes","body":"● Strikes or punching with the head of a one-handed axe are prohibited if the grip of the hand is less than 30 cm away from the blade.\n\n● strikes with hammerheads are prohibited.","page_from":13,"page_to":14,"stable_key":"buhurt-rules:5.8","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"cc9df9a84a503b50f104a01d6f26f3c0acdf5891f04d5a310b600f4f92b77060","has_figures":false,"extraction":"text"},{"ordinal":47,"depth":1,"kind":"rule","number":"5.9","title":"Dangerous Takedowns","body":"● Any takedown that spikes an opponent on their head/neck and suplex (arch throws) variations are prohibited.","page_from":14,"page_to":14,"stable_key":"buhurt-rules:5.9","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c9e28882dde3fe4a09e668638a2b1418f5ddcf4269e8bb30895d47392b4c482c","has_figures":false,"extraction":"text"},{"ordinal":48,"depth":1,"kind":"rule","number":"5.10","title":"Intentional Passivity","body":"● Intentional passivity and stalling of the action (such as an inactive clinch) are prohibited. An inactive clinch is a clinch situation with the fighters performing weak weapon strikes or no grappling techniques aimed at grounding their opponent for 10 seconds or longer. The strikes with a fist, knees, or shield, are not considered.","page_from":14,"page_to":14,"stable_key":"buhurt-rules:5.10","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a5006ec75252ac67540708e312b9d6eed4ea74659f8f0f52e5a1b19fb41d7413","has_figures":false,"extraction":"text"},{"ordinal":49,"depth":1,"kind":"rule","number":"5.11","title":"Joint Locks and Hyperextension","body":"● Arm lock and leg lock techniques, and any actions that may cause a limb to hyperextend, are prohibited.","page_from":14,"page_to":14,"stable_key":"buhurt-rules:5.11","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"be3033b868b0532973ca112ebe7e20a78ab9e9f9cc88fd84494d59ccf72ce013","has_figures":false,"extraction":"text"},{"ordinal":50,"depth":1,"kind":"rule","number":"5.12","title":"Striking Grounded competitors","body":"● Striking a grounded competitor is prohibited.","page_from":14,"page_to":14,"stable_key":"buhurt-rules:5.12","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"395cd74d22fb750d3da0e8cf9af9d7c5a247cd0c03caf952befbeb4321b60962","has_figures":false,"extraction":"text"},{"ordinal":51,"depth":1,"kind":"rule","number":"5.13","title":"Injuring competitor","body":"● Deliberately injuring the fighter who has lost a defensive element of equipment.","page_from":14,"page_to":14,"stable_key":"buhurt-rules:5.13","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e00dbc702b54a0ba09ebc1b7847d8331f7ede7e43f60a22e1519b25d9e70fd96","has_figures":false,"extraction":"text"},{"ordinal":52,"depth":1,"kind":"rule","number":"5.14","title":"Uncontrolled Strikes","body":"● Any uncontrolled strikes and actions with a weapon.","page_from":14,"page_to":14,"stable_key":"buhurt-rules:5.14","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b1f7b0eae0b3333586f27968f41f01ae4d4d9de06289b3e2361fa34e690a90c1","has_figures":false,"extraction":"text"},{"ordinal":53,"depth":1,"kind":"rule","number":"5.15","title":"Weapon Loss","body":"● It is prohibited to pick up a weapon that is lying flat on the ground, to receive a weapon from an already grounded fighter, to receive a weapon from any outside the list except for the squire in the designated area.","page_from":14,"page_to":14,"stable_key":"buhurt-rules:5.15","parent_key":"buhurt-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8897a6d0496167984b698fa211f40c610479727f9de985e53894194664e2a538","has_figures":false,"extraction":"text"},{"ordinal":54,"depth":0,"kind":"section","number":"6","title":"Other Prohibited Actions","body":"These rules contribute to maintaining the integrity, safety, and orderliness of the event. They cover aspects such as participant behavior, substance use, adherence to commands, and respect for officials and other attendees. The role of the Knight Marshal is highlighted in several instances, emphasizing their authority and responsibility in ensuring the proper conduct of the event.","page_from":15,"page_to":15,"stable_key":"buhurt-rules:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d126392e2309f10ce0cd7359190088ace782de9936ce663b2ab442265a8ffae9","has_figures":false,"extraction":"text"},{"ordinal":55,"depth":1,"kind":"rule","number":"6.1","title":"Leaving Lists","body":"● Intentional leaving of the lists after the command “Start Fight” and before the announcement of the results of the fight is prohibited. Permission to leave must be granted by the Knight Marshal.","page_from":15,"page_to":15,"stable_key":"buhurt-rules:6.1","parent_key":"buhurt-rules:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ad85887b7c33bb681ee4eeebfe82c6d3fddd76a42d0884c4f431747afece15e9","has_figures":false,"extraction":"text"},{"ordinal":56,"depth":1,"kind":"rule","number":"6.2","title":"Interference from grounded competitors","body":"● Grounded fighters must remain on the ground until the “All Rise” command of the Knight Marshal. They are not allowed to return to a standing position.\n● The grounded fighters are not allowed to physically interfere in the course of the fight.\n● A grounded fighter must maintain a comfortable seated or lying position until the end of the round. A comfortable position is a signal that the fighter is not injured.\n● The grounded competitors are not allowed to change their position in the list unless there is a threat to their safety.","page_from":15,"page_to":15,"stable_key":"buhurt-rules:6.2","parent_key":"buhurt-rules:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8351bd234636c78103d7d5534e88a4b1a53a9b22e2a01f95cee981418b16e010","has_figures":false,"extraction":"text"},{"ordinal":57,"depth":1,"kind":"rule","number":"6.3","title":"Equipment and Weapon Approval","body":"● Competitors are not allowed to use any part of the equipment or any weapon that hasn't been allowed by the Authenticity.","page_from":15,"page_to":15,"stable_key":"buhurt-rules:6.3","parent_key":"buhurt-rules:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"71977f91c1052a0118f2d766f981b10ab277919b4282c1c0b1ca186ee70a6d48","has_figures":false,"extraction":"text"},{"ordinal":58,"depth":1,"kind":"rule","number":"6.4","title":"Substance Use","body":"● It's not allowed for the competitor to be under the influence of alcohol or any psychoactive substances.","page_from":15,"page_to":15,"stable_key":"buhurt-rules:6.4","parent_key":"buhurt-rules:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d8ec345a50f467d8e25a76203206324ba2725200b12b50c6fc1ed026cdbf5849","has_figures":false,"extraction":"text"},{"ordinal":59,"depth":1,"kind":"rule","number":"6.5","title":"Offensive Actions Against Others","body":"● Any offensive actions against marshals, corner support, spectators, or anyone else other than the current opponent are prohibited.","page_from":15,"page_to":15,"stable_key":"buhurt-rules:6.5","parent_key":"buhurt-rules:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d84f9fc29d71fc6382ba96c7ffdf68913982c38005db80398dd93a278742e9e0","has_figures":false,"extraction":"text"},{"ordinal":60,"depth":1,"kind":"rule","number":"6.6","title":"Event Interference","body":"● Any actions made by a competitor or their support that may impede the course of the event are prohibited.\n● For a demonstration of poor sportsmanship, derogatory behavior, obscene language, commentaries directed at marshals, opponents, or spectators.","page_from":15,"page_to":15,"stable_key":"buhurt-rules:6.6","parent_key":"buhurt-rules:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"253cb82ead4bc1d2b8ad588833009a9edc85bcfa76061d75cda561e423fb9775","has_figures":false,"extraction":"text"},{"ordinal":61,"depth":0,"kind":"section","number":"7","title":"Prohibited Strike Zones","body":"These rules are designed to prioritize the safety of the participants by prohibiting strikes to vulnerable and potentially dangerous areas. The specific definitions and considerations for the base of the skull and back of the knee provide clarity on the prohibited strike zones. Striking the foot is allowed under certain circumstances, emphasizing the importance of situational awareness and control during combat. The overall intention is to prevent serious injuries and ensure a fair and safe competition.","page_from":16,"page_to":16,"stable_key":"buhurt-rules:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a95e5886009638c7552bb1ef01db269fcc736b669a6bfde4e97a25f271d2454f","has_figures":true,"extraction":"text"},{"ordinal":62,"depth":1,"kind":"rule","number":"7.1","title":"Back and Front of the Neck","body":"● Strikes to the back and front of the neck are prohibited.","page_from":16,"page_to":16,"stable_key":"buhurt-rules:7.1","parent_key":"buhurt-rules:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"27e9724848359bdf714326056f5e23a19b36993710f120decb14058cbbf13894","has_figures":true,"extraction":"text"},{"ordinal":63,"depth":1,"kind":"rule","number":"7.2","title":"Base of Skull","body":"● The base of the skull is considered a prohibited strike zone, specifically defined as the bottom third of the back of the helmet.","page_from":16,"page_to":16,"stable_key":"buhurt-rules:7.2","parent_key":"buhurt-rules:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b35d3b04e9ac50b48f120ce17bb47ceeee0ec7d2b83892bf1ba1d8406f987959","has_figures":true,"extraction":"text"},{"ordinal":64,"depth":1,"kind":"rule","number":"7.3","title":"Back of Knee","body":"● Strikes to the back of the knee are prohibited. No pressure is to be placed on the back of the knee.","page_from":16,"page_to":16,"stable_key":"buhurt-rules:7.3","parent_key":"buhurt-rules:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"91076ae5c7e69b60527ba95fffbfa8ebbb63a79a2791b58eb6bcf380ed9e6c29","has_figures":true,"extraction":"text"},{"ordinal":65,"depth":1,"kind":"rule","number":"7.4","title":"Groin and Crotch","body":"● Strikes to the groin and crotch are prohibited.","page_from":16,"page_to":16,"stable_key":"buhurt-rules:7.4","parent_key":"buhurt-rules:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f40c2efb874e78667245ec4eaa628142a354920b0900bce61b2f192d7ac5343d","has_figures":true,"extraction":"text"},{"ordinal":66,"depth":1,"kind":"rule","number":"7.5","title":"Feet and Ankle","body":"● Strikes to the feet and ankles are prohibited. However, striking the foot is not considered a prohibited strike if the competitor raises their foot while the strike is already occurring.","page_from":16,"page_to":16,"stable_key":"buhurt-rules:7.5","parent_key":"buhurt-rules:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3491783a24c112fef163dfcfa27b746cc0602ce2d0b4af7e71d4f427442e718a","has_figures":true,"extraction":"text"},{"ordinal":67,"depth":1,"kind":"rule","number":"7.6","title":"Unprotected Body Parts","body":"● Any part of the opponent’s body that has lost its protection is considered a prohibited strike zone.","page_from":16,"page_to":16,"stable_key":"buhurt-rules:7.6","parent_key":"buhurt-rules:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1e2bb95808de3e1f3e59e6179e5366be2a8323ba12c1737e7809388414413e03","has_figures":true,"extraction":"text"},{"ordinal":68,"depth":0,"kind":"section","number":"8","title":"Management of the Fights","body":"Fights of the category are managed under the Buhurt International ‘Buhurt Regulations’ by penalties that are imposed depending on the situation in the list and fighters’ and marshals’ actions.","page_from":17,"page_to":17,"stable_key":"buhurt-rules:8","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e1e5e178fdc56478b7e89aeb0ba9ff68613a4fb9c91db91ed2bd82f1bff239cc","has_figures":false,"extraction":"text"},{"ordinal":69,"depth":0,"kind":"note","number":"9","title":"Change log","body":"This will be the change log of this document. It will be updated regularly and we will display what has been removed/added/reworded/formatted. This way we keep transparent communication and clarity about the rules January 2026 (Version update from 2024.12 to 2026.1)\n\nUpdate date: January-2026 -add: 2.1 Shall stop rounds with the “Hold” command and yellow flag between helmets of the fighters. The fighters must stop across the entire list and should not move.\n-clarification: 3.1.4 Medieval Shoes with low profile(non lugged/studded/spiked) soles as referenced in Authenticity Standards -add: 4.1 That is at the ready and unsheathed.\n-clarification: 5.3 Any offensive actions that land on prohibited strike zones (See section: 7. Prohibited Strike Zones) are prohibited.\n.\n\nUpdate date: December-2024 -replaced: “Oral” with “Verbal” -add: 4.6.2 : This will impose a penalty (See article 5 in “Buhurt Regulations”) -add: 4.6.1 : This will impose a penalty (See article 5 in “Buhurt Regulations”) -add: 3.1 Reference ”Weapons requirements” for all the rules -add: 3.1 Reference “Weapons/Shield Chart” for sizes and weights\n\nUpdate date: March-2024\n- format: new design format, document will be used from now on.","page_from":18,"page_to":18,"stable_key":"buhurt-rules:9","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":["5"],"content_sha256":"f577e6dfbb9541a147234f252bed33c606b4152e40b4afb55f9f480507516efe","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_historical_version($rules${"governing_body":"Buhurt International","history":"archive-2026-10-06","inventory_key":"marshal/duels-rules","version":{"version":"2025.03","title":"Duels Rules 2025.03","published_on":null,"effective_from":null,"note":"Title \"Duels Rules\"; cover \"VER. 2025.03\". Older than 26.1 and the current 26.4.","source_url":"https://drive.google.com/file/d/1IFfgJPFh03qaNzZVfZ4lofmFDIB9AAPh/view","source_sha256":"bdd993c3bc48a612e55570b627f16db8db4ce84a05fb2c1be99b6ad0e8c2049e","retrieved_at":null,"page_count":11,"extractor":"pdftotext unknown -layout -enc UTF-8","content_sha256":"bf28888e5214ae7774189c67e1c141f5775e1d54e8f655c7f4b77a4f564ec1b1","detected":{"version":null,"date":null},"confirmed_by":"Claude Code (Pack 22 historical import), read from the archived PDF: cover (OCR of the page image), footers and change log","historical":true,"edition_seq":1,"edition_evidence":"Title \"Duels Rules\"; cover \"VER. 2025.03\". Older than 26.1 and the current 26.4.","source_files":[{"file":"Marshal/Archive/Duels rules 2025.03.pdf","archive":"Marshal","sha256":"bdd993c3bc48a612e55570b627f16db8db4ce84a05fb2c1be99b6ad0e8c2049e","drive_file_id":"1IFfgJPFh03qaNzZVfZ4lofmFDIB9AAPh"}],"reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1","10 line(s) looked like a numbered heading but did not fit the sequence","1 provision(s) need review against the official document"],"pages":11,"source_lines":275,"assigned_lines":322,"furniture_lines":47,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99922,"provisions":53,"numbered":52,"needs_review":1,"verified":0,"empty_pages":[1],"rejected_numbers":10,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":0,"picture_text_lines":0,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"duels-rules:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Striking zones (legal vs illegal)","body":"","page_from":3,"page_to":3,"stable_key":"duels-rules:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5c8057b27a4ecf17f3e0d02b2ffe4f2492eae6b74501e362da44f0a33c1aaf59","has_figures":true,"extraction":"text"},{"ordinal":3,"depth":1,"kind":"rule","number":"1.1","title":"Counted strike (legal strikes)","body":"During the fights of each category, the number of strikes by the blade of the weapon delivered into the legal strike zone of the opponent’s body is counted.\n● A counted strike is considered a strike if it was clear and deliberate, and the opponent failed to counter it effectively with a defensive action.","page_from":3,"page_to":3,"stable_key":"duels-rules:1.1","parent_key":"duels-rules:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e2bff8043fbfd4c5097009f474a08e374850ccdd5cff81d14015f24affb4c766","has_figures":true,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"1.2","title":"Prohibited Strike Zones (illegal strikes)","body":"The following zones are “illegal strikes” and will not count for your score. Striking into these zones can result in penalties or disqualification.","page_from":3,"page_to":3,"stable_key":"duels-rules:1.2","parent_key":"duels-rules:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"69c7b200ae00921380b512a7d6907d699d27e2ccdd6e8e8a83e2af778a178e7a","has_figures":true,"extraction":"text"},{"ordinal":5,"depth":2,"kind":"rule","number":"1.2.1","title":"Back and Front of the Neck","body":"● Strikes to the back and front of the neck are prohibited.","page_from":3,"page_to":3,"stable_key":"duels-rules:1.2.1","parent_key":"duels-rules:1.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c1fb504efec4d716a87fcb17ac374f4371fb43a1cb3caf12477154725b3f08c6","has_figures":true,"extraction":"text"},{"ordinal":6,"depth":2,"kind":"rule","number":"1.2.2","title":"Base of Skull","body":"● The base of the skull is considered a prohibited strike zone, specifically defined as the bottom third of the back of the helmet.","page_from":3,"page_to":3,"stable_key":"duels-rules:1.2.2","parent_key":"duels-rules:1.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"cbe81b2b7950d3e5c32bc543a539b1fc4e82c0d7a823157082edc294f3004a9a","has_figures":true,"extraction":"text"},{"ordinal":7,"depth":2,"kind":"rule","number":"1.2.3","title":"Back of Knee","body":"● Strikes to the back of the knee are prohibited. No pressure is to be placed on the back of the knee.","page_from":3,"page_to":3,"stable_key":"duels-rules:1.2.3","parent_key":"duels-rules:1.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2062fe8a437488d323e5e6f0160c6d92409f10079980c110151cb345db84a49b","has_figures":true,"extraction":"text"},{"ordinal":8,"depth":2,"kind":"rule","number":"1.2.4","title":"Groin and Crotch","body":"● Strikes to the groin and crotch are prohibited.","page_from":3,"page_to":3,"stable_key":"duels-rules:1.2.4","parent_key":"duels-rules:1.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"624c29cdbbb52dab416cf67fc351746d7aa8a7cd91c5c2e7c9ed7d294fb07cfb","has_figures":true,"extraction":"text"},{"ordinal":9,"depth":2,"kind":"rule","number":"1.2.5","title":"Feet and Ankles","body":"● Strikes to the feet and ankles are prohibited. However, striking the foot is not considered a prohibited strike if the competitor raises their foot while the strike is already occurring.","page_from":3,"page_to":3,"stable_key":"duels-rules:1.2.5","parent_key":"duels-rules:1.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"71295b51d5d84542a4431a6d48b80666ad724f97fc14f73d2e15c65c67b86a70","has_figures":true,"extraction":"text"},{"ordinal":10,"depth":2,"kind":"rule","number":"1.2.6","title":"Unprotected Body Parts","body":"● Any part of the opponent’s body that has lost itself protection is considered a prohibited strike zone.","page_from":3,"page_to":3,"stable_key":"duels-rules:1.2.6","parent_key":"duels-rules:1.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3880ed55ae11d29668c7163a2b054be65c530df76aeb62b757731df9fb3a45a7","has_figures":true,"extraction":"text"},{"ordinal":11,"depth":0,"kind":"section","number":"2","title":"Scoring and rounds","body":"","page_from":4,"page_to":4,"stable_key":"duels-rules:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f3d6b2765164cc2005156b0d5acc188c1930cb8980b183dd15bc3b66a6e94e72","has_figures":false,"extraction":"text"},{"ordinal":12,"depth":1,"kind":"rule","number":"2.1","title":"Scoring","body":"","page_from":4,"page_to":4,"stable_key":"duels-rules:2.1","parent_key":"duels-rules:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c7eee7c8ef5763cfc8c6e822fe05d14ecae843ee52101caa5dacf18796ca7b02","has_figures":false,"extraction":"text"},{"ordinal":13,"depth":2,"kind":"rule","number":"2.1.1","title":"Sword and Shield","body":"Each strike to the legal strike zone of the opponent will score:\n● Two (2) points:\n● Head\n● Torso\n● One (1) point:\n● Legs\n● Arms\n● Hands","page_from":4,"page_to":4,"stable_key":"duels-rules:2.1.1","parent_key":"duels-rules:2.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3fe0a1578721bc5219a028c67dd99ecf1c3ba96768f1913b8ae1a64058206b9e","has_figures":false,"extraction":"text"},{"ordinal":14,"depth":2,"kind":"rule","number":"2.1.2","title":"Sword and Buckler","body":"Each strike to the legal strike zone of the opponent will score\n● one (1) point.","page_from":4,"page_to":4,"stable_key":"duels-rules:2.1.2","parent_key":"duels-rules:2.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e49e656a71511a08e5b55ca17e36c545183f1fba24e5627fae2f23d426ea572c","has_figures":false,"extraction":"text"},{"ordinal":15,"depth":2,"kind":"rule","number":"2.1.3","title":"Polearm","body":"Each strike to the legal strike zone of the opponent will score.\n● One (1) point:\n● Excluding hands: Zero (0) points if the blow landed on the hands.\n● Offensive actions with the haft of the polearm do not score.\n● The full length of the cutting edge of the weapon is considered a blade.\n● The grip must be held by two (2) hands for the strike to be counted as a point.","page_from":4,"page_to":4,"stable_key":"duels-rules:2.1.3","parent_key":"duels-rules:2.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"716956a6b8fe66338e2014bb18c4ef18183b3fa76be78c309244165b383151a7","has_figures":false,"extraction":"text"},{"ordinal":16,"depth":2,"kind":"rule","number":"2.1.4","title":"Longsword","body":"Each strike to the legal strike zone of the opponent will score.\n● Two (2) points (Holding the grip with (2) hands).\n● Head\n● Torso\n● One (1) point\n● Arms\n● Legs\n● Hands\n● One (1) point (Holding the grip with one (1) hand).\n● All legal striking zones","page_from":4,"page_to":4,"stable_key":"duels-rules:2.1.4","parent_key":"duels-rules:2.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"71d6e29412b1f67cfc9ccb0e154d4f5ffca6f2a28a746bba097ddb834028f789","has_figures":false,"extraction":"text"},{"ordinal":17,"depth":1,"kind":"rule","number":"2.2","title":"Round (breakdown)","body":"","page_from":4,"page_to":4,"stable_key":"duels-rules:2.2","parent_key":"duels-rules:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"029e73bc1caaef2e82d8811d92c3e9850cfb7626e6251ff0035498a2c6a71b6f","has_figures":false,"extraction":"text"},{"ordinal":18,"depth":2,"kind":"rule","number":"2.2.1","title":null,"body":"Sword and buckler:\n● A match consists of three (3) rounds of no longer than one (1) minute.\n● Each round is continued until one of the competitors has scored five (5) points or the time limit has been reached.\n● Max points per round is five (5) or the total of counted strikes.\n● There is no break in between rounds.\n\n2.5.2 Polearm | Longsword | Sword and shield\n● A fight consists of two (2) rounds of no longer than one (1) minute.\n● Break of thirty (30) seconds between rounds.\n● If the match ends in a draw, an extra thirty (30) second round is fought to determine the winner.\n● Competitor with the highest score will win the round.\n\nImportant!\nThe organizers can change the length of the round, provided this decision is coordinated with the Head Organization and is registered in the Tournament Regulations.\n\n2.6 Win conditions The competitor who meets the criteria (2.6.1). Will win the match.\n2.6.1 Match win (criteria)\n\nSword and buckler\n● The competitor who wins two (2) rounds first will win the match.\n● A competitor is given a technical win (art.2.7)\n\nLongsword | Sword&Shield | Polearm\n● Total score from both rounds (the score must have at least 2 point spread)\n\n2.7 Technical Win “Technical win” is awarded to one (1) of the competitors in the following cases 2.7.1 Withdraw\n● Failed to report to the list upon the Head Referee’s call.\n● Failed to prepare the equipment within the designated time.\n● Withdraws before the match has started.\nThe competitor who failed to report to the list for the match is penalized by a yellow card. In the case a competitor cannot participate in the competition because of injury or disqualification, their opponent is awarded a technical win.\n\n2.7.2 Injury\n● If the opponent cannot continue the match because of an “accidental injury”.\n● If the competitor cannot continue the match due to the injury caused by an illegal strike, their opponent receives a penalty of double yellow cards and is banned from further participation in the tournament. The injured competitor is awarded a technical victory. The injured competitor is withdrawn from further matches in this category.\n\n2.7.3 Penalties\n● If an opponent gets two (2) Yellow cards (warnings) or Red card (disqualification).\n2.7.4 Armor failure\n● If the match is impeded due to equipment failure that is impossible to fix within the designated time frame of no more than one (1) minute. Assessment is made by the Knight Marshal (Head Referee).\n\nPoints awarded for “technical win” All categories get 10-0, beside buckler 2-0","page_from":4,"page_to":6,"stable_key":"duels-rules:2.2.1","parent_key":"duels-rules:2.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d560ad504ad45395afed797678336898fbf123e138824daaf47b8e3b62545525","has_figures":false,"extraction":"text"},{"ordinal":19,"depth":0,"kind":"section","number":"3","title":"Authorized Fighting Techniques","body":"These rules aim to define a set of permitted and prohibited actions to ensure the safety of participants while engaging in combat. The guidelines cover striking, grabbing, and various techniques to maintain a fair and controlled environment during the event.","page_from":7,"page_to":7,"stable_key":"duels-rules:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"58d9cdf7113b9072092286d125ddfd1ae3024bdde37ddf15bbc48b2bf68de857","has_figures":false,"extraction":"text"},{"ordinal":20,"depth":1,"kind":"rule","number":"3.1","title":"Permitted Strikes","body":"","page_from":7,"page_to":7,"stable_key":"duels-rules:3.1","parent_key":"duels-rules:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"742ac2d9f821376af3c76bc201e8c1c02096c98b1512437ea9541dae2e5568f9","has_figures":false,"extraction":"text"},{"ordinal":21,"depth":2,"kind":"rule","number":"3.1.2","title":"Buckler strikes are permitted with the flat of the buckler","body":"","page_from":7,"page_to":7,"stable_key":"duels-rules:3.1.2","parent_key":"duels-rules:3.1","review_status":"needs_review","review_note":"numbering skips to 3.1.2 (expected 3.1.1): check the official document for a missing provision","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"bdb4de2d33423074834a67c41a0b8ddbb382befa6e0cef83c5dc35418d2fd04d","has_figures":false,"extraction":"text"},{"ordinal":22,"depth":2,"kind":"rule","number":"3.1.3","title":"Polearm: Competitor is allowed to strike with a free hand if provided they have a","body":"weapon in the other hand","page_from":7,"page_to":7,"stable_key":"duels-rules:3.1.3","parent_key":"duels-rules:3.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"54204a020776fe019edd117a62ac5097dffd7235ea3ca97bb8c2180b33b5333b","has_figures":false,"extraction":"text"},{"ordinal":23,"depth":2,"kind":"rule","number":"3.1.4","title":"Strikes are permitted with the blade and the haft of the weapon","body":"","page_from":7,"page_to":7,"stable_key":"duels-rules:3.1.4","parent_key":"duels-rules:3.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3769fd17711e68678b2fd18920edf4566d23f71e4e9e3ec5ed3fc2613f6384bd","has_figures":false,"extraction":"text"},{"ordinal":24,"depth":1,"kind":"rule","number":"3.2","title":"Strike Zones","body":"● Strikes are allowed to any area not mentioned as a prohibited strike zone.","page_from":7,"page_to":7,"stable_key":"duels-rules:3.2","parent_key":"duels-rules:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0aa8e0a64cb464f24ff4d3cda1e065311760a7335aaaaaf46ce0a3bb193655e9","has_figures":false,"extraction":"text"},{"ordinal":25,"depth":1,"kind":"rule","number":"3.3","title":"Parry","body":"● Participants are allowed to parry the opponent’s strikes","page_from":7,"page_to":7,"stable_key":"duels-rules:3.3","parent_key":"duels-rules:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3142f9e5da5b5f10d389bb4dcfdcb91ea4058e8de5f3ca7677d6067cdb4bb913","has_figures":false,"extraction":"text"},{"ordinal":26,"depth":1,"kind":"rule","number":"3.4","title":"Techniques and moves with shields (Buckler,Sword&Shield)","body":"● Pushing the opponent with the shoulder or the flat of the shield.\n● Pushing the blade, shield, armed hand or upper body (above the waistline) of the opponent with the flat or the edge of the shield.\n● Using the shield to hook or cover the opponent’s shield.","page_from":7,"page_to":7,"stable_key":"duels-rules:3.4","parent_key":"duels-rules:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3001e6d01178f8c0e1835823dc157364a2cb60736d5b68aef2c42f9267d51324","has_figures":false,"extraction":"text"},{"ordinal":27,"depth":1,"kind":"rule","number":"3.5","title":"Techniques and moves (Longsword,Polearm)","body":"● Pushing the opponent with the blade or arms.\n● Pushing off the opponent's arms with your arms.","page_from":7,"page_to":7,"stable_key":"duels-rules:3.5","parent_key":"duels-rules:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1a31c3e88dc3a5c756afca070f239928c22e5d506ccca34d97489870482fd971","has_figures":false,"extraction":"text"},{"ordinal":28,"depth":1,"kind":"rule","number":"3.6","title":"Weapon-Grabbing","body":"● Participants are allowed to grab their own weapon (except the blade) with their hands.\n● Participants are allowed to trap opponents weapon by shield, buckler and/or arm(not by hands)","page_from":7,"page_to":7,"stable_key":"duels-rules:3.6","parent_key":"duels-rules:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"79f039ce219623944820ab0d1a735cfd383709459f9787a6d554dcfa2f57955f","has_figures":false,"extraction":"text"},{"ordinal":29,"depth":1,"kind":"rule","number":"3.7","title":"Pinned to the List Rail","body":"● Pinning an opponent to the list is not against the rules; however, if a competitor is pinned against the list rail, the Knight Marshal will call 'Break Fight' and reset the competitors to the center of the list.","page_from":7,"page_to":7,"stable_key":"duels-rules:3.7","parent_key":"duels-rules:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"29aa4051b2de3efa0e0a51c812d1d915abe65f7a7b521d020336b987c5b22802","has_figures":false,"extraction":"text"},{"ordinal":30,"depth":0,"kind":"section","number":"4","title":"Prohibited Fighting Techniques","body":"These rules aim to ensure the safety, fairness, and adherence to a set of standards.","page_from":8,"page_to":8,"stable_key":"duels-rules:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c48d119d1caa0537f2bc0b79c01e7f2e8752c7369cc19b4d71855ca3ac693521","has_figures":false,"extraction":"text"},{"ordinal":31,"depth":1,"kind":"rule","number":"4.1","title":"Unlisted Techniques","body":"● Any actions not listed in section 3 of the rules are prohibited.","page_from":8,"page_to":8,"stable_key":"duels-rules:4.1","parent_key":"duels-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"1b083a964e84bc649ebd4d8679beae51e1c2ebd37f82b531e0cddd88aca2a952","has_figures":false,"extraction":"text"},{"ordinal":32,"depth":1,"kind":"rule","number":"4.2","title":"Thrusting Actions","body":"● Any thrusting actions with a weapon.\n● Threats of a thrusting action.","page_from":8,"page_to":8,"stable_key":"duels-rules:4.2","parent_key":"duels-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6ad8420344e966514116d08ed876fc1492ad864abfc3bbb428c79a01f727f856","has_figures":false,"extraction":"text"},{"ordinal":33,"depth":1,"kind":"rule","number":"4.3","title":"Offensive Actions at Prohibited Strike Zones","body":"● Any offensive actions aimed at the prohibited strike zones.","page_from":8,"page_to":8,"stable_key":"duels-rules:4.3","parent_key":"duels-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4d74f393926aa37115cadb7d8100c987ed64e3cc907cfdc325bc7a85230a1442","has_figures":false,"extraction":"text"},{"ordinal":34,"depth":1,"kind":"rule","number":"4.4","title":"Striking to Grounded or rising competitors","body":"● Striking a grounded or rising competitor.","page_from":8,"page_to":8,"stable_key":"duels-rules:4.4","parent_key":"duels-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a78ba9abe9d11df715934e505b5077fb7adbf3bc757e56533b52153e48858ee4","has_figures":false,"extraction":"text"},{"ordinal":35,"depth":1,"kind":"rule","number":"4.5","title":"Strikes to Disarmed Opponent","body":"● Strikes to an opponent who has lost their weapon.","page_from":8,"page_to":8,"stable_key":"duels-rules:4.5","parent_key":"duels-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f17ad5fc80d900bef623e46c5cd9dfe8c72b67059b2e4514879c6056380ee25b","has_figures":false,"extraction":"text"},{"ordinal":36,"depth":1,"kind":"rule","number":"4.6","title":"Strikes with head","body":"● Strikes to an opponent with your head.","page_from":8,"page_to":8,"stable_key":"duels-rules:4.6","parent_key":"duels-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b892d54c3b2ac83db2e316bc154f467a29b0d162308bd17427aba8f3380d76ad","has_figures":false,"extraction":"text"},{"ordinal":37,"depth":1,"kind":"rule","number":"4.7","title":"Strikes with legs","body":"● Strikes with feet, shin, and knees are prohibited.","page_from":8,"page_to":8,"stable_key":"duels-rules:4.7","parent_key":"duels-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"48a2f7877eb16dcda1fa714557af81b532609a98ca90ebc780db9ac064790cea","has_figures":false,"extraction":"text"},{"ordinal":38,"depth":1,"kind":"rule","number":"4.8","title":"Techniques and Moves","body":"● Back heels, wrestling throws, and clinching.","page_from":8,"page_to":8,"stable_key":"duels-rules:4.8","parent_key":"duels-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"854a5ca5c107cda69beb40ff6616ef12466a9deb3720c4aceb60bc134f3223f3","has_figures":false,"extraction":"text"},{"ordinal":39,"depth":1,"kind":"rule","number":"4.9","title":"Punches and elbow strikes","body":"● Buckler: reference: 3.1.2 Buckler\n● Polearm: reference: 3.1.3 Polearm","page_from":8,"page_to":8,"stable_key":"duels-rules:4.9","parent_key":"duels-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8fa6964d43f5fe142de467e1c2c645f1c5c85c8ddd70d2920bb4b67751b8fc7f","has_figures":false,"extraction":"text"},{"ordinal":40,"depth":1,"kind":"rule","number":"4.10","title":"Strikes with the pommel or cross guard of the sword","body":"● Strikes delivered with the pommel or cross guard of the sword.","page_from":8,"page_to":8,"stable_key":"duels-rules:4.10","parent_key":"duels-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c73343daece088fd126784616ec9cf237ee69179e0586fa667d0401bc00368ac","has_figures":false,"extraction":"text"},{"ordinal":41,"depth":1,"kind":"rule","number":"4.11","title":"Grappling","body":"● Grappling with hands and arms to the opponent’s torso, head, and limbs\n● Handholds of the opponent’s sword.","page_from":8,"page_to":8,"stable_key":"duels-rules:4.11","parent_key":"duels-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"64fa10e6be4d2a391c63ae1f9c847c194762022b10940d5081c624942a127e97","has_figures":false,"extraction":"text"},{"ordinal":42,"depth":1,"kind":"rule","number":"4.12","title":"Strikes with the shields","body":"● Strikes delivered with the edge of the shield are prohibited.","page_from":8,"page_to":8,"stable_key":"duels-rules:4.12","parent_key":"duels-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"bca3160cab03bc7c61ab903754a3eba64ca1950570b3080411694069bac96156","has_figures":false,"extraction":"text"},{"ordinal":43,"depth":0,"kind":"section","number":"5","title":"Authorized Equipment","body":"These rules aim to ensure a high standard of authenticity, safety, and historical accuracy in the equipment and conduct of the participants","page_from":9,"page_to":9,"stable_key":"duels-rules:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"caaebff8af6c84664834e72d915ab36702a884aae95852dbed5a6d9e863d5dff","has_figures":false,"extraction":"text"},{"ordinal":44,"depth":1,"kind":"rule","number":"5.1","title":"General Requirements","body":"","page_from":9,"page_to":9,"stable_key":"duels-rules:5.1","parent_key":"duels-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"cf3887697b5a48001cebaf05e10f2b3089a5005bb1087826998b751c94a3d0dd","has_figures":false,"extraction":"text"},{"ordinal":45,"depth":2,"kind":"rule","number":"5.1.1","title":"Technical and Authentic Compliance","body":"● All equipment must meet Buhurt International technical and authentic requirements.\n● Reference ”Weapons requirements” for all the rules.\n● Reference “Weapons/Shield Chart” for sizes and weights.","page_from":9,"page_to":9,"stable_key":"duels-rules:5.1.1","parent_key":"duels-rules:5.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"83d6a7669415fff6153b3807906603de7295bede80a44f018fe95634fde507be","has_figures":false,"extraction":"text"},{"ordinal":46,"depth":2,"kind":"rule","number":"5.1.2","title":"Competitor Eligibility","body":"● Competitors are not allowed to compete unless they have passed technical and authenticity checks.","page_from":9,"page_to":9,"stable_key":"duels-rules:5.1.2","parent_key":"duels-rules:5.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8676bc23863ddeb6395307e383aee7794d32571d3a470bd08cf1acf22d179620","has_figures":false,"extraction":"text"},{"ordinal":47,"depth":2,"kind":"rule","number":"5.1.3","title":"Weapon Requirements","body":"● Weapons must meet the Technical Requirement for Permitted Weapons.\n● Low-quality, dirty, rusty, or historically implausible weapons are not allowed.","page_from":9,"page_to":9,"stable_key":"duels-rules:5.1.3","parent_key":"duels-rules:5.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"964a3ae8af22bb017c7ab4293b735e40401d0a0d92b20b70f24357749cde903b","has_figures":false,"extraction":"text"},{"ordinal":48,"depth":2,"kind":"rule","number":"5.1.4","title":"Footwear","body":"● Modern boots or medieval shoes with explicitly modern outsoles are not allowed.","page_from":9,"page_to":9,"stable_key":"duels-rules:5.1.4","parent_key":"duels-rules:5.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c8f89538475b3b68aef1f6f9748b90336d08f5c8ae601cc89aacec0f9c9e093e","has_figures":false,"extraction":"text"},{"ordinal":49,"depth":2,"kind":"rule","number":"5.1.5","title":"Materials","body":"● Modern adhesive tape, plastic ties, and other visible modern materials are not permitted.\n● Textile adhesive tape of neutral colors for kit repair is an exception.","page_from":9,"page_to":9,"stable_key":"duels-rules:5.1.5","parent_key":"duels-rules:5.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"87b2fb90a27f7ae6249211102323bed1bb479469f9329ae43f5ec46597afefe4","has_figures":false,"extraction":"text"},{"ordinal":50,"depth":2,"kind":"rule","number":"5.1.6","title":"Decorations","body":"● Slogans and imagery on equipment should be historically plausible and not derogatory.\n● No modern equipment or decorations are allowed.","page_from":9,"page_to":9,"stable_key":"duels-rules:5.1.6","parent_key":"duels-rules:5.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b8512ccc68867170f272f744cd8f87a1b6526f356334d7e897bfe7d9536d1513","has_figures":false,"extraction":"text"},{"ordinal":51,"depth":2,"kind":"rule","number":"5.1.7","title":"Equipment Changes","body":"● Participants are allowed to change elements of equipment (armor or weapon) during intervals or due to breakage\n● Technical Marshal supervision is required for equipment changes","page_from":9,"page_to":9,"stable_key":"duels-rules:5.1.7","parent_key":"duels-rules:5.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"686ca96fbd0f8ceb6f4eccf93704b8b7e8e10931ee86a94c0f6478bbfa2a5bc2","has_figures":false,"extraction":"text"},{"ordinal":52,"depth":0,"kind":"section","number":"6","title":"Management of the competitors","body":"Management of the competitors is conducted in accordance with the Buhurt International Duels Regulations, with penalties that are imposed depending on the situation in the list and competitors’ and marshals’ actions.","page_from":10,"page_to":10,"stable_key":"duels-rules:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"aa9518e7edc98104c8136adc53d98f750141631fc108b5112d3ec457aaa98a4d","has_figures":false,"extraction":"text"},{"ordinal":53,"depth":0,"kind":"note","number":"7","title":"Change log","body":"This will be the change log of this document. It will be updated regularly and we will display what has been removed/added/reworded/formatted. This way we keep transparent communication and clarity about the rules\n\nUpdate date: March 2025 (2024.12 to 2025.03) Add: 3.7 Pinned to the List Rail\n\nUpdate date: December-2024 -add: 2.1.3 The grip must be held by two (2) hands for the strike to be counted as a point.\nUpdate date: December-2024 -Clearification:3.6 Weapon-Grabbing Participants are allowed to trap opponents weapon by shield, buckler and/or arm(not by hands)Grabbing the opponent's weapon (except the blade) with a free hand is permitted.\n-add: 5.1.8 Shield and Buckler -add: 5.1 Reference ”Weapons requirements” for all the rules -add: 5.1 Reference “Weapons/Shield Chart” for sizes and weights Update date: June-2024\n- format: Combined all duels rules into one document Update date: April-2024 -Removed:\n2.2 Specifics on Weapons and Bucklers ○ All Buhurt International weapons arming swords or One-handed swords and bucklers are permitted.\n-Removed:\n4.11 Strikes with the buckler Strikes delivered with the edge of the buckler in the lower body (below the waistline), head or neck of the opponent are prohibited.\n- Reworded: Fighters > Competitors\n- Reworded: Fights > Matches Update date: March-2024\n- format: new design format, document, will be used from now on.","page_from":11,"page_to":11,"stable_key":"duels-rules:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"a4ed73454fa1b0a2a6f694c178305c6bb71dd8e07dfe3254e9bff3ec31d24f21","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
